//! Кодогенерация — заключительный этап конвейера компиляции для этой версии.
//! Превращает AST в LLVM IR с помощью inkwell, из которого сам LLVM
//! соберёт машинный код.
//!
//! ВАЖНОЕ ОГРАНИЧЕНИЕ ЭТОЙ ВЕРСИИ (см. обсуждение перед этим файлом):
//! мы сознательно отложили семантический анализ, поэтому здесь генерируем
//! код только для подмножества, где тип переменной ВСЕГДА известен на месте:
//!   - ОбъявлениеСТипом (целое х = 5;)
//!   - ОбъявлениеНеизменное (неизменно целое х = 5;)
//! Оператор "Присваивание" (голое "имя = значение;") пока не поддержан
//! кодогенератором — для него нужен семантический анализ, чтобы понять,
//! это новое объявление с выводом типа или присваивание существующей
//! переменной (см. grammar.md, раздел 4). Попытка сгенерировать код для
//! него сейчас вернёт понятную ошибку, а не тихо сломается.
//!
//! Также пока не поддержаны: структуры, generics, результат<тип>/?,
//! массивы/списки, параллельно/канал, интерполяция строк. Всё это —
//! следующие шаги после того, как заработает базовый линейный код.

use std::collections::HashMap;

use inkwell::builder::Builder;
use inkwell::context::Context;
use inkwell::module::Module;
use inkwell::types::{BasicType, BasicTypeEnum, StructType};
use inkwell::values::{BasicValueEnum, FunctionValue, PointerValue};
use inkwell::IntPredicate;
use inkwell::FloatPredicate;

use crate::ast::*;
use crate::semantic::РазрешённоеПрисваивание;
use crate::semantic::РешённыйТип;

/// Индекс LLVM-поля 0 в каждой структуре зарезервирован под счётчик ссылок
/// ARC (см. зарегистрировать_структуры) — значит любой пользовательский
/// "логический" индекс поля (посчитанный по позиции в имена_полей) должен
/// сдвигаться на эту константу перед использованием в build_struct_gep/
/// get_field_type_at_index. Централизовано здесь, а не как магическое "+1"
/// в нескольких местах, чтобы это решение было видно и легко пересмотреть.
const СМЕЩЕНИЕ_ПОЛЕЙ_ARC: u32 = 1;

/// Дополнительная информация о переменной, нужная для доступа к её
/// содержимому позже (полю структуры или элементу массива).
/// Раньше здесь был просто Option<String> (имя структуры или ничего) —
/// расширено до трёх вариантов, когда добавились массивы, у которых
/// своя, отличная от структур механика доступа (см. комментарии у
/// получить_структуру_из_выражения и получить_массив_из_выражения).
#[derive(Clone)]
enum ДополнительнаяИнформация<'ctx> {
    Нет,
    Структура(String),
    Массив {
        элемент: BasicTypeEnum<'ctx>,
        размер: u32,
    },
    /// Переменная хранит результат<T> — для доступа к псевдополям
    /// (успешно/значение/сообщение) не нужен ни тип элемента, ни размер:
    /// макет результат<T> всегда один и тот же (три поля с фиксированными
    /// индексами 0/1/2), одинаковый для любого T. См. сгенерировать_доступ_к_полю.
    /// "имя_структуры_значения" — если T САМА является структурой, её имя
    /// (нужно для поддержки цепочек вида "результат.значение.поле" — иначе
    /// неоткуда узнать, к какой структуре относится "поле" после
    /// "значение" — та же причина, что и у методов/функций, возвращающих
    /// структуру, см. получить_структуру_из_выражения).
    Результат {
        имя_структуры_значения: Option<String>,
    },
    /// Переменная хранит Список<тип>. "ключ" — строковый идентификатор
    /// конкретной инстанциации (например, "целое" для Список<целое>),
    /// используется для поиска соответствующего LLVM struct-типа в
    /// self.списки. "элемент" — LLVM-тип элемента, нужен напрямую (не
    /// выводится из структуры постфактум — та же причина, что и с
    /// структурами: после LLVM 15 указатели непрозрачны, вывести тип
    /// элемента из самого значения невозможно, поэтому храним явно).
    Список {
        ключ: String,
        элемент: BasicTypeEnum<'ctx>,
        /// Если элементы списка сами являются структурой — её имя (для
        /// ARC: нужно "захватить" при .добавить(...), если передают
        /// уже существующую переменную, а не свежий вызов конструктора —
        /// см. сгенерировать_метод_списка, тот же принцип, что и в
        /// сгенерировать_вызов_конструктора для полей-структур).
        имя_структуры_элемента: Option<String>,
        /// НОВОЕ (Список<Контракт>): если элементы списка — КОНТРАКТ (не
        /// обычная структура) — его имя. ⚠️ НАЙДЕНО РЕАЛЬНОЙ ПРОВЕРКОЙ,
        /// самая содержательная находка во всей этой цепочке: без этого
        /// поля .добавить(...) не знало, что элемент нужно УПАКОВАТЬ в
        /// "толстый указатель" {данные, vtable} перед записью — вместо
        /// этого записывался голый указатель на структуру (8 байт вместо
        /// нужных 16), а вторая половина элемента оставалась
        /// неинициализированным мусором из malloc — именно оттуда при
        /// последующем динамическом вызове через vtable читался мусорный
        /// адрес функции, вызывая Segmentation fault.
        имя_контракта_элемента: Option<String>,
    },
    /// Переменная хранит Словарь<Ключ, Значение> — аналогично Список, но с двумя типами
    /// (ключа и значения) вместо одного.
    Словарь {
        ключ: String,
        тип_ключа: BasicTypeEnum<'ctx>,
        тип_значения: BasicTypeEnum<'ctx>,
        /// То же самое, что и у Список, но для типа ЗНАЧЕНИЯ (ключи пока
        /// не бывают структурами — ограничены целыми числами и текстом).
        имя_структуры_значения: Option<String>,
    },
    /// НОВОЕ (многопоточность, вторая часть): переменная хранит канал<тип>.
    /// В отличие от Список/Словарь, у канала нет отдельных LLVM struct-типов
    /// на каждую инстанциацию T — сам layout в памяти (мьютекс + условная
    /// переменная + флаг + 8-байтный слот значения) одинаков независимо от
    /// T, различается только то, как интерпретируется этот 8-байтный слот
    /// при чтении/записи (см. сгенерировать_метод_канала).
    Канал {
        элемент: BasicTypeEnum<'ctx>,
    },
    /// НОВОЕ (настоящий полиморфизм через контракты): переменная хранит
    /// значение типа "контракт" — "толстый указатель". Имя контракта
    /// нужно для поиска нужного индекса метода в self.контракты_методы
    /// при динамическом вызове (см. сгенерировать_вызов_метода).
    Контракт(String),
}

pub struct Кодогенератор<'ctx> {
    контекст: &'ctx Context,
    модуль: Module<'ctx>,
    билдер: Builder<'ctx>,
    /// Таблица переменных текущей функции: имя -> (указатель в стеке, тип,
    /// дополнительная информация — структура это или массив).
    /// ВАЖНО: третий элемент — не оптимизация, а необходимость. Начиная с
    /// LLVM 15 указатели "непрозрачны" (opaque pointers) — указатель на
    /// структуру Пользователь и указатель на структуру Собака выглядят в
    /// LLVM IR совершенно одинаково (просто "ptr", без информации о типе
    /// того, на что указывают). Значит, УЗНАТЬ имя структуры (или тип
    /// элемента массива) ИЗ САМОГО LLVM-значения после LLVM 15 невозможно
    /// в принципе — эту информацию нужно хранить отдельно, на уровне
    /// нашего собственного кодогенератора, с самого момента создания
    /// переменной.
    переменные: HashMap<String, (PointerValue<'ctx>, BasicTypeEnum<'ctx>, ДополнительнаяИнформация<'ctx>)>,
    /// Какие переменные объявлены как "неизменно" — для проверки на этапе кодогенерации
    неизменные: HashMap<String, bool>,
    /// Счётчик для уникальных имён глобальных строковых констант (текст1, текст2, ...)
    счётчик_строк: usize,
    /// Решения семантического анализатора для узлов Присваивание, в том же
    /// порядке, в каком анализатор их обходил. Кодогенератор идёт по AST
    /// в том же порядке и "потребляет" их по одному через следующее_решение().
    /// Это простой, но рабочий способ передать информацию между этапами без
    /// переписывания всего AST заново — годится для текущего масштаба проекта.
    решения_присваиваний: std::vec::IntoIter<РазрешённоеПрисваивание>,
    /// LLVM struct-типы для каждой известной структуры языка "Сфера",
    /// плюс список полей в том же порядке, что и в LLVM-типе (нужен, чтобы
    /// по имени поля найти его числовой индекс для GEP-инструкции).
    структуры: HashMap<String, (StructType<'ctx>, Vec<String>)>,
    /// НОВОЕ (настоящий полиморфизм через контракты): (имя_структуры,
    /// имя_контракта) -> глобальный массив указателей на функции — по
    /// одному на каждый метод контракта, В ПОРЯДКЕ ЕГО ОБЪЯВЛЕНИЯ,
    /// указывающих на КОНКРЕТНУЮ реализацию метода именно у этой
    /// структуры. Заполняется один раз, при регистрации структур (см.
    /// сгенерировать_программу) — переиспользуется при каждом
    /// присваивании "ИмяКонтракта переменная = экземпляр_структуры;",
    /// не генерируется заново на каждое такое присваивание.
    vtables: HashMap<(String, String), inkwell::values::GlobalValue<'ctx>>,
    /// НОВОЕ (настоящий полиморфизм через контракты): имя контракта ->
    /// ПОЛНЫЕ сигнатуры его методов (не только имена — нужны типы
    /// параметров/возврата для построения правильного типа функции при
    /// indirect call), В ПОРЯДКЕ ОБЪЯВЛЕНИЯ — индекс метода в этом списке
    /// определяет его индекс в vtable ЛЮБОЙ структуры, реализующей этот
    /// контракт (см. сгенерировать_вызов_метода). Заполняется один раз, в
    /// сгенерировать_программу, вместе с генерацией самих vtable.
    /// НОВОЕ (настоящий полиморфизм через контракты): "имя функции ->
    /// AST-типы её параметров, в порядке объявления" — нужно при генерации
    /// ОБЫЧНОГО вызова функции (Выражение::ВызовФункции), чтобы узнать,
    /// ожидает ли какой-то конкретный параметр тип-контракт — из одного
    /// только LLVM-типа параметра (всегда одинаковый "толстый указатель"
    /// для ЛЮБОГО контракта) не различить, КАКОЙ именно контракт имеется
    /// в виду, а для упаковки нужно точное имя (чтобы найти нужную vtable).
    параметры_функций: HashMap<String, Vec<Тип>>,
    контракты_методы: HashMap<String, Vec<СигнатураМетодаКонтракта>>,
    /// Текущая функция/метод, чьё тело сейчас генерируется — нужна оператору
    /// "?" (Проброс), чтобы создавать новые базовые блоки для условного
    /// раннего возврата при ошибке (append_basic_block требует FunctionValue).
    текущая_функция: Option<FunctionValue<'ctx>>,
    /// LLVM-тип "успешного" значения (T в результат<T>) ТЕКУЩЕЙ функции —
    /// нужен для "ошибка(...)" и для оператора "?", чтобы построить
    /// результат<T> с правильным типом поля "значение" при раннем возврате.
    /// None, если текущая функция не объявлена как результат<тип>.
    текущий_ok_тип_llvm: Option<BasicTypeEnum<'ctx>>,
    /// LLVM struct-типы для каждой использованной в программе инстанциации
    /// Список<тип> — ключ строится функцией ключ_типа_списка. Заполняется
    /// ЗАРАНЕЕ, одним проходом (см. зарегистрировать_списки), той же схемой,
    /// что и структуры — поэтому тип_в_llvm может читать эту таблицу
    /// как &self, не требуя мутации во время генерации тел функций.
    списки: HashMap<String, StructType<'ctx>>,
    /// То же самое, но для Словарь<Ключ, Значение> — ключ строится функцией
    /// ключ_типа_словаря из пары (тип_ключа, тип_значения).
    словари: HashMap<String, StructType<'ctx>>,
    /// ARC (автоматическое освобождение): СТЕК областей видимости — каждый
    /// элемент стека соответствует одному блоку кода (тело функции целиком —
    /// самый нижний/первый элемент; каждый вложенный если/пока/для каждого
    /// добавляет свой элемент поверх). Внутри каждого элемента — список
    /// структурных переменных, объявленных ИМЕННО в этом блоке.
    ///
    /// Правила (подробное обоснование — в README, раздел про ARC):
    /// - При объявлении структурной переменной — добавляем её в ВЕРХНИЙ
    ///   (самый вложенный, "текущий") элемент стека.
    /// - При "вернуть" на ЛЮБОЙ глубине вложенности — освобождаем ВСЕ
    ///   структуры из ВСЕХ элементов стека (кроме той, что совпадает с
    ///   самим возвращаемым значением — её владение "перемещается" наружу).
    /// - При ЕСТЕСТВЕННОМ выходе из блока (условие цикла стало ложным,
    ///   переход к следующей ветке если/иначе, без явного "вернуть" внутри) —
    ///   освобождаем структуры ТОЛЬКО верхнего элемента (этого блока),
    ///   затем убираем этот элемент со стека.
    ///
    /// Почему это безопасно (в отличие от прежней, более узкой версии):
    /// освобождение всегда генерируется ВНУТРИ ТОГО ЖЕ блока, где были
    /// объявлены структуры — если LLVM в рантайме вообще дошёл до этой
    /// точки, значит и объявление структуры (более раннее в том же блоке)
    /// точно уже выполнилось. Опасность (обращение к неинициализированной
    /// памяти) была бы только при попытке освободить структуру СНАРУЖИ
    /// блока, где её объявление могло не выполниться — а мы теперь этого
    /// не делаем: каждый блок убирает за собой сам, прежде чем "исчезнуть"
    /// со стека.
    стек_arc_областей: Vec<Vec<(String, String, StructType<'ctx>)>>,
    /// НОВОЕ (текст под ARC — закрытие давно известной утечки): та же
    /// идея, что и у стек_arc_областей выше, но для ТЕКСТОВЫХ переменных,
    /// ВЛАДЕЮЩИХ свежесозданным (malloc'нутым) буфером — конкатенация
    /// ("+"), регистр_в_верхний/нижний, целое_в_текст, дробное_в_текст,
    /// верно_в_текст. Список ИМЁН таких переменных в каждой области
    /// видимости (не нужен StructType/имя_структуры — текст всегда i8*).
    ///
    /// ⚠️ ЧЕСТНО УЗКИЙ ОБЪЁМ v1: отслеживаются ТОЛЬКО простые локальные
    /// переменные вида "текст имя = <текст-порождающее выражение>;" — НЕ
    /// текстовые ПОЛЯ структур (структура может пережить функцию, где
    /// создан её текст — сложная семантика владения, отдельный следующий
    /// шаг) и НЕ параметры функций (текст, пришедший как параметр, никогда
    /// не освобождается ЭТОЙ функцией — защита от double-free, если
    /// вызывающая сторона всё ещё держит собственную ссылку на этот текст).
    стек_arc_областей_текста: Vec<Vec<String>>,
    /// НОВОЕ (многопоточность v1): счётчик для генерации уникальных имён
    /// LLVM-функций из тел блоков "параллельно { ... }" — их может быть
    /// несколько в одной программе, имена не должны конфликтовать.
    счётчик_параллельных_блоков: u32,
    /// ARC (рекурсивное освобождение): для каждой структуры — список её
    /// ПОЛЕЙ, которые сами являются структурами: (индекс_поля_в_llvm_с_учётом_
    /// СМЕЩЕНИЕ_ПОЛЕЙ_ARC, имя_структуры_этого_поля). Заполняется один раз
    /// при регистрации структур (зарегистрировать_структуры), используется
    /// методом "отпустить", чтобы при освобождении объекта также освободить
    /// (рекурсивно) все структуры, на которые он ссылается через свои поля —
    /// иначе они "терялись" бы в памяти, даже если родитель был последней
    /// ссылкой на них.
    структурные_поля: HashMap<String, Vec<(u32, String)>>,
    /// НОВОЕ (текст под ARC, закрытие пробела внутри циклов): для каждой
    /// отслеживаемой текстовой переменной — адрес отдельной, скрытой
    /// булевой (i1) alloca-ячейки, хранящей "владеет ли переменная СЕЙЧАС
    /// (в рантайме) своим значением" — истина, если последнее записанное
    /// в неё значение было malloc'нутым (является_текст_порождающим), а
    /// не литералом. ⚠️ НАЙДЕНО РЕАЛЬНОЙ ПРОВЕРКОЙ: без этого — решение
    /// "освобождать ли старое значение при переприсваивании" принималось
    /// ОДИН раз, статически, в момент компиляции AST-узла присваивания —
    /// но внутри цикла один и тот же узел выполняется много раз, и на
    /// первой итерации переменная ещё может быть литералом (не течёт), а
    /// на второй и далее — уже владеющим значением от предыдущей итерации
    /// (течёт, поскольку СГЕНЕРИРОВАННЫЙ КОД для этого узла — один и тот
    /// же на каждой итерации, а компилятор решил "не освобождать" один
    /// раз навсегда). Ключ — простое имя переменной; создаётся лениво,
    /// при первой необходимости.
    флаги_владения_текстом: HashMap<String, inkwell::values::PointerValue<'ctx>>,
    /// НОВОЕ: та же информация, что и структурные_поля ("это поле —
    /// структура, вот какая"), но БЕЗ ИСКЛЮЧЕНИЯ "слабая" полей — нужна
    /// ОТДЕЛЬНО, потому что "структурные_поля" используется ДЛЯ ДВУХ РАЗНЫХ
    /// ЦЕЛЕЙ: (1) ARC retain/release — там "слабая" ДОЛЖНА быть исключена
    /// (иначе "слабая" не работала бы вообще), и (2) навигация по цепочке
    /// доступа "а.б.в" (получить_структуру_из_выражения) — там "слабая"
    /// поле ВСЁ РАВНО указывает на структуру, доступ к её полям должен
    /// работать нормально (слабость влияет ТОЛЬКО на владение памятью,
    /// не на то, можно ли читать через эту ссылку).
    все_структурные_поля: HashMap<String, Vec<(u32, String)>>,
    /// НОВОЕ (текст под ARC — поля структур): для каждой структуры —
    /// список индексов её полей типа "текст" (с учётом
    /// СМЕЩЕНИЕ_ПОЛЕЙ_ARC). Используется в двух местах: (1) конструктор —
    /// каждое такое поле записывается через strdup (копия), а не напрямую,
    /// чтобы структура ГАРАНТИРОВАННО владела своим текстом всегда; (2)
    /// "отпустить" — безусловно освобождает (free) каждое такое поле при
    /// уничтожении структуры, безопасно именно благодаря инварианту из
    /// пункта (1) — раз запись всегда идёт через копию, освобождение
    /// никогда не тронет литерал или чужую память.
    текстовые_поля_структур: HashMap<String, Vec<u32>>,
    /// ARC (рекурсивное освобождение), защита от бесконечной рекурсии:
    /// множество имён структур, для которых МЫ СЕЙЧАС генерируем код
    /// освобождения (по цепочке рекурсивных вызовов "отпустить"). Если
    /// структура А хранит поле типа Б, а Б хранит поле типа А (циклическая
    /// ссылка типов — саму такую ситуацию язык пока не проверяет отдельно,
    /// см. grammar.md, TODO про проверку циклов между структурами), без
    /// этой защиты кодогенератор попытался бы генерировать
    /// отпустить(А) → отпустить(Б) → отпустить(А) → ... до переполнения
    /// СОБСТВЕННОГО стека компилятора (не программы пользователя!) прямо
    /// во время сборки. При повторной встрече уже обрабатываемой структуры
    /// рекурсия просто останавливается (её собственный "верхний" отпустить
    /// уже случится один раз, из вызвавшего кода — этого достаточно, чтобы
    /// не потерять ссылку полностью, хотя сама циклическая ссылка типов
    /// всё равно останется утечкой — та же категория проблемы, что и
    /// "слабая" для разрыва циклов, которая тоже пока не реализована).
    цепочка_рекурсивного_освобождения: std::collections::HashSet<String>,
    /// Распределённая карта "(структура, метод) -> имя структуры результата" —
    /// только для методов, возвращающих структуру. Нужна для поддержки
    /// цепочек вида "объект.метод().поле" в получить_структуру_из_выражения —
    /// см. подробный комментарий там же и у геттера в semantic.rs.
    методы_возвращающие_структуру: HashMap<(String, String), String>,
    /// То же самое, но для СВОБОДНЫХ функций — "имя_функции -> имя структуры
    /// результата". Поддерживает цепочки вида "функция().поле".
    функции_возвращающие_структуру: HashMap<String, String>,
    /// Имена ШАБЛОНОВ пользовательских обобщённых структур ("Коробка", не
    /// "Коробка__целое") — нужно, чтобы распознать "Коробка<целое>(...)"
    /// как вызов конструктора обобщённой структуры (требует мономорфизации
    /// имени в манглированное), не как обычный вызов функции.
    имена_обобщённых_структур: std::collections::HashSet<String>,
    /// То же самое, что и у структур выше, только для обобщённых функций —
    /// нужно, чтобы распознать "макс_из_двух<целое>(...)" как вызов
    /// обобщённой функции (требует мономорфизации имени в манглированное),
    /// не как обычный вызов функции.
    имена_обобщённых_функций: std::collections::HashSet<String>,
    /// НОВОЕ (v2 — разрешение коллизий имён между модулями): манглированные
    /// LLVM-имена для ВСЕХ функций из подключённых модулей — ключ (модуль, имя).
    манглированные_имена_функций: HashMap<(String, String), String>,
    /// "имя функции -> модуль", для функций, доступных БЕЗ квалификации.
    однозначные_модульные_функции: HashMap<String, String>,
    /// "русское имя внешней функции -> реальное имя символа библиотеки" —
    /// см. подробное объяснение в semantic.rs.
    внешние_алиасы: HashMap<String, String>,
    /// "(имя_структуры, имя_поля)" для полей, объявленных с "слабая" — см.
    /// подробное объяснение в semantic.rs.
    слабые_поля: std::collections::HashSet<(String, String)>,
}

#[derive(Debug)]
pub struct ОшибкаКодогенерации {
    pub сообщение: String,
}

fn ошибка(сообщение: impl Into<String>) -> ОшибкаКодогенерации {
    ОшибкаКодогенерации {
        сообщение: сообщение.into(),
    }
}

impl<'ctx> Кодогенератор<'ctx> {
    pub fn новый(
        контекст: &'ctx Context,
        имя_модуля: &str,
        решения_присваиваний: Vec<РазрешённоеПрисваивание>,
        структуры_из_анализа: &HashMap<String, Vec<(String, РешённыйТип)>>,
        используемые_списки: &std::collections::HashSet<РешённыйТип>,
        используемые_словари: &std::collections::HashSet<(РешённыйТип, РешённыйТип)>,
        методы_возвращающие_структуру: &HashMap<(String, String), String>,
        функции_возвращающие_структуру: &HashMap<String, String>,
        имена_обобщённых_структур: &std::collections::HashSet<String>,
        имена_обобщённых_функций: &std::collections::HashSet<String>,
        манглированные_имена_функций: &HashMap<(String, String), String>,
        однозначные_модульные_функции: &HashMap<String, String>,
        внешние_алиасы: &HashMap<String, String>,
        слабые_поля: &std::collections::HashSet<(String, String)>,
    ) -> Result<Self, ОшибкаКодогенерации> {
        let модуль = контекст.create_module(имя_модуля);
        let билдер = контекст.create_builder();

        let mut кодогенератор = Кодогенератор {
            контекст,
            модуль,
            билдер,
            переменные: HashMap::new(),
            неизменные: HashMap::new(),
            счётчик_строк: 0,
            решения_присваиваний: решения_присваиваний.into_iter(),
            структуры: HashMap::new(),
            vtables: HashMap::new(),
            параметры_функций: HashMap::new(),
            контракты_методы: HashMap::new(),
            текущая_функция: None,
            текущий_ok_тип_llvm: None,
            списки: HashMap::new(),
            словари: HashMap::new(),
            стек_arc_областей: Vec::new(),
            стек_arc_областей_текста: Vec::new(),
            счётчик_параллельных_блоков: 0,
            структурные_поля: HashMap::new(),
            флаги_владения_текстом: HashMap::new(),
            все_структурные_поля: HashMap::new(),
            текстовые_поля_структур: HashMap::new(),
            цепочка_рекурсивного_освобождения: std::collections::HashSet::new(),
            методы_возвращающие_структуру: методы_возвращающие_структуру.clone(),
            функции_возвращающие_структуру: функции_возвращающие_структуру.clone(),
            имена_обобщённых_структур: имена_обобщённых_структур.clone(),
            имена_обобщённых_функций: имена_обобщённых_функций.clone(),
            манглированные_имена_функций: манглированные_имена_функций.clone(),
            однозначные_модульные_функции: однозначные_модульные_функции.clone(),
            внешние_алиасы: внешние_алиасы.clone(),
            слабые_поля: слабые_поля.clone(),
        };
        кодогенератор.объявить_системные_функции();
        кодогенератор.объявить_глобальные_argc_argv();
        кодогенератор.зарегистрировать_структуры(структуры_из_анализа)?;
        for тип_элемента in используемые_списки {
            кодогенератор.получить_или_создать_тип_списка(тип_элемента)?;
        }
        for (тип_ключа, тип_значения) in используемые_словари {
            кодогенератор.получить_или_создать_тип_словаря(тип_ключа, тип_значения)?;
        }
        Ok(кодогенератор)
    }

    /// Строит LLVM struct-тип для каждой структуры языка "Сфера", в порядке
    /// полей, как их вычислил семантический анализатор. Делается один раз,
    /// до генерации тел функций — чтобы любая функция могла ссылаться на
    /// любую структуру независимо от порядка объявления в файле.
    fn зарегистрировать_структуры(
        &mut self,
        структуры_из_анализа: &HashMap<String, Vec<(String, РешённыйТип)>>,
    ) -> Result<(), ОшибкаКодогенерации> {
        let контекст = self.контекст;

        // ⚠️ НАЙДЕННЫЙ ПРИ РЕАЛЬНОМ ТЕСТИРОВАНИИ, СЕРЬЁЗНЫЙ БАГ (не просто
        // "неудобный порядок в файле", а НАСТОЯЩАЯ НЕДЕТЕРМИНИРОВАННОСТЬ):
        // раньше здесь был ОДИН проход, итерирующий структуры_из_анализа
        // (HashMap) напрямую — порядок итерации HashMap в Rust НЕ
        // ГАРАНТИРОВАН и СЛУЧАЕН между запусками процесса (случайный seed
        // хеширования, защита от DoS-атак через коллизии хешей). Значит
        // ОДИН И ТОТ ЖЕ исходный код мог успешно скомпилироваться в один
        // запуск компилятора и упасть в другой — не из-за порядка структур
        // В ФАЙЛЕ, а из-за случайности самого HashMap.
        //
        // Решение — двухпроходная регистрация, классический приём для LLVM:
        // сначала объявляем ВСЕ структуры как ПУСТЫЕ (opaque) именованные
        // типы (это не требует знания тел ДРУГИХ структур — просто
        // резервирует имя), и только ПОТОМ, вторым проходом, заполняем
        // реальные поля. Работает потому, что структуры у нас ВСЕГДА
        // представлены как УКАЗАТЕЛИ, когда используются как тип ПОЛЯ
        // другой структуры — а указатель имеет фиксированный размер (8 байт)
        // независимо от того, заполнено ли ещё тело типа, на который он
        // указывает. Значит к моменту второго прохода порядок уже совершенно
        // не важен — на этом этапе КАЖДАЯ структура уже существует хотя бы
        // как opaque-объявление, к которому можно построить указатель.

        // --- Первый проход: имена, без тел ---
        for имя_структуры in структуры_из_анализа.keys() {
            let llvm_struct = self.контекст.opaque_struct_type(имя_структуры);
            let поля = &структуры_из_анализа[имя_структуры];
            let имена_полей: Vec<String> = поля.iter().map(|(имя, _)| имя.clone()).collect();
            self.структуры.insert(имя_структуры.clone(), (llvm_struct, имена_полей));
        }

        // --- Второй проход: реальные тела (порядок уже не важен) ---
        for (имя_структуры, поля) in структуры_из_анализа {
            // ⚠️ НАЙДЕНО ПРИ РЕАЛЬНОМ ИСПОЛЬЗОВАНИИ: раньше здесь был
            // единый .map(...).collect() через свободную функцию
            // решённый_тип_в_llvm — та сознательно ОТКАЗЫВАЕТСЯ обрабатывать
            // Список<T>/Словарь<К,З> (у неё нет доступа к &mut self, а
            // регистрация конкретной инстанциации списка/словаря его
            // требует — см. получить_или_создать_тип_списка). Значит
            // Список<T> КАК ПОЛЕ СТРУКТУРЫ (не просто локальная переменная
            // или аргумент функции) раньше не работал вообще — этот
            // случай не встречался ни разу, пока не потребовался прямо
            // здесь, для поля "ширины_колонок: Список<целое>" у Таблица.
            let mut llvm_типы_полей: Vec<BasicTypeEnum> = Vec::new();
            for (_, тип) in поля {
                let llvm_тип = match тип {
                    РешённыйТип::Список(тип_элемента) => {
                        let llvm_struct = self.получить_или_создать_тип_списка(тип_элемента)?;
                        llvm_struct.ptr_type(inkwell::AddressSpace::default()).into()
                    }
                    РешённыйТип::Словарь(тип_ключа, тип_значения) => {
                        let llvm_struct = self.получить_или_создать_тип_словаря(тип_ключа, тип_значения)?;
                        llvm_struct.ptr_type(inkwell::AddressSpace::default()).into()
                    }
                    _ => решённый_тип_в_llvm(контекст, тип, &self.структуры)?,
                };
                llvm_типы_полей.push(llvm_тип);
            }

            // Поле счётчика ссылок (i64) идёт ПЕРВЫМ, перед всеми полями,
            // которые видит программист языка "Сфера" — это основа ARC:
            // каждый объект структуры "знает", сколько мест на него сейчас
            // ссылаются. Индекс 0 зарезервирован под счётчик; пользовательские
            // поля сдвинуты на +1 (см. константу СМЕЩЕНИЕ_ПОЛЕЙ_ARC).
            let счётчик_тип: BasicTypeEnum = self.контекст.i64_type().into();
            let mut llvm_типы_с_счётчиком = vec![счётчик_тип];
            llvm_типы_с_счётчиком.extend(llvm_типы_полей);

            // llvm_struct УЖЕ существует (создан в первом проходе выше) —
            // здесь только заполняем его тело, не создаём заново.
            let (llvm_struct, _) = self
                .структуры
                .get(имя_структуры)
                .cloned()
                .ok_or_else(|| ошибка(format!(
                    "внутренняя ошибка: структура '{}' потеряна между проходами регистрации",
                    имя_структуры
                )))?;
            llvm_struct.set_body(&llvm_типы_с_счётчиком, false);

            // ARC (рекурсивное освобождение): запоминаем, какие поля этой
            // структуры сами являются структурами — используется методом
            // "отпустить", чтобы при освобождении объекта рекурсивно
            // освободить и то, на что он ссылается через такие поля.
            // Индекс поля — с учётом СМЕЩЕНИЕ_ПОЛЕЙ_ARC (счётчик занимает 0).
            //
            // НОВОЕ: "слабая" поля СОЗНАТЕЛЬНО ИСКЛЮЧЕНЫ отсюда — эта же
            // карта используется И для retain при записи поля (конструктор,
            // присваивание), И для release при уничтожении владельца —
            // раз слабое поле просто не попадает в карту, оно автоматически
            // не участвует в ARC вообще (не увеличивает счётчик ссылок цели
            // при записи, не уменьшает при уничтожении владельца) — именно
            // так разрываются циклы (А хранит сильную ссылку на Б, Б хранит
            // слабую на А — тогда А может быть освобождён, даже пока жив Б).
            //
            // ⚠️ ЧЕСТНОЕ ОГРАНИЧЕНИЕ v1: это НЕ "настоящая" слабая ссылка с
            // проверкой живости цели (как в Swift/Objective-C, где слабая
            // ссылка автоматически становится nil при освобождении цели) —
            // здесь слабая ссылка МОЖЕТ стать висячей (dangling), если цель
            // будет освобождена, а слабая ссылка использована после этого.
            // Правильная защита потребовала бы отдельного механизма
            // отслеживания "жива ли цель ещё" (side-table/индирекция) —
            // самостоятельный, больший следующий шаг, честно отложенный.
            let структурные_поля_этой_структуры: Vec<(u32, String)> = поля
                .iter()
                .enumerate()
                .filter_map(|(индекс, (имя_поля, тип_поля))| {
                    if self.слабые_поля.contains(&(имя_структуры.to_string(), имя_поля.clone())) {
                        return None;
                    }
                    match тип_поля {
                        РешённыйТип::Структура(имя_структуры_поля) => {
                            Some((индекс as u32 + СМЕЩЕНИЕ_ПОЛЕЙ_ARC, имя_структуры_поля.clone()))
                        }
                        _ => None,
                    }
                })
                .collect();
            if !структурные_поля_этой_структуры.is_empty() {
                self.структурные_поля.insert(имя_структуры.clone(), структурные_поля_этой_структуры);
            }

            // НОВОЕ: та же логика, БЕЗ исключения "слабая" — для навигации
            // по цепочке доступа (получить_структуру_из_выражения), где
            // слабость поля не имеет значения (слабая ссылка всё ещё
            // указывает на структуру, читать через неё можно нормально —
            // см. подробное объяснение у поля все_структурные_поля).
            let все_структурные_поля_этой_структуры: Vec<(u32, String)> = поля
                .iter()
                .enumerate()
                .filter_map(|(индекс, (_, тип_поля))| match тип_поля {
                    РешённыйТип::Структура(имя_структуры_поля) => {
                        Some((индекс as u32 + СМЕЩЕНИЕ_ПОЛЕЙ_ARC, имя_структуры_поля.clone()))
                    }
                    _ => None,
                })
                .collect();
            if !все_структурные_поля_этой_структуры.is_empty() {
                self.все_структурные_поля.insert(имя_структуры.clone(), все_структурные_поля_этой_структуры);
            }

            // НОВОЕ (текст под ARC — поля структур): та же самая, простая
            // фильтрация, что и выше для полей-структур — только по типу
            // РешённыйТип::Текст вместо РешённыйТип::Структура.
            let текстовые_поля_этой_структуры: Vec<u32> = поля
                .iter()
                .enumerate()
                .filter_map(|(индекс, (_, тип_поля))| match тип_поля {
                    РешённыйТип::Текст => Some(индекс as u32 + СМЕЩЕНИЕ_ПОЛЕЙ_ARC),
                    _ => None,
                })
                .collect();
            if !текстовые_поля_этой_структуры.is_empty() {
                self.текстовые_поля_структур.insert(имя_структуры.clone(), текстовые_поля_этой_структуры);
            }
        }
        Ok(())
    }

    /// Возвращает (создавая при необходимости) LLVM struct-тип для конкретной
    /// инстанциации Список<тип>. Макет: { i64 счётчик_ссылок, i64 размер,
    /// i64 вместимость, T* данные } — тот же принцип ARC-заголовка, что и у
    /// обычных структур (счётчик первым полем), плюс два служебных поля для
    /// растущего буфера и указатель на сами данные в куче.
    ///
    /// Вызывается ЗАРАНЕЕ, до генерации тел функций (см. Кодогенератор::новый) —
    /// поэтому во время генерации тел эта таблица уже полностью заполнена, и
    /// её можно только читать (не пересоздавать на лету), что и позволяет
    /// тип_в_llvm оставаться простым методом с &self, а не &mut self.
    fn получить_или_создать_тип_списка(&mut self, тип_элемента: &РешённыйТип) -> Result<StructType<'ctx>, ОшибкаКодогенерации> {
        let ключ = ключ_типа_списка(тип_элемента);

        if let Some(существующий) = self.списки.get(&ключ) {
            return Ok(*существующий);
        }

        let llvm_элемент = решённый_тип_в_llvm(self.контекст, тип_элемента, &self.структуры)?;
        let указатель_на_элемент: BasicTypeEnum = llvm_элемент.ptr_type(inkwell::AddressSpace::default()).into();

        let i64_тип: BasicTypeEnum = self.контекст.i64_type().into();
        let поля = [i64_тип, i64_тип, i64_тип, указатель_на_элемент];

        let llvm_struct = self.контекст.opaque_struct_type(&format!("Список__{}", ключ));
        llvm_struct.set_body(&поля, false);

        self.списки.insert(ключ, llvm_struct);
        Ok(llvm_struct)
    }

    /// Аналог получить_или_создать_тип_списка, но для Словарь<Ключ, Значение> — макет
    /// { i64 счётчик_ссылок, i64 размер, i64 вместимость, K* ключи, V* значения } —
    /// два параллельных массива вместо одного (см. обсуждение архитектурного
    /// решения "словарь как список пар с линейным поиском" перед реализацией).
    fn получить_или_создать_тип_словаря(
        &mut self,
        тип_ключа: &РешённыйТип,
        тип_значения: &РешённыйТип,
    ) -> Result<StructType<'ctx>, ОшибкаКодогенерации> {
        let ключ = ключ_типа_словаря(тип_ключа, тип_значения);

        if let Some(существующий) = self.словари.get(&ключ) {
            return Ok(*существующий);
        }

        let llvm_тип_ключа = решённый_тип_в_llvm(self.контекст, тип_ключа, &self.структуры)?;
        let llvm_тип_значения = решённый_тип_в_llvm(self.контекст, тип_значения, &self.структуры)?;
        let указатель_на_ключ: BasicTypeEnum = llvm_тип_ключа.ptr_type(inkwell::AddressSpace::default()).into();
        let указатель_на_значение: BasicTypeEnum = llvm_тип_значения.ptr_type(inkwell::AddressSpace::default()).into();

        let i64_тип: BasicTypeEnum = self.контекст.i64_type().into();
        let поля = [i64_тип, i64_тип, i64_тип, указатель_на_ключ, указатель_на_значение];

        let llvm_struct = self.контекст.opaque_struct_type(&format!("Словарь__{}", ключ));
        llvm_struct.set_body(&поля, false);

        self.словари.insert(ключ, llvm_struct);
        Ok(llvm_struct)
    }

    /// Объявляет внешние функции из системной библиотеки C — это FFI
    /// "изнутри" компилятора: способ, которым сгенерированный код связывается
    /// с уже существующей, скомпилированной в системе функциональностью,
    /// не переписывая её с нуля. Ровно тот же принцип, который мы закладывали
    /// как FFI-механизм самого языка "Сфера" — здесь применён компилятором
    /// "для собственных нужд", чтобы получить вывод текста без необходимости
    /// самим писать системные вызовы под каждую платформу.
    fn объявить_системные_функции(&mut self) {
        let i32_тип = self.контекст.i32_type();
        let i64_тип = self.контекст.i64_type();
        let текст_указатель = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default());

        // int printf(const char* формат, ...);
        let тип_printf = i32_тип.fn_type(&[текст_указатель.into()], true);
        self.модуль.add_function("printf", тип_printf, None);

        // void* malloc(size_t размер);
        // Используем для выделения структур в куче — см. обсуждение перед
        // реализацией структур о том, почему объекты живут в куче, а не на
        // стеке (это готовит почву для будущего ARC, который будет управлять
        // временем жизни именно кучи через счётчик ссылок).
        let байт_указатель = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default());
        let тип_malloc = байт_указатель.fn_type(&[i64_тип.into()], false);
        self.модуль.add_function("malloc", тип_malloc, None);

        // void free(void* указатель);
        // Пара к malloc — используется методом "отпустить" (ARC), когда
        // счётчик ссылок объекта доходит до нуля.
        let тип_free = self.контекст.void_type().fn_type(&[байт_указатель.into()], false);
        self.модуль.add_function("free", тип_free, None);

        // НОВОЕ: int pthread_create(pthread_t *thread, const pthread_attr_t
        // *attr, void *(*start_routine)(void *), void *arg);
        // — для "параллельно { тело }". Все указательные аргументы (thread,
        // attr, arg) представлены как i8* — та же прагматичная модель
        // "непрозрачного указателя", что уже применена везде в FFI (см.
        // README про "текст" как universal pointer representation).
        // start_routine — указатель на функцию с сигнатурой "i8* (i8*)",
        // сгенерированную из тела блока "параллельно" (см.
        // сгенерировать_параллельно).
        let тип_функции_потока = байт_указатель.fn_type(&[байт_указатель.into()], false);
        let тип_pthread_create = self.контекст.i32_type().fn_type(
            &[
                байт_указатель.into(),
                байт_указатель.into(),
                тип_функции_потока.ptr_type(inkwell::AddressSpace::default()).into(),
                байт_указатель.into(),
            ],
            false,
        );
        self.модуль.add_function("pthread_create", тип_pthread_create, None);

        // НОВОЕ (join для потоков): int pthread_join(pthread_t thread,
        // void **retval); — ждёт завершения указанного потока. В отличие
        // от pthread_create, первый аргумент здесь — САМО значение
        // идентификатора потока (не адрес, куда его записать) — то, что
        // pthread_create вернул через свой первый (out-)параметр.
        // "retval" передаём как NULL — результат завершения потока язык
        // сейчас не пробрасывает наружу (сам факт завершения — не значение).
        let тип_pthread_join = self.контекст.i32_type().fn_type(&[байт_указатель.into(), байт_указатель.into()], false);
        self.модуль.add_function("pthread_join", тип_pthread_join, None);

        // НОВОЕ (многопоточность, вторая часть — "канал<T>"): все mutex/cond
        // функции работают с указателем на область памяти, которую сама
        // ОС заполняет своими внутренними данными — размер этой области
        // отличается между Linux и macOS (наша "арена" под неё специально
        // выделена с большим запасом, см. создать_канал ниже) — но сами
        // функции для вызывающего кода выглядят одинаково: непрозрачный
        // указатель на неё, как и everywhere в нашем FFI.
        // int pthread_mutex_init(pthread_mutex_t*, const pthread_mutexattr_t*);
        let тип_init = self.контекст.i32_type().fn_type(&[байт_указатель.into(), байт_указатель.into()], false);
        self.модуль.add_function("pthread_mutex_init", тип_init, None);
        // int pthread_cond_init(pthread_cond_t*, const pthread_condattr_t*);
        self.модуль.add_function("pthread_cond_init", тип_init, None);
        // int pthread_mutex_lock(pthread_mutex_t*); int pthread_mutex_unlock(pthread_mutex_t*);
        let тип_один_указатель = self.контекст.i32_type().fn_type(&[байт_указатель.into()], false);
        self.модуль.add_function("pthread_mutex_lock", тип_один_указатель, None);
        self.модуль.add_function("pthread_mutex_unlock", тип_один_указатель, None);
        // int pthread_cond_signal(pthread_cond_t*);
        self.модуль.add_function("pthread_cond_signal", тип_один_указатель, None);
        // int pthread_cond_wait(pthread_cond_t*, pthread_mutex_t*);
        let тип_два_указателя = self.контекст.i32_type().fn_type(&[байт_указатель.into(), байт_указатель.into()], false);
        self.модуль.add_function("pthread_cond_wait", тип_два_указателя, None);

        // void* memcpy(void* назначение, const void* источник, size_t байт);
        // Используется при росте буфера Список<тип> — когда вместимости не
        // хватает, нужно скопировать уже имеющиеся элементы в новый, больший
        // участок памяти, прежде чем освободить старый.
        let тип_memcpy = байт_указатель.fn_type(&[байт_указатель.into(), байт_указатель.into(), i64_тип.into()], false);
        self.модуль.add_function("memcpy", тип_memcpy, None);

        // int strcmp(const char* а, const char* б);
        // Используется для сравнения текста ("текст == текст") — сравнивает
        // СОДЕРЖИМОЕ строк (побайтово, до первого несовпадения или до конца),
        // возвращает 0 если строки равны. Гораздо безопаснее и проще, чем
        // писать цикл побайтового сравнения вручную в LLVM IR — libc уже
        // даёт готовую, проверенную десятилетиями реализацию.
        let тип_strcmp = i32_тип.fn_type(&[текст_указатель.into(), текст_указатель.into()], false);
        self.модуль.add_function("strcmp", тип_strcmp, None);

        // char* strdup(const char* строка);
        // НОВОЕ (текст под ARC — поля структур): выделяет НОВУЮ, malloc'нутую
        // копию строки — используется при записи текстового поля структуры
        // (конструктор, присваивание полю), чтобы структура ГАРАНТИРОВАННО
        // владела своим текстовым полем всегда — независимо от того, был ли
        // переданный аргумент литералом (глобальная константа, free() на
        // которой был бы крахом) или уже malloc'нутым значением. Простой,
        // безопасный инвариант вместо рантайм-флага владения "иногда да,
        // иногда нет" — цена: одно лишнее копирование памяти при каждой
        // записи текстового поля, взамен на возможность БЕЗУСЛОВНО
        // освобождать текстовые поля при уничтожении структуры.
        let тип_strdup = текст_указатель.fn_type(&[текст_указатель.into()], false);
        self.модуль.add_function("strdup", тип_strdup, None);

        // size_t strlen(const char* строка);
        // Используется для конкатенации текста ("текст + текст") — нужно
        // знать длину каждой строки, чтобы выделить буфер под результат
        // нужного размера.
        let тип_strlen = i64_тип.fn_type(&[текст_указатель.into()], false);
        self.модуль.add_function("strlen", тип_strlen, None);

        // long strtol(const char* строка, char** конец, int основание);
        // Используется для "текст_в_целое(...)" — разбирает текст в число.
        // Приём с "конец" (out-параметр, указатель-на-указатель) — стандартный
        // способ у этой функции сообщить, удалось ли распознать хоть одну
        // цифру: если после вызова *конец == строка (указатель не сдвинулся),
        // значит разбор не удался (строка не была числом).
        let указатель_на_текст_указатель = текст_указатель.ptr_type(inkwell::AddressSpace::default());
        let тип_strtol = i64_тип.fn_type(&[текст_указатель.into(), указатель_на_текст_указатель.into(), i32_тип.into()], false);
        self.модуль.add_function("strtol", тип_strtol, None);

        // int snprintf(char* буфер, size_t размер, const char* формат, ...);
        // Используется для "целое_в_текст(...)" — форматирует число в текст,
        // записывая результат в заранее выделенный буфер фиксированного
        // размера (i64 умещается максимум в ~20 символов + знак + нулевой
        // байт — буфер с запасом в 32 байта гарантированно достаточен,
        // поэтому не нужно вызывать snprintf дважды, как это иногда делают
        // для вычисления точного нужного размера буфера заранее).
        let тип_snprintf = i32_тип.fn_type(&[текст_указатель.into(), i64_тип.into(), текст_указатель.into()], true);
        self.модуль.add_function("snprintf", тип_snprintf, None);

        // char* strstr(const char* строка, const char* подстрока);
        // Используется для "содержит(...)" и "найти(...)" — ищет первое
        // вхождение подстроки, возвращает указатель на него или null, если
        // не найдено.
        let тип_strstr = текст_указатель.fn_type(&[текст_указатель.into(), текст_указатель.into()], false);
        self.модуль.add_function("strstr", тип_strstr, None);

        // FILE* fdopen(int дескриптор, const char* режим);
        // Используется для "прочитать_строку()" — получает поток для файлового
        // дескриптора 0 (стандартный ввод) БЕЗ обращения к глобальной
        // переменной stdin напрямую. Это важно для переносимости: имя этой
        // глобальной переменной ПЛАТФОРМО-ЗАВИСИМО (на Linux — "stdin", на
        // macOS — "__stdinp", другой символ!) — fdopen(0, "r") даёт тот же
        // результат стандартным, переносимым способом, без завязки на
        // конкретную платформу. FILE* представляем как обычный i8* — нам не
        // нужно знать внутреннее устройство структуры FILE, только передавать
        // указатель на неё дальше, в fgets.
        let тип_fdopen = текст_указатель.fn_type(&[i32_тип.into(), текст_указатель.into()], false);
        self.модуль.add_function("fdopen", тип_fdopen, None);

        // char* fgets(char* буфер, int размер, FILE* поток);
        // Читает одну строку (до перевода строки включительно, или до конца
        // буфера) из потока. Возвращает тот же указатель на буфер при
        // успехе, или null при ошибке/конце ввода (EOF без единого
        // прочитанного символа).
        let тип_fgets = текст_указатель.fn_type(&[текст_указатель.into(), i32_тип.into(), текст_указатель.into()], false);
        self.модуль.add_function("fgets", тип_fgets, None);

        // FILE* fopen(const char* путь, const char* режим);
        // Открывает файл — та же механика, что и fdopen, только по пути на
        // диске, а не по уже открытому файловому дескриптору.
        let тип_fopen = текст_указатель.fn_type(&[текст_указатель.into(), текст_указатель.into()], false);
        self.модуль.add_function("fopen", тип_fopen, None);

        // int fseek(FILE* поток, long смещение, int откуда);
        // Перемещает "курсор чтения/записи" внутри файла. Используется в
        // "прочитать_файл(...)" вместе с ftell, чтобы сначала узнать размер
        // файла (перейти в конец, спросить позицию, вернуться в начало),
        // прежде чем выделять буфер под всё содержимое разом.
        let i64_тип = self.контекст.i64_type();
        let тип_fseek = i32_тип.fn_type(&[текст_указатель.into(), i64_тип.into(), i32_тип.into()], false);
        self.модуль.add_function("fseek", тип_fseek, None);

        // long ftell(FILE* поток);
        // Текущая позиция курсора в файле — используем сразу после
        // "прыжка в конец" через fseek, чтобы узнать полный размер файла.
        let тип_ftell = i64_тип.fn_type(&[текст_указатель.into()], false);
        self.модуль.add_function("ftell", тип_ftell, None);

        // size_t fread(void* буфер, size_t размер_элемента, size_t количество, FILE* поток);
        // Читает данные из файла в буфер. Возвращает количество РЕАЛЬНО
        // прочитанных элементов (может быть меньше запрошенного, если файл
        // короче, чем мы думали, или произошла ошибка чтения).
        let тип_fread = i64_тип.fn_type(&[текст_указатель.into(), i64_тип.into(), i64_тип.into(), текст_указатель.into()], false);
        self.модуль.add_function("fread", тип_fread, None);

        // size_t fwrite(const void* данные, size_t размер_элемента, size_t количество, FILE* поток);
        // Записывает данные в файл. Возвращает количество РЕАЛЬНО записанных
        // элементов — проверяем это в "записать_файл(...)", чтобы не молчать
        // о неполной записи (диск заполнен, права и т.д.).
        let тип_fwrite = i64_тип.fn_type(&[текст_указатель.into(), i64_тип.into(), i64_тип.into(), текст_указатель.into()], false);
        self.модуль.add_function("fwrite", тип_fwrite, None);

        // int fclose(FILE* поток);
        // Закрывает файл, освобождая связанные с ним ресурсы ОС.
        let тип_fclose = i32_тип.fn_type(&[текст_указатель.into()], false);
        self.модуль.add_function("fclose", тип_fclose, None);

        // int system(const char* команда);
        // Запускает команду через командный процессор ОС (оболочку) и ждёт
        // её завершения. Используется для "выполнить_команду(...)".
        let тип_system = i32_тип.fn_type(&[текст_указатель.into()], false);
        self.модуль.add_function("system", тип_system, None);
    }

    /// Объявляет две глобальные переменные модуля — "хранилище" для argc и
    /// argv, которые операционная система передаёт в C-совместимую функцию
    /// main при старте программы. Обёртка main (сгенерировать_обёртку_main)
    /// сохраняет сюда полученные значения ДО вызова "главная" — а функция
    /// "аргументы_командной_строки()" (доступная из ЛЮБОГО места программы,
    /// не только из "главная") читает их обратно отсюда.
    ///
    /// Почему через глобальные переменные, а не параметры "главная" —
    /// "главная" в языке "Сфера" по-прежнему НЕ принимает параметров (это
    /// сознательно не менялось), значит нужен отдельный канал передачи этих
    /// значений внутрь программы, доступный из произвольной точки кода.
    fn объявить_глобальные_argc_argv(&mut self) {
        let i32_тип = self.контекст.i32_type();
        let текст_указатель = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default());
        let указатель_на_текст_указатель = текст_указатель.ptr_type(inkwell::AddressSpace::default());

        let глобальный_argc = self.модуль.add_global(i32_тип, None, "глобальный_argc");
        глобальный_argc.set_initializer(&i32_тип.const_int(0, false));

        let глобальный_argv = self.модуль.add_global(указатель_на_текст_указатель, None, "глобальный_argv");
        глобальный_argv.set_initializer(&указатель_на_текст_указатель.const_null());

        // ⚠️ НАЙДЕННЫЙ ПРИ РЕАЛЬНОМ ТЕСТИРОВАНИИ БАГ (реальная программа —
        // текстовый кликер с интерактивным циклом ввода — вскрыла это
        // немедленно; тест_ввода.код никогда не ловил проблему, поскольку
        // вызывал "прочитать_строку()" только ОДИН раз, не в цикле):
        // "прочитать_строку()" раньше вызывала fdopen(0, "r") заново при
        // КАЖДОМ вызове — создавая НОВЫЙ, отдельный поток FILE* каждый раз.
        // Стандартная библиотека C буферизует чтение ВНУТРИ структуры
        // FILE* — если новый поток создаётся заново, любые уже прочитанные,
        // но ещё не потреблённые байты из ВНУТРЕННЕГО буфера ПРЕДЫДУЩЕГО
        // потока теряются (тот объект просто "забывается", не закрывается
        // явно) — на практике это проявлялось как "вторая и последующие
        // команды в интерактивном цикле не читаются". Решение — глобальная
        // переменная-одиночка: поток создаётся ОДИН раз, при первом вызове,
        // и переиспользуется при всех последующих (та же техника, что уже
        // применена для argc/argv — ленивая инициализация через глобальное
        // состояние, не пересоздание на каждый вызов).
        let глобальный_поток_ввода = self.модуль.add_global(текст_указатель, None, "глобальный_поток_ввода");
        глобальный_поток_ввода.set_initializer(&текст_указатель.const_null());

        // НОВОЕ (join для потоков): "параллельно { ... }" — оператор, не
        // выражение — не возвращает наружу никакого дескриптора потока,
        // который можно было бы передать в отдельную функцию "подождать
        // именно этот поток". Полноценная поддержка этого потребовала бы
        // менять грамматику языка (Параллельно из Оператора в Выражение) —
        // самостоятельный, больший следующий шаг. Вместо этого — более
        // простое, но всё же полезное решение: глобальный, фиксированного
        // размера список ВСЕХ запущенных с начала программы (или с
        // последнего вызова дождаться_все_потоки()) потоков — новая
        // встроенная функция "дождаться_все_потоки()" ждёт и очищает их
        // все разом. ⚠️ Честное ограничение v1: максимум 256 потоков,
        // запущенных БЕЗ вызова дождаться_все_потоки() между ними —
        // превышение молча перезапишет память (нет проверки переполнения),
        // тот же компромисс "простота вместо динамического роста", что
        // уже был сделан для машинной части "арена"-распределителя.
        let тип_массива_потоков = текст_указатель.array_type(256);
        let глобальный_id_потоков = self.модуль.add_global(тип_массива_потоков, None, "sfera_id_потоков");
        глобальный_id_потоков.set_initializer(&тип_массива_потоков.const_zero());

        let глобальное_количество_потоков = self.модуль.add_global(self.контекст.i64_type(), None, "sfera_количество_потоков");
        глобальное_количество_потоков.set_initializer(&self.контекст.i64_type().const_int(0, false));
    }

    /// `библиотечный_режим` — если true, НЕ генерирует обёртку "main" и не
    /// требует наличия функции "главная" в программе. Библиотека — это код,
    /// предназначенный для подключения В ДРУГОЙ проект (через будущую
    /// систему пакетов), а не для самостоятельного запуска — у неё просто
    /// нет своей точки входа, и это нормально, не ошибка.
    pub fn сгенерировать_программу(
        &mut self,
        программа: &Программа,
        библиотечный_режим: bool,
        инстанциированные_обобщённые_структуры: &HashMap<String, ОбъявлениеСтруктуры>,
        решения_присваиваний_обобщённых_структур: &HashMap<String, Vec<РазрешённоеПрисваивание>>,
        // НОВОЕ (обобщённые функции): та же самая инфраструктура, что уже
        // работает для обобщённых структур выше — см. подробное объяснение
        // у их использования ниже в этой же функции.
        инстанциированные_обобщённые_функции: &HashMap<String, ОбъявлениеФункции>,
        решения_присваиваний_обобщённых_функций: &HashMap<String, Vec<РазрешённоеПрисваивание>>,
        модуль_каждого_узла: &[Option<String>],
        android_so: bool,
    ) -> Result<(), ОшибкаКодогенерации> {
        // Вспомогательная функция — вычисляет LLVM-имя функции, с учётом
        // того, из какого модуля она пришла (None — главный файл, буквальное
        // имя без изменений; Some(модуль) — манглированное "модуль__имя",
        // см. подробное объяснение у поля манглированные_имена_функций).
        let llvm_имя_функции = |кодогенератор: &Self, имя: &str, модуль: &Option<String>| -> String {
            match модуль {
                None => имя.to_string(),
                Some(модуль) => кодогенератор
                    .манглированные_имена_функций
                    .get(&(модуль.clone(), имя.to_string()))
                    .cloned()
                    .unwrap_or_else(|| format!("{}__{}", модуль, имя)),
            }
        };

        // НОВОЕ (настоящий полиморфизм через контракты): заполняем список
        // известных контрактов И ИХ МЕТОДОВ САМЫМ ПЕРВЫМ ДЕЛОМ — раньше
        // это происходило значительно позже (см. ниже, у генерации vtable),
        // а типы параметров функций (тип_в_llvm, вызывается уже в первом
        // цикле ниже) должны уметь отличить "Печатаемый" (контракт) от
        // обычного, отсутствующего имени структуры уже на этом, самом
        // первом шаге — иначе падает с "неизвестная структура".
        for узел in программа {
            if let ВерхнийУзел::Контракт(к) = узел {
                self.контракты_методы.insert(к.имя.clone(), к.методы.clone());
            }
        }

        // Сначала объявляем все функции (чтобы вызовы "вперёд" — до фактического
        // определения функции в файле — работали корректно).
        for (узел, модуль) in программа.iter().zip(модуль_каждого_узла.iter()) {
            if let ВерхнийУзел::Функция(ф) = узел {
                let llvm_имя = llvm_имя_функции(self, &ф.имя, модуль);
                self.объявить_сигнатуру_функции(ф, &llvm_имя)?;
            }
        }

        // НОВОЕ (обобщённые функции): уже полностью мономорфизированы
        // семантикой (манглированное имя записано прямо в поле "имя" самой
        // подставленной копии) — та же самая инфраструктура, что и методы
        // обобщённых структур чуть выше, просто источник данных другой (не
        // программа напрямую, а отдельная таблица инстанциаций). LLVM-имя —
        // буквально "ф.имя" самой копии (уже манглированное, не нужно
        // манглировать ещё раз через llvm_имя_функции — та функция для
        // ДРУГОГО случая, разрешения коллизий между модулями, здесь не
        // применимо).
        for (_, инстанциированная_функция) in инстанциированные_обобщённые_функции {
            self.объявить_сигнатуру_функции(инстанциированная_функция, &инстанциированная_функция.имя)?;
        }

        // НОВОЕ: внешние функции (FFI) — объявляем их LLVM-сигнатуры БЕЗ
        // тела (LLVM трактует функцию без тела как "внешнюю" — declaration,
        // не definition; линковщик найдёт настоящую реализацию в
        // C-библиотеке при сборке). LLVM-имя — ВСЕГДА буквальное (не через
        // llvm_имя_функции/манглирование), должно точно совпадать с именем
        // символа в библиотеке.
        for узел in программа {
            if let ВерхнийУзел::ВнешняяФункция(вф) = узел {
                self.объявить_сигнатуру_внешней_функции(вф)?;
            }
        }

        // Аналогично — сигнатуры методов, отдельным проходом до генерации
        // каких-либо тел, чтобы методы могли вызывать друг друга и другие
        // функции независимо от порядка объявления в файле.
        for узел in программа {
            if let ВерхнийУзел::Структура(структура_узел) = узел {
                // Обобщённая структура ("структура Коробка<тип> {...}") —
                // это ШАБЛОН, не настоящая структура — self.структуры НЕ
                // содержит буквальное "Коробка" (только манглированные
                // инстанциации вроде "Коробка__целое") — попытка обработать
                // шаблон здесь напрямую упала бы с "структура не зарегистрирована".
                // Методы каждой инстанциации обрабатываются ОТДЕЛЬНО, новым
                // циклом ниже, по манглированному имени.
                if !структура_узел.обобщённые_параметры.is_empty() {
                    continue;
                }
                for метод in &структура_узел.методы {
                    self.объявить_сигнатуру_метода(&структура_узел.имя, метод)?;
                }
            }
        }

        // НОВОЕ (настоящий полиморфизм через контракты): генерируем
        // vtable для каждой пары (структура, контракт), которую структура
        // заявляет реализующей — ровно один раз, сразу после того, как
        // ВСЕ сигнатуры методов уже объявлены (сами тела функций ещё не
        // сгенерированы, но нам и не нужны — для vtable достаточно
        // адресов объявленных функций, LLVM разрешит их окончательно на
        // этапе линковки, как forward-reference).
        //
        // "имя контракта -> список имён его методов, В ПОРЯДКЕ ОБЪЯВЛЕНИЯ"
        // (self.контракты_методы) уже заполнен самым первым шагом этой
        // функции — этот порядок и определяет расположение указателей в
        // итоговой таблице (индекс метода в vtable должен совпадать у
        // ЛЮБОЙ структуры, реализующей этот контракт, иначе динамический
        // вызов обратится не к тому методу).
        let байт_указатель = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default());

        for узел in программа {
            if let ВерхнийУзел::Структура(структура_узел) = узел {
                if !структура_узел.обобщённые_параметры.is_empty() {
                    continue;
                }
                for имя_контракта in &структура_узел.контракты {
                    let имена_методов = self.контракты_методы.get(имя_контракта).cloned().ok_or_else(|| {
                        ошибка(format!(
                            "внутренняя ошибка: контракт '{}' не найден при генерации vtable для структуры '{}'",
                            имя_контракта, структура_узел.имя
                        ))
                    })?;

                    let указатели_на_методы: Result<Vec<_>, ОшибкаКодогенерации> = имена_методов
                        .iter()
                        .map(|сигнатура| {
                            let имя_метода = &сигнатура.имя;
                            let llvm_имя = Self::имя_llvm_метода(&структура_узел.имя, имя_метода);
                            let llvm_функция = self.модуль.get_function(&llvm_имя).ok_or_else(|| {
                                ошибка(format!(
                                    "внутренняя ошибка: метод '{}' структуры '{}' (для vtable контракта '{}') не был объявлен",
                                    имя_метода, структура_узел.имя, имя_контракта
                                ))
                            })?;
                            let указатель = llvm_функция.as_global_value().as_pointer_value();
                            // Все элементы vtable должны быть ОДНОГО LLVM-типа
                            // (i8*) — реальные сигнатуры методов отличаются
                            // (разные параметры/возврат), приводим к общему,
                            // непрозрачному виду; на этапе вызова (см.
                            // сгенерировать_вызов_метода) приведём обратно к
                            // нужному, конкретному типу функции перед indirect
                            // call. ⚠️ const_cast, НЕ build_pointer_cast — это
                            // значение идёт в ИНИЦИАЛИЗАТОР глобальной
                            // переменной, там нужна КОНСТАНТА, а
                            // build_pointer_cast создаёт обычную инструкцию,
                            // которая физически не может существовать вне
                            // тела какой-либо функции.
                            Ok(указатель.const_cast(байт_указатель))
                        })
                        .collect();
                    let указатели_на_методы = указатели_на_методы?;

                    let тип_vtable = байт_указатель.array_type(указатели_на_методы.len() as u32);
                    let имя_глобальной = format!("vtable__{}__{}", структура_узел.имя, имя_контракта);
                    let глобальная = self.модуль.add_global(тип_vtable, None, &имя_глобальной);
                    глобальная.set_constant(true);
                    глобальная.set_initializer(&байт_указатель.const_array(&указатели_на_методы));

                    self.vtables.insert((структура_узел.имя.clone(), имя_контракта.clone()), глобальная);
                }
            }
        }

        // НОВОЕ: методы обобщённых структур — уже полностью мономорфизированы
        // семантикой (манглированное имя, подставленные типы параметров/
        // возврата/тела) — обрабатываем их той же самой инфраструктурой,
        // что и методы обычных структур, просто источник данных другой
        // (не программа напрямую, а отдельная таблица инстанциаций).
        for (манглированное_имя, инстанциированная_структура) in инстанциированные_обобщённые_структуры {
            for метод in &инстанциированная_структура.методы {
                self.объявить_сигнатуру_метода(манглированное_имя, метод)?;
            }
        }

        // Затем генерируем тела функций и методов.
        for (узел, модуль) in программа.iter().zip(модуль_каждого_узла.iter()) {
            match узел {
                ВерхнийУзел::Функция(ф) => {
                    // НОВОЕ (обобщённые функции): та же самая проверка, что
                    // уже применяется к обобщённым структурам чуть ниже —
                    // у ШАБЛОНА (с параметром типа, без конкретного
                    // значения) нет настоящей LLVM-функции для генерации
                    // тела вообще (объявить_сигнатуру_функции его тоже
                    // пропустила) — реальные тела генерируются отдельным
                    // циклом ниже, для каждой уже мономорфизированной
                    // семантикой инстанциации.
                    if !ф.обобщённые_параметры.is_empty() {
                        continue;
                    }
                    let llvm_имя = llvm_имя_функции(self, &ф.имя, модуль);
                    self.сгенерировать_тело_функции(ф, &llvm_имя)?;
                }
                ВерхнийУзел::Подключение(_) => {
                    // TODO: подключение модулей — пока не влияет на кодогенерацию,
                    // модульная система будет реализована отдельно
                }
                ВерхнийУзел::Структура(структура_узел) => {
                    // То же самое ограничение, что и выше — обобщённый
                    // шаблон обрабатывается отдельным циклом ниже.
                    if !структура_узел.обобщённые_параметры.is_empty() {
                        continue;
                    }
                    // Сам LLVM struct-тип уже зарегистрирован заранее, в конструкторе
                    // Кодогенератора (см. зарегистрировать_структуры) — здесь остаётся
                    // сгенерировать только тела методов, если они есть.
                    for метод in &структура_узел.методы {
                        self.сгенерировать_тело_метода(&структура_узел.имя, метод)?;
                    }
                }
                // Контракт не порождает никакого кода сам по себе — v1
                // это чисто семантическая проверка (структура реализует
                // требуемые методы), без настоящего полиморфизма, значит
                // кодогенератору здесь просто нечего делать.
                ВерхнийУзел::Контракт(_) => {}
                // У внешней функции тоже нет тела для генерации — её
                // СИГНАТУРА уже объявлена раньше (см. первый проход ниже,
                // объявить_сигнатуру_внешней_функции) БЕЗ тела — LLVM
                // трактует функцию без тела как "внешнюю" (declaration,
                // не definition) — реализация придёт при ЛИНКОВКЕ, из
                // настоящей C-библиотеки.
                ВерхнийУзел::ВнешняяФункция(_) => {}
            }
        }

        // НОВОЕ: тела методов каждой инстанциации обобщённой структуры —
        // тот же принцип, что и в проходе сигнатур выше.
        //
        // ⚠️ КРИТИЧНО (см. подробное объяснение в semantic.rs у поля
        // решения_присваиваний_обобщённых_структур): self.решения_присваиваний
        // — ОБЩИЙ итератор, который должен строго соответствовать порядку
        // встречи операторов присваивания ИМЕННО В ЭТОМ, ОСНОВНОМ потоке
        // генерации программы. Решения методов обобщённых структур были
        // изолированы семантикой в ОТДЕЛЬНЫЙ список именно для того, чтобы
        // не рассинхронизировать этот общий поток — здесь ВРЕМЕННО подменяем
        // общий итератор на итератор ИЗ ЭТОГО ОТДЕЛЬНОГО списка перед
        // генерацией каждой инстанциации, и восстанавливаем обратно после.
        for (манглированное_имя, инстанциированная_структура) in инстанциированные_обобщённые_структуры {
            let решения_этой_структуры = решения_присваиваний_обобщённых_структур
                .get(манглированное_имя)
                .cloned()
                .unwrap_or_default();
            let сохранённые_решения = std::mem::replace(
                &mut self.решения_присваиваний,
                решения_этой_структуры.into_iter(),
            );

            for метод in &инстанциированная_структура.методы {
                self.сгенерировать_тело_метода(манглированное_имя, метод)?;
            }

            self.решения_присваиваний = сохранённые_решения;
        }

        // НОВОЕ (обобщённые функции): та же самая изоляция решений
        // присваиваний, что и у обобщённых структур чуть выше — подробное
        // объяснение найденного архитектурного бага там же.
        for (манглированное_имя, инстанциированная_функция) in инстанциированные_обобщённые_функции {
            let решения_этой_функции = решения_присваиваний_обобщённых_функций
                .get(манглированное_имя)
                .cloned()
                .unwrap_or_default();
            let сохранённые_решения = std::mem::replace(
                &mut self.решения_присваиваний,
                решения_этой_функции.into_iter(),
            );

            self.сгенерировать_тело_функции(инстанциированная_функция, манглированное_имя)?;

            self.решения_присваиваний = сохранённые_решения;
        }

        // Точка входа операционной системы называется "main" по универсальной
        // договорённости C/C++/большинства нативно компилируемых языков — она
        // никак не связана с тем, как называется точка входа В НАШЕМ языке
        // ("главная"). Значит, нужно сгенерировать настоящую C-функцию main,
        // которая просто вызывает нашу "главная" и возвращает её результат.
        // Без этого линковщик не находит, откуда операционной системе начинать
        // выполнение программы (именно это и была последняя ошибка сборки).
        //
        // В библиотечном режиме этот шаг пропускается целиком — у библиотеки
        // нет и не должно быть точки входа, она не запускается сама по себе.
        if !библиотечный_режим {
            self.сгенерировать_обёртку_main(программа, android_so)?;
        }

        Ok(())
    }

    /// Генерирует настоящую C-совместимую функцию `main`, вызывающую
    /// пользовательскую "главная". Если "главная" отсутствует в программе —
    /// возвращает понятную ошибку вместо непонятного сбоя линковщика.
    fn сгенерировать_обёртку_main(&mut self, программа: &Программа, android_so: bool) -> Result<(), ОшибкаКодогенерации> {
        let функция_главная = программа.iter().find_map(|узел| match узел {
            ВерхнийУзел::Функция(ф) if ф.имя == "главная" => Some(ф),
            _ => None,
        });

        let ф = функция_главная.ok_or_else(|| {
            ошибка("в программе нет функции 'главная' — компилятору некуда поместить точку входа")
        })?;

        if !ф.параметры.is_empty() {
            return Err(ошибка(
                "функция 'главная' пока не может принимать параметры напрямую — используй \
                 отдельную функцию 'аргументы_командной_строки() -> Список<текст>', доступную \
                 из любого места программы (не только из 'главная')",
            ));
        }

        let llvm_главная = self
            .модуль
            .get_function("главная")
            .ok_or_else(|| ошибка("внутренняя ошибка: функция 'главная' не была объявлена заранее"))?;

        // main принимает argc/argv по стандартной C-сигнатуре ОС — даже
        // если сама "главная" в языке "Сфера" их не принимает напрямую
        // (см. проверку выше), эти значения нужно ПОЙМАТЬ здесь, на самом
        // старте программы, чтобы потом сохранить их в глобальные переменные
        // (см. объявить_глобальные_argc_argv) — иначе "аргументы_командной_
        // строки()", вызванная из любого места программы позже, не будет
        // знать, откуда их взять.
        let i32_тип = self.контекст.i32_type();
        let текст_указатель = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default());
        let указатель_на_текст_указатель = текст_указатель.ptr_type(inkwell::AddressSpace::default());
        let тип_main = i32_тип.fn_type(&[i32_тип.into(), указатель_на_текст_указатель.into()], false);
        // НОВОЕ: для Android/SDL2 точка входа обязана называться "SDL_main"
        // (не "main") — готовая, официальная Java-обвязка SDL2 сама ищет
        // именно это имя внутри подключаемой библиотеки через dlsym(), см.
        // подробности в ИСТОРИЯ_РАЗРАБОТКИ.md. Сигнатура (int argc, char**
        // argv) остаётся той же самой — меняется только имя символа.
        let имя_функции_входа = if android_so { "SDL_main" } else { "main" };
        let main_функция = self.модуль.add_function(имя_функции_входа, тип_main, None);

        let блок = self.контекст.append_basic_block(main_функция, "вход");
        self.билдер.position_at_end(блок);

        let параметр_argc = main_функция
            .get_nth_param(0)
            .ok_or_else(|| ошибка("внутренняя ошибка: у main нет параметра argc"))?;
        let параметр_argv = main_функция
            .get_nth_param(1)
            .ok_or_else(|| ошибка("внутренняя ошибка: у main нет параметра argv"))?;

        let глобальный_argc = self
            .модуль
            .get_global("глобальный_argc")
            .ok_or_else(|| ошибка("внутренняя ошибка: глобальный_argc не была объявлена"))?;
        let глобальный_argv = self
            .модуль
            .get_global("глобальный_argv")
            .ok_or_else(|| ошибка("внутренняя ошибка: глобальный_argv не была объявлена"))?;
        self.билдер
            .build_store(глобальный_argc.as_pointer_value(), параметр_argc)
            .map_err(|e| ошибка(format!("ошибка сохранения argc: {:?}", e)))?;
        self.билдер
            .build_store(глобальный_argv.as_pointer_value(), параметр_argv)
            .map_err(|e| ошибка(format!("ошибка сохранения argv: {:?}", e)))?;

        let результат = self
            .билдер
            .build_call(llvm_главная, &[], "результат_главной")
            .map_err(|e| ошибка(format!("ошибка вызова 'главная' из обёртки main: {:?}", e)))?;

        // "главная" в языке "Сфера" объявлена как -> целое (i64), а C-совместимая
        // main должна возвращать i32 — приводим результат к нужной разрядности.
        // Если "главная" когда-нибудь будет объявлена без возвращаемого значения
        // (void) — этот код потребует доработки (см. TODO ниже).
        match результат.try_as_basic_value().left() {
            Some(значение) if ф.тип_возврата.is_some() => {
                // build_int_cast (а не build_int_truncate) специально — он сам
                // разбирается, нужно ли расширять или сужать разрядность, и не
                // падает, если "главная" в будущем будет объявлена, например,
                // как "-> целое32" (уже 32 бита, без необходимости сужения).
                let код_возврата = self
                    .билдер
                    .build_int_cast(значение.into_int_value(), i32_тип, "код_возврата")
                    .map_err(|e| ошибка(format!("ошибка приведения кода возврата: {:?}", e)))?;
                self.билдер
                    .build_return(Some(&код_возврата))
                    .map_err(|e| ошибка(format!("ошибка генерации возврата из main: {:?}", e)))?;
            }
            _ => {
                // "главная" ничего не вернула (void) — main просто возвращает 0.
                // TODO: пока это единственный обработанный случай для void-главной;
                // формально его стоит выделить явной веткой, если появятся другие
                // варианты (например, "главная" через результат<целое>).
                self.билдер
                    .build_return(Some(&i32_тип.const_int(0, false)))
                    .map_err(|e| ошибка(format!("ошибка генерации возврата из main: {:?}", e)))?;
            }
        }

        Ok(())
    }

    /// Отдать наружу готовый LLVM-модуль (например, чтобы записать .ll файл или
    /// передать дальше в JIT/AOT-компиляцию).
    pub fn модуль(&self) -> &Module<'ctx> {
        &self.модуль
    }

    /// Компилирует модуль в НАСТОЯЩИЙ машинный код (объектный файл .o)
    /// напрямую через LLVM API — вместо того, чтобы полагаться на внешнюю
    /// команду `clang`, которая заново читала бы текстовый .ll файл и сама
    /// его компилировала. Это стандартная, широко задокументированная схема
    /// работы с `inkwell` (используется практически в любом руководстве по
    /// написанию компилятора на его основе) — в отличие от некоторых более
    /// самобытных техник в других частях этого файла, риск здесь ниже.
    ///
    /// Линковка (сборка объектного файла + системных библиотек в готовый
    /// исполняемый файл) — это ОТДЕЛЬНАЯ задача, требующая платформенно-
    /// специфичного линковщика. LLVM поставляется со своим (`lld`), но
    /// подключить его напрямую из нашего кода потребовало бы сырых FFI-
    /// биндингов (в `inkwell` нет готовой обёртки для lld) — отдельный,
    /// больший проект. Поэтому внешний `clang` пока остаётся, но уже только
    /// для финальной линковки уже готового .o файла — не для компиляции.
    /// НОВОЕ: "целевая_платформа" — если указана (тройка вида
    /// "aarch64-linux-gnu"), компилируем НЕ под ту архитектуру, на которой
    /// запущен сам компилятор ("родную"), а под указанную явно. Раньше
    /// этот выбор был жёстко зашит — Target::initialize_native берёт ТОЛЬКО
    /// родную платформу. Возможность генерировать код под любую другую
    /// архитектуру УЖЕ полностью присутствовала внутри LLVM (мы и так на
    /// него полагаемся для всей кодогенерации) — не хватало только явного
    /// способа её запросить, никакой другой логики компилятора это не
    /// затрагивает (весь путь от исходного кода до LLVM IR полностью
    /// architecture-independent, архитектура появляется только здесь,
    /// на самом последнем шаге).
    pub fn записать_объектный_файл(&self, путь: &std::path::Path, целевая_платформа: Option<&str>) -> Result<(), ОшибкаКодогенерации> {
        use inkwell::targets::{CodeModel, FileType, InitializationConfig, RelocMode, Target, TargetMachine};

        let (triple, cpu, features) = match целевая_платформа {
            Some(тройка) => {
                // Инициализируем ВСЕ платформы, которые умеет LLVM (не
                // только родную) — при кросс-компиляции заранее не знаем,
                // какая именно понадобится.
                Target::initialize_all(&InitializationConfig::default());
                let triple = inkwell::targets::TargetTriple::create(тройка);
                // "generic" CPU и пустые "features" — безопасный выбор при
                // кросс-компиляции: get_host_cpu_name/get_host_cpu_features
                // дали бы характеристики ЭТОЙ (родной) машины, а не целевой
                // — в корне неверно для другой архитектуры. LLVM сам
                // подберёт разумные настройки по умолчанию для указанной
                // платформы, раз более точные не заданы явно.
                (triple, "generic".to_string(), String::new())
            }
            None => {
                Target::initialize_native(&InitializationConfig::default())
                    .map_err(|e| ошибка(format!("не удалось инициализировать целевую платформу LLVM: {}", e)))?;
                let triple = TargetMachine::get_default_triple();
                let cpu = TargetMachine::get_host_cpu_name().to_string();
                let features = TargetMachine::get_host_cpu_features().to_string();
                (triple, cpu, features)
            }
        };

        let target = Target::from_triple(&triple)
            .map_err(|e| ошибка(format!("не удалось определить целевую платформу '{}': {:?}", triple.as_str().to_string_lossy(), e)))?;

        let target_machine = target
            .create_target_machine(
                &triple,
                &cpu,
                &features,
                inkwell::OptimizationLevel::None,
                RelocMode::Default,
                CodeModel::Default,
            )
            .ok_or_else(|| ошибка(format!("не удалось создать TargetMachine для платформы '{}'", triple.as_str().to_string_lossy())))?;

        target_machine
            .write_to_file(&self.модуль, FileType::Object, путь)
            .map_err(|e| ошибка(format!("ошибка записи объектного файла: {}", e)))?;

        Ok(())
    }

    // ================== Типы: наши -> LLVM ==================

    fn тип_в_llvm(&mut self, тип: &Тип) -> Result<BasicTypeEnum<'ctx>, ОшибкаКодогенерации> {
        match тип {
            Тип::Целое | Тип::Целое64 => Ok(self.контекст.i64_type().into()),
            Тип::Целое32 | Тип::Беззнак32 => Ok(self.контекст.i32_type().into()),
            Тип::Целое16 | Тип::Беззнак16 => Ok(self.контекст.i16_type().into()),
            Тип::Целое8 | Тип::Беззнак8 => Ok(self.контекст.i8_type().into()),
            Тип::Беззнак64 => Ok(self.контекст.i64_type().into()),
            Тип::Дробное | Тип::Дробное64 => Ok(self.контекст.f64_type().into()),
            Тип::Дробное32 => Ok(self.контекст.f32_type().into()),
            Тип::Верно => Ok(self.контекст.bool_type().into()),
            Тип::Текст => {
                // Пока представляем текст как указатель на i8 (в духе C-строки).
                // Полноценная строка (с длиной, ARC-заголовком) — задача следующего этапа,
                // когда дойдём до реализации ARC на уровне кодогенерации.
                Ok(self
                    .контекст
                    .i8_type()
                    .ptr_type(inkwell::AddressSpace::default())
                    .into())
            }
            Тип::Пользовательский(имя) => {
                // НОВОЕ (настоящий полиморфизм через контракты): на
                // синтаксическом уровне нет различия между именем структуры
                // и именем контракта (оба — просто идентификатор с
                // заглавной буквы) — значит "Печатаемый х" (тип параметра/
                // переменной) сначала попадает сюда как Тип::Пользовательский,
                // и только здесь можно различить, что это на самом деле
                // контракт, а не структура. LLVM-представление — тот же
                // "толстый указатель" { данные: i8*, vtable: i8* }, что и
                // при упаковке (см. РазрешённоеПрисваивание::НовоеОбъявление).
                if self.контракты_методы.contains_key(имя) {
                    let байт_указатель = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default());
                    return Ok(self.контекст.struct_type(&[байт_указатель.into(), байт_указатель.into()], false).into());
                }
                let (llvm_struct, _) = self.структуры.get(имя).ok_or_else(|| {
                    ошибка(format!("неизвестная структура '{}' при генерации типа параметра/переменной", имя))
                })?;
                // Значения структур всегда представлены как УКАЗАТЕЛЬ на объект в куче
                // (см. обсуждение перед реализацией структур) — готовим почву для ARC.
                Ok(llvm_struct.ptr_type(inkwell::AddressSpace::default()).into())
            }
            Тип::Массив { элемент, размер: Some(n) } => {
                let llvm_элемент = self.тип_в_llvm(элемент)?;
                Ok(llvm_элемент.array_type(*n as u32).into())
            }
            Тип::Массив { размер: None, .. } => Err(ошибка(
                "массив без явно указанного размера ('тип[]') можно использовать только \
                 в объявлении переменной с литералом-инициализатором (тип[] имя = [1, 2, 3];) — \
                 здесь размер должен быть уже известен",
            )),
            Тип::Результат(внутренний) => {
                let llvm_внутренний = self.тип_в_llvm(внутренний)?;
                Ok(тип_результата_llvm(self.контекст, llvm_внутренний).into())
            }
            Тип::Канал(_) => Ok(self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default()).into()),
            Тип::Обобщённый { имя, параметры } if имя == "Список" && параметры.len() == 1 => {
                // ⚠️ БЫЛО СТРОГОЕ ЧТЕНИЕ (полагалось на предварительную
                // регистрацию через используемые_списки) — НАЙДЕННЫЙ ПРИ
                // РЕАЛЬНОМ ТЕСТИРОВАНИИ БАГ: используемые_списки собирается
                // ТОЛЬКО при явном обнаружении вызова "Список<T>()" — но
                // объявление вида "Список<текст> аргументы = функция();",
                // где справа вызывается СОВСЕМ ДРУГАЯ функция (не "Список"),
                // просто ВОЗВРАЩАЮЩАЯ Список<текст> — эта инстанциация
                // никогда не регистрировалась заранее. Теперь — ЛЕНИВОЕ
                // создание (получить_или_создать_тип_списка сама проверяет,
                // существует ли уже нужный тип, и создаёт при необходимости) —
                // устраняет весь класс таких ошибок, а не только этот
                // конкретный случай.
                //
                // НОВОЕ (Список<Контракт>): та же самая, уже несколько раз
                // встречавшаяся путаница — "РешённыйТип::from" не знает о
                // контрактах, безусловно превращает "Печатаемый" в обычную
                // Структура. Проверяем самостоятельно через
                // self.контракты_методы, доступную здесь (метод self).
                let тип_элемента_решённый = if let Тип::Пользовательский(имя_типа) = &параметры[0] {
                    if self.контракты_методы.contains_key(имя_типа) {
                        РешённыйТип::Контракт(имя_типа.clone())
                    } else {
                        РешённыйТип::from(&параметры[0])
                    }
                } else {
                    РешённыйТип::from(&параметры[0])
                };
                let llvm_struct = self.получить_или_создать_тип_списка(&тип_элемента_решённый)?;
                Ok(llvm_struct.ptr_type(inkwell::AddressSpace::default()).into())
            }
            Тип::Обобщённый { имя, параметры } if имя == "Словарь" && параметры.len() == 2 => {
                // Та же находка и то же исправление, что и у Список выше.
                let тип_ключа_решённый = РешённыйТип::from(&параметры[0]);
                let тип_значения_решённый = РешённыйТип::from(&параметры[1]);
                let llvm_struct = self.получить_или_создать_тип_словаря(&тип_ключа_решённый, &тип_значения_решённый)?;
                Ok(llvm_struct.ptr_type(inkwell::AddressSpace::default()).into())
            }
            other => Err(ошибка(format!(
                "тип {:?} пока не поддержан кодогенератором — реализовано только базовое подмножество",
                other
            ))),
        }
    }

    /// Если тип возврата функции — результат<T>, вычисляет LLVM-тип T
    /// (используется для "ошибка(...)" и "?" — см. поле текущий_ok_тип_llvm).
    /// Для любого другого типа возврата (или его отсутствия) — None.
    fn ok_тип_из_типа_возврата(&mut self, тип_возврата: &Option<Тип>) -> Result<Option<BasicTypeEnum<'ctx>>, ОшибкаКодогенерации> {
        match тип_возврата {
            Some(Тип::Результат(внутренний)) => Ok(Some(self.тип_в_llvm(внутренний)?)),
            _ => Ok(None),
        }
    }

    /// Определяет, что дополнительно нужно запомнить о переменной такого
    /// типа — что это структура (и какая) или массив (какого элемента и
    /// какого размера) — чтобы потом можно было корректно обратиться к
    /// её полям/элементам. См. комментарий у ДополнительнаяИнформация.
    fn дополнительная_информация_из_ast_типа(&mut self, тип: &Тип) -> Result<ДополнительнаяИнформация<'ctx>, ОшибкаКодогенерации> {
        match тип {
            Тип::Пользовательский(имя) => {
                // НОВОЕ (настоящий полиморфизм через контракты): та же
                // самая, уже несколько раз встречавшаяся путаница —
                // "Печатаемый" на уровне AST неотличимо от имени структуры,
                // различать нужно по факту регистрации в контракты_методы.
                if self.контракты_методы.contains_key(имя) {
                    Ok(ДополнительнаяИнформация::Контракт(имя.clone()))
                } else {
                    Ok(ДополнительнаяИнформация::Структура(имя.clone()))
                }
            }
            Тип::Массив { элемент, размер: Some(n) } => {
                let llvm_элемент = self.тип_в_llvm(элемент)?;
                Ok(ДополнительнаяИнформация::Массив { элемент: llvm_элемент, размер: *n as u32 })
            }
            Тип::Массив { размер: None, .. } => Err(ошибка(
                "внутренняя ошибка: размер массива должен быть уже известен на этом этапе \
                 (см. решить_тип_объявления в semantic.rs — размер выводится там)",
            )),
            Тип::Результат(внутренний) => {
                let имя_структуры_значения = match внутренний.as_ref() {
                    Тип::Пользовательский(имя) => Some(имя.clone()),
                    _ => None,
                };
                Ok(ДополнительнаяИнформация::Результат { имя_структуры_значения })
            }
            Тип::Канал(внутренний) => {
                let llvm_элемент = self.тип_в_llvm(внутренний)?;
                Ok(ДополнительнаяИнформация::Канал { элемент: llvm_элемент })
            }
            Тип::Обобщённый { имя, параметры } if имя == "Список" && параметры.len() == 1 => {
                // НОВОЕ (Список<Контракт>): та же самая, уже несколько раз
                // встречавшаяся путаница, что и выше (строки 1495-1503) —
                // "РешённыйТип::from" сама по себе (свободная функция) не
                // знает о контрактах, безусловно превращает
                // "Тип::Пользовательский" в "РешённыйТип::Структура".
                // Проверяем самостоятельно, тем же способом, что уже
                // применяется в этой же функции чуть выше.
                let тип_элемента_решённый = if let Тип::Пользовательский(имя_типа) = &параметры[0] {
                    if self.контракты_методы.contains_key(имя_типа) {
                        РешённыйТип::Контракт(имя_типа.clone())
                    } else {
                        РешённыйТип::from(&параметры[0])
                    }
                } else {
                    РешённыйТип::from(&параметры[0])
                };
                let ключ = ключ_типа_списка(&тип_элемента_решённый);
                let llvm_элемент = self.тип_в_llvm(&параметры[0])?;
                let имя_структуры_элемента = match &тип_элемента_решённый {
                    РешённыйТип::Структура(имя_структуры) => Some(имя_структуры.clone()),
                    _ => None,
                };
                let имя_контракта_элемента = match &тип_элемента_решённый {
                    РешённыйТип::Контракт(имя_контракта) => Some(имя_контракта.clone()),
                    _ => None,
                };
                Ok(ДополнительнаяИнформация::Список { ключ, элемент: llvm_элемент, имя_структуры_элемента, имя_контракта_элемента })
            }
            Тип::Обобщённый { имя, параметры } if имя == "Словарь" && параметры.len() == 2 => {
                let тип_ключа_решённый = РешённыйТип::from(&параметры[0]);
                let тип_значения_решённый = РешённыйТип::from(&параметры[1]);
                let ключ = ключ_типа_словаря(&тип_ключа_решённый, &тип_значения_решённый);
                let llvm_тип_ключа = self.тип_в_llvm(&параметры[0])?;
                let llvm_тип_значения = self.тип_в_llvm(&параметры[1])?;
                let имя_структуры_значения = match &тип_значения_решённый {
                    РешённыйТип::Структура(имя_структуры) => Some(имя_структуры.clone()),
                    _ => None,
                };
                Ok(ДополнительнаяИнформация::Словарь {
                    ключ,
                    тип_ключа: llvm_тип_ключа,
                    тип_значения: llvm_тип_значения,
                    имя_структуры_значения,
                })
            }
            _ => Ok(ДополнительнаяИнформация::Нет),
        }
    }

    // ================== Функции ==================

    fn объявить_сигнатуру_функции(&mut self, ф: &ОбъявлениеФункции, llvm_имя: &str) -> Result<(), ОшибкаКодогенерации> {
        // НОВОЕ (обобщённые функции): сам ШАБЛОН (с параметром типа, без
        // конкретного значения) не может иметь настоящую LLVM-сигнатуру —
        // у него, например, нет конкретного LLVM-типа для параметра "Т".
        // Реальные, конкретные сигнатуры объявляются ОТДЕЛЬНЫМ проходом,
        // для каждой уже мономорфизированной семантикой инстанциации (см.
        // цикл по инстанциированные_обобщённые_функции в
        // сгенерировать_программу) — здесь просто пропускаем шаблон,
        // не считаем это ошибкой (та же логика уже применяется к шаблонам
        // обобщённых структур).
        if !ф.обобщённые_параметры.is_empty() {
            return Ok(());
        }

        // НОВОЕ (настоящий полиморфизм через контракты): запоминаем
        // AST-типы параметров ПО ИМЕНИ ФУНКЦИИ — нужно при генерации
        // обычного вызова этой функции, чтобы узнать, какой параметр
        // ожидает тип-контракт (см. параметры_функций, комментарий там же).
        self.параметры_функций.insert(ф.имя.clone(), ф.параметры.iter().map(|п| п.тип.clone()).collect());

        let типы_параметров: Result<Vec<BasicTypeEnum>, ОшибкаКодогенерации> = ф
            .параметры
            .iter()
            .map(|п| self.тип_в_llvm(&п.тип))
            .collect();
        let типы_параметров = типы_параметров?;

        let llvm_типы_параметров: Vec<inkwell::types::BasicMetadataTypeEnum> = типы_параметров.iter().map(|т| (*т).into()).collect();

        let тип_функции = match &ф.тип_возврата {
            Some(тип) => {
                let возвращаемый = self.тип_в_llvm(тип)?;
                возвращаемый.fn_type(&llvm_типы_параметров, false)
            }
            None => self.контекст.void_type().fn_type(&llvm_типы_параметров, false),
        };

        // ⚠️ ИЗМЕНЕНО В v2 (разрешение коллизий имён между модулями):
        // раньше здесь ВСЕГДА использовалось буквальное "ф.имя" — теперь
        // используется "llvm_имя", вычисленное вызывающим кодом (см.
        // сгенерировать_программу) — для функций главного файла оно
        // совпадает с буквальным именем (без изменений), а для функций
        // из подключённых модулей — это ВСЕГДА манглированное имя
        // ("модуль__имя"), единообразно, независимо от того, коллизирует
        // ли оно с чем-то ещё (тот же принцип единообразного манглирования,
        // что уже применён для инстанциаций обобщённых структур).
        self.модуль.add_function(llvm_имя, тип_функции, None);
        Ok(())
    }

    /// Объявляет LLVM-сигнатуру для "внешняя функция ...;" (FFI) — БЕЗ
    /// тела и БЕЗ манглирования (в отличие от обычных функций, см.
    /// объявить_сигнатуру_функции) — LLVM-имя ВСЕГДА буквальное, должно
    /// точно совпадать с именем символа в C-библиотеке. Функция без тела
    /// в LLVM — это "declaration" (объявление без определения); линковщик
    /// сам найдёт настоящую реализацию в библиотеке при сборке (см.
    /// main.rs, флаг "--линковать").
    fn объявить_сигнатуру_внешней_функции(&mut self, вф: &ОбъявлениеВнешнейФункции) -> Result<(), ОшибкаКодогенерации> {
        let типы_параметров: Result<Vec<BasicTypeEnum>, ОшибкаКодогенерации> = вф
            .параметры
            .iter()
            .map(|п| self.тип_в_llvm(&п.тип))
            .collect();
        let типы_параметров = типы_параметров?;
        let llvm_типы_параметров: Vec<inkwell::types::BasicMetadataTypeEnum> = типы_параметров.iter().map(|т| (*т).into()).collect();

        let тип_функции = match &вф.тип_возврата {
            Some(тип) => {
                let возвращаемый = self.тип_в_llvm(тип)?;
                возвращаемый.fn_type(&llvm_типы_параметров, false)
            }
            None => self.контекст.void_type().fn_type(&llvm_типы_параметров, false),
        };

        // НОВОЕ: "как "SDL_Init"" — если задано реальное имя символа
        // библиотеки, LLVM-функция объявляется под НИМ (обязательное
        // требование линковщика — иначе не найдёт настоящую реализацию
        // в C-библиотеке), а не под русским именем, использованным в коде.
        let llvm_имя = вф.реальное_имя.as_deref().unwrap_or(&вф.имя);
        self.модуль.add_function(llvm_имя, тип_функции, None);
        Ok(())
    }

    fn сгенерировать_тело_функции(&mut self, ф: &ОбъявлениеФункции, llvm_имя: &str) -> Result<(), ОшибкаКодогенерации> {
        let llvm_функция = self
            .модуль
            .get_function(llvm_имя)
            .ok_or_else(|| ошибка(format!("внутренняя ошибка: функция '{}' не была объявлена заранее", ф.имя)))?;

        let блок_входа = self.контекст.append_basic_block(llvm_функция, "вход");
        self.билдер.position_at_end(блок_входа);

        // Новая функция — новая, чистая таблица переменных.
        self.переменные.clear();
        self.неизменные.clear();
        self.текущая_функция = Some(llvm_функция);
        self.текущий_ok_тип_llvm = self.ok_тип_из_типа_возврата(&ф.тип_возврата)?;
        // Один фрейм для верхнего уровня тела функции — вложенные блоки будут
        // добавлять свои фреймы поверх по мере генерации (см. сгенерировать_если
        // и другие места, переключающие вход/выход из вложенных блоков).
        self.стек_arc_областей = vec![Vec::new()];
        self.стек_arc_областей_текста = vec![Vec::new()];

        // Параметры функции: заводим под них локальные ячейки в стеке (alloca),
        // чтобы с ними можно было обращаться единообразно с обычными переменными.
        for (индекс, параметр) in ф.параметры.iter().enumerate() {
            let llvm_параметр = llvm_функция
                .get_nth_param(индекс as u32)
                .ok_or_else(|| ошибка(format!("не удалось получить параметр №{} функции '{}'", индекс, ф.имя)))?;

            let llvm_тип = self.тип_в_llvm(&параметр.тип)?;
            let указатель = self
                .билдер
                .build_alloca(llvm_тип, &параметр.имя)
                .map_err(|e| ошибка(format!("ошибка выделения памяти для параметра '{}': {:?}", параметр.имя, e)))?;

            self.билдер
                .build_store(указатель, llvm_параметр)
                .map_err(|e| ошибка(format!("ошибка сохранения параметра '{}': {:?}", параметр.имя, e)))?;

            // ПАРАМЕТРЫ намеренно НЕ добавляются в стек_arc_областей —
            // мы их не ретейним при получении (см. документацию у захватить/отпустить),
            // значит и отпускать их при выходе из функции было бы несимметрично
            // и уменьшило бы чужой счётчик ссылок без нашего на то права.
            let доп_информация = self.дополнительная_информация_из_ast_типа(&параметр.тип)?;
            self.переменные.insert(параметр.имя.clone(), (указатель, llvm_тип, доп_информация));
        }

        self.сгенерировать_блок(&ф.тело, &llvm_функция)?;

        // Если функция void и явного "вернуть;" в конце не было — добавляем неявный возврат,
        // иначе LLVM откажется верифицировать блок без терминирующей инструкции.
        if ф.тип_возврата.is_none() && блок_не_завершён(&self.билдер) {
            self.освободить_при_возврате(None)?;
            self.билдер
                .build_return(None)
                .map_err(|e| ошибка(format!("ошибка генерации неявного возврата: {:?}", e)))?;
        }

        Ok(())
    }

    /// Генерирует уникальное LLVM-имя для метода структуры, чтобы избежать
    /// конфликтов между одноимёнными методами разных структур (например,
    /// у Пользователь и у Собака может быть метод "поздороваться" —
    /// как свободные функции они бы конфликтовали в одном модуле, но
    /// как методы разных структур это нормально и ожидаемо).
    fn имя_llvm_метода(имя_структуры: &str, имя_метода: &str) -> String {
        format!("{}__{}", имя_структуры, имя_метода)
    }

    /// Аналог объявить_сигнатуру_функции, но для метода структуры: добавляет
    /// неявный первый параметр "это" (указатель на структуру-владельца)
    /// перед обычными параметрами метода.
    fn объявить_сигнатуру_метода(&mut self, имя_структуры: &str, метод: &ОбъявлениеФункции) -> Result<(), ОшибкаКодогенерации> {
        if !метод.обобщённые_параметры.is_empty() {
            return Err(ошибка(format!(
                "метод '{}.{}': обобщённые методы (<тип>) пока не поддержаны кодогенератором",
                имя_структуры, метод.имя
            )));
        }

        let (llvm_struct, _) = self.структуры.get(имя_структуры).ok_or_else(|| {
            ошибка(format!("внутренняя ошибка: структура '{}' не зарегистрирована", имя_структуры))
        })?;
        let тип_это: BasicTypeEnum = llvm_struct.ptr_type(inkwell::AddressSpace::default()).into();

        let типы_параметров: Result<Vec<BasicTypeEnum>, ОшибкаКодогенерации> = метод
            .параметры
            .iter()
            .map(|п| self.тип_в_llvm(&п.тип))
            .collect();
        let типы_параметров = типы_параметров?;

        let mut llvm_типы_параметров: Vec<inkwell::types::BasicMetadataTypeEnum> = vec![тип_это.into()];
        llvm_типы_параметров.extend(типы_параметров.iter().map(|т| inkwell::types::BasicMetadataTypeEnum::from(*т)));

        let тип_функции = match &метод.тип_возврата {
            Some(тип) => {
                let возвращаемый = self.тип_в_llvm(тип)?;
                возвращаемый.fn_type(&llvm_типы_параметров, false)
            }
            None => self.контекст.void_type().fn_type(&llvm_типы_параметров, false),
        };

        let llvm_имя = Self::имя_llvm_метода(имя_структуры, &метод.имя);
        self.модуль.add_function(&llvm_имя, тип_функции, None);
        Ok(())
    }

    /// Аналог сгенерировать_тело_функции, но для метода: первый LLVM-параметр
    /// (индекс 0) — это неявное "это", остальные параметры метода сдвинуты
    /// на 1. "это" заводится в таблицу переменных так же, как обычная
    /// переменная-структура — благодаря этому "это.поле" внутри тела метода
    /// работает через тот же самый механизм, что и "юзер.поле" снаружи.
    fn сгенерировать_тело_метода(&mut self, имя_структуры: &str, метод: &ОбъявлениеФункции) -> Result<(), ОшибкаКодогенерации> {
        let llvm_имя = Self::имя_llvm_метода(имя_структуры, &метод.имя);
        let llvm_функция = self
            .модуль
            .get_function(&llvm_имя)
            .ok_or_else(|| ошибка(format!("внутренняя ошибка: метод '{}' не был объявлен заранее", llvm_имя)))?;

        let блок_входа = self.контекст.append_basic_block(llvm_функция, "вход");
        self.билдер.position_at_end(блок_входа);

        self.переменные.clear();
        self.неизменные.clear();
        self.текущая_функция = Some(llvm_функция);
        self.текущий_ok_тип_llvm = self.ok_тип_из_типа_возврата(&метод.тип_возврата)?;
        self.стек_arc_областей = vec![Vec::new()];
        self.стек_arc_областей_текста = vec![Vec::new()];

        // Параметр №0 — неявное "это".
        let llvm_это = llvm_функция
            .get_nth_param(0)
            .ok_or_else(|| ошибка(format!("внутренняя ошибка: у метода '{}' нет параметра 'это'", llvm_имя)))?;

        let (llvm_struct, _) = self.структуры.get(имя_структуры).ok_or_else(|| {
            ошибка(format!("внутренняя ошибка: структура '{}' не зарегистрирована", имя_структуры))
        })?;
        let тип_это: BasicTypeEnum = llvm_struct.ptr_type(inkwell::AddressSpace::default()).into();

        let указатель_это = self
            .билдер
            .build_alloca(тип_это, "это")
            .map_err(|e| ошибка(format!("ошибка выделения памяти для 'это': {:?}", e)))?;
        self.билдер
            .build_store(указатель_это, llvm_это)
            .map_err(|e| ошибка(format!("ошибка сохранения 'это': {:?}", e)))?;
        self.переменные.insert(
            "это".to_string(),
            (указатель_это, тип_это, ДополнительнаяИнформация::Структура(имя_структуры.to_string())),
        );

        // Остальные параметры метода — начиная с LLVM-индекса 1, потому что
        // индекс 0 занят неявным "это".
        for (индекс, параметр) in метод.параметры.iter().enumerate() {
            let llvm_параметр = llvm_функция
                .get_nth_param((индекс + 1) as u32)
                .ok_or_else(|| ошибка(format!("не удалось получить параметр №{} метода '{}'", индекс, llvm_имя)))?;

            let llvm_тип = self.тип_в_llvm(&параметр.тип)?;
            let указатель = self
                .билдер
                .build_alloca(llvm_тип, &параметр.имя)
                .map_err(|e| ошибка(format!("ошибка выделения памяти для параметра '{}': {:?}", параметр.имя, e)))?;

            self.билдер
                .build_store(указатель, llvm_параметр)
                .map_err(|e| ошибка(format!("ошибка сохранения параметра '{}': {:?}", параметр.имя, e)))?;

            let доп_информация_параметра = self.дополнительная_информация_из_ast_типа(&параметр.тип)?;
            self.переменные.insert(параметр.имя.clone(), (указатель, llvm_тип, доп_информация_параметра));
        }

        self.сгенерировать_блок(&метод.тело, &llvm_функция)?;

        if метод.тип_возврата.is_none() && блок_не_завершён(&self.билдер) {
            self.освободить_при_возврате(None)?;
            self.билдер
                .build_return(None)
                .map_err(|e| ошибка(format!("ошибка генерации неявного возврата: {:?}", e)))?;
        }

        Ok(())
    }

    fn сгенерировать_блок(&mut self, блок: &Блок, функция: &FunctionValue<'ctx>) -> Result<(), ОшибкаКодогенерации> {
        for оператор in блок {
            self.сгенерировать_оператор(оператор, функция)?;
        }
        Ok(())
    }

    // ================== Операторы ==================

    fn сгенерировать_оператор(
        &mut self,
        оператор: &Оператор,
        функция: &FunctionValue<'ctx>,
    ) -> Result<(), ОшибкаКодогенерации> {
        match оператор {
            Оператор::ОбъявлениеСТипом { тип, имя, значение } => {
                self.объявить_переменную(тип, имя, значение, false)
            }
            Оператор::ОбъявлениеНеизменное { тип, имя, значение } => {
                self.объявить_переменную(тип, имя, значение, true)
            }
            Оператор::Присваивание { место, значение } => {
                let решение = self.решения_присваиваний.next().ok_or_else(|| {
                    ошибка(
                        "внутренняя ошибка: закончились решения семантического анализатора \
                         раньше, чем ожидал кодогенератор — порядок обхода AST разошёлся \
                         между анализатором и кодогенератором",
                    )
                })?;

                match решение {
                    РазрешённоеПрисваивание::НовоеОбъявление { тип } => {
                        // Семантический анализатор гарантирует: НовоеОбъявление
                        // возможно только для МестоЗаписи::Имя (присваивание в
                        // поле структуры — всегда РазрешённоеПрисваивание::Присваивание,
                        // см. semantic.rs). Поэтому здесь безопасно ожидать именно Имя.
                        let МестоЗаписи::Имя(имя) = место else {
                            return Err(ошибка(
                                "внутренняя ошибка: НовоеОбъявление получено для не-простого места записи — \
                                 это нарушает гарантию семантического анализатора",
                            ));
                        };

                        let llvm_тип = решённый_тип_в_llvm(self.контекст, &тип, &self.структуры)?;

                        // НОВОЕ (настоящий полиморфизм через контракты):
                        // "ИмяКонтракта переменная = экземпляр_структуры;" —
                        // вместо обычного вычисления и прямой записи (ниже)
                        // нужно упаковать "толстый указатель" — { данные,
                        // vtable } — используя vtable, заранее
                        // сгенерированную для КОНКРЕТНОЙ пары (структура,
                        // этот контракт) в сгенерировать_программу.
                        if let РешённыйТип::Контракт(имя_контракта) = &тип {
                            let (указатель_на_данные, имя_структуры) = self.получить_структуру_из_выражения(значение)?;
                            let vtable = self
                                .vtables
                                .get(&(имя_структуры.clone(), имя_контракта.clone()))
                                .copied()
                                .ok_or_else(|| {
                                    ошибка(format!(
                                        "внутренняя ошибка: vtable для '{}' : '{}' не была сгенерирована заранее",
                                        имя_структуры, имя_контракта
                                    ))
                                })?;

                            let байт_указатель = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default());
                            let данные_как_i8 = self
                                .билдер
                                .build_pointer_cast(указатель_на_данные, байт_указатель, "данные_контракта")
                                .map_err(|e| ошибка(format!("ошибка приведения указателя данных для '{}': {:?}", имя, e)))?;
                            let vtable_как_i8 = self
                                .билдер
                                .build_pointer_cast(vtable.as_pointer_value(), байт_указатель, "vtable_контракта")
                                .map_err(|e| ошибка(format!("ошибка приведения указателя vtable для '{}': {:?}", имя, e)))?;

                            let толстый_указатель_тип = self.контекст.struct_type(&[байт_указатель.into(), байт_указатель.into()], false);
                            let mut толстый_указатель = толстый_указатель_тип.get_undef();
                            толстый_указатель = self
                                .билдер
                                .build_insert_value(толстый_указатель, данные_как_i8, 0, "вставить_данные")
                                .map_err(|e| ошибка(format!("ошибка сборки толстого указателя для '{}': {:?}", имя, e)))?
                                .into_struct_value();
                            толстый_указатель = self
                                .билдер
                                .build_insert_value(толстый_указатель, vtable_как_i8, 1, "вставить_vtable")
                                .map_err(|e| ошибка(format!("ошибка сборки толстого указателя для '{}': {:?}", имя, e)))?
                                .into_struct_value();

                            let указатель_переменной = self
                                .билдер
                                .build_alloca(llvm_тип, имя)
                                .map_err(|e| ошибка(format!("ошибка выделения памяти для '{}': {:?}", имя, e)))?;
                            self.билдер
                                .build_store(указатель_переменной, толстый_указатель)
                                .map_err(|e| ошибка(format!("ошибка инициализации '{}': {:?}", имя, e)))?;

                            self.переменные.insert(имя.clone(), (указатель_переменной, llvm_тип, ДополнительнаяИнформация::Контракт(имя_контракта.clone())));
                            self.неизменные.insert(имя.clone(), false);
                            return Ok(());
                        }

                        let вычисленное = self.сгенерировать_выражение(значение)?;

                        // ARC: тот же случай, что и в объявить_переменную —
                        // копирование существующей переменной-структуры в новую
                        // требует retain. См. подробный комментарий там же.
                        if let (РешённыйТип::Структура(имя_структуры), Выражение::Идентификатор(_)) = (&тип, значение) {
                            let (llvm_struct, _) = self
                                .структуры
                                .get(имя_структуры)
                                .ok_or_else(|| ошибка(format!("внутренняя ошибка: структура '{}' не найдена", имя_структуры)))?
                                .clone();
                            self.захватить(вычисленное.into_pointer_value(), llvm_struct)?;
                        }

                        let указатель = self
                            .билдер
                            .build_alloca(llvm_тип, имя)
                            .map_err(|e| ошибка(format!("ошибка выделения памяти для '{}': {:?}", имя, e)))?;
                        self.билдер
                            .build_store(указатель, вычисленное)
                            .map_err(|e| ошибка(format!("ошибка инициализации '{}': {:?}", имя, e)))?;

                        let доп_информация = дополнительная_информация_из_решённого_типа(self.контекст, &тип, &self.структуры)?;
                        self.переменные.insert(имя.clone(), (указатель, llvm_тип, доп_информация));
                        self.неизменные.insert(имя.clone(), false);

                        // ARC: регистрируем в ТЕКУЩЕМ (самом вложенном) фрейме
                        // стека областей видимости — см. комментарий у поля
                        // стек_arc_областей. Стек всегда непустой (минимум
                        // один фрейм для тела функции), поэтому last_mut()
                        // безопасен без дополнительной проверки.
                        if let РешённыйТип::Структура(имя_структуры) = &тип {
                            if let Some((llvm_struct, _)) = self.структуры.get(имя_структуры).cloned() {
                                if let Some(текущий_фрейм) = self.стек_arc_областей.last_mut() {
                                    текущий_фрейм.push((имя.clone(), имя_структуры.clone(), llvm_struct));
                                }
                            }
                        }

                        // НОВОЕ (текст под ARC): та же идея, что и выше для
                        // структур — если тип переменной "текст" И
                        // инициализирующее выражение реально ПОРОЖДАЕТ новый
                        // malloc'нутый буфер (не литерал, не параметр, не
                        // чтение поля/переменной — те "заимствуют" чужой
                        // текст, не владеют им) — запоминаем эту переменную
                        // как подлежащую освобождению при выходе из области
                        // видимости.
                        if тип == РешённыйТип::Текст {
                            let владеет_изначально = является_текст_порождающим(значение);
                            if владеет_изначально {
                                if let Some(текущий_фрейм_текста) = self.стек_arc_областей_текста.last_mut() {
                                    текущий_фрейм_текста.push(имя.clone());
                                }
                            }
                            // НОВОЕ (текст под ARC, закрытие пробела внутри
                            // циклов): см. подробное объяснение у
                            // получить_или_создать_флаг_владения и у
                            // аналогичного исправления в объявить_переменную
                            // — флаг заводится всегда, не только при
                            // изначально владеющем значении.
                            let флаг = self.получить_или_создать_флаг_владения(имя)?;
                            self.билдер
                                .build_store(флаг, self.контекст.bool_type().const_int(владеет_изначально as u64, false))
                                .map_err(|e| ошибка(format!("ошибка инициализации флага владения для '{}': {:?}", имя, e)))?;
                        }

                        // НОВОЕ (текст под ARC, продолжение): та же самая
                        // идея, но для "результат<текст> р = подстрока(...);"
                        // — значение ВНУТРИ обёртки результат<T> тоже может
                        // быть свежим malloc'нутым буфером. Переиспользуем
                        // тот же список отслеживания (не заводим отдельный
                        // параллельный стек — риск повторить недавно
                        // найденный double-free от забытого pop() в одном
                        // из мест push/pop слишком реален, проще опираться
                        // на уже проверенный механизм) — при освобождении
                        // (отпустить_список_текстовых_переменных) отличаем
                        // "голый текст" от "результат<текст>" по фактическому
                        // LLVM-типу переменной.
                        if тип == РешённыйТип::Результат(Box::new(РешённыйТип::Текст)) && является_результат_текст_порождающим(значение) {
                            if let Some(текущий_фрейм_текста) = self.стек_arc_областей_текста.last_mut() {
                                текущий_фрейм_текста.push(имя.clone());
                            }
                        }

                        Ok(())
                    }
                    РазрешённоеПрисваивание::Присваивание => {
                        let адрес = self.найти_адрес_места_записи(место)?;

                        // ⚠️ НАЙДЕНА И ИСПРАВЛЕНА РЕАЛЬНАЯ, СЕРЬЁЗНАЯ ОШИБКА
                        // (не просто утечка — настоящий use-after-free,
                        // обнаруженный valgrind на тесте вида
                        // "сообщение = регистр_в_верхний(сообщение);"):
                        // старая версия этого кода освобождала СТАРОЕ значение
                        // переменной ДО вычисления нового — но если новое
                        // значение само читает старое (функция, принимающая
                        // эту же переменную как аргумент, — ровно такой
                        // случай), чтение происходит уже ПОСЛЕ освобождения
                        // памяти. Исправление — простое, но принципиальное:
                        // сначала полностью ВЫЧИСЛИТЬ новое значение, и
                        // только ПОТОМ решать, что делать со старым.
                        let вычисленное = self.сгенерировать_выражение(значение)?;
                        let mut вычисленное = вычисленное;

                        // ⚠️ Текст под ARC, вторая часть — закрытие давно
                        // известного, честно названного пробела): раньше это
                        // касалось только НОВОГО объявления переменной
                        // ("текст имя = ...;") — обычное ПЕРЕПРИСВАИВАНИЕ уже
                        // существующей переменной ("имя = новое_значение;")
                        // вообще не освобождало старое значение, даже если
                        // оно было "владеющим" (созданным конкатенацией/
                        // регистр_в_верхний и т.д.) — тихий источник утечки
                        // при каждом повторном присваивании в цикле.
                        //
                        // Единственный надёжный способ отличить текстовую
                        // переменную от структуры на этом уровне —
                        // ДополнительнаяИнформация::Нет при указательном
                        // LLVM-типе: в нашем языке ЕДИНСТВЕННЫЙ "голый"
                        // указатель без какой-либо дополнительной
                        // информации — это именно "текст" (у структур,
                        // Список/Словарь, результат<T> — всегда есть своя,
                        // соответствующая ДополнительнаяИнформация).
                        if let МестоЗаписи::Имя(имя_переменной) = место {
                            let это_текстовая_переменная = self
                                .переменные
                                .get(имя_переменной)
                                .map(|(_, llvm_тип, доп_информация)| {
                                    llvm_тип.is_pointer_type() && matches!(доп_информация, ДополнительнаяИнформация::Нет)
                                })
                                .unwrap_or(false);

                            // ⚠️ НАЙДЕНО РЕАЛЬНОЙ ПРОВЕРКОЙ (утечка внутри
                            // циклов): раньше решение "освобождать ли старое
                            // значение" принималось ОДИН раз, статически, по
                            // тому, отслеживалась ли переменная НА МОМЕНТ
                            // КОМПИЛЯЦИИ этого узла — но внутри цикла один и
                            // тот же узел выполняется много раз, и на первой
                            // итерации переменная может ещё не владеть
                            // значением (не течёт), а на второй и далее —
                            // уже владеть (течёт, поскольку сгенерированный
                            // код для узла один и тот же для всех итераций).
                            // Теперь решение принимается В РАНТАЙМЕ, через
                            // отдельный, скрытый булев флаг рядом с
                            // переменной — читается и обновляется на каждом
                            // реальном выполнении присваивания, а не один
                            // раз при компиляции.
                            if это_текстовая_переменная {
                                let флаг = self.получить_или_создать_флаг_владения(имя_переменной)?;
                                let владеет_сейчас = self
                                    .билдер
                                    .build_load(self.контекст.bool_type(), флаг, "флаг_владения_чтение")
                                    .map_err(|e| ошибка(format!("ошибка чтения флага владения: {:?}", e)))?
                                    .into_int_value();

                                let функция = self
                                    .текущая_функция
                                    .ok_or_else(|| ошибка("внутренняя ошибка: присваивание текста вне функции"))?;
                                let блок_освобождения = self.контекст.append_basic_block(функция, "текст_освободить_старое");
                                let блок_продолжения = self.контекст.append_basic_block(функция, "текст_продолжить");

                                self.билдер
                                    .build_conditional_branch(владеет_сейчас, блок_освобождения, блок_продолжения)
                                    .map_err(|e| ошибка(format!("ошибка условного перехода флага владения: {:?}", e)))?;

                                self.билдер.position_at_end(блок_освобождения);
                                if let Some((адрес_переменной, llvm_тип, _)) = self.переменные.get(имя_переменной).cloned() {
                                    let старое_значение = self
                                        .билдер
                                        .build_load(llvm_тип, адрес_переменной, "старый_текст_для_освобождения")
                                        .map_err(|e| ошибка(format!("ошибка чтения старого значения текста: {:?}", e)))?;
                                    let free = self
                                        .модуль
                                        .get_function("free")
                                        .ok_or_else(|| ошибка("внутренняя ошибка: free не была объявлена"))?;
                                    self.билдер
                                        .build_call(free, &[старое_значение.into()], "освободить_старый_текст")
                                        .map_err(|e| ошибка(format!("ошибка освобождения старого текста: {:?}", e)))?;
                                }
                                self.билдер
                                    .build_unconditional_branch(блок_продолжения)
                                    .map_err(|e| ошибка(format!("ошибка перехода после освобождения текста: {:?}", e)))?;

                                self.билдер.position_at_end(блок_продолжения);

                                // Обновляем флаг для НОВОГО значения — это
                                // компиляционно известное свойство ИМЕННО
                                // ЭТОГО выражения (является_текст_порождающим
                                // не зависит от рантайма), поэтому просто
                                // константа, не рантайм-вычисление.
                                let новое_владение = является_текст_порождающим(значение);
                                self.билдер
                                    .build_store(флаг, self.контекст.bool_type().const_int(новое_владение as u64, false))
                                    .map_err(|e| ошибка(format!("ошибка обновления флага владения: {:?}", e)))?;

                                // Переменная теперь МОЖЕТ владеть значением —
                                // гарантируем, что она попадёт в список
                                // проверки при естественном выходе из области
                                // видимости (если ещё не была добавлена).
                                let уже_в_списке = self.стек_arc_областей_текста.iter().any(|фрейм| фрейм.contains(имя_переменной));
                                if новое_владение && !уже_в_списке {
                                    if let Some(внешний_фрейм) = self.стек_arc_областей_текста.first_mut() {
                                        внешний_фрейм.push(имя_переменной.clone());
                                    }
                                }
                            }
                        }

                        // НОВОЕ (текст под ARC — поля структур): та же самая
                        // находка, что была выше для простых переменных, но
                        // для "это.поле = новое_значение;" — реальный краш
                        // (free() на литерале), найденный ТЕСТОМ, не
                        // предугаданный заранее. Инвариант "текстовое поле
                        // структуры ВСЕГДА своя копия" (см. strdup в
                        // сгенерировать_вызов_конструктора) сохраняется
                        // здесь ТЕМ ЖЕ способом: старое значение освобождаем
                        // БЕЗУСЛОВНО (оно гарантированно тоже было копией —
                        // либо от конструктора, либо от предыдущего такого
                        // же присваивания), новое — копируем через strdup
                        // ПЕРЕД записью, а не после (иначе на один момент
                        // поле держало бы "чужой", не скопированный указатель).
                        if let МестоЗаписи::Поле { объект, поле } = место {
                            if let Ok((_, имя_структуры)) = self.получить_структуру_из_места(объект) {
                                if let Some((llvm_struct, имена_полей)) = self.структуры.get(&имя_структуры).cloned() {
                                    if let Some(индекс) = имена_полей.iter().position(|имя_поля| имя_поля == поле) {
                                        let llvm_индекс = индекс as u32 + СМЕЩЕНИЕ_ПОЛЕЙ_ARC;
                                        let текстовые_поля = self.текстовые_поля_структур.get(&имя_структуры).cloned().unwrap_or_default();
                                        if текстовые_поля.contains(&llvm_индекс) {
                                            let байт_указатель = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default());
                                            let старое_значение = self
                                                .билдер
                                                .build_load(байт_указатель, адрес, "старое_текстовое_поле_для_освобождения")
                                                .map_err(|e| ошибка(format!("ошибка чтения старого текстового поля: {:?}", e)))?;
                                            let free = self
                                                .модуль
                                                .get_function("free")
                                                .ok_or_else(|| ошибка("внутренняя ошибка: free не была объявлена"))?;
                                            self.билдер
                                                .build_call(free, &[старое_значение.into()], "освободить_старое_текстовое_поле")
                                                .map_err(|e| ошибка(format!("ошибка освобождения старого текстового поля: {:?}", e)))?;

                                            let strdup = self
                                                .модуль
                                                .get_function("strdup")
                                                .ok_or_else(|| ошибка("внутренняя ошибка: strdup не была объявлена"))?;
                                            вычисленное = self
                                                .билдер
                                                .build_call(strdup, &[вычисленное.into()], "копия_нового_текстового_поля")
                                                .map_err(|e| ошибка(format!("ошибка копирования нового текстового поля: {:?}", e)))?
                                                .try_as_basic_value()
                                                .left()
                                                .ok_or_else(|| ошибка("strdup неожиданно не вернул значение"))?;
                                        }
                                    }
                                    // ⚠️ Заглушаем неиспользуемое предупреждение —
                                    // llvm_struct здесь не нужен, только имена_полей.
                                    let _ = llvm_struct;
                                }
                            }
                        }

                        self.билдер
                            .build_store(адрес, вычисленное)
                            .map_err(|e| ошибка(format!("ошибка присваивания: {:?}", e)))?;
                        Ok(())
                    }
                }
            }
            Оператор::ВыражениеОператор(выражение) => {
                self.сгенерировать_выражение(выражение)?;
                Ok(())
            }
            Оператор::Если { условие, тогда, иначе } => {
                self.сгенерировать_если(условие, тогда, иначе.as_ref(), функция)
            }
            Оператор::Вернуть(значение) => {
                match значение {
                    Some(выр) => {
                        let значение_llvm = self.сгенерировать_выражение(выр)?;
                        self.освободить_при_возврате(Some(выр))?;
                        self.билдер
                            .build_return(Some(&значение_llvm))
                            .map_err(|e| ошибка(format!("ошибка генерации 'вернуть': {:?}", e)))?;
                    }
                    None => {
                        self.освободить_при_возврате(None)?;
                        self.билдер
                            .build_return(None)
                            .map_err(|e| ошибка(format!("ошибка генерации 'вернуть': {:?}", e)))?;
                    }
                }
                Ok(())
            }
            Оператор::ЦиклПока { условие, тело } => self.сгенерировать_цикл_пока(условие, тело, функция),
            Оператор::ЦиклДляКаждого { переменная, коллекция, тело } => {
                self.сгенерировать_цикл_для_каждого(переменная, коллекция, тело, функция)
            }
            Оператор::Параллельно(блок) => self.сгенерировать_параллельно(блок),
        }
    }

    /// Генерирует "параллельно { тело }" — запускает тело в ОТДЕЛЬНОМ
    /// потоке ОС (через pthread_create), НЕ дожидаясь его завершения —
    /// родительская функция продолжает выполняться сразу после запуска.
    ///
    /// ⚠️ ЧЕСТНОЕ, НАМЕРЕННОЕ ОГРАНИЧЕНИЕ v1: тело блока генерируется как
    /// СОВЕРШЕННО ОТДЕЛЬНАЯ LLVM-функция — с ЧИСТОЙ (пустой) таблицей
    /// переменных (self.переменные.clear() перед генерацией, аналогично
    /// тому, как это уже делается для обычных функций языка). Это не
    /// искусственное ограничение "потому что лень" — это РЕАЛЬНАЯ защита
    /// от опасной ошибки: если бы тело блока могло ссылаться на локальную
    /// переменную родительской функции (её адрес в стеке), а родительская
    /// функция завершилась бы раньше потока — поток обращался бы к уже
    /// освобождённой памяти стека (use-after-return). Правильная защита
    /// потребовала бы либо статического анализа AST (какие идентификаторы
    /// использует блок, копирование их значений в кучу перед запуском
    /// потока), либо связывания с временем жизни через дополнительный
    /// механизм — самостоятельный, больший следующий шаг. Сейчас: попытка
    /// использовать внешнюю переменную внутри "параллельно" естественно
    /// провалится на этапе компиляции с "переменная не найдена" — то есть
    /// ограничение НЕ тихое, оно ловится компилятором, просто не с
    /// специальным, понятным сообщением именно про потоки.
    fn сгенерировать_параллельно(&mut self, блок: &Блок) -> Result<(), ОшибкаКодогенерации> {
        // Сохраняем ВЕСЬ контекст текущей (родительской) генерации — после
        // генерации функции потока нужно вернуться сюда и продолжить как
        // ни в чём не бывало.
        let сохранённые_переменные = std::mem::take(&mut self.переменные);
        let сохранённые_неизменные = std::mem::take(&mut self.неизменные);
        let сохранённая_функция = self.текущая_функция;
        let сохранённый_ok_тип = self.текущий_ok_тип_llvm;
        let сохранённый_стек_arc = std::mem::take(&mut self.стек_arc_областей);
        let сохранённый_стек_arc_текста = std::mem::take(&mut self.стек_arc_областей_текста);
        let сохранённая_позиция = self
            .билдер
            .get_insert_block()
            .ok_or_else(|| ошибка("внутренняя ошибка: 'параллельно' вызван вне тела функции"))?;

        // НОВОЕ (многопоточность, вторая часть — "канал<T>"): единственное,
        // сознательное исключение из "чистого контекста" ниже. Канал —
        // указатель на кучу, безопасно скопировать его ЗНАЧЕНИЕ в новый
        // поток — в отличие от произвольной локальной переменной.
        //
        // ⚠️ РЕАЛЬНАЯ, ФУНДАМЕНТАЛЬНАЯ ОШИБКА, НАЙДЕННАЯ ПРИ ПЕРВОМ ТЕСТЕ
        // (segfault, gdb показал мусорный адрес мьютекса): LLVM-значения
        // (SSA) НЕ МОГУТ пересекать границы функций — значение, вычисленное
        // (build_load) в РОДИТЕЛЬСКОЙ функции, нельзя просто "перенести" и
        // использовать как операнд в СОВЕРШЕННО ОТДЕЛЬНОЙ функции потока —
        // это не то же самое, что обычная память. Правильный способ
        // передать данные между функциями в LLVM — через настоящую память,
        // используя штатный параметр "arg" у pthread_create (до этого
        // момента мы его попросту игнорировали, передавая NULL): пишем
        // указатели каналов в небольшой malloc-буфер ЗДЕСЬ, в родительском
        // коде, передаём АДРЕС этого буфера в поток как arg, поток сам
        // читает из него (и освобождает буфер) в своём собственном коде.
        let имена_каналов: Vec<String> = сохранённые_переменные
            .iter()
            .filter_map(|(имя, (_, _, доп_информация))| {
                if matches!(доп_информация, ДополнительнаяИнформация::Канал { .. }) {
                    Some(имя.clone())
                } else {
                    None
                }
            })
            .collect();

        let байт_указатель: BasicTypeEnum = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default()).into();
        let i64_тип = self.контекст.i64_type();

        // НОВОЕ: обычная локальная переменная Rust (не self-поле!) —
        // сознательный выбор. Генерация тела потока ниже рекурсивно вызывает
        // сгенерировать_блок, которая сама может встретить ВЛОЖЕННЫЙ
        // "параллельно" — если бы это значение хранилось в self-поле, тот
        // вложенный вызов перезаписал бы его, и мы потеряли бы указатель
        // на СВОЙ буфер к моменту вызова pthread_create в конце этой же
        // функции. Обычная переменная стека вызова Rust свободна от этой
        // проблемы — она принадлежит именно этому вызову функции.
        let буфер_каналов: Option<inkwell::values::PointerValue<'ctx>> = if имена_каналов.is_empty() {
            None
        } else {
            let malloc = self
                .модуль
                .get_function("malloc")
                .ok_or_else(|| ошибка("внутренняя ошибка: malloc не была объявлена"))?;
            let размер_буфера = i64_тип.const_int((имена_каналов.len() * 8) as u64, false);
            let буфер = self
                .билдер
                .build_call(malloc, &[размер_буфера.into()], "буфер_каналов_потока")
                .map_err(|e| ошибка(format!("ошибка выделения буфера для каналов потока: {:?}", e)))?
                .try_as_basic_value()
                .left()
                .ok_or_else(|| ошибка("malloc не вернул значение"))?
                .into_pointer_value();

            for (индекс, имя) in имена_каналов.iter().enumerate() {
                let (адрес, llvm_тип, _) = сохранённые_переменные.get(имя).unwrap();
                let значение_канала = self
                    .билдер
                    .build_load(*llvm_тип, *адрес, "загрузка_канала_для_потока")
                    .map_err(|e| ошибка(format!("ошибка чтения канала '{}' для передачи в поток: {:?}", имя, e)))?
                    .into_pointer_value();
                let значение_как_i64 = self
                    .билдер
                    .build_ptr_to_int(значение_канала, i64_тип, "канал_в_i64")
                    .map_err(|e| ошибка(format!("ошибка приведения канала '{}': {:?}", имя, e)))?;
                let ячейка = unsafe {
                    self.билдер.build_gep(
                        self.контекст.i8_type(),
                        буфер,
                        &[i64_тип.const_int((индекс * 8) as u64, false)],
                        "ячейка_буфера_каналов",
                    )
                }
                .map_err(|e| ошибка(format!("ошибка вычисления адреса в буфере каналов: {:?}", e)))?;
                self.билдер
                    .build_store(ячейка, значение_как_i64)
                    .map_err(|e| ошибка(format!("ошибка записи канала '{}' в буфер: {:?}", имя, e)))?;
            }

            Some(буфер)
        };

        // Новая, отдельная LLVM-функция для тела потока — сигнатура
        // "i8* (i8*)", ожидаемая pthread_create для start_routine.
        self.счётчик_параллельных_блоков += 1;
        let имя_функции_потока = format!("параллельно_блок_{}", self.счётчик_параллельных_блоков);
        let тип_функции_потока = байт_указатель.fn_type(&[байт_указатель.into()], false);
        let llvm_функция_потока = self.модуль.add_function(&имя_функции_потока, тип_функции_потока, None);

        let блок_входа = self.контекст.append_basic_block(llvm_функция_потока, "вход");
        self.билдер.position_at_end(блок_входа);

        // Чистый контекст — см. подробное объяснение выше про безопасность.
        self.переменные = HashMap::new();
        self.неизменные = HashMap::new();
        self.текущая_функция = Some(llvm_функция_потока);
        self.текущий_ok_тип_llvm = None;
        self.стек_arc_областей = vec![Vec::new()];
        self.стек_arc_областей_текста = vec![Vec::new()];

        // Восстанавливаем каналы под теми же именами — читаем ИЗ ПАМЯТИ
        // (параметр функции потока — arg, полученный от pthread_create),
        // а не пытаемся "перенести" SSA-значение напрямую (см. подробное
        // объяснение про фундаментальную ошибку выше).
        if !имена_каналов.is_empty() {
            let аргумент_потока = llvm_функция_потока
                .get_nth_param(0)
                .ok_or_else(|| ошибка("внутренняя ошибка: у функции потока нет параметра"))?
                .into_pointer_value();

            for (индекс, имя) in имена_каналов.iter().enumerate() {
                let (_, llvm_тип, доп_информация) = сохранённые_переменные.get(имя).unwrap().clone();
                let ячейка = unsafe {
                    self.билдер.build_gep(
                        self.контекст.i8_type(),
                        аргумент_потока,
                        &[i64_тип.const_int((индекс * 8) as u64, false)],
                        "чтение_ячейки_буфера_каналов",
                    )
                }
                .map_err(|e| ошибка(format!("ошибка вычисления адреса при чтении канала '{}': {:?}", имя, e)))?;
                let значение_как_i64 = self
                    .билдер
                    .build_load(i64_тип, ячейка, "значение_канала_i64")
                    .map_err(|e| ошибка(format!("ошибка чтения канала '{}' внутри потока: {:?}", имя, e)))?
                    .into_int_value();
                let значение_канала = self
                    .билдер
                    .build_int_to_ptr(значение_как_i64, llvm_тип.into_pointer_type(), "i64_в_канал")
                    .map_err(|e| ошибка(format!("ошибка приведения канала '{}' внутри потока: {:?}", имя, e)))?;

                let новый_адрес = self
                    .билдер
                    .build_alloca(llvm_тип, &format!("канал_{}", имя))
                    .map_err(|e| ошибка(format!("ошибка выделения памяти для канала '{}' внутри потока: {:?}", имя, e)))?;
                self.билдер
                    .build_store(новый_адрес, значение_канала)
                    .map_err(|e| ошибка(format!("ошибка записи канала '{}' внутри потока: {:?}", имя, e)))?;
                self.переменные.insert(имя.clone(), (новый_адрес, llvm_тип, доп_информация));
            }

            // Буфер сослужил свою службу — освобождаем его же в потоке,
            // не оставляя утечку на каждый запуск "параллельно" с каналами.
            let free = self
                .модуль
                .get_function("free")
                .ok_or_else(|| ошибка("внутренняя ошибка: free не была объявлена"))?;
            self.билдер
                .build_call(free, &[аргумент_потока.into()], "освобождение_буфера_каналов")
                .map_err(|e| ошибка(format!("ошибка освобождения буфера каналов: {:?}", e)))?;
        }

        self.сгенерировать_блок(блок, &llvm_функция_потока)?;

        if блок_не_завершён(&self.билдер) {
            self.освободить_при_возврате(None)?;
            let null_указатель = байт_указатель.into_pointer_type().const_null();
            self.билдер
                .build_return(Some(&null_указатель))
                .map_err(|e| ошибка(format!("ошибка генерации возврата из функции потока: {:?}", e)))?;
        }

        // Восстанавливаем контекст родительской функции — как будто
        // "параллельно {...}" был обычным оператором, ничего вокруг не
        // трогающим (что и есть замысел: он лишь ЗАПУСКАЕТ поток, дальше
        // родительский код продолжается своим чередом).
        self.переменные = сохранённые_переменные;
        self.неизменные = сохранённые_неизменные;
        self.текущая_функция = сохранённая_функция;
        self.текущий_ok_тип_llvm = сохранённый_ok_тип;
        self.стек_arc_областей = сохранённый_стек_arc;
        self.стек_arc_областей_текста = сохранённый_стек_arc_текста;
        self.билдер.position_at_end(сохранённая_позиция);

        // Запускаем поток: pthread_create(&id_потока, NULL, наша_функция, arg).
        // "arg" — NULL, если каналов не было (обычный, прежний случай), либо
        // указатель на подготовленный выше malloc-буфер с их значениями —
        // ЕДИНСТВЕННЫЙ штатный, безопасный способ передать что-либо
        // (кроме самого факта запуска) из родительского кода в функцию
        // потока в LLVM (см. подробное объяснение выше, у объявления
        // "буфер_каналов").
        let pthread_create = self
            .модуль
            .get_function("pthread_create")
            .ok_or_else(|| ошибка("внутренняя ошибка: pthread_create не была объявлена"))?;
        let буфер_id_потока = self
            .билдер
            .build_alloca(байт_указатель, "id_потока")
            .map_err(|e| ошибка(format!("ошибка выделения памяти для id потока: {:?}", e)))?;
        let null_указатель = байт_указатель.into_pointer_type().const_null();
        let аргумент_для_потока: inkwell::values::BasicValueEnum = match буфер_каналов {
            Some(буфер) => буфер.into(),
            None => null_указатель.into(),
        };
        self.билдер
            .build_call(
                pthread_create,
                &[
                    буфер_id_потока.into(),
                    null_указатель.into(),
                    llvm_функция_потока.as_global_value().as_pointer_value().into(),
                    аргумент_для_потока.into(),
                ],
                "запуск_потока",
            )
            .map_err(|e| ошибка(format!("ошибка запуска потока: {:?}", e)))?;

        // НОВОЕ (join для потоков): сохраняем только что полученный id
        // потока в глобальный, долгоживущий массив — "буфер_id_потока"
        // выше это alloca, живущая только до конца ТЕКУЩЕЙ (родительской)
        // функции, для дождаться_все_потоки() нужно что-то, доступное
        // из любой точки программы, в любое время.
        let байт_указатель_тип = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default());
        let id_потока = self
            .билдер
            .build_load(байт_указатель_тип, буфер_id_потока, "id_потока_значение")
            .map_err(|e| ошибка(format!("ошибка чтения id потока: {:?}", e)))?;

        let глобальный_счётчик = self
            .модуль
            .get_global("sfera_количество_потоков")
            .ok_or_else(|| ошибка("внутренняя ошибка: sfera_количество_потоков не была объявлена"))?
            .as_pointer_value();
        let текущий_индекс = self
            .билдер
            .build_load(self.контекст.i64_type(), глобальный_счётчик, "текущий_индекс_потока")
            .map_err(|e| ошибка(format!("ошибка чтения счётчика потоков: {:?}", e)))?
            .into_int_value();

        let глобальный_массив = self
            .модуль
            .get_global("sfera_id_потоков")
            .ok_or_else(|| ошибка("внутренняя ошибка: sfera_id_потоков не была объявлена"))?
            .as_pointer_value();
        let тип_массива_потоков = байт_указатель_тип.array_type(256);
        let ноль = self.контекст.i64_type().const_int(0, false);
        let адрес_ячейки = unsafe {
            self.билдер
                .build_gep(тип_массива_потоков, глобальный_массив, &[ноль, текущий_индекс], "адрес_ячейки_потока")
                .map_err(|e| ошибка(format!("ошибка адресации массива потоков: {:?}", e)))?
        };
        self.билдер
            .build_store(адрес_ячейки, id_потока)
            .map_err(|e| ошибка(format!("ошибка сохранения id потока: {:?}", e)))?;

        let новый_индекс = self
            .билдер
            .build_int_add(текущий_индекс, self.контекст.i64_type().const_int(1, false), "новый_индекс_потока")
            .map_err(|e| ошибка(format!("ошибка увеличения счётчика потоков: {:?}", e)))?;
        self.билдер
            .build_store(глобальный_счётчик, новый_индекс)
            .map_err(|e| ошибка(format!("ошибка записи счётчика потоков: {:?}", e)))?;

        Ok(())
    }

    fn объявить_переменную(
        &mut self,
        тип: &Тип,
        имя: &str,
        значение: &Выражение,
        неизменная: bool,
    ) -> Result<(), ОшибкаКодогенерации> {
        // НОВОЕ (настоящий полиморфизм через контракты): та же логика
        // упаковки "толстого указателя" { данные, vtable }, что уже
        // реализована для Оператор::Присваивание/НовоеОбъявление (см. там
        // подробный комментарий) — нужна ЗДЕСЬ ЖЕ, поскольку "ИмяКонтракта
        // переменная = значение;" С ЯВНЫМ ТИПОМ СЛЕВА идёт другим путём
        // через кодогенератор (Оператор::ОбъявлениеСТипом, не Присваивание)
        // — без этой ветки объявить_переменную ниже трактовала бы
        // "Печатаемый" как обычное имя структуры и падала бы, не находя
        // такую структуру (контракты в отдельном списке, не в self.структуры).
        if let Тип::Пользовательский(имя_контракта) = тип {
            if self.контракты_методы.contains_key(имя_контракта) {
                // НОВОЕ (Список<Контракт>): "значение" может быть ДВУХ
                // принципиально разных видов — (а) сырая структура,
                // нуждающаяся в упаковке в "толстый указатель" (обычный,
                // уже работавший случай — "Печатаемый х = кот;"), или (б)
                // УЖЕ готовый, упакованный контракт — например, результат
                // "зоопарк.получить(индекс)" из Список<Печатаемый>, где
                // упаковывать нечего, он уже в нужном виде. Различить на
                // уровне AST заранее сложно (оба — просто выражения) —
                // пробуем путь (а) первым; если он не подходит (значение —
                // не структура), это и есть признак случая (б).
                if let Ok((указатель_на_данные, имя_структуры)) = self.получить_структуру_из_выражения(значение) {
                    self.объявить_переменную_контракт_из_структуры(тип, имя, неизменная, имя_контракта, указатель_на_данные, &имя_структуры)?;
                    return Ok(());
                }

                // Случай (б): значение уже упаковано — генерируем как
                // обычное выражение типа "толстый указатель" и сохраняем
                // напрямую, без повторной упаковки.
                let толстый_указатель_тип = self.контекст.struct_type(
                    &[
                        self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default()).into(),
                        self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default()).into(),
                    ],
                    false,
                );
                let вычисленное = self.сгенерировать_выражение(значение)?;
                let указатель_переменной = self
                    .билдер
                    .build_alloca(толстый_указатель_тип, имя)
                    .map_err(|e| ошибка(format!("ошибка выделения памяти для '{}': {:?}", имя, e)))?;
                self.билдер
                    .build_store(указатель_переменной, вычисленное)
                    .map_err(|e| ошибка(format!("ошибка инициализации '{}': {:?}", имя, e)))?;
                self.переменные.insert(
                    имя.to_string(),
                    (указатель_переменной, толстый_указатель_тип.into(), ДополнительнаяИнформация::Контракт(имя_контракта.to_string())),
                );
                self.неизменные.insert(имя.to_string(), неизменная);
                return Ok(());
            }
        }
        self.объявить_переменную_обычная(тип, имя, значение, неизменная)
    }

    /// Часть "объявить_переменную" для случая (а) выше — вынесена в
    /// отдельную функцию, чтобы не дублировать код упаковки "толстого
    /// указателя" (та же логика, что уже была здесь до разделения на
    /// два случая).
    fn объявить_переменную_контракт_из_структуры(
        &mut self,
        _тип: &Тип,
        имя: &str,
        неизменная: bool,
        имя_контракта: &str,
        указатель_на_данные: PointerValue<'ctx>,
        имя_структуры: &str,
    ) -> Result<(), ОшибкаКодогенерации> {
        let vtable = self
            .vtables
                    .get(&(имя_структуры.to_string(), имя_контракта.to_string()))
                    .copied()
                    .ok_or_else(|| {
                        ошибка(format!(
                            "внутренняя ошибка: vtable для '{}' : '{}' не была сгенерирована заранее",
                            имя_структуры, имя_контракта
                        ))
                    })?;

                let байт_указатель = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default());
                let данные_как_i8 = self
                    .билдер
                    .build_pointer_cast(указатель_на_данные, байт_указатель, "данные_контракта")
                    .map_err(|e| ошибка(format!("ошибка приведения указателя данных для '{}': {:?}", имя, e)))?;
                let vtable_как_i8 = self
                    .билдер
                    .build_pointer_cast(vtable.as_pointer_value(), байт_указатель, "vtable_контракта")
                    .map_err(|e| ошибка(format!("ошибка приведения указателя vtable для '{}': {:?}", имя, e)))?;

                let толстый_указатель_тип = self.контекст.struct_type(&[байт_указатель.into(), байт_указатель.into()], false);
                let mut толстый_указатель = толстый_указатель_тип.get_undef();
                толстый_указатель = self
                    .билдер
                    .build_insert_value(толстый_указатель, данные_как_i8, 0, "вставить_данные")
                    .map_err(|e| ошибка(format!("ошибка сборки толстого указателя для '{}': {:?}", имя, e)))?
                    .into_struct_value();
                толстый_указатель = self
                    .билдер
                    .build_insert_value(толстый_указатель, vtable_как_i8, 1, "вставить_vtable")
                    .map_err(|e| ошибка(format!("ошибка сборки толстого указателя для '{}': {:?}", имя, e)))?
                    .into_struct_value();

                let указатель_переменной = self
                    .билдер
                    .build_alloca(толстый_указатель_тип, имя)
                    .map_err(|e| ошибка(format!("ошибка выделения памяти для '{}': {:?}", имя, e)))?;
                self.билдер
                    .build_store(указатель_переменной, толстый_указатель)
                    .map_err(|e| ошибка(format!("ошибка инициализации '{}': {:?}", имя, e)))?;

                self.переменные.insert(
                    имя.to_string(),
                    (указатель_переменной, толстый_указатель_тип.into(), ДополнительнаяИнформация::Контракт(имя_контракта.to_string())),
                );
                self.неизменные.insert(имя.to_string(), неизменная);
                Ok(())
    }

    /// Обычный, не-контрактный путь "объявить_переменную" — вся остальная
    /// логика (массивы, обычные структуры, текст под ARC и так далее),
    /// без изменений от того, что было до разделения на случаи (а)/(б)
    /// для контрактов выше.
    fn объявить_переменную_обычная(
        &mut self,
        тип: &Тип,
        имя: &str,
        значение: &Выражение,
        неизменная: bool,
    ) -> Result<(), ОшибкаКодогенерации> {
        // Особый случай: "тип[] имя = [1, 2, 3];" — размер в самом типе
        // не указан (Массив { размер: None }), семантический анализ уже
        // проверил совместимость, но кодогенератору тоже нужно знать
        // конкретный размер, чтобы построить ArrayType. Проще всего взять
        // его напрямую из литерала — длина literal'а И ЕСТЬ размер массива.
        let (llvm_тип, доп_информация) = if let (Тип::Массив { элемент, размер: None }, Выражение::МассивЛит(элементы)) = (тип, значение) {
            let llvm_элемент = self.тип_в_llvm(элемент)?;
            let размер = элементы.len() as u32;
            (llvm_элемент.array_type(размер).into(), ДополнительнаяИнформация::Массив { элемент: llvm_элемент, размер })
        } else {
            let llvm_тип = self.тип_в_llvm(тип)?;
            let доп_информация = self.дополнительная_информация_из_ast_типа(тип)?;
            (llvm_тип, доп_информация)
        };

        let вычисленное = self.сгенерировать_выражение(значение)?;

        // ARC: если объявляем переменную-структуру, копируя УЖЕ СУЩЕСТВУЮЩУЮ
        // переменную ("Пользователь другой = юзер;", а не свежий вызов
        // конструктора "Пользователь другой = Пользователь(...);") — нужно
        // увеличить счётчик ссылок объекта: теперь на него ссылаются ДВЕ
        // переменные, а не одна. Свежесозданный конструктором объект уже
        // стартует со счётчиком 1 (см. сгенерировать_вызов_конструктора) —
        // retain для него был бы ОШИБКОЙ (счётчик стал бы 2 вместо 1 для
        // единственной существующей ссылки).
        if let (ДополнительнаяИнформация::Структура(имя_структуры), Выражение::Идентификатор(_)) = (&доп_информация, значение) {
            let (llvm_struct, _) = self
                .структуры
                .get(имя_структуры)
                .ok_or_else(|| ошибка(format!("внутренняя ошибка: структура '{}' не найдена", имя_структуры)))?
                .clone();
            self.захватить(вычисленное.into_pointer_value(), llvm_struct)?;
        }

        let указатель = self
            .билдер
            .build_alloca(llvm_тип, имя)
            .map_err(|e| ошибка(format!("ошибка выделения памяти для '{}': {:?}", имя, e)))?;

        self.билдер
            .build_store(указатель, вычисленное)
            .map_err(|e| ошибка(format!("ошибка инициализации '{}': {:?}", имя, e)))?;

        self.переменные.insert(имя.to_string(), (указатель, llvm_тип, доп_информация.clone()));
        self.неизменные.insert(имя.to_string(), неизменная);

        // ARC: регистрируем в ТЕКУЩЕМ (самом вложенном) фрейме стека областей
        // видимости — см. подробный комментарий у поля стек_arc_областей.
        if let ДополнительнаяИнформация::Структура(имя_структуры) = &доп_информация {
            if let Some((llvm_struct, _)) = self.структуры.get(имя_структуры).cloned() {
                if let Some(текущий_фрейм) = self.стек_arc_областей.last_mut() {
                    текущий_фрейм.push((имя.to_string(), имя_структуры.clone(), llvm_struct));
                }
            }
        }

        // НОВОЕ (текст под ARC): та же идея, что и выше для структур — см.
        // подробное объяснение в другой ветке (РазрешённоеПрисваивание::
        // НовоеОбъявление) — этот путь кода используется для объявления
        // переменной с ЯВНО указанным типом ("текст имя = ...;"), тот —
        // для объявления с выводом типа. Оба должны отслеживать владение
        // одинаково, иначе перегрузка "какой путь используется" стала бы
        // непредсказуемым источником утечек.
        // НОВОЕ (текст под ARC): та же идея, что и выше для структур — если
        // тип переменной "текст" — заводим флаг владения ВСЕГДА (не только
        // если инициализирующее значение уже владеющее) — иначе при первом
        // переприсваивании (потенциально внутри цикла) флага ещё не
        // существовало бы, хотя чтение уже требуется. Список фрейма
        // (безусловное освобождение при выходе из области видимости) по-
        // прежнему пополняется только если значение реально порождающее —
        // но САМ флаг заводится безусловно, для любой текстовой переменной.
        if matches!(тип, Тип::Текст) {
            let владеет_изначально = является_текст_порождающим(значение);
            if владеет_изначально {
                if let Some(текущий_фрейм_текста) = self.стек_arc_областей_текста.last_mut() {
                    текущий_фрейм_текста.push(имя.to_string());
                }
            }
            let флаг = self.получить_или_создать_флаг_владения(имя)?;
            self.билдер
                .build_store(флаг, self.контекст.bool_type().const_int(владеет_изначально as u64, false))
                .map_err(|e| ошибка(format!("ошибка инициализации флага владения для '{}': {:?}", имя, e)))?;
        }

        // НОВОЕ (текст под ARC, продолжение) — см. подробное объяснение
        // у аналогичного места выше (РазрешённоеПрисваивание::НовоеОбъявление).
        let это_результат_текста = matches!(тип, Тип::Результат(внутренний) if matches!(внутренний.as_ref(), Тип::Текст));
        if это_результат_текста && является_результат_текст_порождающим(значение) {
            if let Some(текущий_фрейм_текста) = self.стек_arc_областей_текста.last_mut() {
                текущий_фрейм_текста.push(имя.to_string());
            }
        }

        Ok(())
    }

    fn сгенерировать_если(
        &mut self,
        условие: &Выражение,
        тогда: &Блок,
        иначе: Option<&Блок>,
        функция: &FunctionValue<'ctx>,
    ) -> Result<(), ОшибкаКодогенерации> {
        let условие_llvm = self.сгенерировать_выражение(условие)?;
        let условие_bool = условие_llvm
            .into_int_value();

        let блок_тогда = self.контекст.append_basic_block(*функция, "если_тогда");
        let блок_иначе = self.контекст.append_basic_block(*функция, "если_иначе");
        let блок_после = self.контекст.append_basic_block(*функция, "если_после");

        self.билдер
            .build_conditional_branch(условие_bool, блок_тогда, блок_иначе)
            .map_err(|e| ошибка(format!("ошибка генерации условного перехода: {:?}", e)))?;

        self.билдер.position_at_end(блок_тогда);
        self.стек_arc_областей.push(Vec::new());
        self.стек_arc_областей_текста.push(Vec::new());
        self.сгенерировать_блок(тогда, функция)?;
        if блок_не_завершён(&self.билдер) {
            // Естественный выход из "тогда" (без явного "вернуть" внутри) —
            // освобождаем структуры ЭТОГО блока перед тем, как покинуть его.
            self.освободить_текущий_фрейм()?;
            self.билдер
                .build_unconditional_branch(блок_после)
                .map_err(|e| ошибка(format!("ошибка генерации перехода после 'если': {:?}", e)))?;
        }
        self.стек_arc_областей.pop();
        self.стек_arc_областей_текста.pop();

        self.билдер.position_at_end(блок_иначе);
        if let Some(иначе_блок) = иначе {
            self.стек_arc_областей.push(Vec::new());
        self.стек_arc_областей_текста.push(Vec::new());
            self.сгенерировать_блок(иначе_блок, функция)?;
            if блок_не_завершён(&self.билдер) {
                self.освободить_текущий_фрейм()?;
            }
            self.стек_arc_областей.pop();
        self.стек_arc_областей_текста.pop();
        }
        if блок_не_завершён(&self.билдер) {
            self.билдер
                .build_unconditional_branch(блок_после)
                .map_err(|e| ошибка(format!("ошибка генерации перехода после 'иначе': {:?}", e)))?;
        }

        self.билдер.position_at_end(блок_после);
        Ok(())
    }

    /// НОВОЕ (join для потоков): "дождаться_все_потоки()" — простой цикл
    /// от 0 до текущего значения глобального счётчика, pthread_join для
    /// каждого сохранённого id, затем сброс счётчика в 0 (чтобы можно
    /// было снова запускать новые "параллельно" и ждать их отдельной,
    /// следующей группой). См. подробное объяснение архитектуры у
    /// глобальных sfera_id_потоков / sfera_количество_потоков.
    fn сгенерировать_дождаться_все_потоки(&mut self) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        let функция = self
            .текущая_функция
            .ok_or_else(|| ошибка("внутренняя ошибка: 'дождаться_все_потоки' вызван вне тела функции"))?;

        let байт_указатель = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default());
        let i64_тип = self.контекст.i64_type();

        let глобальный_счётчик = self
            .модуль
            .get_global("sfera_количество_потоков")
            .ok_or_else(|| ошибка("внутренняя ошибка: sfera_количество_потоков не была объявлена"))?
            .as_pointer_value();
        let глобальный_массив = self
            .модуль
            .get_global("sfera_id_потоков")
            .ok_or_else(|| ошибка("внутренняя ошибка: sfera_id_потоков не была объявлена"))?
            .as_pointer_value();
        let тип_массива_потоков = байт_указатель.array_type(256);

        let количество = self
            .билдер
            .build_load(i64_тип, глобальный_счётчик, "количество_потоков_для_ожидания")
            .map_err(|e| ошибка(format!("ошибка чтения счётчика потоков: {:?}", e)))?
            .into_int_value();

        // Локальный, отдельный от глобального, индекс итерации — обычная
        // alloca-переменная, живущая только на время этого цикла.
        let индекс_alloca = self
            .билдер
            .build_alloca(i64_тип, "индекс_ожидания_потока")
            .map_err(|e| ошибка(format!("ошибка выделения индекса ожидания: {:?}", e)))?;
        self.билдер
            .build_store(индекс_alloca, i64_тип.const_int(0, false))
            .map_err(|e| ошибка(format!("ошибка инициализации индекса ожидания: {:?}", e)))?;

        let блок_условия = self.контекст.append_basic_block(функция, "ждать_потоки_условие");
        let блок_тела = self.контекст.append_basic_block(функция, "ждать_потоки_тело");
        let блок_после = self.контекст.append_basic_block(функция, "ждать_потоки_после");

        self.билдер
            .build_unconditional_branch(блок_условия)
            .map_err(|e| ошибка(format!("ошибка перехода к условию ожидания потоков: {:?}", e)))?;

        self.билдер.position_at_end(блок_условия);
        let текущий_индекс = self
            .билдер
            .build_load(i64_тип, индекс_alloca, "текущий_индекс_ожидания")
            .map_err(|e| ошибка(format!("ошибка чтения индекса ожидания: {:?}", e)))?
            .into_int_value();
        let условие = self
            .билдер
            .build_int_compare(IntPredicate::SLT, текущий_индекс, количество, "ждать_потоки_сравнение")
            .map_err(|e| ошибка(format!("ошибка сравнения индекса ожидания: {:?}", e)))?;
        self.билдер
            .build_conditional_branch(условие, блок_тела, блок_после)
            .map_err(|e| ошибка(format!("ошибка условного перехода ожидания потоков: {:?}", e)))?;

        self.билдер.position_at_end(блок_тела);
        let адрес_ячейки = unsafe {
            self.билдер
                .build_gep(тип_массива_потоков, глобальный_массив, &[i64_тип.const_int(0, false), текущий_индекс], "адрес_ячейки_ожидания")
                .map_err(|e| ошибка(format!("ошибка адресации массива потоков при ожидании: {:?}", e)))?
        };
        let id_потока = self
            .билдер
            .build_load(байт_указатель, адрес_ячейки, "id_потока_для_ожидания")
            .map_err(|e| ошибка(format!("ошибка чтения id потока при ожидании: {:?}", e)))?;

        let pthread_join = self
            .модуль
            .get_function("pthread_join")
            .ok_or_else(|| ошибка("внутренняя ошибка: pthread_join не была объявлена"))?;
        self.билдер
            .build_call(pthread_join, &[id_потока.into(), байт_указатель.const_null().into()], "ожидание_потока")
            .map_err(|e| ошибка(format!("ошибка вызова pthread_join: {:?}", e)))?;

        let новый_индекс = self
            .билдер
            .build_int_add(текущий_индекс, i64_тип.const_int(1, false), "следующий_индекс_ожидания")
            .map_err(|e| ошибка(format!("ошибка увеличения индекса ожидания: {:?}", e)))?;
        self.билдер
            .build_store(индекс_alloca, новый_индекс)
            .map_err(|e| ошибка(format!("ошибка записи индекса ожидания: {:?}", e)))?;
        self.билдер
            .build_unconditional_branch(блок_условия)
            .map_err(|e| ошибка(format!("ошибка возврата к условию ожидания потоков: {:?}", e)))?;

        self.билдер.position_at_end(блок_после);
        // Сбрасываем глобальный счётчик — все потоки этой "партии" уже
        // дождались, следующий вызов "параллельно" начнёт заполнять
        // массив заново с индекса 0.
        self.билдер
            .build_store(глобальный_счётчик, i64_тип.const_int(0, false))
            .map_err(|e| ошибка(format!("ошибка сброса счётчика потоков: {:?}", e)))?;

        Ok(i64_тип.const_int(0, false).into())
    }

    fn сгенерировать_цикл_пока(
        &mut self,
        условие: &Выражение,
        тело: &Блок,
        функция: &FunctionValue<'ctx>,
    ) -> Result<(), ОшибкаКодогенерации> {
        let блок_условия = self.контекст.append_basic_block(*функция, "пока_условие");
        let блок_тела = self.контекст.append_basic_block(*функция, "пока_тело");
        let блок_после = self.контекст.append_basic_block(*функция, "пока_после");

        self.билдер
            .build_unconditional_branch(блок_условия)
            .map_err(|e| ошибка(format!("ошибка генерации перехода к условию цикла: {:?}", e)))?;

        self.билдер.position_at_end(блок_условия);
        let условие_llvm = self.сгенерировать_выражение(условие)?;
        self.билдер
            .build_conditional_branch(условие_llvm.into_int_value(), блок_тела, блок_после)
            .map_err(|e| ошибка(format!("ошибка генерации условия цикла: {:?}", e)))?;

        self.билдер.position_at_end(блок_тела);
        self.стек_arc_областей.push(Vec::new());
        self.стек_arc_областей_текста.push(Vec::new());
        self.сгенерировать_блок(тело, функция)?;
        if блок_не_завершён(&self.билдер) {
            // Освобождаем структуры ЭТОЙ итерации перед переходом к следующей —
            // важно делать это КАЖДУЮ итерацию: иначе при повторном входе в
            // тело цикла alloca-ячейка перезапишется новым объектом, а старый
            // (из предыдущей итерации) "утечёт", так и не будучи отпущенным.
            self.освободить_текущий_фрейм()?;
            self.билдер
                .build_unconditional_branch(блок_условия)
                .map_err(|e| ошибка(format!("ошибка генерации возврата к условию цикла: {:?}", e)))?;
        }
        self.стек_arc_областей.pop();
        self.стек_arc_областей_текста.pop();

        self.билдер.position_at_end(блок_после);
        Ok(())
    }

    /// Генерирует "для каждого элемент в массив { тело }" как классический
    /// цикл со скрытым счётчиком-индексом, невидимым пользователю языка:
    ///
    ///   __индекс = 0;
    ///   пока (__индекс < размер) {
    ///       элемент = массив[__индекс];
    ///       тело;
    ///       __индекс = __индекс + 1;
    ///   }
    ///
    /// Переменная цикла ("элемент") заводится как обычная переменная в
    /// таблице self.переменные — на каждой итерации в неё просто
    /// перезаписывается следующий элемент массива (через GEP+load+store),
    /// а не создаётся заново — так проще и ничем не хуже с точки зрения
    /// пользователя языка (сам он никак не может заметить разницу).
    fn сгенерировать_цикл_для_каждого(
        &mut self,
        переменная: &str,
        коллекция: &Выражение,
        тело: &Блок,
        функция: &FunctionValue<'ctx>,
    ) -> Result<(), ОшибкаКодогенерации> {
        let (указатель_на_массив, элемент_тип, размер) = self.получить_массив_из_выражения(коллекция)?;

        let i64_тип = self.контекст.i64_type();

        // Скрытый счётчик — не переменная языка "Сфера", а служебная ячейка
        // самого кодогенератора, поэтому не кладём её в self.переменные.
        let указатель_индекса = self
            .билдер
            .build_alloca(i64_тип, "для_каждого_индекс")
            .map_err(|e| ошибка(format!("ошибка выделения памяти для индекса цикла: {:?}", e)))?;
        self.билдер
            .build_store(указатель_индекса, i64_тип.const_int(0, false))
            .map_err(|e| ошибка(format!("ошибка инициализации индекса цикла: {:?}", e)))?;

        // Переменная цикла — уже настоящая переменная языка "Сфера", кладём
        // её в общую таблицу, чтобы тело цикла могло обращаться к ней по
        // имени как к любой другой переменной.
        let указатель_переменной = self
            .билдер
            .build_alloca(элемент_тип, переменная)
            .map_err(|e| ошибка(format!("ошибка выделения памяти для переменной цикла '{}': {:?}", переменная, e)))?;
        self.переменные
            .insert(переменная.to_string(), (указатель_переменной, элемент_тип, ДополнительнаяИнформация::Нет));

        let блок_условия = self.контекст.append_basic_block(*функция, "для_каждого_условие");
        let блок_тела = self.контекст.append_basic_block(*функция, "для_каждого_тело");
        let блок_после = self.контекст.append_basic_block(*функция, "для_каждого_после");

        self.билдер
            .build_unconditional_branch(блок_условия)
            .map_err(|e| ошибка(format!("ошибка генерации перехода к условию 'для каждого': {:?}", e)))?;

        self.билдер.position_at_end(блок_условия);
        let текущий_индекс = self
            .билдер
            .build_load(i64_тип, указатель_индекса, "индекс")
            .map_err(|e| ошибка(format!("ошибка чтения индекса цикла: {:?}", e)))?
            .into_int_value();
        let условие = self
            .билдер
            .build_int_compare(IntPredicate::SLT, текущий_индекс, i64_тип.const_int(размер as u64, false), "условие_цикла")
            .map_err(|e| ошибка(format!("ошибка генерации условия 'для каждого': {:?}", e)))?;
        self.билдер
            .build_conditional_branch(условие, блок_тела, блок_после)
            .map_err(|e| ошибка(format!("ошибка генерации ветвления 'для каждого': {:?}", e)))?;

        self.билдер.position_at_end(блок_тела);

        // Копируем текущий элемент массива в переменную цикла — та же самая
        // GEP-механика с двумя индексами [0, i], что и в обычной индексации
        // (см. сгенерировать_доступ_по_индексу).
        let ноль = i64_тип.const_int(0, false);
        let тип_массива_llvm = элемент_тип.array_type(размер);
        let адрес_элемента = unsafe {
            self.билдер
                .build_gep(тип_массива_llvm, указатель_на_массив, &[ноль, текущий_индекс], "адрес_элемента")
                .map_err(|e| ошибка(format!("ошибка доступа к элементу массива в 'для каждого': {:?}", e)))?
        };
        let значение_элемента = self
            .билдер
            .build_load(элемент_тип, адрес_элемента, "элемент")
            .map_err(|e| ошибка(format!("ошибка чтения элемента массива в 'для каждого': {:?}", e)))?;
        self.билдер
            .build_store(указатель_переменной, значение_элемента)
            .map_err(|e| ошибка(format!("ошибка записи переменной цикла '{}': {:?}", переменная, e)))?;

        self.стек_arc_областей.push(Vec::new());
        self.стек_arc_областей_текста.push(Vec::new());
        self.сгенерировать_блок(тело, функция)?;

        if блок_не_завершён(&self.билдер) {
            // Освобождаем структуры этой итерации перед переходом к следующей —
            // та же причина, что и в сгенерировать_цикл_пока.
            self.освободить_текущий_фрейм()?;
            let индекс_плюс_один = self
                .билдер
                .build_int_add(текущий_индекс, i64_тип.const_int(1, false), "индекс_плюс_один")
                .map_err(|e| ошибка(format!("ошибка инкремента индекса 'для каждого': {:?}", e)))?;
            self.билдер
                .build_store(указатель_индекса, индекс_плюс_один)
                .map_err(|e| ошибка(format!("ошибка сохранения индекса 'для каждого': {:?}", e)))?;
            self.билдер
                .build_unconditional_branch(блок_условия)
                .map_err(|e| ошибка(format!("ошибка возврата к условию 'для каждого': {:?}", e)))?;
        }
        self.стек_arc_областей.pop();
        self.стек_arc_областей_текста.pop();

        self.билдер.position_at_end(блок_после);
        Ok(())
    }

    // ================== Выражения ==================

    fn сгенерировать_выражение(&mut self, выражение: &Выражение) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        match выражение {
            Выражение::ЦелоеЛит(n) => {
                Ok(self.контекст.i64_type().const_int(*n as u64, true).into())
            }
            Выражение::ДробноеЛит(n) => Ok(self.контекст.f64_type().const_float(*n).into()),
            Выражение::ВерноЛит(b) => Ok(self
                .контекст
                .bool_type()
                .const_int(if *b { 1 } else { 0 }, false)
                .into()),
            Выражение::ТекстЛит(текст) => self.сгенерировать_текстовый_литерал(текст),

            // Если ИнтерполированныйТекст дошёл сюда — значит, он использован
            // НЕ как прямой аргумент вывести(...) (иначе его бы перехватила
            // отдельная ветка в сгенерировать_вызов_вывести раньше). Это
            // осознанное ограничение текущей версии, а не забытый случай —
            // см. подробности в ast.rs у Выражение::ИнтерполированныйТекст.
            Выражение::ИнтерполированныйТекст(_) => Err(ошибка(
                "интерполированную строку ($имя внутри текста) можно использовать только \
                 как прямой единственный аргумент вывести(...) — сохранить её в переменную \
                 или передать в другую функцию пока нельзя (требует runtime-конкатенации строк, \
                 которой ещё нет — см. README)",
            )),
            Выражение::НеуказаноЛит => Err(ошибка(
                "'неуказано' пока не поддержано кодогенератором — требует реализации опциональных типов",
            )),

            Выражение::Идентификатор(имя) => {
                let (указатель, тип, _) = self
                    .переменные
                    .get(имя)
                    .ok_or_else(|| ошибка(format!("переменная '{}' не найдена (не объявлена в этой области видимости)", имя)))?;
                self.билдер
                    .build_load(*тип, *указатель, имя)
                    .map_err(|e| ошибка(format!("ошибка чтения переменной '{}': {:?}", имя, e)))
            }

            Выражение::Бинарное { левое, оператор, правое } => {
                self.сгенерировать_бинарное(левое, *оператор, правое)
            }

            Выражение::Унарное { оператор, операнд } => self.сгенерировать_унарное(*оператор, операнд),

            Выражение::ВызовФункции { имя, аргументы, .. } if имя == "вывести" => {
                self.сгенерировать_вызов_вывести(аргументы)
            }

            Выражение::ВызовФункции { имя, аргументы, .. } if имя == "длина" => {
                self.сгенерировать_длина(аргументы)
            }

            Выражение::ВызовФункции { имя, аргументы, .. } if имя == "целое_в_текст" => {
                self.сгенерировать_целое_в_текст(аргументы)
            }

            Выражение::ВызовФункции { имя, аргументы, .. } if имя == "дробное_в_текст" => {
                self.сгенерировать_дробное_в_текст(аргументы)
            }

            Выражение::ВызовФункции { имя, аргументы, .. } if имя == "текст_в_целое" => {
                self.сгенерировать_текст_в_целое(аргументы)
            }

            Выражение::ВызовФункции { имя, аргументы, .. } if имя == "абс" => {
                self.сгенерировать_абс(аргументы)
            }

            Выражение::ВызовФункции { имя, аргументы, .. } if имя == "мин" => {
                self.сгенерировать_мин_макс(аргументы, IntPredicate::SLT)
            }

            Выражение::ВызовФункции { имя, аргументы, .. } if имя == "макс" => {
                self.сгенерировать_мин_макс(аргументы, IntPredicate::SGT)
            }

            Выражение::ВызовФункции { имя, аргументы, .. } if имя == "верно_в_текст" => {
                self.сгенерировать_верно_в_текст(аргументы)
            }

            Выражение::ВызовФункции { имя, аргументы, .. } if имя == "содержит" => {
                self.сгенерировать_содержит(аргументы)
            }

            Выражение::ВызовФункции { имя, аргументы, .. } if имя == "найти" => {
                self.сгенерировать_найти(аргументы)
            }

            Выражение::ВызовФункции { имя, аргументы, .. } if имя == "подстрока" => {
                self.сгенерировать_подстрока(аргументы)
            }

            Выражение::ВызовФункции { имя, аргументы, .. } if имя == "прочитать_целое32" => {
                self.сгенерировать_прочитать_целое32(аргументы)
            }

            Выражение::ВызовФункции { имя, аргументы, .. } if имя == "записать_целое32" => {
                self.сгенерировать_записать_целое32(аргументы)
            }

            // НОВОЕ (join для потоков): "дождаться_все_потоки()" — см.
            // подробное объяснение архитектуры у глобального массива
            // sfera_id_потоков (объявление глобальных переменных) и у
            // сохранения id потока в сгенерировать_параллельно.
            Выражение::ВызовФункции { имя, .. } if имя == "дождаться_все_потоки" => {
                self.сгенерировать_дождаться_все_потоки()
            }

            Выражение::ВызовФункции { имя, аргументы, .. } if имя == "прочитать_текст_по_смещению" => {
                self.сгенерировать_прочитать_текст_по_смещению(аргументы)
            }

            Выражение::ВызовФункции { имя, аргументы, .. } if имя == "регистр_в_верхний" => {
                self.сгенерировать_регистр(аргументы, true)
            }

            Выражение::ВызовФункции { имя, аргументы, .. } if имя == "регистр_в_нижний" => {
                self.сгенерировать_регистр(аргументы, false)
            }

            Выражение::ВызовФункции { имя, .. } if имя == "прочитать_строку" => {
                self.сгенерировать_прочитать_строку()
            }

            Выражение::ВызовФункции { имя, .. } if имя == "аргументы_командной_строки" => {
                self.сгенерировать_аргументы_командной_строки()
            }

            Выражение::ВызовФункции { имя, .. } if имя == "создать_канал" => {
                self.сгенерировать_создать_канал()
            }

            Выражение::ВызовФункции { имя, аргументы, .. } if имя == "прочитать_файл" => {
                self.сгенерировать_прочитать_файл(аргументы)
            }

            Выражение::ВызовФункции { имя, аргументы, .. } if имя == "записать_файл" => {
                self.сгенерировать_записать_файл(аргументы)
            }

            Выражение::ВызовФункции { имя, аргументы, .. } if имя == "выполнить_команду" => {
                self.сгенерировать_выполнить_команду(аргументы)
            }

            Выражение::ВызовФункции { имя, типовые_параметры, .. } if имя == "Список" => {
                self.сгенерировать_список_конструктор(типовые_параметры)
            }

            Выражение::ВызовФункции { имя, типовые_параметры, .. } if имя == "Словарь" => {
                self.сгенерировать_словарь_конструктор(типовые_параметры)
            }

            // НОВОЕ: "Коробка<целое>(5)" — вызов конструктора ПОЛЬЗОВАТЕЛЬСКОЙ
            // обобщённой структуры. Проверяем ПЕРЕД обычной проверкой ниже,
            // потому что self.структуры содержит МАНГЛИРОВАННОЕ имя
            // ("Коробка__целое"), не буквальное AST-имя ("Коробка") — нужно
            // сначала вычислить манглированное имя (та же формула, что и в
            // семантике — см. манглированное_имя_обобщённой_структуры),
            // и вызвать обычный сгенерировать_вызов_конструктора уже с ним.
            Выражение::ВызовФункции { имя, типовые_параметры, аргументы, .. } if self.имена_обобщённых_структур.contains(имя) => {
                if типовые_параметры.len() != 1 {
                    return Err(ошибка(format!(
                        "внутренняя ошибка: {}<...>(...) должен иметь ровно один типовый параметр \
                         (семантика должна была отклонить это раньше, если это не так)",
                        имя
                    )));
                }
                let конкретный_тип = РешённыйТип::from(&типовые_параметры[0]);
                let манглированное = манглированное_имя_обобщённой_структуры(имя, &конкретный_тип);
                self.сгенерировать_вызов_конструктора(&манглированное, аргументы)
            }

            // НОВОЕ (обобщённые функции): та же самая логика, что и выше
            // для обобщённых структур — только вместо генерации
            // конструктора переиспользуем ВЕСЬ уже работающий, довольно
            // длинный путь обычного вызова функции (контракты, обычные
            // FFI-вызовы и так далее) — просто ПОДМЕНЯЯ имя на уже
            // мономорфизированное семантикой манглированное и рекурсивно
            // вызывая сгенерировать_выражение на новом узле, вместо того
            // чтобы дублировать всю эту логику здесь заново.
            Выражение::ВызовФункции { имя, типовые_параметры, аргументы, .. } if self.имена_обобщённых_функций.contains(имя) => {
                if типовые_параметры.len() != 1 {
                    return Err(ошибка(format!(
                        "внутренняя ошибка: {}<...>(...) должен иметь ровно один типовый параметр \
                         (семантика должна была отклонить это раньше, если это не так)",
                        имя
                    )));
                }
                let конкретный_тип = РешённыйТип::from(&типовые_параметры[0]);
                let манглированное = манглированное_имя_обобщённой_структуры(имя, &конкретный_тип);
                let подменённое_выражение = Выражение::ВызовФункции {
                    имя: манглированное,
                    типовые_параметры: Vec::new(),
                    аргументы: аргументы.clone(),
                };
                self.сгенерировать_выражение(&подменённое_выражение)
            }

            // НОВОЕ: явное приведение типов — "целое32(значение)" и
            // подобные (см. подробное объяснение в semantic.rs, у функции
            // имя_числового_типа_в_решённый_тип — та же логика здесь,
            // намеренно продублированная для кодогенерации, где нужна
            // ДОПОЛНИТЕЛЬНАЯ информация — знаковость и "дробность" типа,
            // чтобы выбрать правильную LLVM-инструкцию приведения).
            Выражение::ВызовФункции { имя, аргументы, .. } if аргументы.len() == 1 && информация_числового_типа(self.контекст, имя).is_some() => {
                let (целевой_llvm_тип, целевой_дробный, целевой_беззнаковый) = информация_числового_типа(self.контекст, имя).unwrap();
                let исходное_значение = self.сгенерировать_выражение(&аргументы[0])?;
                self.сгенерировать_приведение_числа(исходное_значение, целевой_llvm_тип, целевой_дробный, целевой_беззнаковый)
            }

            // Вызов с именем, совпадающим с известной структурой, — это вызов
            // автоконструктора: Пользователь("Аня", 30). Проверяем ПЕРЕД обычным
            // поиском функции в модуле, потому что конструкторы структур не
            // регистрируются как обычные LLVM-функции — они генерируются
            // "инлайново" прямо в месте вызова (malloc + запись каждого поля).
            Выражение::ВызовФункции { имя, аргументы, .. } if self.структуры.contains_key(имя) => {
                self.сгенерировать_вызов_конструктора(имя, аргументы)
            }

            Выражение::ВызовФункции { имя, аргументы, .. } => {
                // ⚠️ НОВОЕ В v2 (разрешение коллизий имён между модулями):
                // раньше self.модуль.get_function(имя) ВСЕГДА находил
                // функцию по буквальному имени — теперь функции из
                // подключённых модулей ВСЕГДА зарегистрированы под
                // МАНГЛИРОВАННЫМ LLVM-именем ("модуль__имя"), даже если
                // они однозначны (не коллизируют) — единообразие важнее
                // условной логики (тот же принцип, что и у generics).
                // Значит для ОДНОЗНАЧНОЙ модульной функции, вызванной БЕЗ
                // квалификации, нужен fallback: буквальное имя не найдётся
                // напрямую — ищем через self.однозначные_модульные_функции,
                // чтобы узнать манглированное имя.
                let llvm_функция = match self.модуль.get_function(имя) {
                    Some(ф) => ф,
                    None => {
                        let модуль = self.однозначные_модульные_функции.get(имя).cloned();
                        let манглированное = модуль.and_then(|модуль| {
                            self.манглированные_имена_функций.get(&(модуль, имя.clone())).cloned()
                        });
                        match манглированное.and_then(|м| self.модуль.get_function(&м)) {
                            Some(ф) => ф,
                            None => {
                                // НОВОЕ: "как "SDL_Init"" — если "имя" это
                                // русское имя внешней функции с алиасом,
                                // настоящая LLVM-функция зарегистрирована
                                // под РЕАЛЬНЫМ именем (см.
                                // объявить_сигнатуру_внешней_функции) —
                                // ищем через self.внешние_алиасы.
                                match self.внешние_алиасы.get(имя).cloned().and_then(|реальное| self.модуль.get_function(&реальное)) {
                                    Some(ф) => ф,
                                    None => return Err(ошибка(format!("функция '{}' не объявлена", имя))),
                                }
                            }
                        }
                    }
                };

                // НОВОЕ (настоящий полиморфизм через контракты): если
                // соответствующий параметр функции ожидает тип-контракт, а
                // передан аргумент-структура — нужно упаковать его в
                // "толстый указатель" перед передачей, иначе функция
                // получит обычный, "тонкий" указатель там, где ожидает
                // структуру из двух указателей (данные+vtable) — именно
                // так проявился реальный, найденный тестом segfault
                // (чтение мусора вместо vtable, переход по случайному
                // адресу внутри неё).
                let типы_параметров_этой_функции = self.параметры_функций.get(имя).cloned().unwrap_or_default();
                let вычисленные_аргументы: Result<Vec<inkwell::values::BasicMetadataValueEnum>, ОшибкаКодогенерации> = аргументы
                    .iter()
                    .enumerate()
                    .map(|(индекс, а)| {
                        if let Some(Тип::Пользовательский(имя_контракта)) = типы_параметров_этой_функции.get(индекс) {
                            if self.контракты_методы.contains_key(имя_контракта) {
                                return self
                                    .упаковать_в_толстый_указатель(а, имя_контракта)
                                    .map(inkwell::values::BasicMetadataValueEnum::from);
                            }
                        }
                        self.сгенерировать_выражение(а).map(inkwell::values::BasicMetadataValueEnum::from)
                    })
                    .collect();
                let вычисленные_аргументы = вычисленные_аргументы?;

                let результат = self
                    .билдер
                    .build_call(llvm_функция, &вычисленные_аргументы, "вызов")
                    .map_err(|e| ошибка(format!("ошибка вызова функции '{}': {:?}", имя, e)))?;

                // ⚠️ Та же находка, что уже чинили для методов (см.
                // сгенерировать_вызов_метода) — void-функция, вызванная
                // как самостоятельный оператор, законна (побочный эффект,
                // не результат) — заглушка вместо ошибки, семантика уже
                // гарантировала, что реальное значение здесь не потребуется.
                match результат.try_as_basic_value().left() {
                    Some(значение) => Ok(значение),
                    None => Ok(self.контекст.i32_type().const_int(0, false).into()),
                }
            }

            Выражение::ДоступКПолю { объект, поле } => self.сгенерировать_доступ_к_полю(объект, поле),

            Выражение::ВызовМетода { объект, метод, аргументы } => {
                self.сгенерировать_вызов_метода(объект, метод, аргументы)
            }
            Выражение::ДоступПоИндексу { массив, индекс } => self.сгенерировать_доступ_по_индексу(массив, индекс),
            Выражение::МассивЛит(элементы) => self.сгенерировать_массив_литерал(элементы),
            Выражение::Проброс(внутреннее) => self.сгенерировать_проброс(внутреннее),
            Выражение::Успех(внутреннее) => self.сгенерировать_успех(внутреннее),
            Выражение::Ошибка(внутреннее) => self.сгенерировать_ошибку(внутреннее),
        }
    }

    fn сгенерировать_бинарное(
        &mut self,
        левое: &Выражение,
        оператор: БинарныйОператор,
        правое: &Выражение,
    ) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        let л = self.сгенерировать_выражение(левое)?;
        let п = self.сгенерировать_выражение(правое)?;

        // Текст определяем по РЕАЛЬНОМУ LLVM-типу вычисленных значений
        // (указатель), а не по виду AST-узла — тот же принцип, что уже
        // применён в сгенерировать_вызов_вывести при исправлении похожего
        // бага: раньше там различали "текстовый литерал напрямую" от
        // "всего остального", что не работало для переменных/полей текста.
        // Здесь с самого начала делаем правильно.
        if л.get_type().is_pointer_type() && п.get_type().is_pointer_type() {
            let результат = self.сгенерировать_текстовую_операцию(л.into_pointer_value(), оператор, п.into_pointer_value())?;

            // НОВОЕ (текст под ARC, продолжение): освобождаем промежуточные
            // malloc'нутые буферы — если "левое"/"правое" САМИ являются
            // текст-порождающим выражением (вложенная конкатенация, вызов
            // регистр_в_верхний и т.д.), их результат уже скопирован в
            // итоговый буфер (конкатенация) или сравнён и более не нужен
            // (==/!=) — держать его дальше некому. Раньше это было честно
            // названной утечкой на КАЖДОЙ цепочке вида "а + б + в" (средний
            // результат "а + б" никогда не освобождался). Не затрагивает
            // случай, когда операнд — это просто переменная или литерал:
            // тогда мы не владеем этим буфером и не имеем права его
            // освобождать (см. является_текст_порождающим).
            if является_текст_порождающим(левое) {
                let free = self
                    .модуль
                    .get_function("free")
                    .ok_or_else(|| ошибка("внутренняя ошибка: free не была объявлена"))?;
                self.билдер
                    .build_call(free, &[л.into()], "освободить_промежуточный_текст_слева")
                    .map_err(|e| ошибка(format!("ошибка освобождения промежуточного текста: {:?}", e)))?;
            }
            if является_текст_порождающим(правое) {
                let free = self
                    .модуль
                    .get_function("free")
                    .ok_or_else(|| ошибка("внутренняя ошибка: free не была объявлена"))?;
                self.билдер
                    .build_call(free, &[п.into()], "освободить_промежуточный_текст_справа")
                    .map_err(|e| ошибка(format!("ошибка освобождения промежуточного текста: {:?}", e)))?;
            }

            return Ok(результат);
        }

        // Дробные числа определяем так же — по РЕАЛЬНОМУ LLVM-типу, а не
        // по виду AST. Семантика уже гарантирует (проверяет равенство типов
        // операндов), что если один операнд — дробный, второй тоже дробный —
        // но проверяем оба на всякий случай, а не слепо доверяем этой
        // гарантии (защитное программирование).
        //
        // ⚠️ НАЙДЕННЫЙ ДО ЭТОЙ ПРАВКИ РИСК: раньше здесь безусловно вызывался
        // .into_int_value() для ЛЮБОЙ нетекстовой операции — для дробных
        // чисел (FloatValue, не IntValue) это была бы не аккуратная ошибка
        // компиляции, а НАСТОЯЩИЙ КРАХ САМОГО КОМПИЛЯТОРА (паника Rust
        // внутри inkwell). Тип "дробное" существовал в системе типов и
        // парсился, но реальная арифметика над ним была не реализована.
        if л.get_type().is_float_type() || п.get_type().is_float_type() {
            return self.сгенерировать_дробную_операцию(л, оператор, п);
        }

        // Пока поддерживаем только целочисленную арифметику — арифметика с
        // дробными числами обрабатывается отдельным методом выше.
        let (л, п) = (л.into_int_value(), п.into_int_value());

        let результат = match оператор {
            БинарныйОператор::Плюс => self.билдер.build_int_add(л, п, "сумма"),
            БинарныйОператор::Минус => self.билдер.build_int_sub(л, п, "разность"),
            БинарныйОператор::Умножить => self.билдер.build_int_mul(л, п, "произведение"),
            БинарныйОператор::Разделить => self.билдер.build_int_signed_div(л, п, "частное"),
            БинарныйОператор::Остаток => self.билдер.build_int_signed_rem(л, п, "остаток"),
            БинарныйОператор::Равно => self.билдер.build_int_compare(IntPredicate::EQ, л, п, "равно"),
            БинарныйОператор::НеРавно => self.билдер.build_int_compare(IntPredicate::NE, л, п, "неравно"),
            БинарныйОператор::Меньше => self.билдер.build_int_compare(IntPredicate::SLT, л, п, "меньше"),
            БинарныйОператор::Больше => self.билдер.build_int_compare(IntPredicate::SGT, л, п, "больше"),
            БинарныйОператор::МеньшеРавно => self.билдер.build_int_compare(IntPredicate::SLE, л, п, "меньше_равно"),
            БинарныйОператор::БольшеРавно => self.билдер.build_int_compare(IntPredicate::SGE, л, п, "больше_равно"),
            БинарныйОператор::И => self.билдер.build_and(л, п, "и"),
            БинарныйОператор::Или => self.билдер.build_or(л, п, "или"),
            // НОВОЕ: настоящие побитовые операторы — те же самые LLVM
            // примитивы, что уже использовались для логического &&/||
            // (build_and/build_or работают на любой разрядности целых
            // чисел, не только на i1), плюс build_xor для '^'.
            БинарныйОператор::БитИ => self.билдер.build_and(л, п, "бит_и"),
            БинарныйОператор::БитИли => self.билдер.build_or(л, п, "бит_или"),
            БинарныйОператор::БитИскл => self.билдер.build_xor(л, п, "бит_искл"),
        };

        результат
            .map(|v| v.into())
            .map_err(|e| ошибка(format!("ошибка генерации бинарной операции: {:?}", e)))
    }

    /// Генерирует операцию над ДВУМЯ текстовыми значениями — сравнение
    /// (через strcmp — сравнение СОДЕРЖИМОГО, а не адресов указателей) или
    /// конкатенацию (выделяем новый буфер под сумму длин + 1 на завершающий
    /// нулевой байт, копируем обе строки друг за другом).
    ///
    /// ⚠️ Известное следствие этой реализации: результат конкатенации —
    /// НОВЫЙ malloc-буфер, который никогда не освобождается (текст пока
    /// вообще не участвует в ARC — ни литералы, ни результаты конкатенации
    /// не имеют счётчика ссылок). Это утечка при каждой конкатенации, но
    /// не хуже того, что уже было: текст и раньше никак не управлялся по
    /// памяти, просто раньше не было способа создать НОВУЮ текстовую строку
    /// в принципе (только литералы, живущие как глобальные константы).
    fn сгенерировать_текстовую_операцию(
        &mut self,
        л: PointerValue<'ctx>,
        оператор: БинарныйОператор,
        п: PointerValue<'ctx>,
    ) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        match оператор {
            БинарныйОператор::Равно | БинарныйОператор::НеРавно => {
                let strcmp = self
                    .модуль
                    .get_function("strcmp")
                    .ok_or_else(|| ошибка("внутренняя ошибка: strcmp не была объявлена"))?;
                let результат_strcmp = self
                    .билдер
                    .build_call(strcmp, &[л.into(), п.into()], "strcmp_вызов")
                    .map_err(|e| ошибка(format!("ошибка сравнения текста: {:?}", e)))?
                    .try_as_basic_value()
                    .left()
                    .ok_or_else(|| ошибка("strcmp неожиданно не вернул значение"))?
                    .into_int_value();

                let ноль = self.контекст.i32_type().const_int(0, false);
                let условие = if оператор == БинарныйОператор::Равно { IntPredicate::EQ } else { IntPredicate::NE };
                self.билдер
                    .build_int_compare(условие, результат_strcmp, ноль, "текст_сравнение")
                    .map(|v| v.into())
                    .map_err(|e| ошибка(format!("ошибка сравнения текста: {:?}", e)))
            }

            БинарныйОператор::Плюс => {
                let strlen = self
                    .модуль
                    .get_function("strlen")
                    .ok_or_else(|| ошибка("внутренняя ошибка: strlen не была объявлена"))?;
                let malloc = self
                    .модуль
                    .get_function("malloc")
                    .ok_or_else(|| ошибка("внутренняя ошибка: malloc не была объявлена"))?;
                let memcpy = self
                    .модуль
                    .get_function("memcpy")
                    .ok_or_else(|| ошибка("внутренняя ошибка: memcpy не была объявлена"))?;

                let длина_л = self
                    .билдер
                    .build_call(strlen, &[л.into()], "длина_л")
                    .map_err(|e| ошибка(format!("ошибка вычисления длины текста: {:?}", e)))?
                    .try_as_basic_value()
                    .left()
                    .ok_or_else(|| ошибка("strlen неожиданно не вернул значение"))?
                    .into_int_value();
                let длина_п = self
                    .билдер
                    .build_call(strlen, &[п.into()], "длина_п")
                    .map_err(|e| ошибка(format!("ошибка вычисления длины текста: {:?}", e)))?
                    .try_as_basic_value()
                    .left()
                    .ok_or_else(|| ошибка("strlen неожиданно не вернул значение"))?
                    .into_int_value();

                let i64_тип = self.контекст.i64_type();
                let сумма_длин = self
                    .билдер
                    .build_int_add(длина_л, длина_п, "сумма_длин")
                    .map_err(|e| ошибка(format!("ошибка сложения длин текста: {:?}", e)))?;
                // +1 — место под завершающий нулевой байт C-строки.
                let размер_буфера = self
                    .билдер
                    .build_int_add(сумма_длин, i64_тип.const_int(1, false), "размер_буфера")
                    .map_err(|e| ошибка(format!("ошибка вычисления размера буфера текста: {:?}", e)))?;

                let новый_буфер = self
                    .билдер
                    .build_call(malloc, &[размер_буфера.into()], "новый_текст")
                    .map_err(|e| ошибка(format!("ошибка выделения памяти для текста: {:?}", e)))?
                    .try_as_basic_value()
                    .left()
                    .ok_or_else(|| ошибка("malloc неожиданно не вернул значение"))?
                    .into_pointer_value();

                // Копируем левую строку в начало буфера.
                self.билдер
                    .build_call(memcpy, &[новый_буфер.into(), л.into(), длина_л.into()], "memcpy_л")
                    .map_err(|e| ошибка(format!("ошибка копирования текста: {:?}", e)))?;

                // Копируем правую строку СРАЗУ ПОСЛЕ левой — адрес назначения
                // сдвинут на длину_л байт от начала буфера (адресная арифметика
                // через однo-индексный GEP, тот же приём, что и в буферах
                // Список<тип>/Словарь<Ключ, Значение>). Копируем длина_п+1 байт, чтобы
                // прихватить завершающий нулевой байт правой строки — тогда
                // результат автоматически становится корректной C-строкой,
                // отдельно дописывать нулевой байт не нужно.
                let байт_тип = self.контекст.i8_type();
                let адрес_после_л = unsafe {
                    self.билдер
                        .build_gep(байт_тип, новый_буфер, &[длина_л], "адрес_после_л")
                        .map_err(|e| ошибка(format!("ошибка адресации при конкатенации текста: {:?}", e)))?
                };
                let длина_п_с_нулём = self
                    .билдер
                    .build_int_add(длина_п, i64_тип.const_int(1, false), "длина_п_с_нулём")
                    .map_err(|e| ошибка(format!("ошибка вычисления длины при конкатенации: {:?}", e)))?;
                self.билдер
                    .build_call(memcpy, &[адрес_после_л.into(), п.into(), длина_п_с_нулём.into()], "memcpy_п")
                    .map_err(|e| ошибка(format!("ошибка копирования текста: {:?}", e)))?;

                Ok(новый_буфер.into())
            }

            other => Err(ошибка(format!(
                "оператор {:?} не применим к тексту — для текста поддержаны только '+' (склейка) и '==', '!=' (сравнение содержимого)",
                other
            ))),
        }
    }

    /// Генерирует операцию над ДВУМЯ дробными значениями. Отдельная,
    /// независимая от целочисленной ветка — через build_float_* методы
    /// вместо build_int_*, и FloatPredicate вместо IntPredicate для
    /// сравнений (варианты "O..." — "ordered", стандартное для большинства
    /// языков поведение: сравнение считается false, если один из операндов
    /// NaN, а не паникует и не даёт неопределённый результат).
    fn сгенерировать_дробную_операцию(
        &mut self,
        л: BasicValueEnum<'ctx>,
        оператор: БинарныйОператор,
        п: BasicValueEnum<'ctx>,
    ) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        let (л, п) = (л.into_float_value(), п.into_float_value());

        match оператор {
            БинарныйОператор::Плюс => self
                .билдер
                .build_float_add(л, п, "дробная_сумма")
                .map(|v| v.into())
                .map_err(|e| ошибка(format!("ошибка сложения дробных чисел: {:?}", e))),
            БинарныйОператор::Минус => self
                .билдер
                .build_float_sub(л, п, "дробная_разность")
                .map(|v| v.into())
                .map_err(|e| ошибка(format!("ошибка вычитания дробных чисел: {:?}", e))),
            БинарныйОператор::Умножить => self
                .билдер
                .build_float_mul(л, п, "дробное_произведение")
                .map(|v| v.into())
                .map_err(|e| ошибка(format!("ошибка умножения дробных чисел: {:?}", e))),
            БинарныйОператор::Разделить => self
                .билдер
                .build_float_div(л, п, "дробное_частное")
                .map(|v| v.into())
                .map_err(|e| ошибка(format!("ошибка деления дробных чисел: {:?}", e))),
            БинарныйОператор::Остаток => self
                .билдер
                .build_float_rem(л, п, "дробный_остаток")
                .map(|v| v.into())
                .map_err(|e| ошибка(format!("ошибка вычисления остатка дробных чисел: {:?}", e))),
            БинарныйОператор::Равно => self
                .билдер
                .build_float_compare(FloatPredicate::OEQ, л, п, "дробное_равно")
                .map(|v| v.into())
                .map_err(|e| ошибка(format!("ошибка сравнения дробных чисел: {:?}", e))),
            БинарныйОператор::НеРавно => self
                .билдер
                .build_float_compare(FloatPredicate::ONE, л, п, "дробное_неравно")
                .map(|v| v.into())
                .map_err(|e| ошибка(format!("ошибка сравнения дробных чисел: {:?}", e))),
            БинарныйОператор::Меньше => self
                .билдер
                .build_float_compare(FloatPredicate::OLT, л, п, "дробное_меньше")
                .map(|v| v.into())
                .map_err(|e| ошибка(format!("ошибка сравнения дробных чисел: {:?}", e))),
            БинарныйОператор::Больше => self
                .билдер
                .build_float_compare(FloatPredicate::OGT, л, п, "дробное_больше")
                .map(|v| v.into())
                .map_err(|e| ошибка(format!("ошибка сравнения дробных чисел: {:?}", e))),
            БинарныйОператор::МеньшеРавно => self
                .билдер
                .build_float_compare(FloatPredicate::OLE, л, п, "дробное_меньше_равно")
                .map(|v| v.into())
                .map_err(|e| ошибка(format!("ошибка сравнения дробных чисел: {:?}", e))),
            БинарныйОператор::БольшеРавно => self
                .билдер
                .build_float_compare(FloatPredicate::OGE, л, п, "дробное_больше_равно")
                .map(|v| v.into())
                .map_err(|e| ошибка(format!("ошибка сравнения дробных чисел: {:?}", e))),
            БинарныйОператор::И | БинарныйОператор::Или => Err(ошибка(format!(
                "оператор {:?} не применим к дробным числам (только к 'верно')",
                оператор
            ))),
            // НОВОЕ: настоящие побитовые операторы — семантика уже
            // запрещает их для дробных чисел на этапе проверки типов,
            // сюда компиляция дойти не должна, но match обязан быть
            // исчерпывающим.
            БинарныйОператор::БитИ | БинарныйОператор::БитИли | БинарныйОператор::БитИскл => Err(ошибка(format!(
                "оператор {:?} не применим к дробным числам (только к целым)",
                оператор
            ))),
        }
    }

    fn сгенерировать_унарное(
        &mut self,
        оператор: УнарныйОператор,
        операнд: &Выражение,
    ) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        let значение = self.сгенерировать_выражение(операнд)?;

        // Та же находка, что и в сгенерировать_бинарное: раньше здесь
        // безусловно вызывался .into_int_value() — для унарного минуса
        // над дробным числом ("-3.5") это была бы паника Rust внутри
        // inkwell, не аккуратная ошибка компиляции.
        if значение.get_type().is_float_type() {
            let значение = значение.into_float_value();
            return match оператор {
                УнарныйОператор::Минус => self
                    .билдер
                    .build_float_neg(значение, "дробный_минус")
                    .map(|v| v.into())
                    .map_err(|e| ошибка(format!("ошибка генерации унарного минуса для дробного числа: {:?}", e))),
                УнарныйОператор::Не => Err(ошибка(
                    "оператор '!' не применим к дробным числам (только к 'верно')",
                )),
                // НОВОЕ: побитовое отрицание тоже не применимо к дробным.
                УнарныйОператор::БитНе => Err(ошибка(
                    "оператор '~' не применим к дробным числам (только к целым)",
                )),
            };
        }

        let значение = значение.into_int_value();
        let результат = match оператор {
            УнарныйОператор::Минус => self.билдер.build_int_neg(значение, "минус"),
            УнарныйОператор::Не => self.билдер.build_not(значение, "не"),
            // НОВОЕ: побитовое отрицание — та же самая LLVM-функция, что
            // уже использовалась для логического '!' (build_not работает
            // на любой разрядности целых чисел, не только на i1).
            УнарныйОператор::БитНе => self.билдер.build_not(значение, "бит_не"),
        };
        результат
            .map(|v| v.into())
            .map_err(|e| ошибка(format!("ошибка генерации унарной операции: {:?}", e)))
    }

    /// Текстовый литерал становится глобальной константой в модуле (данные
    /// зашиты прямо в бинарник), а само выражение — указателем на неё.
    /// Это стандартный, простой подход для строковых констант в LLVM.
    fn сгенерировать_текстовый_литерал(&mut self, текст: &str) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        self.счётчик_строк += 1;
        let имя_константы = format!("текст_{}", self.счётчик_строк);

        let глобальная = self
            .билдер
            .build_global_string_ptr(текст, &имя_константы)
            .map_err(|e| ошибка(format!("ошибка создания строковой константы: {:?}", e)))?;

        Ok(глобальная.as_pointer_value().into())
    }

    /// вывести(...) — на этом этапе не пользовательская функция языка "Сфера",
    /// а служебная конструкция компилятора, которая транслируется напрямую в
    /// вызов printf. В будущем, когда появится стандартная библиотека самого
    /// языка, "вывести" должна стать обычной функцией ЭТОЙ библиотеки, а не
    /// специальным случаем в кодогенераторе — но для честного hello world
    /// сейчас этого достаточно и это явно помечено как временное решение.
    fn сгенерировать_вызов_вывести(&mut self, аргументы: &[Выражение]) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        if аргументы.len() != 1 {
            return Err(ошибка("вывести(...) сейчас поддерживает ровно один аргумент"));
        }

        let printf = self
            .модуль
            .get_function("printf")
            .ok_or_else(|| ошибка("внутренняя ошибка: printf не была объявлена"))?;

        // Интерполированная строка ("Привет, $имя!") — особый случай, не
        // проходящий через обычный сгенерировать_выражение (у нас физически
        // нет способа построить ОДНО текстовое значение из неё без runtime
        // конкатенации строк, которой пока нет — см. README). Вместо этого
        // превращаем фрагменты НАПРЯМУЮ в printf: текстовые куски идут в
        // формат-строку буквально, а переменные — в format-спецификаторы
        // (%s/%lld) и передаются как отдельные variadic-аргументы printf.
        // Именно поэтому интерполяция работает ТОЛЬКО как прямой аргумент
        // вывести(...) — сама printf-механика не даёт способа "сохранить"
        // результат в обычную переменную языка "Сфера".
        if let Выражение::ИнтерполированныйТекст(фрагменты) = &аргументы[0] {
            return self.сгенерировать_вывести_с_интерполяцией(фрагменты, printf);
        }

        // Раньше здесь было раздельное поведение "текстовый литерал" vs
        // "любое другое выражение" (последнее — всегда через формат %lld),
        // что было НАСТОЯЩИМ БАГОМ: любое текстовое ВЫРАЖЕНИЕ, не являющееся
        // литералом напрямую (переменная, поле структуры, псевдополе
        // результат<тип>.сообщение и т.д.), печаталось бы как число —
        // указатель интерпретировался бы как i64, выводя мусор. Теперь формат
        // печати выбирается по РЕАЛЬНОМУ типу вычисленного значения, а не по
        // виду AST-узла — это единственный надёжный способ.
        let значение = self.сгенерировать_выражение(&аргументы[0])?;

        // ⚠️ НАЙДЕННЫЙ ПРИ ПОВТОРНОЙ ПРОВЕРКЕ ПРОБЕЛ (не паника, но реальное
        // ограничение): раньше дробные числа здесь не обрабатывались вообще
        // и попадали в общий "other => ошибка" — значит после того, как мы
        // реализовали арифметику над "дробное", результат этой арифметики
        // всё ещё нельзя было НАПЕЧАТАТЬ. Теперь обрабатывается отдельно.
        let (формат, значение_для_printf): (&str, BasicValueEnum) = match значение.get_type() {
            BasicTypeEnum::PointerType(_) => ("%s\n", значение),
            BasicTypeEnum::IntType(_) => ("%lld\n", значение),
            BasicTypeEnum::FloatType(тип_float) => {
                // Variadic C-функции (как printf) ВСЕГДА получают float как
                // double — стандартное правило C ABI "default argument
                // promotion". Если у нас f32 ("дробное32"), нужно ЯВНО
                // расширить его до f64 перед передачей — иначе printf
                // прочитает несовпадающий по размеру мусор из variadic-
                // аргументов (в отличие от обычных, не variadic вызовов,
                // где компилятор сам заботится о типах параметров).
                let f64_тип = self.контекст.f64_type();
                if тип_float == self.контекст.f32_type() {
                    let расширенное = self
                        .билдер
                        .build_float_ext(значение.into_float_value(), f64_тип, "дробное_расширенное_для_вывести")
                        .map_err(|e| ошибка(format!("ошибка расширения дробного числа для вывести: {:?}", e)))?;
                    ("%f\n", расширенное.into())
                } else {
                    ("%f\n", значение)
                }
            }
            other => {
                return Err(ошибка(format!(
                    "вывести(...) пока поддерживает только текст, целое или дробное число, получен тип {:?}",
                    other
                )));
            }
        };
        let формат_значение = self.сгенерировать_текстовый_литерал(формат)?;

        self.билдер
            .build_call(printf, &[формат_значение.into(), значение_для_printf.into()], "вывести_вызов")
            .map_err(|e| ошибка(format!("ошибка вызова вывести: {:?}", e)))?;

        // вывести(...) в языке "Сфера" ничего не возвращает — но printf формально
        // возвращает int, поэтому как выражение-заглушку отдаём 0.
        Ok(self.контекст.i32_type().const_int(0, false).into())
    }

    /// Генерирует "длина(текст)" — просто переиспользует уже объявленную
    /// strlen (та же функция, что уже используется для конкатенации текста).
    fn сгенерировать_длина(&mut self, аргументы: &[Выражение]) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        if аргументы.len() != 1 {
            return Err(ошибка("длина(...) ожидает ровно один аргумент"));
        }
        let текст_значение = self.сгенерировать_выражение(&аргументы[0])?;
        let strlen = self
            .модуль
            .get_function("strlen")
            .ok_or_else(|| ошибка("внутренняя ошибка: strlen не была объявлена"))?;
        self.билдер
            .build_call(strlen, &[текст_значение.into()], "длина_вызов")
            .map_err(|e| ошибка(format!("ошибка вычисления длины текста: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("strlen неожиданно не вернул значение"))
    }

    /// Генерирует "целое_в_текст(целое)" — форматирует число в новый
    /// текстовый буфер через snprintf. Буфер фиксированного размера (32
    /// байта) — i64 гарантированно умещается (максимум ~20 символов),
    /// поэтому не нужно вызывать snprintf дважды для точного расчёта размера.
    ///
    /// ⚠️ Тот же класс известного следствия, что и у конкатенации текста:
    /// результат — новый malloc-буфер, который никогда не освобождается
    /// (текст пока вообще не участвует в ARC). Небольшая утечка при каждом
    /// вызове, задокументированная, а не скрытая (см. README).
    fn сгенерировать_целое_в_текст(&mut self, аргументы: &[Выражение]) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        if аргументы.len() != 1 {
            return Err(ошибка("целое_в_текст(...) ожидает ровно один аргумент"));
        }
        let число_значение = self.сгенерировать_выражение(&аргументы[0])?;

        let malloc = self
            .модуль
            .get_function("malloc")
            .ok_or_else(|| ошибка("внутренняя ошибка: malloc не была объявлена"))?;
        let i64_тип = self.контекст.i64_type();
        let размер_буфера = i64_тип.const_int(32, false);
        let буфер = self
            .билдер
            .build_call(malloc, &[размер_буфера.into()], "текст_буфер")
            .map_err(|e| ошибка(format!("ошибка выделения буфера для целое_в_текст: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("malloc неожиданно не вернул значение"))?
            .into_pointer_value();

        let snprintf = self
            .модуль
            .get_function("snprintf")
            .ok_or_else(|| ошибка("внутренняя ошибка: snprintf не была объявлена"))?;
        let формат = self.сгенерировать_текстовый_литерал("%lld")?;
        self.билдер
            .build_call(snprintf, &[буфер.into(), размер_буфера.into(), формат.into(), число_значение.into()], "snprintf_вызов")
            .map_err(|e| ошибка(format!("ошибка форматирования числа в текст: {:?}", e)))?;

        Ok(буфер.into())
    }

    /// Генерирует "дробное_в_текст(дробное)" — тот же принцип, что и
    /// "целое_в_текст", через snprintf, но с форматом "%f" и буфером
    /// побольше (64 байта вместо 32 у целых — вывод "%f" обычно длиннее,
    /// хотя для ОЧЕНЬ больших по модулю дробных чисел даже этого буфера
    /// может не хватить, snprintf в этом случае просто обрежет результат
    /// безопасно, без переполнения памяти — известное, а не скрытое
    /// ограничение).
    ///
    /// Та же логика расширения f32 -> f64 перед передачей в variadic
    /// snprintf, что уже применена в вывести(...)/интерполяции строк (см.
    /// подробный комментарий там же про "default argument promotion") —
    /// именно эта симметрия и была причиной добавить эту функцию: если
    /// её не было, а вывести(дробное) уже умела печатать напрямую, разница
    /// была не всегда очевидна пользователю языка.
    fn сгенерировать_дробное_в_текст(&mut self, аргументы: &[Выражение]) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        if аргументы.len() != 1 {
            return Err(ошибка("дробное_в_текст(...) ожидает ровно один аргумент"));
        }
        let число_значение = self.сгенерировать_выражение(&аргументы[0])?;

        let f64_тип = self.контекст.f64_type();
        let число_как_f64: BasicValueEnum = if число_значение.get_type() == self.контекст.f32_type().into() {
            self.билдер
                .build_float_ext(число_значение.into_float_value(), f64_тип, "дробное_расширенное_для_текста")
                .map_err(|e| ошибка(format!("ошибка расширения дробного числа: {:?}", e)))?
                .into()
        } else {
            число_значение
        };

        let malloc = self
            .модуль
            .get_function("malloc")
            .ok_or_else(|| ошибка("внутренняя ошибка: malloc не была объявлена"))?;
        let i64_тип = self.контекст.i64_type();
        let размер_буфера = i64_тип.const_int(64, false);
        let буфер = self
            .билдер
            .build_call(malloc, &[размер_буфера.into()], "текст_буфер_дробного")
            .map_err(|e| ошибка(format!("ошибка выделения буфера для дробное_в_текст: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("malloc неожиданно не вернул значение"))?
            .into_pointer_value();

        let snprintf = self
            .модуль
            .get_function("snprintf")
            .ok_or_else(|| ошибка("внутренняя ошибка: snprintf не была объявлена"))?;
        let формат = self.сгенерировать_текстовый_литерал("%f")?;
        self.билдер
            .build_call(snprintf, &[буфер.into(), размер_буфера.into(), формат.into(), число_как_f64.into()], "snprintf_вызов_дробного")
            .map_err(|e| ошибка(format!("ошибка форматирования дробного числа в текст: {:?}", e)))?;

        Ok(буфер.into())
    }


    /// strtol, возвращая результат<целое>: успех(число), если удалось
    /// распознать хотя бы одну цифру, иначе ошибка(...) — та же модель,
    /// что уже применена в Словарь.получить(...), переиспользуем те же
    /// вспомогательные методы построения результата.
    fn сгенерировать_текст_в_целое(&mut self, аргументы: &[Выражение]) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        if аргументы.len() != 1 {
            return Err(ошибка("текст_в_целое(...) ожидает ровно один аргумент"));
        }
        let текст_значение = self.сгенерировать_выражение(&аргументы[0])?.into_pointer_value();

        let strtol = self
            .модуль
            .get_function("strtol")
            .ok_or_else(|| ошибка("внутренняя ошибка: strtol не была объявлена"))?;

        // strtol принимает "конец" как out-параметр (char**) — нужна ячейка
        // в стеке, куда strtol запишет указатель на символ, где остановился.
        let текст_указатель_тип = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default());
        let конец_ячейка = self
            .билдер
            .build_alloca(текст_указатель_тип, "конец_разбора")
            .map_err(|e| ошибка(format!("ошибка выделения памяти для текст_в_целое: {:?}", e)))?;

        let десять = self.контекст.i32_type().const_int(10, false);
        let результат_strtol = self
            .билдер
            .build_call(strtol, &[текст_значение.into(), конец_ячейка.into(), десять.into()], "strtol_вызов")
            .map_err(|e| ошибка(format!("ошибка разбора текста в число: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("strtol неожиданно не вернул значение"))?;

        let конец_значение = self
            .билдер
            .build_load(текст_указатель_тип, конец_ячейка, "конец_значение")
            .map_err(|e| ошибка(format!("ошибка чтения результата разбора: {:?}", e)))?
            .into_pointer_value();

        // Если "конец" совпадает с началом строки — strtol не сдвинулся ни
        // на символ, значит не распознал ни одной цифры (строка не была
        // числом, например "абв" или пустая строка).
        let разбор_не_удался = self
            .билдер
            .build_int_compare(IntPredicate::EQ, конец_значение, текст_значение, "разбор_не_удался")
            .map_err(|e| ошибка(format!("ошибка проверки результата разбора: {:?}", e)))?;

        let функция = self
            .текущая_функция
            .ok_or_else(|| ошибка("внутренняя ошибка: 'текст_в_целое' вызван вне тела функции"))?;

        let i64_тип = self.контекст.i64_type();
        let тип_результата = тип_результата_llvm(self.контекст, i64_тип.into());
        let результат_alloca = self
            .билдер
            .build_alloca(тип_результата, "текст_в_целое_результат")
            .map_err(|e| ошибка(format!("ошибка выделения памяти для результата: {:?}", e)))?;

        let блок_успех = self.контекст.append_basic_block(функция, "текст_в_целое_успех");
        let блок_ошибка = self.контекст.append_basic_block(функция, "текст_в_целое_ошибка");
        let блок_конец = self.контекст.append_basic_block(функция, "текст_в_целое_конец");

        self.билдер
            .build_conditional_branch(разбор_не_удался, блок_ошибка, блок_успех)
            .map_err(|e| ошибка(format!("ошибка ветвления текст_в_целое: {:?}", e)))?;

        self.билдер.position_at_end(блок_успех);
        let результат_успех = self.построить_результат_успех(i64_тип.into(), результат_strtol)?;
        self.билдер
            .build_store(результат_alloca, результат_успех)
            .map_err(|e| ошибка(format!("ошибка сохранения результата text_в_целое: {:?}", e)))?;
        self.билдер
            .build_unconditional_branch(блок_конец)
            .map_err(|e| ошибка(format!("ошибка перехода после успешного разбора: {:?}", e)))?;

        self.билдер.position_at_end(блок_ошибка);
        let сообщение = self.сгенерировать_текстовый_литерал("не удалось разобрать текст как целое число")?;
        let результат_ошибка = self.построить_результат_ошибка(i64_тип.into(), сообщение)?;
        self.билдер
            .build_store(результат_alloca, результат_ошибка)
            .map_err(|e| ошибка(format!("ошибка сохранения результата текст_в_целое: {:?}", e)))?;
        self.билдер
            .build_unconditional_branch(блок_конец)
            .map_err(|e| ошибка(format!("ошибка перехода после неудачного разбора: {:?}", e)))?;

        self.билдер.position_at_end(блок_конец);
        self.билдер
            .build_load(тип_результата, результат_alloca, "итоговый_результат")
            .map_err(|e| ошибка(format!("ошибка чтения итогового результата текст_в_целое: {:?}", e)))
    }

    /// Генерирует "абс(целое)" — через build_select, без ветвления базовых
    /// блоков (тот же приём, что уже использован для "новая_вместимость"
    /// в Список<тип>.добавить): "если х < 0, взять -х, иначе х".
    fn сгенерировать_абс(&mut self, аргументы: &[Выражение]) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        if аргументы.len() != 1 {
            return Err(ошибка("абс(...) ожидает ровно один аргумент"));
        }
        let значение = self.сгенерировать_выражение(&аргументы[0])?.into_int_value();
        let тип = значение.get_type();
        let ноль = тип.const_int(0, false);

        let отрицательное = self
            .билдер
            .build_int_compare(IntPredicate::SLT, значение, ноль, "отрицательное")
            .map_err(|e| ошибка(format!("ошибка вычисления абс: {:?}", e)))?;
        let противоположное = self
            .билдер
            .build_int_sub(ноль, значение, "противоположное")
            .map_err(|e| ошибка(format!("ошибка вычисления абс: {:?}", e)))?;

        self.билдер
            .build_select(отрицательное, противоположное, значение, "абс_результат")
            .map_err(|e| ошибка(format!("ошибка вычисления абс: {:?}", e)))
    }

    /// Генерирует "мин(а, б)"/"макс(а, б)" — один общий метод для обоих,
    /// различаются только предиктом сравнения (SLT для мин: "если а < б,
    /// взять а, иначе б"; SGT для макс: "если а > б, взять а, иначе б").
    fn сгенерировать_мин_макс(&mut self, аргументы: &[Выражение], предикат: IntPredicate) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        if аргументы.len() != 2 {
            return Err(ошибка("ожидается ровно два аргумента"));
        }
        let а = self.сгенерировать_выражение(&аргументы[0])?.into_int_value();
        let б = self.сгенерировать_выражение(&аргументы[1])?.into_int_value();

        let условие = self
            .билдер
            .build_int_compare(предикат, а, б, "мин_макс_сравнение")
            .map_err(|e| ошибка(format!("ошибка вычисления мин/макс: {:?}", e)))?;

        self.билдер
            .build_select(условие, а, б, "мин_макс_результат")
            .map_err(|e| ошибка(format!("ошибка вычисления мин/макс: {:?}", e)))
    }

    /// Генерирует "верно_в_текст(верно)" — "да" или "нет", без ветвления
    /// базовых блоков (build_select между двумя уже готовыми текстовыми
    /// константами).
    fn сгенерировать_верно_в_текст(&mut self, аргументы: &[Выражение]) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        if аргументы.len() != 1 {
            return Err(ошибка("верно_в_текст(...) ожидает ровно один аргумент"));
        }
        let значение = self.сгенерировать_выражение(&аргументы[0])?.into_int_value();
        let да = self.сгенерировать_текстовый_литерал("да")?;
        let нет = self.сгенерировать_текстовый_литерал("нет")?;

        self.билдер
            .build_select(значение, да, нет, "верно_в_текст_результат")
            .map_err(|e| ошибка(format!("ошибка преобразования верно_в_текст: {:?}", e)))
    }

    /// Общий помощник для "содержит"/"найти" — оба вызывают strstr и
    /// работают с одним и тем же результатом (указатель на первое вхождение
    /// подстроки, или null, если не найдено), различается только то, что
    /// они делают ДАЛЬШЕ с этим результатом.
    fn вызвать_strstr(&mut self, аргументы: &[Выражение], имя_вызывающей: &str) -> Result<(PointerValue<'ctx>, PointerValue<'ctx>), ОшибкаКодогенерации> {
        if аргументы.len() != 2 {
            return Err(ошибка(format!("{}(...) ожидает ровно два аргумента (текст, подстрока)", имя_вызывающей)));
        }
        let текст_значение = self.сгенерировать_выражение(&аргументы[0])?.into_pointer_value();
        let подстрока_значение = self.сгенерировать_выражение(&аргументы[1])?.into_pointer_value();

        let strstr = self
            .модуль
            .get_function("strstr")
            .ok_or_else(|| ошибка("внутренняя ошибка: strstr не была объявлена"))?;
        let результат = self
            .билдер
            .build_call(strstr, &[текст_значение.into(), подстрока_значение.into()], "strstr_вызов")
            .map_err(|e| ошибка(format!("ошибка поиска подстроки: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("strstr неожиданно не вернул значение"))?
            .into_pointer_value();

        Ok((текст_значение, результат))
    }

    /// Генерирует "содержит(текст, подстрока)" — просто проверяет, что
    /// strstr вернул НЕ null (build_is_null + инверсия через build_not,
    /// тот же build_is_null, что уже использован для роста буферов
    /// Список<тип>/Словарь<Ключ, Значение>).
    fn сгенерировать_содержит(&mut self, аргументы: &[Выражение]) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        let (_, найденный_указатель) = self.вызвать_strstr(аргументы, "содержит")?;
        let не_найдено = self
            .билдер
            .build_is_null(найденный_указатель, "не_найдено")
            .map_err(|e| ошибка(format!("ошибка проверки результата поиска: {:?}", e)))?;
        self.билдер
            .build_not(не_найдено, "содержит_результат")
            .map_err(|e| ошибка(format!("ошибка вычисления содержит: {:?}", e)))
            .map(|v| v.into())
    }

    /// Генерирует "найти(текст, подстрока) -> результат<целое>" — если
    /// strstr вернул null, результат — ошибка("подстрока не найдена");
    /// иначе вычисляем ИНДЕКС вхождения через разницу адресов (приводим оба
    /// указателя к i64 через build_ptr_to_int и вычитаем — "найденный
    /// адрес минус начальный адрес строки = смещение в байтах, оно же
    /// индекс первого символа найденной подстроки").
    ///
    /// ⚠️ build_ptr_to_int — новая техника, не встречавшаяся раньше в этом
    /// компиляторе (везде до этого мы работали с указателями напрямую,
    /// без явного превращения в целое число).
    fn сгенерировать_найти(&mut self, аргументы: &[Выражение]) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        let (текст_указатель, найденный_указатель) = self.вызвать_strstr(аргументы, "найти")?;

        let функция = self
            .текущая_функция
            .ok_or_else(|| ошибка("внутренняя ошибка: 'найти' вызван вне тела функции"))?;
        let i64_тип = self.контекст.i64_type();
        let тип_результата = тип_результата_llvm(self.контекст, i64_тип.into());
        let результат_alloca = self
            .билдер
            .build_alloca(тип_результата, "найти_результат")
            .map_err(|e| ошибка(format!("ошибка выделения памяти для результата 'найти': {:?}", e)))?;

        let не_найдено = self
            .билдер
            .build_is_null(найденный_указатель, "не_найдено")
            .map_err(|e| ошибка(format!("ошибка проверки результата поиска: {:?}", e)))?;

        let блок_найдено = self.контекст.append_basic_block(функция, "найти_найдено");
        let блок_не_найдено = self.контекст.append_basic_block(функция, "найти_не_найдено");
        let блок_конец = self.контекст.append_basic_block(функция, "найти_конец");

        self.билдер
            .build_conditional_branch(не_найдено, блок_не_найдено, блок_найдено)
            .map_err(|e| ошибка(format!("ошибка ветвления 'найти': {:?}", e)))?;

        self.билдер.position_at_end(блок_найдено);
        let текст_как_число = self
            .билдер
            .build_ptr_to_int(текст_указатель, i64_тип, "текст_как_число")
            .map_err(|e| ошибка(format!("ошибка вычисления индекса 'найти': {:?}", e)))?;
        let найденное_как_число = self
            .билдер
            .build_ptr_to_int(найденный_указатель, i64_тип, "найденное_как_число")
            .map_err(|e| ошибка(format!("ошибка вычисления индекса 'найти': {:?}", e)))?;
        let индекс = self
            .билдер
            .build_int_sub(найденное_как_число, текст_как_число, "индекс_вхождения")
            .map_err(|e| ошибка(format!("ошибка вычисления индекса 'найти': {:?}", e)))?;
        let результат_успех = self.построить_результат_успех(i64_тип.into(), индекс.into())?;
        self.билдер
            .build_store(результат_alloca, результат_успех)
            .map_err(|e| ошибка(format!("ошибка сохранения результата 'найти': {:?}", e)))?;
        self.билдер
            .build_unconditional_branch(блок_конец)
            .map_err(|e| ошибка(format!("ошибка перехода после успешного поиска: {:?}", e)))?;

        self.билдер.position_at_end(блок_не_найдено);
        let сообщение = self.сгенерировать_текстовый_литерал("подстрока не найдена")?;
        let результат_ошибка = self.построить_результат_ошибка(i64_тип.into(), сообщение)?;
        self.билдер
            .build_store(результат_alloca, результат_ошибка)
            .map_err(|e| ошибка(format!("ошибка сохранения результата 'найти': {:?}", e)))?;
        self.билдер
            .build_unconditional_branch(блок_конец)
            .map_err(|e| ошибка(format!("ошибка перехода после неудачного поиска: {:?}", e)))?;

        self.билдер.position_at_end(блок_конец);
        self.билдер
            .build_load(тип_результата, результат_alloca, "итоговый_результат")
            .map_err(|e| ошибка(format!("ошибка чтения итогового результата 'найти': {:?}", e)))
    }

    /// Генерирует "регистр_в_верхний(текст)" / "регистр_в_нижний(текст)" —
    /// смена регистра, КОРРЕКТНО работающая для кириллицы, не только латиницы
    /// (в отличие от стандартных `toupper`/`tolower` из libc, которые вне
    /// латинского алфавита обычно ничего не делают — что было бы почти
    /// бесполезно для языка с кириллическими идентификаторами).
    ///
    /// ⚠️ АРХИТЕКТУРНАЯ СЛОЖНОСТЬ, из-за которой эта функция была отложена
    /// раньше в разработке: строчные кириллические буквы (U+0430-U+044F)
    /// В UTF-8 ПЕРЕСЕКАЮТ границу между двумя ведущими байтами — а-п кодируются
    /// как 0xD0 [0xB0-0xBF], а р-я — уже как 0xD1 [0x80-0x8F] (другой ведущий
    /// байт!). Значит смена регистра иногда меняет ОБА байта пары, не только
    /// один — это не простая арифметика "прибавить/вычесть константу ко
    /// ВСЕМ байтам", как для латиницы. Плюс отдельный, вне общего диапазона
    /// случай — Ё (0xD0 0x81) / ё (0xD1 0x91).
    ///
    /// ⚠️ БЕЗОПАСНОСТЬ ДЛЯ ОСТАЛЬНОГО UTF-8: байты 0xD0/0xD1 физически НЕ
    /// МОГУТ быть "продолжающими" байтами (continuation bytes) внутри
    /// ЧУЖОЙ многобайтовой последовательности — валидные continuation-байты
    /// всегда имеют вид "10xxxxxx" (диапазон 0x80-0xBF), а 0xD0/0xD1 — это
    /// "1101xxxx" (ведущий байт, не продолжающий). Значит наш алгоритм —
    /// "заметил 0xD0/0xD1 — обработай как начало кириллической пары,
    /// ИНАЧЕ — скопируй байт как есть" — БЕЗОПАСЕН для ЛЮБОГО валидного
    /// UTF-8 (других алфавитов, эмодзи, чего угодно): такие символы просто
    /// не будут изменены (не задача этой функции), но и не будут повреждены
    /// — каждый их байт копируется байт-в-байт на то же самое место в
    /// буфере ТОГО ЖЕ размера, что и исходный текст (длина в байтах не
    /// меняется НИ для одного из наших преобразований — ASCII 1 байт
    /// остаётся 1 байтом, кириллица 2 байта остаётся 2 байтами).
    /// Генерирует "подстрока(текст, начало, длина) -> результат<текст>" —
    /// извлекает "длина" БАЙТ, начиная с байтового смещения "начало".
    /// Возвращает результат<текст> — если запрошенный диапазон выходит за
    /// границы строки (отрицательное начало/длина, или начало+длина
    /// больше фактической длины текста), безопасно отклоняет как ошибку,
    /// а не читает/пишет за пределы буфера.
    /// Генерирует "прочитать_целое32(указатель, смещение) -> целое32" —
    /// читает 4 байта по адресу (указатель + смещение), интерпретирует
    /// как знаковое 32-битное целое. ПРОЩЕ, чем подстрока() — здесь НЕТ
    /// ветвления (нет проверки границ, эта операция намеренно небезопасна
    /// и полагается на корректность аргументов, переданных программистом
    /// — см. подробное объяснение в semantic.rs) — только вычисление
    /// адреса (GEP) и загрузка (load), без блоков успеха/ошибки.
    /// Генерирует явное приведение числового значения к целевому типу —
    /// "целое32(значение)" и подобные (см. подробное объяснение у функции
    /// информация_числового_типа выше). Определяет исходный "вид" значения
    /// (целое или дробное) прямо по варианту BasicValueEnum — этого
    /// достаточно, поскольку язык уже гарантировал семантически, что
    /// аргумент числовой (см. проверку в semantic.rs).
    fn сгенерировать_приведение_числа(
        &mut self,
        исходное: BasicValueEnum<'ctx>,
        целевой_тип: BasicTypeEnum<'ctx>,
        целевой_дробный: bool,
        целевой_беззнаковый: bool,
    ) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        match исходное {
            inkwell::values::BasicValueEnum::IntValue(исходное_int) => {
                if целевой_дробный {
                    let целевой_float_тип = целевой_тип.into_float_type();
                    // Приведение int -> float: используем СО ЗНАКОМ, если
                    // исходное число само по себе знаковое (наши обычные
                    // целые типы) — беззнаковые исходные типы у нас пока
                    // не отслеживаются на уровне LLVM-значения отдельно
                    // (тип IntValue сам по себе не несёт знаковость), значит
                    // здесь используем знаковое преобразование как разумный
                    // вариант по умолчанию (совпадает с обычным поведением
                    // языка — целые числа по умолчанию знаковые).
                    let результат = self
                        .билдер
                        .build_signed_int_to_float(исходное_int, целевой_float_тип, "приведение_int_в_float")
                        .map_err(|e| ошибка(format!("ошибка приведения целого к дробному: {:?}", e)))?;
                    Ok(результат.into())
                } else {
                    let целевой_int_тип = целевой_тип.into_int_type();
                    let результат = self
                        .билдер
                        .build_int_cast_sign_flag(исходное_int, целевой_int_тип, !целевой_беззнаковый, "приведение_int")
                        .map_err(|e| ошибка(format!("ошибка приведения целого числа: {:?}", e)))?;
                    Ok(результат.into())
                }
            }
            inkwell::values::BasicValueEnum::FloatValue(исходное_float) => {
                if целевой_дробный {
                    let целевой_float_тип = целевой_тип.into_float_type();
                    let результат = self
                        .билдер
                        .build_float_cast(исходное_float, целевой_float_тип, "приведение_float")
                        .map_err(|e| ошибка(format!("ошибка приведения дробного числа: {:?}", e)))?;
                    Ok(результат.into())
                } else {
                    let целевой_int_тип = целевой_тип.into_int_type();
                    let результат = if целевой_беззнаковый {
                        self.билдер
                            .build_float_to_unsigned_int(исходное_float, целевой_int_тип, "приведение_float_в_беззнаковое")
                            .map_err(|e| ошибка(format!("ошибка приведения дробного к целому: {:?}", e)))?
                    } else {
                        self.билдер
                            .build_float_to_signed_int(исходное_float, целевой_int_тип, "приведение_float_в_целое")
                            .map_err(|e| ошибка(format!("ошибка приведения дробного к целому: {:?}", e)))?
                    };
                    Ok(результат.into())
                }
            }
            _ => Err(ошибка("приведение типа применимо только к числовым значениям".to_string())),
        }
    }

    fn сгенерировать_прочитать_целое32(&mut self, аргументы: &[Выражение]) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        if аргументы.len() != 2 {
            return Err(ошибка("прочитать_целое32(...) ожидает ровно два аргумента (указатель, смещение)".to_string()));
        }
        let указатель_значение = self.сгенерировать_выражение(&аргументы[0])?.into_pointer_value();
        let смещение_значение = self.сгенерировать_выражение(&аргументы[1])?.into_int_value();

        let i8_тип = self.контекст.i8_type();
        let i32_тип = self.контекст.i32_type();

        let адрес = unsafe {
            self.билдер
                .build_gep(i8_тип, указатель_значение, &[смещение_значение], "адрес_чтения_целое32")
                .map_err(|e| ошибка(format!("ошибка вычисления адреса: {:?}", e)))?
        };
        let значение = self
            .билдер
            .build_load(i32_тип, адрес, "значение_целое32")
            .map_err(|e| ошибка(format!("ошибка чтения памяти: {:?}", e)))?;

        Ok(значение)
    }

    /// Генерирует "записать_целое32(указатель, смещение, значение)" —
    /// симметрична сгенерировать_прочитать_целое32 (см. её комментарий),
    /// только пишет 4 байта вместо чтения. Значение может прийти любым
    /// целочисленным типом — приводим его к i32 перед записью (та же
    /// логика приведения, что и в сгенерировать_приведение_числа, но
    /// применённая неявно здесь, а не через явный вызов "целое32(...)" —
    /// удобство, раз тип уже гарантированно числовой согласно семантике).
    fn сгенерировать_записать_целое32(&mut self, аргументы: &[Выражение]) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        if аргументы.len() != 3 {
            return Err(ошибка("записать_целое32(...) ожидает ровно три аргумента (указатель, смещение, значение)".to_string()));
        }
        let указатель_значение = self.сгенерировать_выражение(&аргументы[0])?.into_pointer_value();
        let смещение_значение = self.сгенерировать_выражение(&аргументы[1])?.into_int_value();
        let исходное_значение = self.сгенерировать_выражение(&аргументы[2])?.into_int_value();

        let i8_тип = self.контекст.i8_type();
        let i32_тип = self.контекст.i32_type();

        // Приводим значение к i32 (со знаком) — тот же приём, что и в
        // build_int_cast_sign_flag для явного приведения типов, просто
        // применённый неявно, поскольку семантика уже проверила, что
        // значение числовое (см. semantic.rs).
        let значение_i32 = self
            .билдер
            .build_int_cast_sign_flag(исходное_значение, i32_тип, true, "приведение_к_записи_целое32")
            .map_err(|e| ошибка(format!("ошибка приведения значения для записи: {:?}", e)))?;

        let адрес = unsafe {
            self.билдер
                .build_gep(i8_тип, указатель_значение, &[смещение_значение], "адрес_записи_целое32")
                .map_err(|e| ошибка(format!("ошибка вычисления адреса: {:?}", e)))?
        };
        self.билдер
            .build_store(адрес, значение_i32)
            .map_err(|e| ошибка(format!("ошибка записи памяти: {:?}", e)))?;

        // Функция семантически "void" (возвращает Неизвестен) — заглушка,
        // тот же приём, что уже применён для других void-подобных операций
        // (вывести, void-методы как самостоятельный оператор).
        Ok(self.контекст.i32_type().const_int(0, false).into())
    }

    /// Генерирует "прочитать_текст_по_смещению(указатель, смещение) -> текст"
    /// — САМАЯ ПРОСТАЯ из всех примитивов чтения памяти: просто СДВИГАЕТ
    /// адрес (GEP), БЕЗ load — поскольку возвращаемое значение и есть
    /// текст (уже готовая null-terminated строка внутри исходного буфера,
    /// например поле "text" внутри SDL_TextInputEvent), не число для
    /// интерпретации. Валиден, пока жив исходный буфер.
    fn сгенерировать_прочитать_текст_по_смещению(&mut self, аргументы: &[Выражение]) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        if аргументы.len() != 2 {
            return Err(ошибка("прочитать_текст_по_смещению(...) ожидает ровно два аргумента (указатель, смещение)".to_string()));
        }
        let указатель_значение = self.сгенерировать_выражение(&аргументы[0])?.into_pointer_value();
        let смещение_значение = self.сгенерировать_выражение(&аргументы[1])?.into_int_value();

        let i8_тип = self.контекст.i8_type();
        let адрес = unsafe {
            self.билдер
                .build_gep(i8_тип, указатель_значение, &[смещение_значение], "адрес_текста_по_смещению")
                .map_err(|e| ошибка(format!("ошибка вычисления адреса: {:?}", e)))?
        };

        Ok(адрес.into())
    }

    fn сгенерировать_подстрока(&mut self, аргументы: &[Выражение]) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        if аргументы.len() != 3 {
            return Err(ошибка("подстрока(...) ожидает ровно три аргумента (текст, начало, длина)".to_string()));
        }
        let текст_значение = self.сгенерировать_выражение(&аргументы[0])?.into_pointer_value();
        let начало_значение = self.сгенерировать_выражение(&аргументы[1])?.into_int_value();
        let длина_значение = self.сгенерировать_выражение(&аргументы[2])?.into_int_value();

        let i8_тип = self.контекст.i8_type();
        let i64_тип = self.контекст.i64_type();
        let текст_указатель_тип: BasicTypeEnum = i8_тип.ptr_type(inkwell::AddressSpace::default()).into();

        let strlen = self
            .модуль
            .get_function("strlen")
            .ok_or_else(|| ошибка("внутренняя ошибка: strlen не была объявлена"))?;
        let длина_текста = self
            .билдер
            .build_call(strlen, &[текст_значение.into()], "длина_текста_подстрока")
            .map_err(|e| ошибка(format!("ошибка вычисления длины текста: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("strlen неожиданно не вернул значение"))?
            .into_int_value();

        // Приводим "начало"/"длина" (обычные знаковые целые языка) к i64
        // без потери знака (нужен sign-extend, не zero-extend — иначе
        // отрицательное значение стало бы огромным беззнаковым числом,
        // и проверка границ пропустила бы то, что должна отклонить).
        let начало_i64 = self
            .билдер
            .build_int_s_extend(начало_значение, i64_тип, "начало_i64")
            .map_err(|e| ошибка(format!("ошибка приведения индекса: {:?}", e)))?;
        let длина_i64 = self
            .билдер
            .build_int_s_extend(длина_значение, i64_тип, "длина_i64")
            .map_err(|e| ошибка(format!("ошибка приведения длины: {:?}", e)))?;

        let ноль = i64_тип.const_int(0, false);
        let начало_неотрицательно = self
            .билдер
            .build_int_compare(IntPredicate::SGE, начало_i64, ноль, "начало_неотрицательно")
            .map_err(|e| ошибка(format!("ошибка сравнения: {:?}", e)))?;
        let длина_неотрицательна = self
            .билдер
            .build_int_compare(IntPredicate::SGE, длина_i64, ноль, "длина_неотрицательна")
            .map_err(|e| ошибка(format!("ошибка сравнения: {:?}", e)))?;
        let конец = self
            .билдер
            .build_int_add(начало_i64, длина_i64, "конец_подстроки")
            .map_err(|e| ошибка(format!("ошибка вычисления конца диапазона: {:?}", e)))?;
        let конец_в_границах = self
            .билдер
            .build_int_compare(IntPredicate::SLE, конец, длина_текста, "конец_в_границах")
            .map_err(|e| ошибка(format!("ошибка сравнения: {:?}", e)))?;

        let условие_1 = self.билдер.build_and(начало_неотрицательно, длина_неотрицательна, "условие_1").map_err(|e| ошибка(format!("{:?}", e)))?;
        let диапазон_корректен = self.билдер.build_and(условие_1, конец_в_границах, "диапазон_корректен").map_err(|e| ошибка(format!("{:?}", e)))?;

        let функция = self
            .текущая_функция
            .ok_or_else(|| ошибка("внутренняя ошибка: 'подстрока' вызвана вне тела функции"))?;
        let блок_успех = self.контекст.append_basic_block(функция, "подстрока_успех");
        let блок_ошибка = self.контекст.append_basic_block(функция, "подстрока_ошибка");
        let блок_конец_ветвления = self.контекст.append_basic_block(функция, "подстрока_конец");

        // ⚠️ НАЙДЕННЫЙ ПРИ РЕАЛЬНОМ ТЕСТИРОВАНИИ БАГ (реальная программа —
        // сегфолт компилятора при попытке скомпилировать вызов "подстрока",
        // причина — глубоко в LLVMTargetMachineEmit, не сразу очевидная):
        // alloca ДОЛЖНА размещаться в текущем, ЕЩЁ НЕ ЗАВЕРШЁННОМ терминатором
        // блоке — раньше здесь она создавалась ПОСЛЕ build_conditional_branch
        // (который уже завершил блок инструкцией перехода), что добавляло
        // alloca КАК ИНСТРУКЦИЮ ПОСЛЕ ТЕРМИНАТОРА в том же базовом блоке —
        // невалидный LLVM IR, не пойманный на этапе построения (только при
        // попытке реально сгенерировать машинный код). Правильный порядок —
        // сначала alloca, потом ветвление.
        let результат_alloca = self
            .билдер
            .build_alloca(тип_результата_llvm(self.контекст, текст_указатель_тип), "подстрока_результат")
            .map_err(|e| ошибка(format!("ошибка выделения памяти для результата 'подстрока': {:?}", e)))?;

        self.билдер
            .build_conditional_branch(диапазон_корректен, блок_успех, блок_ошибка)
            .map_err(|e| ошибка(format!("ошибка ветвления 'подстрока': {:?}", e)))?;

        self.билдер.position_at_end(блок_успех);
        let malloc = self
            .модуль
            .get_function("malloc")
            .ok_or_else(|| ошибка("внутренняя ошибка: malloc не была объявлена"))?;
        let размер_буфера = self
            .билдер
            .build_int_add(длина_i64, i64_тип.const_int(1, false), "размер_буфера_подстрока")
            .map_err(|e| ошибка(format!("ошибка вычисления размера буфера: {:?}", e)))?;
        let новый_буфер = self
            .билдер
            .build_call(malloc, &[размер_буфера.into()], "буфер_подстрока")
            .map_err(|e| ошибка(format!("ошибка выделения буфера: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("malloc неожиданно не вернул значение"))?
            .into_pointer_value();

        let источник = unsafe {
            self.билдер
                .build_gep(i8_тип, текст_значение, &[начало_i64], "источник_подстрока")
                .map_err(|e| ошибка(format!("ошибка адресации: {:?}", e)))?
        };
        let memcpy = self
            .модуль
            .get_function("memcpy")
            .ok_or_else(|| ошибка("внутренняя ошибка: memcpy не была объявлена"))?;
        self.билдер
            .build_call(memcpy, &[новый_буфер.into(), источник.into(), длина_i64.into()], "memcpy_подстрока")
            .map_err(|e| ошибка(format!("ошибка копирования: {:?}", e)))?;
        let адрес_нуля = unsafe {
            self.билдер
                .build_gep(i8_тип, новый_буфер, &[длина_i64], "адрес_нуля_подстрока")
                .map_err(|e| ошибка(format!("ошибка адресации: {:?}", e)))?
        };
        self.билдер
            .build_store(адрес_нуля, i8_тип.const_int(0, false))
            .map_err(|e| ошибка(format!("ошибка записи нуль-терминатора: {:?}", e)))?;

        let результат_успех = self.построить_результат_успех(текст_указатель_тип, новый_буфер.into())?;
        self.билдер
            .build_store(результат_alloca, результат_успех)
            .map_err(|e| ошибка(format!("ошибка сохранения результата: {:?}", e)))?;
        self.билдер
            .build_unconditional_branch(блок_конец_ветвления)
            .map_err(|e| ошибка(format!("ошибка перехода: {:?}", e)))?;

        self.билдер.position_at_end(блок_ошибка);
        let сообщение = self.сгенерировать_текстовый_литерал("индекс вне границ строки")?;
        let результат_ошибка = self.построить_результат_ошибка(текст_указатель_тип, сообщение)?;
        self.билдер
            .build_store(результат_alloca, результат_ошибка)
            .map_err(|e| ошибка(format!("ошибка сохранения результата: {:?}", e)))?;
        self.билдер
            .build_unconditional_branch(блок_конец_ветвления)
            .map_err(|e| ошибка(format!("ошибка перехода: {:?}", e)))?;

        self.билдер.position_at_end(блок_конец_ветвления);
        self.билдер
            .build_load(тип_результата_llvm(self.контекст, текст_указатель_тип), результат_alloca, "подстрока_итог")
            .map_err(|e| ошибка(format!("ошибка чтения итогового результата 'подстрока': {:?}", e)))
    }


    fn сгенерировать_регистр(&mut self, аргументы: &[Выражение], в_верхний: bool) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        if аргументы.len() != 1 {
            return Err(ошибка(format!(
                "{}(...) ожидает ровно один аргумент",
                if в_верхний { "регистр_в_верхний" } else { "регистр_в_нижний" }
            )));
        }
        let текст_значение = self.сгенерировать_выражение(&аргументы[0])?.into_pointer_value();

        let i8_тип = self.контекст.i8_type();
        let i32_тип = self.контекст.i32_type();
        let i64_тип = self.контекст.i64_type();

        let strlen = self
            .модуль
            .get_function("strlen")
            .ok_or_else(|| ошибка("внутренняя ошибка: strlen не была объявлена"))?;
        let длина = self
            .билдер
            .build_call(strlen, &[текст_значение.into()], "длина_для_регистра")
            .map_err(|e| ошибка(format!("ошибка вычисления длины текста: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("strlen неожиданно не вернул значение"))?
            .into_int_value();

        let malloc = self
            .модуль
            .get_function("malloc")
            .ok_or_else(|| ошибка("внутренняя ошибка: malloc не была объявлена"))?;
        let единица_i64 = i64_тип.const_int(1, false);
        let размер_буфера = self
            .билдер
            .build_int_add(длина, единица_i64, "размер_буфера_регистра")
            .map_err(|e| ошибка(format!("ошибка вычисления размера буфера: {:?}", e)))?;
        let буфер = self
            .билдер
            .build_call(malloc, &[размер_буфера.into()], "буфер_регистра")
            .map_err(|e| ошибка(format!("ошибка выделения буфера для регистра: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("malloc неожиданно не вернул значение"))?
            .into_pointer_value();

        let функция = self
            .текущая_функция
            .ok_or_else(|| ошибка("внутренняя ошибка: смена регистра вызвана вне тела функции"))?;

        let индекс_alloca = self
            .билдер
            .build_alloca(i64_тип, "регистр_индекс")
            .map_err(|e| ошибка(format!("ошибка выделения памяти для индекса: {:?}", e)))?;
        let ноль_i64 = i64_тип.const_int(0, false);
        self.билдер
            .build_store(индекс_alloca, ноль_i64)
            .map_err(|e| ошибка(format!("ошибка инициализации индекса: {:?}", e)))?;

        let блок_условие = self.контекст.append_basic_block(функция, "регистр_условие");
        let блок_тело = self.контекст.append_basic_block(функция, "регистр_тело");
        let блок_проверка_кириллицы = self.контекст.append_basic_block(функция, "регистр_проверка_кириллицы");
        let блок_кириллица = self.контекст.append_basic_block(функция, "регистр_кириллица");
        let блок_ascii = self.контекст.append_basic_block(функция, "регистр_ascii");
        let блок_после = self.контекст.append_basic_block(функция, "регистр_после");

        self.билдер
            .build_unconditional_branch(блок_условие)
            .map_err(|e| ошибка(format!("ошибка перехода к условию цикла регистра: {:?}", e)))?;

        // --- Условие: i < длина? ---
        self.билдер.position_at_end(блок_условие);
        let текущий_индекс = self
            .билдер
            .build_load(i64_тип, индекс_alloca, "текущий_регистр_индекс")
            .map_err(|e| ошибка(format!("ошибка чтения индекса: {:?}", e)))?
            .into_int_value();
        let есть_ещё = self
            .билдер
            .build_int_compare(IntPredicate::ULT, текущий_индекс, длина, "есть_ещё_регистр")
            .map_err(|e| ошибка(format!("ошибка сравнения индекса: {:?}", e)))?;
        self.билдер
            .build_conditional_branch(есть_ещё, блок_тело, блок_после)
            .map_err(|e| ошибка(format!("ошибка ветвления цикла регистра: {:?}", e)))?;

        // --- Тело: читаем b0, решаем — кириллица (2 байта) или нет (1 байт) ---
        self.билдер.position_at_end(блок_тело);
        let адрес_b0 = unsafe {
            self.билдер
                .build_gep(i8_тип, текст_значение, &[текущий_индекс], "адрес_b0")
                .map_err(|e| ошибка(format!("ошибка адресации байта: {:?}", e)))?
        };
        let b0_i8 = self
            .билдер
            .build_load(i8_тип, адрес_b0, "b0_i8")
            .map_err(|e| ошибка(format!("ошибка чтения байта: {:?}", e)))?
            .into_int_value();
        // Приводим к i32 (без знака — байты 0x80-0xFF не должны стать
        // отрицательными при сравнениях ниже) для безопасной арифметики.
        let b0 = self
            .билдер
            .build_int_z_extend(b0_i8, i32_тип, "b0")
            .map_err(|e| ошибка(format!("ошибка расширения байта: {:?}", e)))?;

        let это_d0 = self
            .билдер
            .build_int_compare(IntPredicate::EQ, b0, i32_тип.const_int(0xD0, false), "это_d0")
            .map_err(|e| ошибка(format!("ошибка проверки байта: {:?}", e)))?;
        let это_d1 = self
            .билдер
            .build_int_compare(IntPredicate::EQ, b0, i32_тип.const_int(0xD1, false), "это_d1")
            .map_err(|e| ошибка(format!("ошибка проверки байта: {:?}", e)))?;
        let похоже_на_кириллицу = self
            .билдер
            .build_or(это_d0, это_d1, "похоже_на_кириллицу")
            .map_err(|e| ошибка(format!("ошибка вычисления условия: {:?}", e)))?;

        self.билдер
            .build_conditional_branch(похоже_на_кириллицу, блок_проверка_кириллицы, блок_ascii)
            .map_err(|e| ошибка(format!("ошибка ветвления по типу байта: {:?}", e)))?;

        // --- Проверка кириллицы: защита от чтения за пределы буфера, если
        // 0xD0/0xD1 оказался ПОСЛЕДНИМ байтом строки (обрезанная/невалидная
        // последовательность) — в этом случае просто копируем байт как есть,
        // не читая byte[i+1] (что было бы чтением за пределы буфера). ---
        self.билдер.position_at_end(блок_проверка_кириллицы);
        let индекс_плюс_один = self
            .билдер
            .build_int_add(текущий_индекс, единица_i64, "индекс_плюс_один_регистр")
            .map_err(|e| ошибка(format!("ошибка вычисления индекса: {:?}", e)))?;
        let есть_второй_байт = self
            .билдер
            .build_int_compare(IntPredicate::ULT, индекс_плюс_один, длина, "есть_второй_байт")
            .map_err(|e| ошибка(format!("ошибка сравнения индекса: {:?}", e)))?;
        self.билдер
            .build_conditional_branch(есть_второй_байт, блок_кириллица, блок_ascii)
            .map_err(|e| ошибка(format!("ошибка ветвления защиты границы: {:?}", e)))?;

        // --- Кириллица: читаем b1, вычисляем новые b0'/b1' через select-цепочку ---
        self.билдер.position_at_end(блок_кириллица);
        let адрес_b1 = unsafe {
            self.билдер
                .build_gep(i8_тип, текст_значение, &[индекс_плюс_один], "адрес_b1")
                .map_err(|e| ошибка(format!("ошибка адресации байта: {:?}", e)))?
        };
        let b1_i8 = self
            .билдер
            .build_load(i8_тип, адрес_b1, "b1_i8")
            .map_err(|e| ошибка(format!("ошибка чтения байта: {:?}", e)))?
            .into_int_value();
        let b1 = self
            .билдер
            .build_int_z_extend(b1_i8, i32_тип, "b1")
            .map_err(|e| ошибка(format!("ошибка расширения байта: {:?}", e)))?;

        let к = |n: u64| i32_тип.const_int(n, false);

        // Три случая, ПОЛНОСТЬЮ через build_select (без ветвления базовых
        // блоков) — см. подробную математику диапазонов в doc-комментарии
        // метода выше. Порядок select-ов: каждый следующий "перекрывает"
        // предыдущий итог, если его условие истинно — работает корректно,
        // потому что случаи взаимно исключающие (не могут совпасть два сразу).
        let (случай1, б0_1, б1_1, случай2, б0_2, б1_2, случай3, б0_3, б1_3): (
            inkwell::values::IntValue, inkwell::values::IntValue, inkwell::values::IntValue,
            inkwell::values::IntValue, inkwell::values::IntValue, inkwell::values::IntValue,
            inkwell::values::IntValue, inkwell::values::IntValue, inkwell::values::IntValue,
        ) = if в_верхний {
            // а-п (0xD0,[0xB0-0xBF]) -> А-П (0xD0,[0x90-0x9F]): b0 не меняется, b1 -= 0x20
            let у1 = self.билдер.build_and(это_d0, self.билдер.build_and(
                self.билдер.build_int_compare(IntPredicate::UGE, b1, к(0xB0), "ge").map_err(|e| ошибка(format!("{:?}", e)))?,
                self.билдер.build_int_compare(IntPredicate::ULE, b1, к(0xBF), "le").map_err(|e| ошибка(format!("{:?}", e)))?,
                "and1",
            ).map_err(|e| ошибка(format!("{:?}", e)))?, "случай1").map_err(|e| ошибка(format!("{:?}", e)))?;
            let б0_1 = к(0xD0);
            let б1_1 = self.билдер.build_int_sub(b1, к(0x20), "б1_1").map_err(|e| ошибка(format!("{:?}", e)))?;

            // р-я (0xD1,[0x80-0x8F]) -> Р-Я (0xD0,[0xA0-0xAF]): b0 меняется на 0xD0, b1 += 0x20
            let у2 = self.билдер.build_and(это_d1, self.билдер.build_and(
                self.билдер.build_int_compare(IntPredicate::UGE, b1, к(0x80), "ge").map_err(|e| ошибка(format!("{:?}", e)))?,
                self.билдер.build_int_compare(IntPredicate::ULE, b1, к(0x8F), "le").map_err(|e| ошибка(format!("{:?}", e)))?,
                "and2",
            ).map_err(|e| ошибка(format!("{:?}", e)))?, "случай2").map_err(|e| ошибка(format!("{:?}", e)))?;
            let б0_2 = к(0xD0);
            let б1_2 = self.билдер.build_int_add(b1, к(0x20), "б1_2").map_err(|e| ошибка(format!("{:?}", e)))?;

            // ё (0xD1,0x91) -> Ё (0xD0,0x81)
            let у3 = self.билдер.build_and(это_d1, self.билдер.build_int_compare(IntPredicate::EQ, b1, к(0x91), "eq").map_err(|e| ошибка(format!("{:?}", e)))?, "случай3").map_err(|e| ошибка(format!("{:?}", e)))?;
            let б0_3 = к(0xD0);
            let б1_3 = к(0x81);

            (у1, б0_1, б1_1, у2, б0_2, б1_2, у3, б0_3, б1_3)
        } else {
            // А-П (0xD0,[0x90-0x9F]) -> а-п (0xD0,[0xB0-0xBF]): b0 не меняется, b1 += 0x20
            let у1 = self.билдер.build_and(это_d0, self.билдер.build_and(
                self.билдер.build_int_compare(IntPredicate::UGE, b1, к(0x90), "ge").map_err(|e| ошибка(format!("{:?}", e)))?,
                self.билдер.build_int_compare(IntPredicate::ULE, b1, к(0x9F), "le").map_err(|e| ошибка(format!("{:?}", e)))?,
                "and1",
            ).map_err(|e| ошибка(format!("{:?}", e)))?, "случай1").map_err(|e| ошибка(format!("{:?}", e)))?;
            let б0_1 = к(0xD0);
            let б1_1 = self.билдер.build_int_add(b1, к(0x20), "б1_1").map_err(|e| ошибка(format!("{:?}", e)))?;

            // Р-Я (0xD0,[0xA0-0xAF]) -> р-я (0xD1,[0x80-0x8F]): b0 меняется на 0xD1, b1 -= 0x20
            let у2 = self.билдер.build_and(это_d0, self.билдер.build_and(
                self.билдер.build_int_compare(IntPredicate::UGE, b1, к(0xA0), "ge").map_err(|e| ошибка(format!("{:?}", e)))?,
                self.билдер.build_int_compare(IntPredicate::ULE, b1, к(0xAF), "le").map_err(|e| ошибка(format!("{:?}", e)))?,
                "and2",
            ).map_err(|e| ошибка(format!("{:?}", e)))?, "случай2").map_err(|e| ошибка(format!("{:?}", e)))?;
            let б0_2 = к(0xD1);
            let б1_2 = self.билдер.build_int_sub(b1, к(0x20), "б1_2").map_err(|e| ошибка(format!("{:?}", e)))?;

            // Ё (0xD0,0x81) -> ё (0xD1,0x91)
            let у3 = self.билдер.build_and(это_d0, self.билдер.build_int_compare(IntPredicate::EQ, b1, к(0x81), "eq").map_err(|e| ошибка(format!("{:?}", e)))?, "случай3").map_err(|e| ошибка(format!("{:?}", e)))?;
            let б0_3 = к(0xD1);
            let б1_3 = к(0x91);

            (у1, б0_1, б1_1, у2, б0_2, б1_2, у3, б0_3, б1_3)
        };

        let итог_б0 = self.билдер.build_select(случай1, б0_1, b0, "итог_б0_1").map_err(|e| ошибка(format!("{:?}", e)))?.into_int_value();
        let итог_б0 = self.билдер.build_select(случай2, б0_2, итог_б0, "итог_б0_2").map_err(|e| ошибка(format!("{:?}", e)))?.into_int_value();
        let итог_б0 = self.билдер.build_select(случай3, б0_3, итог_б0, "итог_б0_3").map_err(|e| ошибка(format!("{:?}", e)))?.into_int_value();

        let итог_б1 = self.билдер.build_select(случай1, б1_1, b1, "итог_б1_1").map_err(|e| ошибка(format!("{:?}", e)))?.into_int_value();
        let итог_б1 = self.билдер.build_select(случай2, б1_2, итог_б1, "итог_б1_2").map_err(|e| ошибка(format!("{:?}", e)))?.into_int_value();
        let итог_б1 = self.билдер.build_select(случай3, б1_3, итог_б1, "итог_б1_3").map_err(|e| ошибка(format!("{:?}", e)))?.into_int_value();

        let итог_б0_i8 = self.билдер.build_int_truncate(итог_б0, i8_тип, "итог_б0_i8").map_err(|e| ошибка(format!("{:?}", e)))?;
        let итог_б1_i8 = self.билдер.build_int_truncate(итог_б1, i8_тип, "итог_б1_i8").map_err(|e| ошибка(format!("{:?}", e)))?;

        let выход_адрес_b0 = unsafe {
            self.билдер.build_gep(i8_тип, буфер, &[текущий_индекс], "выход_адрес_b0").map_err(|e| ошибка(format!("{:?}", e)))?
        };
        let выход_адрес_b1 = unsafe {
            self.билдер.build_gep(i8_тип, буфер, &[индекс_плюс_один], "выход_адрес_b1").map_err(|e| ошибка(format!("{:?}", e)))?
        };
        self.билдер.build_store(выход_адрес_b0, итог_б0_i8).map_err(|e| ошибка(format!("{:?}", e)))?;
        self.билдер.build_store(выход_адрес_b1, итог_б1_i8).map_err(|e| ошибка(format!("{:?}", e)))?;

        let индекс_плюс_два = self.билдер.build_int_add(текущий_индекс, i64_тип.const_int(2, false), "индекс_плюс_два").map_err(|e| ошибка(format!("{:?}", e)))?;
        self.билдер.build_store(индекс_alloca, индекс_плюс_два).map_err(|e| ошибка(format!("{:?}", e)))?;
        self.билдер.build_unconditional_branch(блок_условие).map_err(|e| ошибка(format!("{:?}", e)))?;

        // --- ASCII (или любой другой одиночный байт — копируем/меняем регистр
        // только для 'a'-'z'/'A'-'Z', остальное копируем как есть) ---
        self.билдер.position_at_end(блок_ascii);
        let (нижняя_граница, верхняя_граница, смещение): (u64, u64, i64) = if в_верхний {
            (0x61, 0x7A, -0x20) // 'a'..'z' -> вычесть 0x20
        } else {
            (0x41, 0x5A, 0x20) // 'A'..'Z' -> прибавить 0x20
        };
        let в_диапазоне = self
            .билдер
            .build_and(
                self.билдер.build_int_compare(IntPredicate::UGE, b0, к(нижняя_граница), "asc_ge").map_err(|e| ошибка(format!("{:?}", e)))?,
                self.билдер.build_int_compare(IntPredicate::ULE, b0, к(верхняя_граница), "asc_le").map_err(|e| ошибка(format!("{:?}", e)))?,
                "asc_in_range",
            )
            .map_err(|e| ошибка(format!("{:?}", e)))?;
        let со_смещением = if смещение < 0 {
            self.билдер.build_int_sub(b0, к((-смещение) as u64), "ascii_минус").map_err(|e| ошибка(format!("{:?}", e)))?
        } else {
            self.билдер.build_int_add(b0, к(смещение as u64), "ascii_плюс").map_err(|e| ошибка(format!("{:?}", e)))?
        };
        let итог_ascii = self.билдер.build_select(в_диапазоне, со_смещением, b0, "итог_ascii").map_err(|e| ошибка(format!("{:?}", e)))?.into_int_value();
        let итог_ascii_i8 = self.билдер.build_int_truncate(итог_ascii, i8_тип, "итог_ascii_i8").map_err(|e| ошибка(format!("{:?}", e)))?;

        let выход_адрес_ascii = unsafe {
            self.билдер.build_gep(i8_тип, буфер, &[текущий_индекс], "выход_адрес_ascii").map_err(|e| ошибка(format!("{:?}", e)))?
        };
        self.билдер.build_store(выход_адрес_ascii, итог_ascii_i8).map_err(|e| ошибка(format!("{:?}", e)))?;

        let индекс_плюс_один_ascii = self.билдер.build_int_add(текущий_индекс, единица_i64, "индекс_плюс_один_ascii").map_err(|e| ошибка(format!("{:?}", e)))?;
        self.билдер.build_store(индекс_alloca, индекс_плюс_один_ascii).map_err(|e| ошибка(format!("{:?}", e)))?;
        self.билдер.build_unconditional_branch(блок_условие).map_err(|e| ошибка(format!("{:?}", e)))?;

        // --- Конец: нулевой байт-терминатор, возвращаем буфер ---
        self.билдер.position_at_end(блок_после);
        let выход_адрес_нуль = unsafe {
            self.билдер.build_gep(i8_тип, буфер, &[длина], "выход_адрес_нуль").map_err(|e| ошибка(format!("{:?}", e)))?
        };
        self.билдер.build_store(выход_адрес_нуль, i8_тип.const_int(0, false)).map_err(|e| ошибка(format!("{:?}", e)))?;

        // ⚠️ НАЙДЕНО РЕАЛЬНОЙ ПРОВЕРКОЙ (утечка, обнаруженная при отладке
        // совсем другой проблемы — утечки внутри циклов): "текст_значение"
        // (аргумент этой функции) уже прочитан и больше не нужен — если он
        // сам был malloc'нутым, свежесозданным буфером (например,
        // результатом конкатенации, переданным напрямую как аргумент —
        // "регистр_в_верхний(\"а\" + б)"), его нужно освободить здесь же,
        // иначе он утекает безвозвратно. Та же самая логика, что уже
        // применяется к операндам "+" в конкатенации — просто раньше не
        // была распространена на аргументы ЭТОЙ конкретной функции. Не
        // трогаем, если аргумент — простая переменная/литерал/чтение поля
        // (те не создают новый буфер, освобождать нечего/нельзя).
        if является_текст_порождающим(&аргументы[0]) {
            let free = self
                .модуль
                .get_function("free")
                .ok_or_else(|| ошибка("внутренняя ошибка: free не была объявлена"))?;
            self.билдер
                .build_call(free, &[текст_значение.into()], "освободить_аргумент_регистра")
                .map_err(|e| ошибка(format!("ошибка освобождения аргумента регистра: {:?}", e)))?;
        }

        Ok(буфер.into())
    }

    /// Генерирует "прочитать_строку() -> результат<текст>" — читает одну
    /// строку из стандартного ввода через fdopen(0, "r") + fgets (см.
    /// подробный комментарий у объявления fdopen про переносимость между
    /// Linux/macOS). Буфер фиксированного размера (1024 байта) — если
    /// введённая строка длиннее, она будет обрезана (fgets останавливается
    /// на первой из двух границ: перевод строки ИЛИ конец буфера).
    ///
    /// ⚠️ ИЗВЕСТНОЕ ОГРАНИЧЕНИЕ: перевод строки, если он был введён (обычный
    /// случай — Enter), ОСТАЁТСЯ в конце результата (fgets включает его,
    /// если поместился в буфер) — не обрезается автоматически. Обрезка
    /// потребовала бы либо ручного поиска символа '\n' и укорачивания
    /// буфера, либо вызова strchr — не сделано в этой версии, чтобы не
    /// множить риск в одной правке; сравнение прочитанной строки с
    /// ожидаемым текстом через "==" может неожиданно не совпасть из-за
    /// этого лишнего символа, если про это не знать заранее.
    ///
    /// ⚠️ ИЗВЕСТНОЕ ОГРАНИЧЕНИЕ (многократные вызовы): каждый вызов заново
    /// делает fdopen(0, "r") — открывает НОВЫЙ буферизованный поток поверх
    /// одного и того же файлового дескриптора. Для одного-двух вызовов
    /// подряд это должно работать корректно, но при частых повторных
    /// вызовах (например, в цикле, читающем много строк) есть теоретический
    /// риск некорректной буферизации между отдельными потоками одной и той
    /// же системы ввода-вывода — не проверено сборкой, честно обозначено
    /// как риск, а не скрыто.
    fn сгенерировать_прочитать_строку(&mut self) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        let malloc = self
            .модуль
            .get_function("malloc")
            .ok_or_else(|| ошибка("внутренняя ошибка: malloc не была объявлена"))?;
        let i64_тип = self.контекст.i64_type();
        let размер_буфера_i64 = i64_тип.const_int(1024, false);
        let буфер = self
            .билдер
            .build_call(malloc, &[размер_буфера_i64.into()], "строка_буфер")
            .map_err(|e| ошибка(format!("ошибка выделения буфера для прочитать_строку: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("malloc неожиданно не вернул значение"))?
            .into_pointer_value();

        // ⚠️ ИСПРАВЛЕНО (см. подробное объяснение у объявить_глобальные_argc_argv,
        // где заведена глобальная переменная-одиночка для этого потока):
        // раньше здесь был БЕЗУСЛОВНЫЙ вызов fdopen(0, "r") — теперь
        // ленивая инициализация: если глобальный поток ещё не создан
        // (NULL) — создаём его СЕЙЧАС и СОХРАНЯЕМ, если уже создан —
        // просто ИСПОЛЬЗУЕМ сохранённое значение, не открывая новый поток.
        let текст_указатель_чтения: BasicTypeEnum = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default()).into();
        let глобальный_поток_ввода = self
            .модуль
            .get_global("глобальный_поток_ввода")
            .ok_or_else(|| ошибка("внутренняя ошибка: глобальный_поток_ввода не была объявлена"))?;
        let текущий_поток = self
            .билдер
            .build_load(текст_указатель_чтения, глобальный_поток_ввода.as_pointer_value(), "текущий_поток_ввода")
            .map_err(|e| ошибка(format!("ошибка чтения глобального потока ввода: {:?}", e)))?
            .into_pointer_value();
        let поток_не_создан = self
            .билдер
            .build_is_null(текущий_поток, "поток_не_создан")
            .map_err(|e| ошибка(format!("ошибка проверки потока ввода: {:?}", e)))?;

        let функция_для_потока = self
            .текущая_функция
            .ok_or_else(|| ошибка("внутренняя ошибка: 'прочитать_строку' вызван вне тела функции"))?;
        let блок_создать_поток = self.контекст.append_basic_block(функция_для_потока, "создать_поток_ввода");
        let блок_поток_готов = self.контекст.append_basic_block(функция_для_потока, "поток_ввода_готов");

        self.билдер
            .build_conditional_branch(поток_не_создан, блок_создать_поток, блок_поток_готов)
            .map_err(|e| ошибка(format!("ошибка ветвления при инициализации потока ввода: {:?}", e)))?;

        self.билдер.position_at_end(блок_создать_поток);
        let fdopen = self
            .модуль
            .get_function("fdopen")
            .ok_or_else(|| ошибка("внутренняя ошибка: fdopen не была объявлена"))?;
        let дескриптор_ноль = self.контекст.i32_type().const_int(0, false);
        let режим_чтения = self.сгенерировать_текстовый_литерал("r")?;
        let новый_поток = self
            .билдер
            .build_call(fdopen, &[дескриптор_ноль.into(), режим_чтения.into()], "новый_поток_ввода")
            .map_err(|e| ошибка(format!("ошибка открытия потока стандартного ввода: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("fdopen неожиданно не вернул значение"))?;
        self.билдер
            .build_store(глобальный_поток_ввода.as_pointer_value(), новый_поток)
            .map_err(|e| ошибка(format!("ошибка сохранения потока ввода: {:?}", e)))?;
        self.билдер
            .build_unconditional_branch(блок_поток_готов)
            .map_err(|e| ошибка(format!("ошибка перехода после создания потока ввода: {:?}", e)))?;

        self.билдер.position_at_end(блок_поток_готов);
        // Читаем СНОВА — теперь глобальная переменная гарантированно НЕ
        // NULL, независимо от того, каким путём мы сюда попали.
        let поток = self
            .билдер
            .build_load(текст_указатель_чтения, глобальный_поток_ввода.as_pointer_value(), "поток_ввода_итоговый")
            .map_err(|e| ошибка(format!("ошибка чтения потока ввода: {:?}", e)))?;

        let fgets = self
            .модуль
            .get_function("fgets")
            .ok_or_else(|| ошибка("внутренняя ошибка: fgets не была объявлена"))?;
        let размер_буфера_i32 = self.контекст.i32_type().const_int(1024, false);
        let результат_fgets = self
            .билдер
            .build_call(fgets, &[буфер.into(), размер_буфера_i32.into(), поток.into()], "fgets_вызов")
            .map_err(|e| ошибка(format!("ошибка чтения строки: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("fgets неожиданно не вернул значение"))?
            .into_pointer_value();

        let функция = self
            .текущая_функция
            .ok_or_else(|| ошибка("внутренняя ошибка: 'прочитать_строку' вызван вне тела функции"))?;
        let тип_результата = тип_результата_llvm(self.контекст, self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default()).into());
        let результат_alloca = self
            .билдер
            .build_alloca(тип_результата, "прочитать_строку_результат")
            .map_err(|e| ошибка(format!("ошибка выделения памяти для результата 'прочитать_строку': {:?}", e)))?;

        let не_удалось = self
            .билдер
            .build_is_null(результат_fgets, "не_удалось")
            .map_err(|e| ошибка(format!("ошибка проверки результата чтения: {:?}", e)))?;

        let блок_успех = self.контекст.append_basic_block(функция, "прочитать_строку_успех");
        let блок_ошибка = self.контекст.append_basic_block(функция, "прочитать_строку_ошибка");
        let блок_конец = self.контекст.append_basic_block(функция, "прочитать_строку_конец");

        self.билдер
            .build_conditional_branch(не_удалось, блок_ошибка, блок_успех)
            .map_err(|e| ошибка(format!("ошибка ветвления 'прочитать_строку': {:?}", e)))?;

        self.билдер.position_at_end(блок_успех);

        // ⚠️ НАЙДЕННЫЙ ПРИ РЕАЛЬНОМ ТЕСТИРОВАНИИ БАГ (реальная программа —
        // текстовый кликер со сравнением введённых команд — вскрыла это
        // немедленно, хотя раньше существовавший тест_ввода.код никогда
        // не ловил проблему, поскольку только ВЫВОДИЛ введённую строку
        // обратно, не СРАВНИВАЛ её ни с чем): fgets (стандартное,
        // документированное поведение самой функции в C) НЕ убирает
        // завершающий символ новой строки из буфера — значит "прочитать_строку()"
        // ВСЕГДА возвращала текст с лишним "\n" на конце (если ввод не
        // оборвался ровно на границе буфера без newline), что делало ЛЮБОЕ
        // сравнение введённого текста с ожидаемым значением ("если (команда
        // == \"к\")") заведомо неверным — "к\n" никогда не равно "к".
        //
        // Исправление — тот же безопасный приём (build_select вместо
        // ветвления базовых блоков), что уже применён в регистр_в_верхний/
        // нижний: находим последний байт буфера, и ЕСЛИ это '\n' —
        // заменяем его на нулевой байт (обрезаем строку); если нет —
        // записываем ТОТ ЖЕ САМЫЙ байт обратно (ничего не меняется).
        let strlen = self
            .модуль
            .get_function("strlen")
            .ok_or_else(|| ошибка("внутренняя ошибка: strlen не была объявлена"))?;
        let длина_прочитанного = self
            .билдер
            .build_call(strlen, &[буфер.into()], "длина_прочитанной_строки")
            .map_err(|e| ошибка(format!("ошибка вычисления длины прочитанной строки: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("strlen неожиданно не вернул значение"))?
            .into_int_value();

        let i8_тип_чтения = self.контекст.i8_type();
        let i64_тип_чтения = self.контекст.i64_type();
        let ноль_i64 = i64_тип_чтения.const_int(0, false);
        let единица_i64 = i64_тип_чтения.const_int(1, false);
        let есть_символы = self
            .билдер
            .build_int_compare(IntPredicate::UGT, длина_прочитанного, ноль_i64, "есть_символы")
            .map_err(|e| ошибка(format!("ошибка сравнения длины: {:?}", e)))?;
        let длина_минус_один = self
            .билдер
            .build_int_sub(длина_прочитанного, единица_i64, "длина_минус_один")
            .map_err(|e| ошибка(format!("ошибка вычисления индекса: {:?}", e)))?;
        let индекс_последнего = self
            .билдер
            .build_select(есть_символы, длина_минус_один, ноль_i64, "индекс_последнего_байта")
            .map_err(|e| ошибка(format!("ошибка вычисления индекса: {:?}", e)))?
            .into_int_value();
        let адрес_последнего = unsafe {
            self.билдер
                .build_gep(i8_тип_чтения, буфер, &[индекс_последнего], "адрес_последнего_байта")
                .map_err(|e| ошибка(format!("ошибка адресации последнего байта: {:?}", e)))?
        };
        let последний_байт = self
            .билдер
            .build_load(i8_тип_чтения, адрес_последнего, "последний_байт")
            .map_err(|e| ошибка(format!("ошибка чтения последнего байта: {:?}", e)))?
            .into_int_value();
        let это_перевод_строки = self
            .билдер
            .build_int_compare(IntPredicate::EQ, последний_байт, i8_тип_чтения.const_int(b'\n' as u64, false), "это_перевод_строки")
            .map_err(|e| ошибка(format!("ошибка сравнения с переводом строки: {:?}", e)))?;
        let нужно_обрезать = self
            .билдер
            .build_and(есть_символы, это_перевод_строки, "нужно_обрезать")
            .map_err(|e| ошибка(format!("ошибка вычисления условия обрезки: {:?}", e)))?;
        let новое_значение_байта = self
            .билдер
            .build_select(нужно_обрезать, i8_тип_чтения.const_int(0, false), последний_байт, "новое_значение_последнего_байта")
            .map_err(|e| ошибка(format!("ошибка вычисления нового значения байта: {:?}", e)))?
            .into_int_value();
        self.билдер
            .build_store(адрес_последнего, новое_значение_байта)
            .map_err(|e| ошибка(format!("ошибка записи обрезанного байта: {:?}", e)))?;

        let текст_тип: BasicTypeEnum = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default()).into();
        let результат_успех = self.построить_результат_успех(текст_тип, буфер.into())?;
        self.билдер
            .build_store(результат_alloca, результат_успех)
            .map_err(|e| ошибка(format!("ошибка сохранения результата 'прочитать_строку': {:?}", e)))?;
        self.билдер
            .build_unconditional_branch(блок_конец)
            .map_err(|e| ошибка(format!("ошибка перехода после успешного чтения: {:?}", e)))?;

        self.билдер.position_at_end(блок_ошибка);
        let сообщение = self.сгенерировать_текстовый_литерал("не удалось прочитать строку (конец ввода)")?;
        let результат_ошибка = self.построить_результат_ошибка(текст_тип, сообщение)?;
        self.билдер
            .build_store(результат_alloca, результат_ошибка)
            .map_err(|e| ошибка(format!("ошибка сохранения результата 'прочитать_строку': {:?}", e)))?;
        self.билдер
            .build_unconditional_branch(блок_конец)
            .map_err(|e| ошибка(format!("ошибка перехода после неудачного чтения: {:?}", e)))?;

        self.билдер.position_at_end(блок_конец);
        self.билдер
            .build_load(тип_результата, результат_alloca, "итоговый_результат")
            .map_err(|e| ошибка(format!("ошибка чтения итогового результата 'прочитать_строку': {:?}", e)))
    }

    /// Генерирует "аргументы_командной_строки() -> Список<текст>" — читает
    /// argc/argv из глобальных переменных (сохранённых обёрткой main при
    /// старте программы, см. объявить_глобальные_argc_argv и
    /// сгенерировать_обёртку_main) и строит из них Список<текст>, ПРОПУСКАЯ
    /// argv[0] (имя самой программы) — по общепринятой в большинстве языков
    /// конвенции: "аргументы" означают то, что передал пользователь, не имя
    /// программы, которое и так известно заранее.
    ///
    /// В отличие от Список<тип>.добавить(...) (которое растит буфер
    /// постепенно, не зная заранее итоговый размер), здесь количество
    /// аргументов ИЗВЕСТНО СРАЗУ (argc), поэтому buffer выделяется ОДНОГО
    /// нужного размера напрямую — рост буфера тут просто не нужен, это не
    /// сокращённый путь, а по-настоящему более простой случай.
    fn сгенерировать_аргументы_командной_строки(&mut self) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        let llvm_struct_списка = self.получить_или_создать_тип_списка(&РешённыйТип::Текст)?;
        let i64_тип = self.контекст.i64_type();
        let i32_тип = self.контекст.i32_type();
        let текст_указатель_тип = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default());
        let указатель_на_текст_указатель = текст_указатель_тип.ptr_type(inkwell::AddressSpace::default());

        // --- Читаем argc/argv из глобальных переменных ---
        let глобальный_argc = self
            .модуль
            .get_global("глобальный_argc")
            .ok_or_else(|| ошибка("внутренняя ошибка: глобальный_argc не была объявлена"))?;
        let глобальный_argv = self
            .модуль
            .get_global("глобальный_argv")
            .ok_or_else(|| ошибка("внутренняя ошибка: глобальный_argv не была объявлена"))?;
        let argc_i32 = self
            .билдер
            .build_load(i32_тип, глобальный_argc.as_pointer_value(), "argc")
            .map_err(|e| ошибка(format!("ошибка чтения argc: {:?}", e)))?
            .into_int_value();
        let argv = self
            .билдер
            .build_load(указатель_на_текст_указатель, глобальный_argv.as_pointer_value(), "argv")
            .map_err(|e| ошибка(format!("ошибка чтения argv: {:?}", e)))?
            .into_pointer_value();
        let argc = self
            .билдер
            .build_int_cast(argc_i32, i64_тип, "argc_i64")
            .map_err(|e| ошибка(format!("ошибка приведения argc: {:?}", e)))?;

        // --- Количество аргументов = argc - 1 (пропускаем имя программы), но не меньше 0 ---
        let единица = i64_тип.const_int(1, false);
        let ноль = i64_тип.const_int(0, false);
        let argc_минус_один = self
            .билдер
            .build_int_sub(argc, единица, "argc_минус_один")
            .map_err(|e| ошибка(format!("ошибка вычисления количества аргументов: {:?}", e)))?;
        let меньше_нуля = self
            .билдер
            .build_int_compare(IntPredicate::SLT, argc_минус_один, ноль, "меньше_нуля")
            .map_err(|e| ошибка(format!("ошибка вычисления количества аргументов: {:?}", e)))?;
        let количество = self
            .билдер
            .build_select(меньше_нуля, ноль, argc_минус_один, "количество_аргументов")
            .map_err(|e| ошибка(format!("ошибка вычисления количества аргументов: {:?}", e)))?
            .into_int_value();

        // --- Создаём саму служебную структуру списка (malloc + счётчик=1) ---
        let malloc = self
            .модуль
            .get_function("malloc")
            .ok_or_else(|| ошибка("внутренняя ошибка: malloc не была объявлена"))?;
        let размер_структуры = llvm_struct_списка
            .size_of()
            .ok_or_else(|| ошибка("не удалось вычислить размер структуры Список<текст>"))?;
        let сырой_указатель_списка = self
            .билдер
            .build_call(malloc, &[размер_структуры.into()], "новый_список_аргументов")
            .map_err(|e| ошибка(format!("ошибка выделения памяти для списка аргументов: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("malloc неожиданно не вернул значение"))?
            .into_pointer_value();
        let указатель_списка = self
            .билдер
            .build_pointer_cast(сырой_указатель_списка, llvm_struct_списка.ptr_type(inkwell::AddressSpace::default()), "указатель_списка_аргументов")
            .map_err(|e| ошибка(format!("ошибка приведения указателя списка аргументов: {:?}", e)))?;
        self.записать_поле_списка(llvm_struct_списка, указатель_списка, 0, i64_тип.const_int(1, false).into())?;

        // --- Выделяем буфер данных ТОЧНО нужного размера (без роста) ---
        let текст_указатель_как_basic: BasicTypeEnum = текст_указатель_тип.into();
        let размер_элемента = текст_указатель_как_basic
            .size_of()
            .ok_or_else(|| ошибка("не удалось вычислить размер элемента для аргументов командной строки"))?;
        let размер_буфера_данных = self
            .билдер
            .build_int_mul(количество, размер_элемента, "размер_буфера_аргументов")
            .map_err(|e| ошибка(format!("ошибка вычисления размера буфера аргументов: {:?}", e)))?;
        let сырой_буфер_данных = self
            .билдер
            .build_call(malloc, &[размер_буфера_данных.into()], "буфер_аргументов")
            .map_err(|e| ошибка(format!("ошибка выделения буфера аргументов: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("malloc неожиданно не вернул значение"))?
            .into_pointer_value();
        let буфер_данных = self
            .билдер
            .build_pointer_cast(сырой_буфер_данных, текст_указатель_тип.ptr_type(inkwell::AddressSpace::default()), "буфер_аргументов_типизированный")
            .map_err(|e| ошибка(format!("ошибка приведения буфера аргументов: {:?}", e)))?;

        // --- Копируем argv[1..argc] в буфер_данных[0..количество] ---
        let функция = self
            .текущая_функция
            .ok_or_else(|| ошибка("внутренняя ошибка: 'аргументы_командной_строки' вызван вне тела функции"))?;

        let индекс_alloca = self
            .билдер
            .build_alloca(i64_тип, "аргументы_индекс")
            .map_err(|e| ошибка(format!("ошибка выделения памяти для индекса аргументов: {:?}", e)))?;
        self.билдер
            .build_store(индекс_alloca, ноль)
            .map_err(|e| ошибка(format!("ошибка инициализации индекса аргументов: {:?}", e)))?;

        let блок_условие = self.контекст.append_basic_block(функция, "аргументы_условие");
        let блок_тело = self.контекст.append_basic_block(функция, "аргументы_тело");
        let блок_после = self.контекст.append_basic_block(функция, "аргументы_после");

        self.билдер
            .build_unconditional_branch(блок_условие)
            .map_err(|e| ошибка(format!("ошибка перехода к условию цикла аргументов: {:?}", e)))?;

        self.билдер.position_at_end(блок_условие);
        let текущий_индекс = self
            .билдер
            .build_load(i64_тип, индекс_alloca, "текущий_индекс_аргументов")
            .map_err(|e| ошибка(format!("ошибка чтения индекса аргументов: {:?}", e)))?
            .into_int_value();
        let есть_ещё = self
            .билдер
            .build_int_compare(IntPredicate::SLT, текущий_индекс, количество, "есть_ещё_аргументы")
            .map_err(|e| ошибка(format!("ошибка сравнения индекса аргументов: {:?}", e)))?;
        self.билдер
            .build_conditional_branch(есть_ещё, блок_тело, блок_после)
            .map_err(|e| ошибка(format!("ошибка ветвления цикла аргументов: {:?}", e)))?;

        self.билдер.position_at_end(блок_тело);
        // индекс в argv сдвинут на +1 относительно индекса в нашем буфере —
        // именно так мы пропускаем argv[0] (имя программы).
        let индекс_в_argv = self
            .билдер
            .build_int_add(текущий_индекс, единица, "индекс_в_argv")
            .map_err(|e| ошибка(format!("ошибка вычисления индекса в argv: {:?}", e)))?;
        let адрес_в_argv = unsafe {
            self.билдер
                .build_gep(текст_указатель_тип, argv, &[индекс_в_argv], "адрес_в_argv")
                .map_err(|e| ошибка(format!("ошибка адресации argv: {:?}", e)))?
        };
        let значение_argv = self
            .билдер
            .build_load(текст_указатель_тип, адрес_в_argv, "значение_argv")
            .map_err(|e| ошибка(format!("ошибка чтения значения argv: {:?}", e)))?;
        let адрес_в_буфере = unsafe {
            self.билдер
                .build_gep(текст_указатель_тип, буфер_данных, &[текущий_индекс], "адрес_в_буфере_аргументов")
                .map_err(|e| ошибка(format!("ошибка адресации буфера аргументов: {:?}", e)))?
        };
        self.билдер
            .build_store(адрес_в_буфере, значение_argv)
            .map_err(|e| ошибка(format!("ошибка записи аргумента в буфер: {:?}", e)))?;

        let индекс_плюс_один = self
            .билдер
            .build_int_add(текущий_индекс, единица, "индекс_плюс_один_аргументы")
            .map_err(|e| ошибка(format!("ошибка инкремента индекса аргументов: {:?}", e)))?;
        self.билдер
            .build_store(индекс_alloca, индекс_плюс_один)
            .map_err(|e| ошибка(format!("ошибка сохранения индекса аргументов: {:?}", e)))?;
        self.билдер
            .build_unconditional_branch(блок_условие)
            .map_err(|e| ошибка(format!("ошибка возврата к условию цикла аргументов: {:?}", e)))?;

        self.билдер.position_at_end(блок_после);

        // --- Записываем оставшиеся поля списка: размер, вместимость, данные ---
        self.записать_поле_списка(llvm_struct_списка, указатель_списка, 1, количество.into())?;
        self.записать_поле_списка(llvm_struct_списка, указатель_списка, 2, количество.into())?;
        self.записать_поле_списка(llvm_struct_списка, указатель_списка, 3, буфер_данных.into())?;

        Ok(указатель_списка.into())
    }

    /// Генерирует "прочитать_файл(путь) -> результат<текст>". Порядок
    /// действий — классический для C-стиля чтения "всего файла разом":
    /// открыть, перепрыгнуть в конец (fseek), спросить позицию (ftell —
    /// это и есть размер файла), вернуться в начало (fseek), выделить
    /// буфер точно такого размера, прочитать (fread), закрыть (fclose).
    /// НОВОЕ (многопоточность, вторая часть): создаёт канал<T> в куче.
    /// Layout в памяти (одинаков независимо от T — см. ДополнительнаяИнформация
    /// ::Канал, комментарий там же):
    ///   0..128    — pthread_mutex_t (с большим запасом ради переносимости
    ///               между Linux и macOS — точный sizeof отличается, а мы
    ///               не можем себе позволить узнавать его во время сборки
    ///               под каждую платформу отдельно)
    ///   128..256  — pthread_cond_t (тот же запас по той же причине)
    ///   256..260  — has_value: i32 (0 — значения ещё нет, 1 — есть)
    ///   264..272  — значение: 8 байт, достаточно для любого целого числа
    ///               или указателя (текст/структуры) — конкретная
    ///               интерпретация зависит от T, см. сгенерировать_метод_канала
    fn сгенерировать_создать_канал(&mut self) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        let malloc = self
            .модуль
            .get_function("malloc")
            .ok_or_else(|| ошибка("внутренняя ошибка: malloc не была объявлена"))?;

        let размер = self.контекст.i64_type().const_int(272, false);
        let указатель = self
            .билдер
            .build_call(malloc, &[размер.into()], "канал_память")
            .map_err(|e| ошибка(format!("ошибка выделения памяти для канала: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("malloc не вернул значение"))?
            .into_pointer_value();

        let байт_указатель = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default());
        let null_указатель = байт_указатель.const_null();

        // Мьютекс — по смещению 0, инициализация "на месте".
        let pthread_mutex_init = self
            .модуль
            .get_function("pthread_mutex_init")
            .ok_or_else(|| ошибка("внутренняя ошибка: pthread_mutex_init не была объявлена"))?;
        self.билдер
            .build_call(pthread_mutex_init, &[указатель.into(), null_указатель.into()], "init_мьютекса")
            .map_err(|e| ошибка(format!("ошибка инициализации мьютекса: {:?}", e)))?;

        // Условная переменная — по смещению 128.
        let указатель_на_cond = unsafe {
            self.билдер.build_gep(
                self.контекст.i8_type(),
                указатель,
                &[self.контекст.i64_type().const_int(128, false)],
                "указатель_на_cond",
            )
        }
        .map_err(|e| ошибка(format!("ошибка вычисления адреса условной переменной: {:?}", e)))?;

        let pthread_cond_init = self
            .модуль
            .get_function("pthread_cond_init")
            .ok_or_else(|| ошибка("внутренняя ошибка: pthread_cond_init не была объявлена"))?;
        self.билдер
            .build_call(pthread_cond_init, &[указатель_на_cond.into(), null_указатель.into()], "init_условной_переменной")
            .map_err(|e| ошибка(format!("ошибка инициализации условной переменной: {:?}", e)))?;

        // has_value = 0 — по смещению 256.
        let указатель_на_флаг = unsafe {
            self.билдер.build_gep(
                self.контекст.i8_type(),
                указатель,
                &[self.контекст.i64_type().const_int(256, false)],
                "указатель_на_флаг",
            )
        }
        .map_err(|e| ошибка(format!("ошибка вычисления адреса флага: {:?}", e)))?;

        self.билдер
            .build_store(указатель_на_флаг, self.контекст.i32_type().const_int(0, false))
            .map_err(|e| ошибка(format!("ошибка записи начального значения флага: {:?}", e)))?;

        Ok(указатель.into())
    }

    fn сгенерировать_прочитать_файл(&mut self, аргументы: &[Выражение]) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        if аргументы.len() != 1 {
            return Err(ошибка("прочитать_файл(...) ожидает ровно один аргумент (путь)"));
        }
        let путь = self.сгенерировать_выражение(&аргументы[0])?;

        let текст_тип: BasicTypeEnum = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default()).into();
        let i64_тип = self.контекст.i64_type();
        let i32_тип = self.контекст.i32_type();

        let функция = self
            .текущая_функция
            .ok_or_else(|| ошибка("внутренняя ошибка: 'прочитать_файл' вызван вне тела функции"))?;
        let тип_результата = тип_результата_llvm(self.контекст, текст_тип);
        let результат_alloca = self
            .билдер
            .build_alloca(тип_результата, "прочитать_файл_результат")
            .map_err(|e| ошибка(format!("ошибка выделения памяти для результата 'прочитать_файл': {:?}", e)))?;

        let fopen = self
            .модуль
            .get_function("fopen")
            .ok_or_else(|| ошибка("внутренняя ошибка: fopen не была объявлена"))?;
        let режим_чтения = self.сгенерировать_текстовый_литерал("r")?;
        let файл = self
            .билдер
            .build_call(fopen, &[путь.into(), режим_чтения.into()], "открытый_файл")
            .map_err(|e| ошибка(format!("ошибка открытия файла: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("fopen неожиданно не вернул значение"))?
            .into_pointer_value();

        let файл_не_открылся = self
            .билдер
            .build_is_null(файл, "файл_не_открылся")
            .map_err(|e| ошибка(format!("ошибка проверки открытия файла: {:?}", e)))?;

        let блок_чтение = self.контекст.append_basic_block(функция, "прочитать_файл_чтение");
        let блок_не_открылся = self.контекст.append_basic_block(функция, "прочитать_файл_не_открылся");
        let блок_конец = self.контекст.append_basic_block(функция, "прочитать_файл_конец");

        self.билдер
            .build_conditional_branch(файл_не_открылся, блок_не_открылся, блок_чтение)
            .map_err(|e| ошибка(format!("ошибка ветвления 'прочитать_файл': {:?}", e)))?;

        // --- Файл открылся: узнаём размер, читаем целиком, закрываем ---
        self.билдер.position_at_end(блок_чтение);
        let fseek = self
            .модуль
            .get_function("fseek")
            .ok_or_else(|| ошибка("внутренняя ошибка: fseek не была объявлена"))?;
        let ftell = self
            .модуль
            .get_function("ftell")
            .ok_or_else(|| ошибка("внутренняя ошибка: ftell не была объявлена"))?;
        let fread = self
            .модуль
            .get_function("fread")
            .ok_or_else(|| ошибка("внутренняя ошибка: fread не была объявлена"))?;
        let fclose = self
            .модуль
            .get_function("fclose")
            .ok_or_else(|| ошибка("внутренняя ошибка: fclose не была объявлена"))?;
        let malloc = self
            .модуль
            .get_function("malloc")
            .ok_or_else(|| ошибка("внутренняя ошибка: malloc не была объявлена"))?;

        // SEEK_END = 2, SEEK_SET = 0 — стандартные POSIX-константы, одинаковые
        // и на Linux, и на macOS (в отличие от истории с именем "stdin" —
        // здесь платформенных различий нет).
        let seek_end = i32_тип.const_int(2, false);
        let seek_set = i32_тип.const_int(0, false);
        let ноль_i64 = i64_тип.const_int(0, false);

        self.билдер
            .build_call(fseek, &[файл.into(), ноль_i64.into(), seek_end.into()], "fseek_в_конец")
            .map_err(|e| ошибка(format!("ошибка перехода в конец файла: {:?}", e)))?;
        let размер = self
            .билдер
            .build_call(ftell, &[файл.into()], "размер_файла")
            .map_err(|e| ошибка(format!("ошибка вычисления размера файла: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("ftell неожиданно не вернул значение"))?
            .into_int_value();
        self.билдер
            .build_call(fseek, &[файл.into(), ноль_i64.into(), seek_set.into()], "fseek_в_начало")
            .map_err(|e| ошибка(format!("ошибка возврата в начало файла: {:?}", e)))?;

        let размер_с_нулём = self
            .билдер
            .build_int_add(размер, i64_тип.const_int(1, false), "размер_с_нулём")
            .map_err(|e| ошибка(format!("ошибка вычисления размера буфера файла: {:?}", e)))?;
        let сырой_буфер = self
            .билдер
            .build_call(malloc, &[размер_с_нулём.into()], "буфер_файла")
            .map_err(|e| ошибка(format!("ошибка выделения буфера для файла: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("malloc неожиданно не вернул значение"))?
            .into_pointer_value();

        let единица_i64 = i64_тип.const_int(1, false);
        self.билдер
            .build_call(fread, &[сырой_буфер.into(), единица_i64.into(), размер.into(), файл.into()], "fread_вызов")
            .map_err(|e| ошибка(format!("ошибка чтения файла: {:?}", e)))?;

        // Нулевой байт в конце — прочитанные данные не являются C-строкой
        // сами по себе (fread не завершает буфер нулём), значит нужно
        // сделать это вручную, иначе текст "потечёт" за пределы реальных
        // данных при любой операции, ожидающей null-terminated текст
        // (strlen, printf и так далее).
        let адрес_нуля = unsafe {
            self.билдер
                .build_gep(self.контекст.i8_type(), сырой_буфер, &[размер], "адрес_завершающего_нуля")
                .map_err(|e| ошибка(format!("ошибка адресации конца буфера файла: {:?}", e)))?
        };
        self.билдер
            .build_store(адрес_нуля, self.контекст.i8_type().const_int(0, false))
            .map_err(|e| ошибка(format!("ошибка записи завершающего нуля: {:?}", e)))?;

        self.билдер
            .build_call(fclose, &[файл.into()], "fclose_вызов")
            .map_err(|e| ошибка(format!("ошибка закрытия файла: {:?}", e)))?;

        let результат_успех = self.построить_результат_успех(текст_тип, сырой_буфер.into())?;
        self.билдер
            .build_store(результат_alloca, результат_успех)
            .map_err(|e| ошибка(format!("ошибка сохранения результата 'прочитать_файл': {:?}", e)))?;
        self.билдер
            .build_unconditional_branch(блок_конец)
            .map_err(|e| ошибка(format!("ошибка перехода после успешного чтения файла: {:?}", e)))?;

        // --- Файл не открылся ---
        self.билдер.position_at_end(блок_не_открылся);
        let сообщение = self.сгенерировать_текстовый_литерал("не удалось открыть файл")?;
        let результат_ошибка = self.построить_результат_ошибка(текст_тип, сообщение)?;
        self.билдер
            .build_store(результат_alloca, результат_ошибка)
            .map_err(|e| ошибка(format!("ошибка сохранения результата 'прочитать_файл': {:?}", e)))?;
        self.билдер
            .build_unconditional_branch(блок_конец)
            .map_err(|e| ошибка(format!("ошибка перехода после неудачного открытия файла: {:?}", e)))?;

        self.билдер.position_at_end(блок_конец);
        self.билдер
            .build_load(тип_результата, результат_alloca, "итоговый_результат")
            .map_err(|e| ошибка(format!("ошибка чтения итогового результата 'прочитать_файл': {:?}", e)))
    }

    /// Генерирует "записать_файл(путь, содержимое) -> результат<верно>".
    /// Открывает файл на запись (режим "w" — создаёт файл, если его не было,
    /// ПЕРЕЗАПИСЫВАЕТ, если был), пишет всё содержимое разом через fwrite,
    /// проверяет, что записалось РОВНО столько байт, сколько просили
    /// (fwrite может записать МЕНЬШЕ при нехватке места на диске и т.д.).
    fn сгенерировать_записать_файл(&mut self, аргументы: &[Выражение]) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        if аргументы.len() != 2 {
            return Err(ошибка("записать_файл(...) ожидает ровно два аргумента (путь, содержимое)"));
        }
        let путь = self.сгенерировать_выражение(&аргументы[0])?;
        let содержимое = self.сгенерировать_выражение(&аргументы[1])?;

        let верно_тип: BasicTypeEnum = self.контекст.bool_type().into();
        let i64_тип = self.контекст.i64_type();

        let функция = self
            .текущая_функция
            .ok_or_else(|| ошибка("внутренняя ошибка: 'записать_файл' вызван вне тела функции"))?;
        let тип_результата = тип_результата_llvm(self.контекст, верно_тип);
        let результат_alloca = self
            .билдер
            .build_alloca(тип_результата, "записать_файл_результат")
            .map_err(|e| ошибка(format!("ошибка выделения памяти для результата 'записать_файл': {:?}", e)))?;

        let fopen = self
            .модуль
            .get_function("fopen")
            .ok_or_else(|| ошибка("внутренняя ошибка: fopen не была объявлена"))?;
        let режим_записи = self.сгенерировать_текстовый_литерал("w")?;
        let файл = self
            .билдер
            .build_call(fopen, &[путь.into(), режим_записи.into()], "открытый_файл_для_записи")
            .map_err(|e| ошибка(format!("ошибка открытия файла для записи: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("fopen неожиданно не вернул значение"))?
            .into_pointer_value();

        let файл_не_открылся = self
            .билдер
            .build_is_null(файл, "файл_для_записи_не_открылся")
            .map_err(|e| ошибка(format!("ошибка проверки открытия файла для записи: {:?}", e)))?;

        let блок_запись = self.контекст.append_basic_block(функция, "записать_файл_запись");
        let блок_не_открылся = self.контекст.append_basic_block(функция, "записать_файл_не_открылся");
        let блок_конец = self.контекст.append_basic_block(функция, "записать_файл_конец");

        self.билдер
            .build_conditional_branch(файл_не_открылся, блок_не_открылся, блок_запись)
            .map_err(|e| ошибка(format!("ошибка ветвления 'записать_файл': {:?}", e)))?;

        // --- Файл открылся: пишем содержимое, проверяем, всё ли записалось ---
        self.билдер.position_at_end(блок_запись);
        let strlen = self
            .модуль
            .get_function("strlen")
            .ok_or_else(|| ошибка("внутренняя ошибка: strlen не была объявлена"))?;
        let длина_содержимого = self
            .билдер
            .build_call(strlen, &[содержимое.into()], "длина_содержимого_файла")
            .map_err(|e| ошибка(format!("ошибка вычисления длины содержимого: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("strlen неожиданно не вернул значение"))?
            .into_int_value();

        let fwrite = self
            .модуль
            .get_function("fwrite")
            .ok_or_else(|| ошибка("внутренняя ошибка: fwrite не была объявлена"))?;
        let единица = i64_тип.const_int(1, false);
        let записано = self
            .билдер
            .build_call(fwrite, &[содержимое.into(), единица.into(), длина_содержимого.into(), файл.into()], "fwrite_вызов")
            .map_err(|e| ошибка(format!("ошибка записи в файл: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("fwrite неожиданно не вернул значение"))?
            .into_int_value();

        let fclose = self
            .модуль
            .get_function("fclose")
            .ok_or_else(|| ошибка("внутренняя ошибка: fclose не была объявлена"))?;
        self.билдер
            .build_call(fclose, &[файл.into()], "fclose_после_записи")
            .map_err(|e| ошибка(format!("ошибка закрытия файла после записи: {:?}", e)))?;

        let записано_не_всё = self
            .билдер
            .build_int_compare(IntPredicate::NE, записано, длина_содержимого, "записано_не_всё")
            .map_err(|e| ошибка(format!("ошибка проверки полноты записи: {:?}", e)))?;

        let блок_неполная_запись = self.контекст.append_basic_block(функция, "записать_файл_неполная");
        let блок_успех_записи = self.контекст.append_basic_block(функция, "записать_файл_успех");

        self.билдер
            .build_conditional_branch(записано_не_всё, блок_неполная_запись, блок_успех_записи)
            .map_err(|e| ошибка(format!("ошибка ветвления полноты записи: {:?}", e)))?;

        self.билдер.position_at_end(блок_успех_записи);
        let результат_успех = self.построить_результат_успех(верно_тип, self.контекст.bool_type().const_int(1, false).into())?;
        self.билдер
            .build_store(результат_alloca, результат_успех)
            .map_err(|e| ошибка(format!("ошибка сохранения результата 'записать_файл': {:?}", e)))?;
        self.билдер
            .build_unconditional_branch(блок_конец)
            .map_err(|e| ошибка(format!("ошибка перехода после успешной записи файла: {:?}", e)))?;

        self.билдер.position_at_end(блок_неполная_запись);
        let сообщение_неполная = self.сгенерировать_текстовый_литерал("не удалось записать файл полностью")?;
        let результат_неполная = self.построить_результат_ошибка(верно_тип, сообщение_неполная)?;
        self.билдер
            .build_store(результат_alloca, результат_неполная)
            .map_err(|e| ошибка(format!("ошибка сохранения результата 'записать_файл': {:?}", e)))?;
        self.билдер
            .build_unconditional_branch(блок_конец)
            .map_err(|e| ошибка(format!("ошибка перехода после неполной записи файла: {:?}", e)))?;

        // --- Файл не открылся ---
        self.билдер.position_at_end(блок_не_открылся);
        let сообщение_не_открылся = self.сгенерировать_текстовый_литерал("не удалось открыть файл для записи")?;
        let результат_не_открылся = self.построить_результат_ошибка(верно_тип, сообщение_не_открылся)?;
        self.билдер
            .build_store(результат_alloca, результат_не_открылся)
            .map_err(|e| ошибка(format!("ошибка сохранения результата 'записать_файл': {:?}", e)))?;
        self.билдер
            .build_unconditional_branch(блок_конец)
            .map_err(|e| ошибка(format!("ошибка перехода после неудачного открытия файла для записи: {:?}", e)))?;

        self.билдер.position_at_end(блок_конец);
        self.билдер
            .build_load(тип_результата, результат_alloca, "итоговый_результат")
            .map_err(|e| ошибка(format!("ошибка чтения итогового результата 'записать_файл': {:?}", e)))
    }

    /// Генерирует "выполнить_команду(команда) -> результат<целое>" — через
    /// system(). "Сырой" код завершения, который возвращает system(),
    /// НЕ является напрямую кодом завершения самой команды — это код
    /// завершения ОБОЛОЧКИ, запустившей команду, закодированный в формате
    /// wait()/waitpid() (POSIX). Нужно извлечь реальный код через
    /// стандартную конвенцию WEXITSTATUS: "сдвинуть на 8 бит вправо и
    /// оставить младший байт" — обычно это макрос в заголовочном C-файле
    /// (не отдельная функция, значит её нельзя объявить и вызвать как
    /// внешнюю функцию), поэтому воспроизводим её логику вручную через
    /// обычный сдвиг и побитовое "И" — стандартная, ОДИНАКОВАЯ на Linux
    /// и macOS конвенция (в отличие от истории с именем "stdin" — здесь
    /// платформенных различий нет).
    fn сгенерировать_выполнить_команду(&mut self, аргументы: &[Выражение]) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        if аргументы.len() != 1 {
            return Err(ошибка("выполнить_команду(...) ожидает ровно один аргумент (текст команды)"));
        }
        let команда = self.сгенерировать_выражение(&аргументы[0])?;

        let i32_тип = self.контекст.i32_type();
        let i64_тип = self.контекст.i64_type();

        let system = self
            .модуль
            .get_function("system")
            .ok_or_else(|| ошибка("внутренняя ошибка: system не была объявлена"))?;
        let сырой_статус = self
            .билдер
            .build_call(system, &[команда.into()], "system_вызов")
            .map_err(|e| ошибка(format!("ошибка запуска команды: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("system неожиданно не вернул значение"))?
            .into_int_value();

        let функция = self
            .текущая_функция
            .ok_or_else(|| ошибка("внутренняя ошибка: 'выполнить_команду' вызван вне тела функции"))?;
        let тип_результата = тип_результата_llvm(self.контекст, i64_тип.into());
        let результат_alloca = self
            .билдер
            .build_alloca(тип_результата, "выполнить_команду_результат")
            .map_err(|e| ошибка(format!("ошибка выделения памяти для результата 'выполнить_команду': {:?}", e)))?;

        let минус_один = i32_тип.const_int(u64::MAX, true); // -1 в дополнительном коде
        let не_удалось_запустить = self
            .билдер
            .build_int_compare(IntPredicate::EQ, сырой_статус, минус_один, "не_удалось_запустить")
            .map_err(|e| ошибка(format!("ошибка проверки запуска команды: {:?}", e)))?;

        let блок_успех = self.контекст.append_basic_block(функция, "выполнить_команду_успех");
        let блок_ошибка = self.контекст.append_basic_block(функция, "выполнить_команду_ошибка");
        let блок_конец = self.контекст.append_basic_block(функция, "выполнить_команду_конец");

        self.билдер
            .build_conditional_branch(не_удалось_запустить, блок_ошибка, блок_успех)
            .map_err(|e| ошибка(format!("ошибка ветвления 'выполнить_команду': {:?}", e)))?;

        // --- Команда запустилась: извлекаем реальный код завершения ---
        self.билдер.position_at_end(блок_успех);
        let статус_i64 = self
            .билдер
            .build_int_cast(сырой_статус, i64_тип, "статус_i64")
            .map_err(|e| ошибка(format!("ошибка приведения статуса команды: {:?}", e)))?;
        let восемь = i64_тип.const_int(8, false);
        let сдвинутый = self
            .билдер
            .build_right_shift(статус_i64, восемь, false, "статус_сдвинутый")
            .map_err(|e| ошибка(format!("ошибка вычисления кода завершения команды: {:?}", e)))?;
        let маска = i64_тип.const_int(0xFF, false);
        let код_завершения = self
            .билдер
            .build_and(сдвинутый, маска, "код_завершения_команды")
            .map_err(|e| ошибка(format!("ошибка вычисления кода завершения команды: {:?}", e)))?;

        let результат_успех = self.построить_результат_успех(i64_тип.into(), код_завершения.into())?;
        self.билдер
            .build_store(результат_alloca, результат_успех)
            .map_err(|e| ошибка(format!("ошибка сохранения результата 'выполнить_команду': {:?}", e)))?;
        self.билдер
            .build_unconditional_branch(блок_конец)
            .map_err(|e| ошибка(format!("ошибка перехода после успешного запуска команды: {:?}", e)))?;

        // --- Команду не удалось запустить вообще ---
        self.билдер.position_at_end(блок_ошибка);
        let сообщение = self.сгенерировать_текстовый_литерал("не удалось запустить команду")?;
        let результат_ошибка = self.построить_результат_ошибка(i64_тип.into(), сообщение)?;
        self.билдер
            .build_store(результат_alloca, результат_ошибка)
            .map_err(|e| ошибка(format!("ошибка сохранения результата 'выполнить_команду': {:?}", e)))?;
        self.билдер
            .build_unconditional_branch(блок_конец)
            .map_err(|e| ошибка(format!("ошибка перехода после неудачного запуска команды: {:?}", e)))?;

        self.билдер.position_at_end(блок_конец);
        self.билдер
            .build_load(тип_результата, результат_alloca, "итоговый_результат")
            .map_err(|e| ошибка(format!("ошибка чтения итогового результата 'выполнить_команду': {:?}", e)))
    }

    /// Строит и выполняет printf-вызов из фрагментов интерполированной
    /// строки: текстовые куски идут в формат-строку буквально (экранируя
    /// символ '%', если он случайно встретится в тексте пользователя — иначе
    /// он был бы принят printf за спецификатор формата, что и баг, и
    /// потенциальная дыра в безопасности в духе классических "format string"
    /// уязвимостей C-программ), переменные — как %s/%lld плюс отдельный
    /// variadic-аргумент.
    fn сгенерировать_вывести_с_интерполяцией(
        &mut self,
        фрагменты: &[ФрагментТекста],
        printf: FunctionValue<'ctx>,
    ) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        let mut формат_строка = String::new();
        let mut аргументы_printf: Vec<BasicValueEnum<'ctx>> = Vec::new();

        for фрагмент in фрагменты {
            match фрагмент {
                ФрагментТекста::Текст(текст) => {
                    формат_строка.push_str(&текст.replace('%', "%%"));
                }
                ФрагментТекста::Переменная(имя) => {
                    let значение = self.сгенерировать_выражение(&Выражение::Идентификатор(имя.clone()))?;
                    let значение_для_printf = match значение.get_type() {
                        BasicTypeEnum::PointerType(_) => {
                            формат_строка.push_str("%s");
                            значение
                        }
                        BasicTypeEnum::IntType(_) => {
                            формат_строка.push_str("%lld");
                            значение
                        }
                        BasicTypeEnum::FloatType(тип_float) => {
                            // Та же логика расширения f32 -> f64, что и в
                            // обычном вывести(...) (см. подробный комментарий
                            // там же про "default argument promotion" в
                            // variadic C-функциях) — здесь тот же класс риска,
                            // просто в другом месте кода, легко было упустить.
                            формат_строка.push_str("%f");
                            let f64_тип = self.контекст.f64_type();
                            if тип_float == self.контекст.f32_type() {
                                self.билдер
                                    .build_float_ext(значение.into_float_value(), f64_тип, "дробное_расширенное_для_интерполяции")
                                    .map_err(|e| ошибка(format!("ошибка расширения дробного числа для интерполяции: {:?}", e)))?
                                    .into()
                            } else {
                                значение
                            }
                        }
                        other => {
                            return Err(ошибка(format!(
                                "переменную '{}' (тип {:?}) нельзя вставить в строку через '$' — \
                                 поддерживаются только текст, целые числа, дробные числа и 'верно'",
                                имя, other
                            )));
                        }
                    };
                    аргументы_printf.push(значение_для_printf);
                }
            }
        }
        формат_строка.push('\n');

        let формат_значение = self.сгенерировать_текстовый_литерал(&формат_строка)?;

        let mut все_аргументы: Vec<inkwell::values::BasicMetadataValueEnum> = vec![формат_значение.into()];
        все_аргументы.extend(аргументы_printf.into_iter().map(inkwell::values::BasicMetadataValueEnum::from));

        self.билдер
            .build_call(printf, &все_аргументы, "вывести_интерполяция_вызов")
            .map_err(|e| ошибка(format!("ошибка вызова вывести с интерполяцией: {:?}", e)))?;

        Ok(self.контекст.i32_type().const_int(0, false).into())
    }

    /// ARC: увеличивает счётчик ссылок объекта на 1 — вызывается каждый раз,
    /// когда указатель на СУЩЕСТВУЮЩИЙ объект копируется в новое место
    /// (другую переменную, поле другой структуры), а не создаётся заново
    /// через конструктор (у свежесозданного объекта счётчик и так уже 1).
    fn захватить(&mut self, указатель: PointerValue<'ctx>, llvm_struct: StructType<'ctx>) -> Result<(), ОшибкаКодогенерации> {
        let адрес_счётчика = self
            .билдер
            .build_struct_gep(llvm_struct, указатель, 0, "адрес_счётчика")
            .map_err(|e| ошибка(format!("ошибка захвата (ARC): {:?}", e)))?;
        let текущий = self
            .билдер
            .build_load(self.контекст.i64_type(), адрес_счётчика, "текущий_счётчик")
            .map_err(|e| ошибка(format!("ошибка захвата (ARC): {:?}", e)))?
            .into_int_value();
        let новый = self
            .билдер
            .build_int_add(текущий, self.контекст.i64_type().const_int(1, false), "новый_счётчик")
            .map_err(|e| ошибка(format!("ошибка захвата (ARC): {:?}", e)))?;
        self.билдер
            .build_store(адрес_счётчика, новый)
            .map_err(|e| ошибка(format!("ошибка захвата (ARC): {:?}", e)))?;
        Ok(())
    }

    /// ARC: уменьшает счётчик ссылок объекта на 1; если счётчик доходит до
    /// нуля — объект больше никому не нужен, рекурсивно освобождаем все его
    /// поля-структуры (см. структурные_поля), затем освобождаем память
    /// самого объекта через free.
    ///
    /// Рекурсия ПЕРЕД free — важный порядок: структура ещё валидна и её
    /// поля ещё читаемы в момент, когда мы идём вглубь; если бы порядок был
    /// обратным (free, потом чтение полей), это было бы чтением уже
    /// освобождённой памяти.
    ///
    /// `имя_структуры` — нужно, чтобы найти список полей-структур в
    /// self.структурные_поля (сам LLVM-тип этой информации не несёт —
    /// та же причина, по которой мы вообще стали хранить имена структур
    /// явно, а не пытаться вывести их из LLVM-типа, см. обсуждение opaque
    /// pointers при более ранней работе над ARC).
    fn отпустить(&mut self, указатель: PointerValue<'ctx>, имя_структуры: &str, llvm_struct: StructType<'ctx>) -> Result<(), ОшибкаКодогенерации> {
        let адрес_счётчика = self
            .билдер
            .build_struct_gep(llvm_struct, указатель, 0, "адрес_счётчика")
            .map_err(|e| ошибка(format!("ошибка освобождения (ARC): {:?}", e)))?;
        let текущий = self
            .билдер
            .build_load(self.контекст.i64_type(), адрес_счётчика, "текущий_счётчик")
            .map_err(|e| ошибка(format!("ошибка освобождения (ARC): {:?}", e)))?
            .into_int_value();
        let новый = self
            .билдер
            .build_int_sub(текущий, self.контекст.i64_type().const_int(1, false), "новый_счётчик")
            .map_err(|e| ошибка(format!("ошибка освобождения (ARC): {:?}", e)))?;
        self.билдер
            .build_store(адрес_счётчика, новый)
            .map_err(|e| ошибка(format!("ошибка освобождения (ARC): {:?}", e)))?;

        let функция = self
            .текущая_функция
            .ok_or_else(|| ошибка("внутренняя ошибка: 'отпустить' вызван вне тела функции"))?;

        let условие_ноль = self
            .билдер
            .build_int_compare(IntPredicate::EQ, новый, self.контекст.i64_type().const_int(0, false), "счётчик_ноль")
            .map_err(|e| ошибка(format!("ошибка освобождения (ARC): {:?}", e)))?;

        let блок_освободить = self.контекст.append_basic_block(функция, "arc_освободить");
        let блок_продолжить = self.контекст.append_basic_block(функция, "arc_продолжить");

        self.билдер
            .build_conditional_branch(условие_ноль, блок_освободить, блок_продолжить)
            .map_err(|e| ошибка(format!("ошибка освобождения (ARC): {:?}", e)))?;

        self.билдер.position_at_end(блок_освободить);

        // Рекурсивное освобождение полей-структур — ДО free, пока память
        // ещё валидна. Защита от циклических ссылок ТИПОВ (структура А
        // ссылается на Б, Б ссылается обратно на А в самом ОБЪЯВЛЕНИИ
        // типов) — если структура с этим именем уже где-то выше по цепочке
        // рекурсивных вызовов "отпустить", не рекурсируем повторно, иначе
        // кодогенератор ушёл бы в бесконечную рекурсию ПРЯМО ВО ВРЕМЯ
        // СБОРКИ (не в рантайме программы пользователя — в самом
        // компиляторе). Это отдельная защита от РЕАЛЬНЫХ циклов ССЫЛОК
        // между ЭКЗЕМПЛЯРАМИ структур в рантайме — для НИХ теперь есть
        // "слабая" (см. слабые_поля/все_структурные_поля), исключающая
        // поле из ЭТОЙ САМОЙ ЛОГИКИ рекурсивного освобождения ниже.
        if !self.цепочка_рекурсивного_освобождения.contains(имя_структуры) {
            if let Some(поля) = self.структурные_поля.get(имя_структуры).cloned() {
                self.цепочка_рекурсивного_освобождения.insert(имя_структуры.to_string());

                for (индекс_поля, имя_структуры_поля) in поля {
                    let (llvm_struct_поля, _) = match self.структуры.get(&имя_структуры_поля).cloned() {
                        Some(запись) => запись,
                        None => continue, // защитная проверка, не должна срабатывать в норме
                    };
                    let тип_указателя_поля = llvm_struct_поля.ptr_type(inkwell::AddressSpace::default());

                    let адрес_поля = self
                        .билдер
                        .build_struct_gep(llvm_struct, указатель, индекс_поля, "адрес_поля_для_рекурсивного_отпускания")
                        .map_err(|e| ошибка(format!("ошибка рекурсивного освобождения (ARC): {:?}", e)))?;
                    let значение_поля = self
                        .билдер
                        .build_load(тип_указателя_поля, адрес_поля, "значение_поля_для_рекурсивного_отпускания")
                        .map_err(|e| ошибка(format!("ошибка рекурсивного освобождения (ARC): {:?}", e)))?
                        .into_pointer_value();

                    self.отпустить(значение_поля, &имя_структуры_поля, llvm_struct_поля)?;
                }

                self.цепочка_рекурсивного_освобождения.remove(имя_структуры);
            }
        }

        let free = self
            .модуль
            .get_function("free")
            .ok_or_else(|| ошибка("внутренняя ошибка: free не была объявлена"))?;

        // НОВОЕ (текст под ARC — поля структур): безусловное освобождение
        // каждого текстового поля — безопасно именно потому, что запись в
        // такое поле ВСЕГДА идёт через strdup (см. сгенерировать_вызов_
        // конструктора) — структура гарантированно владеет этой памятью,
        // никогда не хранит указатель на литерал или чужие данные.
        if let Some(текстовые_поля) = self.текстовые_поля_структур.get(имя_структуры).cloned() {
            for llvm_индекс in текстовые_поля {
                let адрес_текстового_поля = self
                    .билдер
                    .build_struct_gep(llvm_struct, указатель, llvm_индекс, "адрес_текстового_поля_для_освобождения")
                    .map_err(|e| ошибка(format!("ошибка освобождения текстового поля (ARC): {:?}", e)))?;
                let значение_текстового_поля = self
                    .билдер
                    .build_load(
                        self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default()),
                        адрес_текстового_поля,
                        "значение_текстового_поля_для_освобождения",
                    )
                    .map_err(|e| ошибка(format!("ошибка освобождения текстового поля (ARC): {:?}", e)))?;
                self.билдер
                    .build_call(free, &[значение_текстового_поля.into()], "освободить_текстовое_поле")
                    .map_err(|e| ошибка(format!("ошибка освобождения текстового поля (ARC): {:?}", e)))?;
            }
        }

        let сырой_указатель = self
            .билдер
            .build_pointer_cast(
                указатель,
                self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default()),
                "сырой_указатель",
            )
            .map_err(|e| ошибка(format!("ошибка освобождения (ARC): {:?}", e)))?;
        self.билдер
            .build_call(free, &[сырой_указатель.into()], "free_вызов")
            .map_err(|e| ошибка(format!("ошибка освобождения (ARC): {:?}", e)))?;
        self.билдер
            .build_unconditional_branch(блок_продолжить)
            .map_err(|e| ошибка(format!("ошибка освобождения (ARC): {:?}", e)))?;

        self.билдер.position_at_end(блок_продолжить);
        Ok(())
    }

    /// ARC, низкоуровневый помощник: отпускает конкретный СПИСОК структурных
    /// переменных (по имени + их LLVM-тип), кроме той, что совпадает с
    /// `возвращаемое_имя` (если задано) — используется и "освободить весь
    /// стек" (для "вернуть"), и "освободить один фрейм" (для естественного
    /// выхода из блока), чтобы не дублировать сам цикл дважды.
    fn отпустить_список_структур(
        &mut self,
        структуры: &[(String, String, StructType<'ctx>)],
        возвращаемое_имя: Option<&str>,
    ) -> Result<(), ОшибкаКодогенерации> {
        for (имя, имя_структуры, llvm_struct) in структуры {
            if Some(имя.as_str()) == возвращаемое_имя {
                continue; // владение перемещается наружу — не трогаем счётчик
            }

            let (указатель_ячейки, llvm_тип_ячейки, _) = match self.переменные.get(имя) {
                Some(запись) => запись.clone(),
                None => continue, // защитная проверка, не должна срабатывать в норме
            };

            let указатель_на_объект = self
                .билдер
                .build_load(llvm_тип_ячейки, указатель_ячейки, "загрузка_для_освобождения")
                .map_err(|e| ошибка(format!("ошибка чтения '{}' для освобождения (ARC): {:?}", имя, e)))?
                .into_pointer_value();

            self.отпустить(указатель_на_объект, имя_структуры, *llvm_struct)?;
        }
        Ok(())
    }

    /// ARC: вызывается перед КАЖДЫМ "вернуть", на ЛЮБОЙ глубине вложенности
    /// (и перед неявным возвратом void-функции) — отпускает структурные
    /// переменные из ВСЕХ уровней стека областей видимости (вся функция,
    /// плюс все блоки если/пока/для каждого, внутри которых мы сейчас
    /// находимся), кроме той, что совпадает с самим возвращаемым выражением
    /// (если оно — простое имя переменной): в этом случае владение объектом
    /// не уменьшается и не увеличивается, а просто "перемещается" наружу —
    /// та же идея, что и семантика перемещения (move) в Rust.
    ///
    /// `возвращаемое_выражение` — `None` для неявного/пустого "вернуть;",
    /// `Some(выражение)` для "вернуть выражение;".
    fn освободить_при_возврате(&mut self, возвращаемое_выражение: Option<&Выражение>) -> Result<(), ОшибкаКодогенерации> {
        let возвращаемое_имя = match возвращаемое_выражение {
            Some(Выражение::Идентификатор(имя)) => Some(имя.clone()),
            _ => None,
        };

        // Клонируем стек ДО цикла — внутри цикла вызывается self.отпустить(...),
        // которая берёт &mut self, что конфликтовало бы с одновременным
        // заимствованием self.стек_arc_областей на чтение.
        let весь_стек = self.стек_arc_областей.clone();
        for фрейм in &весь_стек {
            self.отпустить_список_структур(фрейм, возвращаемое_имя.as_deref())?;
        }

        // НОВОЕ (текст под ARC): та же защита, что и для структур выше —
        // если возвращается ИМЕННО эта текстовая переменная, не освобождаем
        // её здесь (она "передаётся" вызывающей стороне вместе со своим
        // содержимым, а не копируется).
        let весь_стек_текста = self.стек_arc_областей_текста.clone();
        for фрейм in &весь_стек_текста {
            self.отпустить_список_текстовых_переменных(фрейм, возвращаемое_имя.as_deref())?;
        }
        Ok(())
    }

    /// ARC (текст): освобождает (free) каждую текстовую переменную из
    /// списка ИМЁН, КРОМЕ той, что указана в "защищённое_имя" (если есть)
    /// — та же логика, что и у отпустить_список_структур, только для
    /// текста (обычный free(), не рекурсивное "отпустить" — у текста нет
    /// счётчика ссылок и вложенных полей для рекурсивного освобождения).
    /// НОВОЕ (текст под ARC, закрытие пробела внутри циклов): возвращает
    /// адрес булевой (i1) alloca-ячейки для флага владения указанной
    /// текстовой переменной — создаёт её, если ещё не было (лениво, один
    /// раз за всю компиляцию тела функции — компиляционная проверка
    /// "уже есть в HashMap" гарантирует это, даже если место обращения —
    /// внутри цикла, выполняющегося много раз в рантайме). См. подробное
    /// объяснение архитектуры у поля флаги_владения_текстом.
    fn получить_или_создать_флаг_владения(&mut self, имя: &str) -> Result<inkwell::values::PointerValue<'ctx>, ОшибкаКодогенерации> {
        if let Some(адрес) = self.флаги_владения_текстом.get(имя) {
            return Ok(*адрес);
        }

        // ⚠️ НАЙДЕНА РЕАЛЬНОЙ ПРОВЕРКОЙ, КЛАССИЧЕСКАЯ ЛОВУШКА LLVM: если
        // просто вызвать build_alloca в ТЕКУЩЕЙ позиции билдера — а первая
        // встреча этой переменной может оказаться ВНУТРИ ветки "если"/
        // "иначе" — alloca физически размещается внутри ЭТОГО базового
        // блока, а не в начале функции. Раз флаг переиспользуется через
        // HashMap МЕЖДУ разными ветками (в отличие от обычных локальных
        // переменных, каждая из которых используется только там, где
        // объявлена) — при повторном входе в тот же условный блок внутри
        // цикла эта alloca-инструкция выполняется заново, каждый раз выделяя
        // НОВУЮ ячейку на стеке — предыдущее записанное в неё значение
        // теряется, ломая всю логику отслеживания владения. Решение —
        // всегда размещать alloca флага в самом начале функции (entry
        // block), независимо от того, где по коду это первая встреча.
        let текущая_позиция = self
            .билдер
            .get_insert_block()
            .ok_or_else(|| ошибка("внутренняя ошибка: флаг владения текстом создаётся вне тела функции"))?;
        let функция = self
            .текущая_функция
            .ok_or_else(|| ошибка("внутренняя ошибка: флаг владения текстом создаётся вне тела функции"))?;
        let entry_блок = функция
            .get_first_basic_block()
            .ok_or_else(|| ошибка("внутренняя ошибка: у функции нет ни одного базового блока"))?;

        match entry_блок.get_first_instruction() {
            Some(первая_инструкция) => self.билдер.position_before(&первая_инструкция),
            None => self.билдер.position_at_end(entry_блок),
        }

        let адрес = self
            .билдер
            .build_alloca(self.контекст.bool_type(), &format!("флаг_владения_{}", имя))
            .map_err(|e| ошибка(format!("ошибка создания флага владения для '{}': {:?}", имя, e)))?;

        // Возвращаем билдер туда, откуда реально вызвали эту функцию —
        // дальнейшая генерация кода должна продолжиться с того места, а
        // не с начала функции.
        self.билдер.position_at_end(текущая_позиция);

        self.флаги_владения_текстом.insert(имя.to_string(), адрес);
        Ok(адрес)
    }

    fn отпустить_список_текстовых_переменных(&mut self, имена: &[String], защищённое_имя: Option<&str>) -> Result<(), ОшибкаКодогенерации> {
        for имя in имена {
            if Some(имя.as_str()) == защищённое_имя {
                continue;
            }
            let (адрес, llvm_тип, _) = match self.переменные.get(имя) {
                Some(запись) => запись.clone(),
                None => continue, // защитная проверка, не должна срабатывать в норме
            };
            let значение = self
                .билдер
                .build_load(llvm_тип, адрес, &format!("текст_для_освобождения_{}", имя))
                .map_err(|e| ошибка(format!("ошибка чтения текстовой переменной '{}' для освобождения: {:?}", имя, e)))?;

            let free = self
                .модуль
                .get_function("free")
                .ok_or_else(|| ошибка("внутренняя ошибка: free не была объявлена"))?;

            // НОВОЕ (текст под ARC, продолжение): переменная может хранить
            // либо голый текст (простой указатель — освобождаем как раньше,
            // безусловно), либо результат<текст> (структура { успешно,
            // значение, сообщение } — освобождаем ТОЛЬКО поле "значение",
            // и ТОЛЬКО если "успешно" истинно — при неудаче поле значение
            // не было создано этим вызовом, освобождать нечего/нельзя).
            if значение.is_struct_value() {
                let структура = значение.into_struct_value();
                let успешно = self
                    .билдер
                    .build_extract_value(структура, 0, "успешно_для_освобождения")
                    .map_err(|e| ошибка(format!("ошибка чтения поля 'успешно' у '{}': {:?}", имя, e)))?
                    .into_int_value();

                let текущая_функция = self
                    .текущая_функция
                    .ok_or_else(|| ошибка("внутренняя ошибка: освобождение результат<текст> вне функции"))?;
                let блок_освобождения = self.контекст.append_basic_block(текущая_функция, "результат_текст_освободить");
                let блок_продолжения = self.контекст.append_basic_block(текущая_функция, "результат_текст_продолжить");

                self.билдер
                    .build_conditional_branch(успешно, блок_освобождения, блок_продолжения)
                    .map_err(|e| ошибка(format!("ошибка условного перехода при освобождении '{}': {:?}", имя, e)))?;

                self.билдер.position_at_end(блок_освобождения);
                let значение_текста = self
                    .билдер
                    .build_extract_value(структура, 1, "значение_результат_текста")
                    .map_err(|e| ошибка(format!("ошибка чтения поля 'значение' у '{}': {:?}", имя, e)))?;
                self.билдер
                    .build_call(free, &[значение_текста.into()], "освободить_значение_результата")
                    .map_err(|e| ошибка(format!("ошибка освобождения значения результат<текст> '{}': {:?}", имя, e)))?;
                self.билдер
                    .build_unconditional_branch(блок_продолжения)
                    .map_err(|e| ошибка(format!("ошибка перехода после освобождения '{}': {:?}", имя, e)))?;

                self.билдер.position_at_end(блок_продолжения);
            } else {
                // ⚠️ НАЙДЕНО РЕАЛЬНОЙ ПРОВЕРКОЙ (закрытие утечки внутри
                // циклов): раньше здесь было БЕЗУСЛОВНОЕ free() — правильно,
                // пока переменная попадала в этот список ТОЛЬКО когда точно
                // владела значением. Теперь, когда решение о владении
                // проверяется в рантайме (флаг), переменная в этом списке
                // может НЕ владеть значением НА МОМЕНТ ВЫХОДА из функции
                // (например, последнее присваивание внутри цикла оказалось
                // литералом) — безусловный free() был бы крахом. Проверяем
                // флаг, если он существует для этой переменной (для
                // переменных, объявленных до этого исправления кода — не
                // бывает, но для единообразия используем ленивое создание).
                if let Some(флаг) = self.флаги_владения_текстом.get(имя).copied() {
                    let владеет = self
                        .билдер
                        .build_load(self.контекст.bool_type(), флаг, "флаг_владения_чтение_при_освобождении")
                        .map_err(|e| ошибка(format!("ошибка чтения флага владения при освобождении '{}': {:?}", имя, e)))?
                        .into_int_value();

                    let текущая_функция = self
                        .текущая_функция
                        .ok_or_else(|| ошибка("внутренняя ошибка: освобождение текста вне функции"))?;
                    let блок_освобождения = self.контекст.append_basic_block(текущая_функция, "текст_фрейм_освободить");
                    let блок_продолжения = self.контекст.append_basic_block(текущая_функция, "текст_фрейм_продолжить");

                    self.билдер
                        .build_conditional_branch(владеет, блок_освобождения, блок_продолжения)
                        .map_err(|e| ошибка(format!("ошибка условного перехода при освобождении '{}': {:?}", имя, e)))?;

                    self.билдер.position_at_end(блок_освобождения);
                    self.билдер
                        .build_call(free, &[значение.into()], "освободить_текст")
                        .map_err(|e| ошибка(format!("ошибка освобождения текстовой переменной '{}': {:?}", имя, e)))?;
                    self.билдер
                        .build_unconditional_branch(блок_продолжения)
                        .map_err(|e| ошибка(format!("ошибка перехода после освобождения '{}': {:?}", имя, e)))?;

                    self.билдер.position_at_end(блок_продолжения);
                } else {
                    // Флага нет — переменная никогда не проходила через
                    // логику переприсваивания/объявления с флагом (не
                    // должно происходить в норме после этого исправления,
                    // но безопасный запасной путь — старое, безусловное
                    // поведение).
                    self.билдер
                        .build_call(free, &[значение.into()], "освободить_текст")
                        .map_err(|e| ошибка(format!("ошибка освобождения текстовой переменной '{}': {:?}", имя, e)))?;
                }
            }
        }
        Ok(())
    }

    /// ARC: вызывается при ЕСТЕСТВЕННОМ выходе из вложенного блока (если/
    /// пока/для каждого) — то есть когда управление доходит до конца блока
    /// БЕЗ явного "вернуть" внутри него (проверяется через блок_не_завершён
    /// в вызывающем коде). Отпускает структуры ТОЛЬКО текущего (самого
    /// вложенного) уровня стека — родительские уровни трогать нельзя, они
    /// всё ещё "живы", мы просто возвращаемся в них, а не покидаем функцию.
    /// НЕ убирает фрейм со стека сам — это делает вызывающий код сразу
    /// после (см. сгенерировать_если и другие места).
    fn освободить_текущий_фрейм(&mut self) -> Result<(), ОшибкаКодогенерации> {
        let текущий_фрейм = match self.стек_arc_областей.last() {
            Some(фрейм) => фрейм.clone(),
            None => return Ok(()), // защитная проверка, не должна срабатывать в норме
        };
        self.отпустить_список_структур(&текущий_фрейм, None)?;

        // НОВОЕ (текст под ARC): аналогично — освобождаем текстовые
        // переменные ТОЛЬКО текущего уровня, без защиты (естественный
        // выход из блока не возвращает никакое значение наружу).
        let текущий_фрейм_текста = match self.стек_arc_областей_текста.last() {
            Some(фрейм) => фрейм.clone(),
            None => return Ok(()),
        };
        self.отпустить_список_текстовых_переменных(&текущий_фрейм_текста, None)
    }

    /// Генерирует "Список<целое>()" — создаёт ПУСТОЙ список: выделяет память
    /// под саму служебную структуру (не под данные — данные выделятся позже,
    /// при первом .добавить()), счётчик ссылок = 1 (как у любого свежего
    /// объекта, см. структуры), размер = 0, вместимость = 0, указатель на
    /// данные = null (безопасное, "ничего ещё не выделено" состояние).
    fn сгенерировать_список_конструктор(&mut self, типовые_параметры: &[Тип]) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        if типовые_параметры.len() != 1 {
            return Err(ошибка("внутренняя ошибка: Список<тип>() должен иметь ровно один типовый параметр (должно быть отловлено семантикой раньше)"));
        }

        // НОВОЕ (Список<Контракт>): та же самая, уже несколько раз
        // встречавшаяся путаница — "РешённыйТип::from" не знает о
        // контрактах, безусловно превращает "Печатаемый" в обычную
        // Структура. Это ЧЕТВЁРТОЕ по счёту место с этой же ошибкой,
        // найденное только благодаря временному отладочному выводу —
        // семантика и другие места кодогенерации (тип_в_llvm,
        // дополнительная_информация_из_ast_типа) уже были исправлены
        // раньше, но именно ЭТО место (генерация самого вызова
        // "Список<Печатаемый>()") оставалось нетронутым.
        let тип_элемента_решённый = if let Тип::Пользовательский(имя_типа) = &типовые_параметры[0] {
            if self.контракты_методы.contains_key(имя_типа) {
                РешённыйТип::Контракт(имя_типа.clone())
            } else {
                РешённыйТип::from(&типовые_параметры[0])
            }
        } else {
            РешённыйТип::from(&типовые_параметры[0])
        };
        let ключ = ключ_типа_списка(&тип_элемента_решённый);
        let llvm_struct = *self.списки.get(&ключ).ok_or_else(|| {
            ошибка(format!("внутренняя ошибка: Список<{}> не был зарегистрирован заранее", ключ))
        })?;

        let malloc = self
            .модуль
            .get_function("malloc")
            .ok_or_else(|| ошибка("внутренняя ошибка: malloc не была объявлена"))?;

        let размер_структуры = llvm_struct
            .size_of()
            .ok_or_else(|| ошибка("не удалось вычислить размер структуры Список<тип>"))?;

        let сырой_указатель = self
            .билдер
            .build_call(malloc, &[размер_структуры.into()], "новый_список")
            .map_err(|e| ошибка(format!("ошибка выделения памяти для списка: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("malloc неожиданно не вернул значение"))?
            .into_pointer_value();

        let указатель_на_список = self
            .билдер
            .build_pointer_cast(сырой_указатель, llvm_struct.ptr_type(inkwell::AddressSpace::default()), "указатель_списка")
            .map_err(|e| ошибка(format!("ошибка приведения указателя списка: {:?}", e)))?;

        let i64_тип = self.контекст.i64_type();

        // Поле 0: счётчик_ссылок = 1
        self.записать_поле_списка(llvm_struct, указатель_на_список, 0, i64_тип.const_int(1, false).into())?;
        // Поле 1: размер = 0
        self.записать_поле_списка(llvm_struct, указатель_на_список, 1, i64_тип.const_int(0, false).into())?;
        // Поле 2: вместимость = 0
        self.записать_поле_списка(llvm_struct, указатель_на_список, 2, i64_тип.const_int(0, false).into())?;
        // Поле 3: данные = null
        let llvm_элемент = self.тип_в_llvm(&типовые_параметры[0])?;
        let тип_указателя_данных = llvm_элемент.ptr_type(inkwell::AddressSpace::default());
        self.записать_поле_списка(llvm_struct, указатель_на_список, 3, тип_указателя_данных.const_null().into())?;

        Ok(указатель_на_список.into())
    }

    /// Генерирует "Словарь<Ключ, Значение>()" — аналогично сгенерировать_список_конструктор,
    /// но с ДВУМЯ полями-указателями (ключи, значения) вместо одного.
    fn сгенерировать_словарь_конструктор(&mut self, типовые_параметры: &[Тип]) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        if типовые_параметры.len() != 2 {
            return Err(ошибка("внутренняя ошибка: Словарь<Ключ, Значение>() должен иметь ровно два типовых параметра (должно быть отловлено семантикой раньше)"));
        }

        let тип_ключа_решённый = РешённыйТип::from(&типовые_параметры[0]);
        let тип_значения_решённый = РешённыйТип::from(&типовые_параметры[1]);
        let ключ = ключ_типа_словаря(&тип_ключа_решённый, &тип_значения_решённый);
        let llvm_struct = *self.словари.get(&ключ).ok_or_else(|| {
            ошибка(format!("внутренняя ошибка: Словарь<{}> не был зарегистрирован заранее", ключ))
        })?;

        let malloc = self
            .модуль
            .get_function("malloc")
            .ok_or_else(|| ошибка("внутренняя ошибка: malloc не была объявлена"))?;

        let размер_структуры = llvm_struct
            .size_of()
            .ok_or_else(|| ошибка("не удалось вычислить размер структуры Словарь<Ключ, Значение>"))?;

        let сырой_указатель = self
            .билдер
            .build_call(malloc, &[размер_структуры.into()], "новый_словарь")
            .map_err(|e| ошибка(format!("ошибка выделения памяти для словаря: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("malloc неожиданно не вернул значение"))?
            .into_pointer_value();

        let указатель_на_словарь = self
            .билдер
            .build_pointer_cast(сырой_указатель, llvm_struct.ptr_type(inkwell::AddressSpace::default()), "указатель_словаря")
            .map_err(|e| ошибка(format!("ошибка приведения указателя словаря: {:?}", e)))?;

        let i64_тип = self.контекст.i64_type();

        // Поле 0: счётчик_ссылок = 1; поле 1: размер = 0; поле 2: вместимость = 0
        self.записать_поле_списка(llvm_struct, указатель_на_словарь, 0, i64_тип.const_int(1, false).into())?;
        self.записать_поле_списка(llvm_struct, указатель_на_словарь, 1, i64_тип.const_int(0, false).into())?;
        self.записать_поле_списка(llvm_struct, указатель_на_словарь, 2, i64_тип.const_int(0, false).into())?;

        // Поле 3: ключи = null; поле 4: значения = null
        let llvm_тип_ключа = self.тип_в_llvm(&типовые_параметры[0])?;
        let llvm_тип_значения = self.тип_в_llvm(&типовые_параметры[1])?;
        let тип_указателя_ключей = llvm_тип_ключа.ptr_type(inkwell::AddressSpace::default());
        let тип_указателя_значений = llvm_тип_значения.ptr_type(inkwell::AddressSpace::default());
        self.записать_поле_списка(llvm_struct, указатель_на_словарь, 3, тип_указателя_ключей.const_null().into())?;
        self.записать_поле_списка(llvm_struct, указатель_на_словарь, 4, тип_указателя_значений.const_null().into())?;

        Ok(указатель_на_словарь.into())
    }

    /// Вспомогательный метод: GEP + store в конкретное поле служебной
    /// структуры Список<тип> по числовому индексу. Используется и конструктором,
    /// и методами (добавить/получить/размер) — вынесено отдельно, чтобы не
    /// повторять одну и ту же пару GEP+store каждый раз вручную.
    fn записать_поле_списка(
        &mut self,
        llvm_struct: StructType<'ctx>,
        указатель: PointerValue<'ctx>,
        индекс: u32,
        значение: BasicValueEnum<'ctx>,
    ) -> Result<(), ОшибкаКодогенерации> {
        let адрес = self
            .билдер
            .build_struct_gep(llvm_struct, указатель, индекс, "адрес_поля_списка")
            .map_err(|e| ошибка(format!("ошибка доступа к полю списка №{}: {:?}", индекс, e)))?;
        self.билдер
            .build_store(адрес, значение)
            .map_err(|e| ошибка(format!("ошибка записи поля списка №{}: {:?}", индекс, e)))?;
        Ok(())
    }

    /// Вспомогательный метод: GEP + load для чтения поля служебной
    /// структуры Список<тип> по числовому индексу и известному LLVM-типу поля.
    fn прочитать_поле_списка(
        &mut self,
        llvm_struct: StructType<'ctx>,
        указатель: PointerValue<'ctx>,
        индекс: u32,
        тип_поля: BasicTypeEnum<'ctx>,
        имя: &str,
    ) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        let адрес = self
            .билдер
            .build_struct_gep(llvm_struct, указатель, индекс, &format!("адрес_{}", имя))
            .map_err(|e| ошибка(format!("ошибка доступа к полю списка '{}': {:?}", имя, e)))?;
        self.билдер
            .build_load(тип_поля, адрес, имя)
            .map_err(|e| ошибка(format!("ошибка чтения поля списка '{}': {:?}", имя, e)))
    }

    fn сгенерировать_вызов_конструктора(
        &mut self,
        имя_структуры: &str,
        аргументы: &[Выражение],
    ) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        let (llvm_struct, имена_полей) = self
            .структуры
            .get(имя_структуры)
            .ok_or_else(|| ошибка(format!("внутренняя ошибка: структура '{}' не зарегистрирована", имя_структуры)))?
            .clone();

        if аргументы.len() != имена_полей.len() {
            return Err(ошибка(format!(
                "конструктор '{}' ожидает {} аргумент(ов), передано {} — \
                 это должно было быть отловлено семантическим анализатором раньше",
                имя_структуры, имена_полей.len(), аргументы.len()
            )));
        }

        // Узнаём размер структуры в байтах, чтобы попросить malloc ровно
        // столько памяти, сколько нужно. LLVM даёт это через size_of на типе.
        let размер = llvm_struct
            .size_of()
            .ok_or_else(|| ошибка(format!("не удалось вычислить размер структуры '{}'", имя_структуры)))?;

        let malloc = self
            .модуль
            .get_function("malloc")
            .ok_or_else(|| ошибка("внутренняя ошибка: malloc не была объявлена"))?;

        let сырой_указатель = self
            .билдер
            .build_call(malloc, &[размер.into()], "новый_объект")
            .map_err(|e| ошибка(format!("ошибка выделения памяти для '{}': {:?}", имя_структуры, e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("malloc неожиданно не вернул значение"))?
            .into_pointer_value();

        // malloc возвращает i8* (обычный "сырой" указатель на байты) — приводим
        // его к указателю на нашу конкретную структуру, чтобы дальше можно было
        // использовать типизированный GEP.
        let указатель_на_структуру = self
            .билдер
            .build_pointer_cast(
                сырой_указатель,
                llvm_struct.ptr_type(inkwell::AddressSpace::default()),
                "указатель_структуры",
            )
            .map_err(|e| ошибка(format!("ошибка приведения указателя для '{}': {:?}", имя_структуры, e)))?;

        // ARC: новый объект начинает жизнь с ровно одной ссылкой на себя —
        // той самой, что мы сейчас возвращаем как результат конструктора.
        let адрес_счётчика = self
            .билдер
            .build_struct_gep(llvm_struct, указатель_на_структуру, 0, "счётчик_ссылок")
            .map_err(|e| ошибка(format!("ошибка доступа к счётчику ссылок '{}': {:?}", имя_структуры, e)))?;
        self.билдер
            .build_store(адрес_счётчика, self.контекст.i64_type().const_int(1, false))
            .map_err(|e| ошибка(format!("ошибка инициализации счётчика ссылок '{}': {:?}", имя_структуры, e)))?;

        // ARC: если аргумент конструктора — ПРОСТАЯ ПЕРЕМЕННАЯ (не свежий
        // вызов другого конструктора), и это поле само является структурой —
        // нужно "захватить" (увеличить счётчик ссылок), потому что теперь
        // на этот объект ссылаются ДВА места: исходная переменная И новое
        // поле. Без этого при освобождении обеих (переменной и структуры,
        // в которую она была передана) счётчик уменьшился бы дважды за
        // один и тот же объект — классический use-after-free (счётчик
        // дойдёт до нуля и вызовет free раньше, чем реально нужно, а второе
        // отпускание тронет уже освобождённую память). Не ретейним, если
        // аргумент — свежий вызов конструктора (`Компания("Р", Пользователь(...))`)
        // — там счётчик и так уже 1 после создания, повторный retain создал
        // бы утечку (счётчик никогда не дойдёт до 0).
        let структурные_поля_этой_структуры = self.структурные_поля.get(имя_структуры).cloned().unwrap_or_default();

        for (индекс, аргумент) in аргументы.iter().enumerate() {
            let значение = self.сгенерировать_выражение(аргумент)?;
            let llvm_индекс = индекс as u32 + СМЕЩЕНИЕ_ПОЛЕЙ_ARC;

            if matches!(аргумент, Выражение::Идентификатор(_)) {
                if let Some((_, имя_структуры_поля)) = структурные_поля_этой_структуры
                    .iter()
                    .find(|(индекс_поля, _)| *индекс_поля == llvm_индекс)
                {
                    if let Some((llvm_struct_поля, _)) = self.структуры.get(имя_структуры_поля).cloned() {
                        self.захватить(значение.into_pointer_value(), llvm_struct_поля)?;
                    }
                }
            }

            let адрес_поля = self.билдер
                .build_struct_gep(llvm_struct, указатель_на_структуру, llvm_индекс, &имена_полей[индекс])
                .map_err(|e| ошибка(format!(
                    "ошибка получения адреса поля '{}' структуры '{}': {:?}",
                    имена_полей[индекс], имя_структуры, e
                )))?;

            // ⚠️ НАЙДЕНО ПРИ РЕАЛЬНОЙ РАБОТЕ НАД UI-ВИДЖЕТАМИ: семантика
            // теперь допускает конструктор с числовым аргументом ДРУГОГО
            // размера, чем поле (см. проверить_совместимость_конструктора
            // в semantic.rs — например, "целое" литерал для поля "целое32"),
            // но LLVM требует ТОЧНОГО совпадения типов при записи в память
            // — без явного приведения здесь была бы паника inkwell.
            let ожидаемый_тип_поля = llvm_struct
                .get_field_type_at_index(llvm_индекс)
                .ok_or_else(|| ошибка(format!("не удалось определить тип поля '{}' структуры '{}'", имена_полей[индекс], имя_структуры)))?;
            let значение_для_записи = if значение.get_type() != ожидаемый_тип_поля {
                let целевой_дробный = ожидаемый_тип_поля.is_float_type();
                self.сгенерировать_приведение_числа(значение, ожидаемый_тип_поля, целевой_дробный, false)?
            } else {
                значение
            };

            // НОВОЕ (текст под ARC — поля структур): если это текстовое
            // поле — записываем НЕ сам переданный указатель, а его копию
            // через strdup. Это гарантирует, что структура ВСЕГДА владеет
            // своим текстовым полем (независимо от того, был ли аргумент
            // литералом или уже malloc'нутым значением) — без этого
            // безусловное освобождение при уничтожении структуры (см.
            // "отпустить") было бы небезопасным: попытка free() на
            // указателе строкового литерала — настоящий краш, не просто
            // утечка (та же самая категория ошибки, что уже была найдена
            // и исправлена один раз для "верно_в_текст").
            let текстовые_поля_этой_структуры = self.текстовые_поля_структур.get(имя_структуры).cloned().unwrap_or_default();
            let значение_для_записи = if текстовые_поля_этой_структуры.contains(&llvm_индекс) {
                let strdup = self
                    .модуль
                    .get_function("strdup")
                    .ok_or_else(|| ошибка("внутренняя ошибка: strdup не была объявлена"))?;
                self.билдер
                    .build_call(strdup, &[значение_для_записи.into()], "копия_текстового_поля")
                    .map_err(|e| ошибка(format!("ошибка копирования текстового поля '{}': {:?}", имена_полей[индекс], e)))?
                    .try_as_basic_value()
                    .left()
                    .ok_or_else(|| ошибка("strdup неожиданно не вернул значение"))?
            } else {
                значение_для_записи
            };

            self.билдер
                .build_store(адрес_поля, значение_для_записи)
                .map_err(|e| ошибка(format!(
                    "ошибка записи поля '{}' структуры '{}': {:?}",
                    имена_полей[индекс], имя_структуры, e
                )))?;
        }

        Ok(указатель_на_структуру.into())
    }

    /// Генерирует доступ к полю структуры: объект.поле. Сначала вычисляем
    /// выражение слева от точки (получаем указатель на структуру), затем
    /// находим числовой индекс нужного поля по имени и читаем значение
    /// оттуда через GEP + load.
    fn сгенерировать_доступ_к_полю(
        &mut self,
        объект: &Выражение,
        поле: &str,
    ) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        // Особый случай: объект — переменная типа результат<T>. У результат<T>
        // ровно три фиксированных псевдополя (успешно/значение/сообщение) с
        // одним и тем же макетом для ЛЮБОГО T — в отличие от пользовательских
        // структур, здесь не нужно искать структуру по имени в self.структуры,
        // достаточно знать индекс поля по его названию. Плюс результат<T>
        // хранится в переменной НАПРЯМУЮ (как массив), а не за указателем в
        // куче (как структуры) — значит нужен обычный load всего значения,
        // а не GEP до адреса структуры.
        if let Выражение::Идентификатор(имя) = объект {
            if let Some((указатель, llvm_тип, ДополнительнаяИнформация::Результат { .. })) = self.переменные.get(имя).cloned() {
                let индекс_поля = match поле {
                    "успешно" => 0,
                    "значение" => 1,
                    "сообщение" => 2,
                    other => {
                        return Err(ошибка(format!(
                            "у результат<тип> нет поля '{}' — доступны 'успешно', 'значение', 'сообщение'",
                            other
                        )));
                    }
                };

                let агрегат = self
                    .билдер
                    .build_load(llvm_тип, указатель, "результат")
                    .map_err(|e| ошибка(format!("ошибка чтения переменной '{}': {:?}", имя, e)))?
                    .into_struct_value();

                return self
                    .билдер
                    .build_extract_value(агрегат, индекс_поля, поле)
                    .map_err(|e| ошибка(format!("ошибка чтения поля '{}' результата: {:?}", поле, e)));
            }
        }

        // Обычный случай — доступ к полю пользовательской структуры.
        // Нам нужен именно указатель на структуру (а не "загруженное" значение),
        // поэтому для идентификатора берём указатель из таблицы переменных
        // напрямую, а не через обычный сгенерировать_выражение (который бы
        // сразу сделал load и потерял адрес, откуда читать поле).
        let (указатель_на_структуру, имя_структуры) = self.получить_структуру_из_выражения(объект)?;

        let (llvm_struct, имена_полей) = self
            .структуры
            .get(&имя_структуры)
            .ok_or_else(|| ошибка(format!("внутренняя ошибка: структура '{}' не найдена", имя_структуры)))?
            .clone();

        let индекс = имена_полей
            .iter()
            .position(|имя_поля| имя_поля == поле)
            .ok_or_else(|| ошибка(format!("у структуры '{}' нет поля '{}'", имя_структуры, поле)))?;
        let llvm_индекс = индекс as u32 + СМЕЩЕНИЕ_ПОЛЕЙ_ARC;

        let адрес_поля = self.билдер
            .build_struct_gep(llvm_struct, указатель_на_структуру, llvm_индекс, поле)
            .map_err(|e| ошибка(format!("ошибка доступа к полю '{}': {:?}", поле, e)))?;

        let тип_поля = llvm_struct
            .get_field_type_at_index(llvm_индекс)
            .ok_or_else(|| ошибка(format!("не удалось определить тип поля '{}'", поле)))?;

        self.билдер
            .build_load(тип_поля, адрес_поля, поле)
            .map_err(|e| ошибка(format!("ошибка чтения поля '{}': {:?}", поле, e)))
    }

    /// Генерирует вызов встроенного метода Список<тип> — размер/получить/добавить.
    ///
    /// ⚠️ Эта реализация использует несколько LLVM-техник впервые в этом
    /// компиляторе: `build_select` (для "новая_вместимость = если 0 {4} иначе
    /// {×2}"), `build_is_null` (проверка "есть ли уже выделенные данные"),
    /// и однo-индексный `build_gep` (для адресной арифметики "данные + индекс" —
    /// ОТЛИЧАЕТСЯ от двух-индексного GEP для фиксированных массивов: там
    /// pointee_ty — ArrayType с известным размером, здесь pointee_ty — просто
    /// элемент_тип, указатель на "начало буфера", а не на целый массив).
    /// Если здесь ошибка компиляции — вероятно, в сигнатуре одного из этих
    /// вызовов, см. README, раздел про риски Список<тип>.
    /// НОВОЕ (многопоточность, вторая часть): отправить(значение)/получить()
    /// у канал<T>. "значение" — 8-байтный слот по смещению 264 (см. layout
    /// в сгенерировать_создать_канал) — конкретная интерпретация этих 8
    /// байт зависит от того, целое это, указатель (текст/структура) или
    /// что-то более узкое (целое32) — приводим соответственно перед
    /// записью/после чтения, храня всегда ровно 8 байт "как есть" через
    /// битовое представление (не через числовое расширение/усечение,
    /// которое исказило бы указатели).
    fn сгенерировать_метод_канала(
        &mut self,
        указатель_на_канал: inkwell::values::PointerValue<'ctx>,
        элемент: BasicTypeEnum<'ctx>,
        метод: &str,
        аргументы: &[Выражение],
    ) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        let i64_тип = self.контекст.i64_type();
        let указатель_на_мьютекс = указатель_на_канал;
        let указатель_на_cond = unsafe {
            self.билдер.build_gep(
                self.контекст.i8_type(),
                указатель_на_канал,
                &[i64_тип.const_int(128, false)],
                "указатель_на_cond",
            )
        }
        .map_err(|e| ошибка(format!("ошибка вычисления адреса условной переменной: {:?}", e)))?;
        let указатель_на_флаг = unsafe {
            self.билдер.build_gep(
                self.контекст.i8_type(),
                указатель_на_канал,
                &[i64_тип.const_int(256, false)],
                "указатель_на_флаг",
            )
        }
        .map_err(|e| ошибка(format!("ошибка вычисления адреса флага: {:?}", e)))?;
        let указатель_на_слот = unsafe {
            self.билдер.build_gep(
                self.контекст.i8_type(),
                указатель_на_канал,
                &[i64_тип.const_int(264, false)],
                "указатель_на_слот",
            )
        }
        .map_err(|e| ошибка(format!("ошибка вычисления адреса слота значения: {:?}", e)))?;

        match метод {
            "отправить" => {
                if аргументы.len() != 1 {
                    return Err(ошибка("канал.отправить(...) ожидает ровно один аргумент"));
                }
                let значение = self.сгенерировать_выражение(&аргументы[0])?;

                let pthread_mutex_lock = self
                    .модуль
                    .get_function("pthread_mutex_lock")
                    .ok_or_else(|| ошибка("внутренняя ошибка: pthread_mutex_lock не была объявлена"))?;
                self.билдер
                    .build_call(pthread_mutex_lock, &[указатель_на_мьютекс.into()], "блокировка")
                    .map_err(|e| ошибка(format!("ошибка блокировки мьютекса: {:?}", e)))?;

                // Записываем 8 байт значения "как есть" — целое пишется
                // напрямую, указатель приводится к i64 через ptrtoint
                // (сохраняет битовое представление, не меняет адрес).
                let значение_как_i64 = if элемент.is_pointer_type() {
                    self.билдер
                        .build_ptr_to_int(значение.into_pointer_value(), i64_тип, "указатель_в_i64")
                        .map_err(|e| ошибка(format!("ошибка приведения указателя для канала: {:?}", e)))?
                } else if значение.is_int_value() {
                    self.билдер
                        .build_int_z_extend_or_bit_cast(значение.into_int_value(), i64_тип, "целое_в_i64")
                        .map_err(|e| ошибка(format!("ошибка приведения целого для канала: {:?}", e)))?
                } else {
                    return Err(ошибка("канал<...>: поддерживаются только целочисленные и указательные типы значения в этой версии"));
                };
                self.билдер
                    .build_store(указатель_на_слот, значение_как_i64)
                    .map_err(|e| ошибка(format!("ошибка записи значения в канал: {:?}", e)))?;

                self.билдер
                    .build_store(указатель_на_флаг, self.контекст.i32_type().const_int(1, false))
                    .map_err(|e| ошибка(format!("ошибка установки флага канала: {:?}", e)))?;

                let pthread_cond_signal = self
                    .модуль
                    .get_function("pthread_cond_signal")
                    .ok_or_else(|| ошибка("внутренняя ошибка: pthread_cond_signal не была объявлена"))?;
                self.билдер
                    .build_call(pthread_cond_signal, &[указатель_на_cond.into()], "сигнал")
                    .map_err(|e| ошибка(format!("ошибка сигнала условной переменной: {:?}", e)))?;

                let pthread_mutex_unlock = self
                    .модуль
                    .get_function("pthread_mutex_unlock")
                    .ok_or_else(|| ошибка("внутренняя ошибка: pthread_mutex_unlock не была объявлена"))?;
                self.билдер
                    .build_call(pthread_mutex_unlock, &[указатель_на_мьютекс.into()], "разблокировка")
                    .map_err(|e| ошибка(format!("ошибка разблокировки мьютекса: {:?}", e)))?;

                Ok(self.контекст.i32_type().const_int(0, false).into())
            }
            "получить" => {
                if !аргументы.is_empty() {
                    return Err(ошибка("канал<...>.получить() не принимает аргументов"));
                }

                let pthread_mutex_lock = self
                    .модуль
                    .get_function("pthread_mutex_lock")
                    .ok_or_else(|| ошибка("внутренняя ошибка: pthread_mutex_lock не была объявлена"))?;
                self.билдер
                    .build_call(pthread_mutex_lock, &[указатель_на_мьютекс.into()], "блокировка")
                    .map_err(|e| ошибка(format!("ошибка блокировки мьютекса: {:?}", e)))?;

                // Цикл ожидания (не "если") — стандартная, обязательная защита
                // от "ложных пробуждений" (spurious wakeup) — pthread_cond_wait
                // иногда возвращается без реального сигнала, нужно перепроверить
                // условие заново, а не считать его выполненным по факту возврата.
                let текущая_функция = self.текущая_функция.ok_or_else(|| ошибка("внутренняя ошибка: получить() вне функции"))?;
                let блок_проверки = self.контекст.append_basic_block(текущая_функция, "канал_проверка_флага");
                let блок_ожидания = self.контекст.append_basic_block(текущая_функция, "канал_ожидание");
                let блок_готово = self.контекст.append_basic_block(текущая_функция, "канал_значение_готово");

                self.билдер
                    .build_unconditional_branch(блок_проверки)
                    .map_err(|e| ошибка(format!("ошибка перехода: {:?}", e)))?;

                self.билдер.position_at_end(блок_проверки);
                let текущий_флаг = self
                    .билдер
                    .build_load(self.контекст.i32_type(), указатель_на_флаг, "текущий_флаг")
                    .map_err(|e| ошибка(format!("ошибка чтения флага канала: {:?}", e)))?
                    .into_int_value();
                let флаг_установлен = self
                    .билдер
                    .build_int_compare(inkwell::IntPredicate::NE, текущий_флаг, self.контекст.i32_type().const_int(0, false), "флаг_установлен")
                    .map_err(|e| ошибка(format!("ошибка сравнения флага: {:?}", e)))?;
                self.билдер
                    .build_conditional_branch(флаг_установлен, блок_готово, блок_ожидания)
                    .map_err(|e| ошибка(format!("ошибка условного перехода: {:?}", e)))?;

                self.билдер.position_at_end(блок_ожидания);
                let pthread_cond_wait = self
                    .модуль
                    .get_function("pthread_cond_wait")
                    .ok_or_else(|| ошибка("внутренняя ошибка: pthread_cond_wait не была объявлена"))?;
                self.билдер
                    .build_call(pthread_cond_wait, &[указатель_на_cond.into(), указатель_на_мьютекс.into()], "ожидание")
                    .map_err(|e| ошибка(format!("ошибка ожидания условной переменной: {:?}", e)))?;
                self.билдер
                    .build_unconditional_branch(блок_проверки)
                    .map_err(|e| ошибка(format!("ошибка перехода обратно к проверке: {:?}", e)))?;

                self.билдер.position_at_end(блок_готово);
                let значение_i64 = self
                    .билдер
                    .build_load(i64_тип, указатель_на_слот, "значение_из_канала")
                    .map_err(|e| ошибка(format!("ошибка чтения значения из канала: {:?}", e)))?
                    .into_int_value();

                let результат: BasicValueEnum = if элемент.is_pointer_type() {
                    self.билдер
                        .build_int_to_ptr(значение_i64, элемент.into_pointer_type(), "i64_в_указатель")
                        .map_err(|e| ошибка(format!("ошибка приведения к указателю из канала: {:?}", e)))?
                        .into()
                } else if элемент.is_int_type() {
                    self.билдер
                        .build_int_truncate_or_bit_cast(значение_i64, элемент.into_int_type(), "i64_в_целое")
                        .map_err(|e| ошибка(format!("ошибка приведения к целому из канала: {:?}", e)))?
                        .into()
                } else {
                    return Err(ошибка("канал<...>: поддерживаются только целочисленные и указательные типы значения в этой версии"));
                };

                let pthread_mutex_unlock = self
                    .модуль
                    .get_function("pthread_mutex_unlock")
                    .ok_or_else(|| ошибка("внутренняя ошибка: pthread_mutex_unlock не была объявлена"))?;
                self.билдер
                    .build_call(pthread_mutex_unlock, &[указатель_на_мьютекс.into()], "разблокировка")
                    .map_err(|e| ошибка(format!("ошибка разблокировки мьютекса: {:?}", e)))?;

                Ok(результат)
            }
            _ => Err(ошибка(format!("у канал<...> нет метода '{}'", метод))),
        }
    }

    fn сгенерировать_метод_списка(
        &mut self,
        указатель_на_список: PointerValue<'ctx>,
        ключ: &str,
        элемент_тип: BasicTypeEnum<'ctx>,
        имя_структуры_элемента: Option<&str>,
        имя_контракта_элемента: Option<&str>,
        метод: &str,
        аргументы: &[Выражение],
    ) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        let llvm_struct = *self
            .списки
            .get(ключ)
            .ok_or_else(|| ошибка(format!("внутренняя ошибка: Список<{}> не зарегистрирован", ключ)))?;
        let i64_тип = self.контекст.i64_type();
        let указатель_на_элемент_тип = элемент_тип.ptr_type(inkwell::AddressSpace::default());

        match метод {
            "размер" => {
                if !аргументы.is_empty() {
                    return Err(ошибка("размер() не принимает аргументов"));
                }
                self.прочитать_поле_списка(llvm_struct, указатель_на_список, 1, i64_тип.into(), "размер")
            }

            "получить" => {
                if аргументы.len() != 1 {
                    return Err(ошибка("получить(...) ожидает ровно один аргумент (индекс)"));
                }
                let индекс_значение = self.сгенерировать_выражение(&аргументы[0])?.into_int_value();
                let индекс_i64 = self
                    .билдер
                    .build_int_cast(индекс_значение, i64_тип, "индекс")
                    .map_err(|e| ошибка(format!("ошибка приведения индекса: {:?}", e)))?;

                let данные = self
                    .прочитать_поле_списка(llvm_struct, указатель_на_список, 3, указатель_на_элемент_тип.into(), "данные")?
                    .into_pointer_value();

                let адрес_элемента = unsafe {
                    self.билдер
                        .build_gep(элемент_тип, данные, &[индекс_i64], "адрес_элемента_списка")
                        .map_err(|e| ошибка(format!("ошибка адресации элемента списка: {:?}", e)))?
                };

                self.билдер
                    .build_load(элемент_тип, адрес_элемента, "элемент_списка")
                    .map_err(|e| ошибка(format!("ошибка чтения элемента списка: {:?}", e)))
            }

            "добавить" => {
                if аргументы.len() != 1 {
                    return Err(ошибка("добавить(...) ожидает ровно один аргумент"));
                }
                let новое_значение = self.сгенерировать_выражение(&аргументы[0])?;

                // НОВОЕ (Список<Контракт>): ⚠️ НАЙДЕНО РЕАЛЬНОЙ ПРОВЕРКОЙ —
                // настоящая, содержательная причина краха при добавлении
                // структур в Список<Контракт>. Без этой упаковки в список
                // записывался бы голый указатель на структуру (8 байт)
                // вместо нужного "толстого указателя" {данные, vtable}
                // (16 байт) — вторая половина элемента оставалась бы
                // неинициализированным мусором из malloc, вызывая
                // Segmentation fault при следующем динамическом вызове
                // метода через vtable, прочитанную из этого мусора.
                let новое_значение = if let Some(имя_контракта) = имя_контракта_элемента {
                    let (указатель_на_данные, имя_структуры_аргумента) = self.получить_структуру_из_выражения(&аргументы[0])?;
                    let vtable = self
                        .vtables
                        .get(&(имя_структуры_аргумента.clone(), имя_контракта.to_string()))
                        .copied()
                        .ok_or_else(|| {
                            ошибка(format!(
                                "внутренняя ошибка: vtable для '{}' : '{}' не была сгенерирована заранее",
                                имя_структуры_аргумента, имя_контракта
                            ))
                        })?;
                    let байт_указатель = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default());
                    let данные_как_i8 = self
                        .билдер
                        .build_pointer_cast(указатель_на_данные, байт_указатель, "данные_контракта_в_списке")
                        .map_err(|e| ошибка(format!("ошибка приведения указателя данных: {:?}", e)))?;
                    let vtable_как_i8 = self
                        .билдер
                        .build_pointer_cast(vtable.as_pointer_value(), байт_указатель, "vtable_контракта_в_списке")
                        .map_err(|e| ошибка(format!("ошибка приведения указателя vtable: {:?}", e)))?;
                    let толстый_указатель_тип = self.контекст.struct_type(&[байт_указатель.into(), байт_указатель.into()], false);
                    let mut толстый_указатель = толстый_указатель_тип.get_undef();
                    толстый_указатель = self
                        .билдер
                        .build_insert_value(толстый_указатель, данные_как_i8, 0, "вставить_данные_в_списке")
                        .map_err(|e| ошибка(format!("ошибка сборки толстого указателя: {:?}", e)))?
                        .into_struct_value();
                    толстый_указатель = self
                        .билдер
                        .build_insert_value(толстый_указатель, vtable_как_i8, 1, "вставить_vtable_в_списке")
                        .map_err(|e| ошибка(format!("ошибка сборки толстого указателя: {:?}", e)))?
                        .into_struct_value();
                    толстый_указатель.into()
                } else {
                    новое_значение
                };

                // ARC: если элементы списка сами являются структурой И
                // аргумент — ПРОСТАЯ ПЕРЕМЕННАЯ (не свежий вызов конструктора,
                // у которого и так уже счётчик 1) — нужно "захватить": теперь
                // на объект ссылаются ДВА места (исходная переменная и новый
                // элемент буфера). Тот же принцип, что уже исправлен для
                // конструкторов структур — см. сгенерировать_вызов_конструктора
                // и подробный комментарий там же про use-after-free, которого
                // это избегает.
                if let Some(имя_структуры_элемента) = имя_структуры_элемента {
                    if matches!(&аргументы[0], Выражение::Идентификатор(_)) {
                        if let Some((llvm_struct_элемента, _)) = self.структуры.get(имя_структуры_элемента).cloned() {
                            self.захватить(новое_значение.into_pointer_value(), llvm_struct_элемента)?;
                        }
                    }
                }

                let функция = self
                    .текущая_функция
                    .ok_or_else(|| ошибка("внутренняя ошибка: 'добавить' вызван вне тела функции"))?;

                let размер = self
                    .прочитать_поле_списка(llvm_struct, указатель_на_список, 1, i64_тип.into(), "размер")?
                    .into_int_value();
                let вместимость = self
                    .прочитать_поле_списка(llvm_struct, указатель_на_список, 2, i64_тип.into(), "вместимость")?
                    .into_int_value();

                let нужен_рост = self
                    .билдер
                    .build_int_compare(IntPredicate::EQ, размер, вместимость, "нужен_рост")
                    .map_err(|e| ошибка(format!("ошибка сравнения при росте списка: {:?}", e)))?;

                let блок_рост = self.контекст.append_basic_block(функция, "список_рост");
                let блок_копировать = self.контекст.append_basic_block(функция, "список_копировать");
                let блок_после_копирования = self.контекст.append_basic_block(функция, "список_после_копирования");
                let блок_после_роста = self.контекст.append_basic_block(функция, "список_после_роста");

                self.билдер
                    .build_conditional_branch(нужен_рост, блок_рост, блок_после_роста)
                    .map_err(|e| ошибка(format!("ошибка ветвления роста списка: {:?}", e)))?;

                // --- Блок роста: вычисляем новую вместимость и выделяем новый буфер ---
                self.билдер.position_at_end(блок_рост);
                let ноль_i64 = i64_тип.const_int(0, false);
                let вместимость_ноль = self
                    .билдер
                    .build_int_compare(IntPredicate::EQ, вместимость, ноль_i64, "вместимость_ноль")
                    .map_err(|e| ошибка(format!("ошибка проверки вместимости списка: {:?}", e)))?;
                let удвоенная = self
                    .билдер
                    .build_int_mul(вместимость, i64_тип.const_int(2, false), "удвоенная_вместимость")
                    .map_err(|e| ошибка(format!("ошибка удвоения вместимости списка: {:?}", e)))?;
                let новая_вместимость = self
                    .билдер
                    .build_select(вместимость_ноль, i64_тип.const_int(4, false), удвоенная, "новая_вместимость")
                    .map_err(|e| ошибка(format!("ошибка вычисления новой вместимости списка: {:?}", e)))?
                    .into_int_value();

                let размер_элемента = элемент_тип
                    .size_of()
                    .ok_or_else(|| ошибка("не удалось вычислить размер элемента списка"))?;
                let новый_объём_байт = self
                    .билдер
                    .build_int_mul(новая_вместимость, размер_элемента, "новый_объём_байт")
                    .map_err(|e| ошибка(format!("ошибка вычисления объёма памяти списка: {:?}", e)))?;

                let malloc = self
                    .модуль
                    .get_function("malloc")
                    .ok_or_else(|| ошибка("внутренняя ошибка: malloc не была объявлена"))?;
                let новые_данные_сырые = self
                    .билдер
                    .build_call(malloc, &[новый_объём_байт.into()], "новые_данные_списка")
                    .map_err(|e| ошибка(format!("ошибка выделения памяти для списка: {:?}", e)))?
                    .try_as_basic_value()
                    .left()
                    .ok_or_else(|| ошибка("malloc неожиданно не вернул значение"))?
                    .into_pointer_value();

                let старые_данные = self
                    .прочитать_поле_списка(llvm_struct, указатель_на_список, 3, указатель_на_элемент_тип.into(), "старые_данные")?
                    .into_pointer_value();

                let байт_указатель_тип = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default());
                let старые_данные_null = self
                    .билдер
                    .build_is_null(старые_данные, "старые_данные_null")
                    .map_err(|e| ошибка(format!("ошибка проверки старых данных списка: {:?}", e)))?;

                self.билдер
                    .build_conditional_branch(старые_данные_null, блок_после_копирования, блок_копировать)
                    .map_err(|e| ошибка(format!("ошибка ветвления копирования списка: {:?}", e)))?;

                // --- Блок копирования: переносим старые элементы в новый буфер ---
                self.билдер.position_at_end(блок_копировать);
                let старый_объём_байт = self
                    .билдер
                    .build_int_mul(вместимость, размер_элемента, "старый_объём_байт")
                    .map_err(|e| ошибка(format!("ошибка вычисления старого объёма списка: {:?}", e)))?;
                let старые_данные_байт = self
                    .билдер
                    .build_pointer_cast(старые_данные, байт_указатель_тип, "старые_данные_байт")
                    .map_err(|e| ошибка(format!("ошибка приведения старых данных списка: {:?}", e)))?;
                let memcpy = self
                    .модуль
                    .get_function("memcpy")
                    .ok_or_else(|| ошибка("внутренняя ошибка: memcpy не была объявлена"))?;
                self.билдер
                    .build_call(memcpy, &[новые_данные_сырые.into(), старые_данные_байт.into(), старый_объём_байт.into()], "memcpy_список")
                    .map_err(|e| ошибка(format!("ошибка копирования данных списка: {:?}", e)))?;
                let free = self
                    .модуль
                    .get_function("free")
                    .ok_or_else(|| ошибка("внутренняя ошибка: free не была объявлена"))?;
                self.билдер
                    .build_call(free, &[старые_данные_байт.into()], "free_список")
                    .map_err(|e| ошибка(format!("ошибка освобождения старых данных списка: {:?}", e)))?;
                self.билдер
                    .build_unconditional_branch(блок_после_копирования)
                    .map_err(|e| ошибка(format!("ошибка перехода после копирования списка: {:?}", e)))?;

                // --- Общая точка после копирования (или сразу, если копировать было нечего) ---
                self.билдер.position_at_end(блок_после_копирования);
                let новые_данные = self
                    .билдер
                    .build_pointer_cast(новые_данные_сырые, указатель_на_элемент_тип, "новые_данные_список")
                    .map_err(|e| ошибка(format!("ошибка приведения новых данных списка: {:?}", e)))?;
                self.записать_поле_списка(llvm_struct, указатель_на_список, 2, новая_вместимость.into())?;
                self.записать_поле_списка(llvm_struct, указатель_на_список, 3, новые_данные.into())?;
                self.билдер
                    .build_unconditional_branch(блок_после_роста)
                    .map_err(|e| ошибка(format!("ошибка перехода после роста списка: {:?}", e)))?;

                // --- После роста (или сразу, если рост не требовался) — записываем элемент ---
                self.билдер.position_at_end(блок_после_роста);
                let данные_текущие = self
                    .прочитать_поле_списка(llvm_struct, указатель_на_список, 3, указатель_на_элемент_тип.into(), "данные")?
                    .into_pointer_value();
                let адрес_нового_элемента = unsafe {
                    self.билдер
                        .build_gep(элемент_тип, данные_текущие, &[размер], "адрес_нового_элемента")
                        .map_err(|e| ошибка(format!("ошибка адресации нового элемента списка: {:?}", e)))?
                };
                self.билдер
                    .build_store(адрес_нового_элемента, новое_значение)
                    .map_err(|e| ошибка(format!("ошибка записи нового элемента списка: {:?}", e)))?;

                let новый_размер = self
                    .билдер
                    .build_int_add(размер, i64_тип.const_int(1, false), "новый_размер_списка")
                    .map_err(|e| ошибка(format!("ошибка обновления размера списка: {:?}", e)))?;
                self.записать_поле_списка(llvm_struct, указатель_на_список, 1, новый_размер.into())?;

                // добавить(...) в языке "Сфера" ничего не возвращает — заглушка.
                Ok(self.контекст.i32_type().const_int(0, false).into())
            }

            other => Err(ошибка(format!(
                "у Список<...> нет метода '{}' — доступны 'добавить', 'получить', 'размер'",
                other
            ))),
        }
    }

    /// Генерирует вызов встроенного метода Словарь<Ключ, Значение> — размер/положить/получить.
    /// Реализован как ЛИНЕЙНЫЙ ПОИСК по параллельным массивам ключей/значений
    /// (не настоящая хеш-таблица — см. обсуждение архитектуры перед реализацией).
    /// Поиск построен как ЦИКЛ через скрытый alloca-счётчик — тот же приём,
    /// что уже использован в "для каждого" (см. сгенерировать_цикл_для_каждого):
    /// вместо ручного построения PHI-узлов используем изменяемую ячейку памяти,
    /// а LLVM сам оптимизирует это в регистр позже (проход mem2reg).
    ///
    /// ⚠️ Единственная НОВАЯ техника здесь (сверх уже использованных для
    /// Список<тип>) — использование alloca-ячейки для "результата" метода,
    /// заполняемой в РАЗНЫХ базовых блоках (найден/не найден) и читаемой
    /// в общей точке после — это способ объединить два возможных исхода
    /// без ручного построения PHI. Тот же принцип, что и с индексом цикла,
    /// просто применённый к возвращаемому значению, а не к счётчику.
    /// Сравнивает два значения-ключа Словарь<Ключ, Значение> на равенство, определяя
    /// способ сравнения по РЕАЛЬНОМУ типу значений: текст (указатель) —
    /// через strcmp (сравнение содержимого), любой другой тип (целые числа)
    /// — через build_int_compare, как и раньше. Тот же принцип "определяем
    /// по факту, а не заранее по объявленному типу", что уже применён в
    /// сгенерировать_бинарное для операторов над текстом.
    fn сравнить_ключи_словаря(&mut self, а: BasicValueEnum<'ctx>, б: BasicValueEnum<'ctx>) -> Result<inkwell::values::IntValue<'ctx>, ОшибкаКодогенерации> {
        if а.get_type().is_pointer_type() && б.get_type().is_pointer_type() {
            let strcmp = self
                .модуль
                .get_function("strcmp")
                .ok_or_else(|| ошибка("внутренняя ошибка: strcmp не была объявлена"))?;
            let результат_strcmp = self
                .билдер
                .build_call(strcmp, &[а.into(), б.into()], "strcmp_ключ")
                .map_err(|e| ошибка(format!("ошибка сравнения текстовых ключей: {:?}", e)))?
                .try_as_basic_value()
                .left()
                .ok_or_else(|| ошибка("strcmp неожиданно не вернул значение"))?
                .into_int_value();
            let ноль = self.контекст.i32_type().const_int(0, false);
            self.билдер
                .build_int_compare(IntPredicate::EQ, результат_strcmp, ноль, "ключи_равны")
                .map_err(|e| ошибка(format!("ошибка сравнения текстовых ключей: {:?}", e)))
        } else {
            self.билдер
                .build_int_compare(IntPredicate::EQ, а.into_int_value(), б.into_int_value(), "ключи_равны")
                .map_err(|e| ошибка(format!("ошибка сравнения ключей: {:?}", e)))
        }
    }

    fn сгенерировать_метод_словаря(
        &mut self,
        указатель_на_словарь: PointerValue<'ctx>,
        ключ_типа: &str,
        тип_ключа: BasicTypeEnum<'ctx>,
        тип_значения: BasicTypeEnum<'ctx>,
        имя_структуры_значения: Option<&str>,
        метод: &str,
        аргументы: &[Выражение],
    ) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        let llvm_struct = *self
            .словари
            .get(ключ_типа)
            .ok_or_else(|| ошибка(format!("внутренняя ошибка: Словарь<{}> не зарегистрирован", ключ_типа)))?;
        let i64_тип = self.контекст.i64_type();
        let указатель_на_тип_ключа = тип_ключа.ptr_type(inkwell::AddressSpace::default());
        let указатель_на_тип_значения = тип_значения.ptr_type(inkwell::AddressSpace::default());

        match метод {
            "размер" => {
                if !аргументы.is_empty() {
                    return Err(ошибка("размер() не принимает аргументов"));
                }
                self.прочитать_поле_списка(llvm_struct, указатель_на_словарь, 1, i64_тип.into(), "размер")
            }

            "положить" => {
                if аргументы.len() != 2 {
                    return Err(ошибка("положить(...) ожидает ровно два аргумента (ключ, значение)"));
                }
                let искомый_ключ = self.сгенерировать_выражение(&аргументы[0])?;
                let новое_значение = self.сгенерировать_выражение(&аргументы[1])?;

                // ARC: та же логика, что и в Список.добавить — если значение
                // само является структурой И аргумент — простая переменная
                // (не свежий вызов конструктора) — нужно "захватить". Ключ
                // сюда не попадает: ключи пока ограничены целыми числами и
                // текстом, структуры-ключи не поддержаны.
                if let Some(имя_структуры_значения) = имя_структуры_значения {
                    if matches!(&аргументы[1], Выражение::Идентификатор(_)) {
                        if let Some((llvm_struct_значения, _)) = self.структуры.get(имя_структуры_значения).cloned() {
                            self.захватить(новое_значение.into_pointer_value(), llvm_struct_значения)?;
                        }
                    }
                }

                let функция = self
                    .текущая_функция
                    .ok_or_else(|| ошибка("внутренняя ошибка: 'положить' вызван вне тела функции"))?;

                let размер = self
                    .прочитать_поле_списка(llvm_struct, указатель_на_словарь, 1, i64_тип.into(), "размер")?
                    .into_int_value();

                // --- Цикл линейного поиска: ищем, нет ли уже такого ключа ---
                let индекс_alloca = self
                    .билдер
                    .build_alloca(i64_тип, "словарь_положить_индекс")
                    .map_err(|e| ошибка(format!("ошибка выделения памяти для индекса поиска: {:?}", e)))?;
                self.билдер
                    .build_store(индекс_alloca, i64_тип.const_int(0, false))
                    .map_err(|e| ошибка(format!("ошибка инициализации индекса поиска: {:?}", e)))?;

                let блок_условие = self.контекст.append_basic_block(функция, "словарь_положить_условие");
                let блок_проверить = self.контекст.append_basic_block(функция, "словарь_положить_проверить");
                let блок_следующий = self.контекст.append_basic_block(функция, "словарь_положить_следующий");
                let блок_найден = self.контекст.append_basic_block(функция, "словарь_положить_найден");
                let блок_не_найден = self.контекст.append_basic_block(функция, "словарь_положить_не_найден");
                let блок_конец = self.контекст.append_basic_block(функция, "словарь_положить_конец");

                self.билдер
                    .build_unconditional_branch(блок_условие)
                    .map_err(|e| ошибка(format!("ошибка перехода к условию поиска: {:?}", e)))?;

                self.билдер.position_at_end(блок_условие);
                let текущий_индекс = self
                    .билдер
                    .build_load(i64_тип, индекс_alloca, "индекс")
                    .map_err(|e| ошибка(format!("ошибка чтения индекса поиска: {:?}", e)))?
                    .into_int_value();
                let есть_ещё = self
                    .билдер
                    .build_int_compare(IntPredicate::SLT, текущий_индекс, размер, "есть_ещё")
                    .map_err(|e| ошибка(format!("ошибка сравнения индекса поиска: {:?}", e)))?;
                self.билдер
                    .build_conditional_branch(есть_ещё, блок_проверить, блок_не_найден)
                    .map_err(|e| ошибка(format!("ошибка ветвления поиска: {:?}", e)))?;

                self.билдер.position_at_end(блок_проверить);
                let ключи_данные = self
                    .прочитать_поле_списка(llvm_struct, указатель_на_словарь, 3, указатель_на_тип_ключа.into(), "ключи")?
                    .into_pointer_value();
                let адрес_ключа = unsafe {
                    self.билдер
                        .build_gep(тип_ключа, ключи_данные, &[текущий_индекс], "адрес_ключа")
                        .map_err(|e| ошибка(format!("ошибка адресации ключа: {:?}", e)))?
                };
                let текущий_ключ = self
                    .билдер
                    .build_load(тип_ключа, адрес_ключа, "текущий_ключ")
                    .map_err(|e| ошибка(format!("ошибка чтения ключа: {:?}", e)))?;
                let совпадает = self.сравнить_ключи_словаря(текущий_ключ, искомый_ключ)?;
                self.билдер
                    .build_conditional_branch(совпадает, блок_найден, блок_следующий)
                    .map_err(|e| ошибка(format!("ошибка ветвления совпадения ключа: {:?}", e)))?;

                self.билдер.position_at_end(блок_следующий);
                let индекс_плюс_один = self
                    .билдер
                    .build_int_add(текущий_индекс, i64_тип.const_int(1, false), "индекс_плюс_один")
                    .map_err(|e| ошибка(format!("ошибка инкремента индекса поиска: {:?}", e)))?;
                self.билдер
                    .build_store(индекс_alloca, индекс_плюс_один)
                    .map_err(|e| ошибка(format!("ошибка сохранения индекса поиска: {:?}", e)))?;
                self.билдер
                    .build_unconditional_branch(блок_условие)
                    .map_err(|e| ошибка(format!("ошибка возврата к условию поиска: {:?}", e)))?;

                // --- Найден: перезаписываем значение по этому индексу ---
                self.билдер.position_at_end(блок_найден);
                let значения_данные_найден = self
                    .прочитать_поле_списка(llvm_struct, указатель_на_словарь, 4, указатель_на_тип_значения.into(), "значения")?
                    .into_pointer_value();
                let адрес_значения_найден = unsafe {
                    self.билдер
                        .build_gep(тип_значения, значения_данные_найден, &[текущий_индекс], "адрес_значения_найден")
                        .map_err(|e| ошибка(format!("ошибка адресации значения: {:?}", e)))?
                };
                self.билдер
                    .build_store(адрес_значения_найден, новое_значение)
                    .map_err(|e| ошибка(format!("ошибка перезаписи значения: {:?}", e)))?;
                self.билдер
                    .build_unconditional_branch(блок_конец)
                    .map_err(|e| ошибка(format!("ошибка перехода после перезаписи: {:?}", e)))?;

                // --- Не найден: растим оба буфера при необходимости, добавляем в конец ---
                self.билдер.position_at_end(блок_не_найден);
                let вместимость = self
                    .прочитать_поле_списка(llvm_struct, указатель_на_словарь, 2, i64_тип.into(), "вместимость")?
                    .into_int_value();
                let нужен_рост = self
                    .билдер
                    .build_int_compare(IntPredicate::EQ, размер, вместимость, "нужен_рост")
                    .map_err(|e| ошибка(format!("ошибка сравнения при росте словаря: {:?}", e)))?;

                let блок_рост = self.контекст.append_basic_block(функция, "словарь_рост");
                let блок_после_роста = self.контекст.append_basic_block(функция, "словарь_после_роста");

                self.билдер
                    .build_conditional_branch(нужен_рост, блок_рост, блок_после_роста)
                    .map_err(|e| ошибка(format!("ошибка ветвления роста словаря: {:?}", e)))?;

                self.билдер.position_at_end(блок_рост);
                let ноль_i64 = i64_тип.const_int(0, false);
                let вместимость_ноль = self
                    .билдер
                    .build_int_compare(IntPredicate::EQ, вместимость, ноль_i64, "вместимость_ноль")
                    .map_err(|e| ошибка(format!("ошибка проверки вместимости словаря: {:?}", e)))?;
                let удвоенная = self
                    .билдер
                    .build_int_mul(вместимость, i64_тип.const_int(2, false), "удвоенная_вместимость")
                    .map_err(|e| ошибка(format!("ошибка удвоения вместимости словаря: {:?}", e)))?;
                let новая_вместимость = self
                    .билдер
                    .build_select(вместимость_ноль, i64_тип.const_int(4, false), удвоенная, "новая_вместимость")
                    .map_err(|e| ошибка(format!("ошибка вычисления новой вместимости словаря: {:?}", e)))?
                    .into_int_value();

                // Растим буфер ключей
                let старые_ключи = self
                    .прочитать_поле_списка(llvm_struct, указатель_на_словарь, 3, указатель_на_тип_ключа.into(), "старые_ключи")?
                    .into_pointer_value();
                let новые_ключи = self.вырастить_буфер(старые_ключи, тип_ключа, вместимость, новая_вместимость)?;
                self.записать_поле_списка(llvm_struct, указатель_на_словарь, 3, новые_ключи.into())?;

                // Растим буфер значений (тот же новый размер вместимости, отдельный буфер)
                let старые_значения = self
                    .прочитать_поле_списка(llvm_struct, указатель_на_словарь, 4, указатель_на_тип_значения.into(), "старые_значения")?
                    .into_pointer_value();
                let новые_значения = self.вырастить_буфер(старые_значения, тип_значения, вместимость, новая_вместимость)?;
                self.записать_поле_списка(llvm_struct, указатель_на_словарь, 4, новые_значения.into())?;

                self.записать_поле_списка(llvm_struct, указатель_на_словарь, 2, новая_вместимость.into())?;
                self.билдер
                    .build_unconditional_branch(блок_после_роста)
                    .map_err(|e| ошибка(format!("ошибка перехода после роста словаря: {:?}", e)))?;

                self.билдер.position_at_end(блок_после_роста);
                let ключи_текущие = self
                    .прочитать_поле_списка(llvm_struct, указатель_на_словарь, 3, указатель_на_тип_ключа.into(), "ключи_текущие")?
                    .into_pointer_value();
                let адрес_нового_ключа = unsafe {
                    self.билдер
                        .build_gep(тип_ключа, ключи_текущие, &[размер], "адрес_нового_ключа")
                        .map_err(|e| ошибка(format!("ошибка адресации нового ключа: {:?}", e)))?
                };
                self.билдер
                    .build_store(адрес_нового_ключа, искомый_ключ)
                    .map_err(|e| ошибка(format!("ошибка записи нового ключа: {:?}", e)))?;

                let значения_текущие = self
                    .прочитать_поле_списка(llvm_struct, указатель_на_словарь, 4, указатель_на_тип_значения.into(), "значения_текущие")?
                    .into_pointer_value();
                let адрес_нового_значения = unsafe {
                    self.билдер
                        .build_gep(тип_значения, значения_текущие, &[размер], "адрес_нового_значения")
                        .map_err(|e| ошибка(format!("ошибка адресации нового значения: {:?}", e)))?
                };
                self.билдер
                    .build_store(адрес_нового_значения, новое_значение)
                    .map_err(|e| ошибка(format!("ошибка записи нового значения: {:?}", e)))?;

                let новый_размер = self
                    .билдер
                    .build_int_add(размер, i64_тип.const_int(1, false), "новый_размер_словаря")
                    .map_err(|e| ошибка(format!("ошибка обновления размера словаря: {:?}", e)))?;
                self.записать_поле_списка(llvm_struct, указатель_на_словарь, 1, новый_размер.into())?;

                self.билдер
                    .build_unconditional_branch(блок_конец)
                    .map_err(|e| ошибка(format!("ошибка перехода в конец 'положить': {:?}", e)))?;

                self.билдер.position_at_end(блок_конец);
                // положить(...) в языке "Сфера" ничего не возвращает — заглушка.
                Ok(self.контекст.i32_type().const_int(0, false).into())
            }

            "получить" => {
                if аргументы.len() != 1 {
                    return Err(ошибка("получить(...) ожидает ровно один аргумент (ключ)"));
                }
                let искомый_ключ = self.сгенерировать_выражение(&аргументы[0])?;

                let функция = self
                    .текущая_функция
                    .ok_or_else(|| ошибка("внутренняя ошибка: 'получить' вызван вне тела функции"))?;

                let размер = self
                    .прочитать_поле_списка(llvm_struct, указатель_на_словарь, 1, i64_тип.into(), "размер")?
                    .into_int_value();

                let тип_результата = тип_результата_llvm(self.контекст, тип_значения);
                let результат_alloca = self
                    .билдер
                    .build_alloca(тип_результата, "словарь_получить_результат")
                    .map_err(|e| ошибка(format!("ошибка выделения памяти для результата: {:?}", e)))?;

                let индекс_alloca = self
                    .билдер
                    .build_alloca(i64_тип, "словарь_получить_индекс")
                    .map_err(|e| ошибка(format!("ошибка выделения памяти для индекса поиска: {:?}", e)))?;
                self.билдер
                    .build_store(индекс_alloca, i64_тип.const_int(0, false))
                    .map_err(|e| ошибка(format!("ошибка инициализации индекса поиска: {:?}", e)))?;

                let блок_условие = self.контекст.append_basic_block(функция, "словарь_получить_условие");
                let блок_проверить = self.контекст.append_basic_block(функция, "словарь_получить_проверить");
                let блок_следующий = self.контекст.append_basic_block(функция, "словарь_получить_следующий");
                let блок_найден = self.контекст.append_basic_block(функция, "словарь_получить_найден");
                let блок_не_найден = self.контекст.append_basic_block(функция, "словарь_получить_не_найден");
                let блок_конец = self.контекст.append_basic_block(функция, "словарь_получить_конец");

                self.билдер
                    .build_unconditional_branch(блок_условие)
                    .map_err(|e| ошибка(format!("ошибка перехода к условию поиска: {:?}", e)))?;

                self.билдер.position_at_end(блок_условие);
                let текущий_индекс = self
                    .билдер
                    .build_load(i64_тип, индекс_alloca, "индекс")
                    .map_err(|e| ошибка(format!("ошибка чтения индекса поиска: {:?}", e)))?
                    .into_int_value();
                let есть_ещё = self
                    .билдер
                    .build_int_compare(IntPredicate::SLT, текущий_индекс, размер, "есть_ещё")
                    .map_err(|e| ошибка(format!("ошибка сравнения индекса поиска: {:?}", e)))?;
                self.билдер
                    .build_conditional_branch(есть_ещё, блок_проверить, блок_не_найден)
                    .map_err(|e| ошибка(format!("ошибка ветвления поиска: {:?}", e)))?;

                self.билдер.position_at_end(блок_проверить);
                let ключи_данные = self
                    .прочитать_поле_списка(llvm_struct, указатель_на_словарь, 3, указатель_на_тип_ключа.into(), "ключи")?
                    .into_pointer_value();
                let адрес_ключа = unsafe {
                    self.билдер
                        .build_gep(тип_ключа, ключи_данные, &[текущий_индекс], "адрес_ключа")
                        .map_err(|e| ошибка(format!("ошибка адресации ключа: {:?}", e)))?
                };
                let текущий_ключ = self
                    .билдер
                    .build_load(тип_ключа, адрес_ключа, "текущий_ключ")
                    .map_err(|e| ошибка(format!("ошибка чтения ключа: {:?}", e)))?;
                let совпадает = self.сравнить_ключи_словаря(текущий_ключ, искомый_ключ)?;
                self.билдер
                    .build_conditional_branch(совпадает, блок_найден, блок_следующий)
                    .map_err(|e| ошибка(format!("ошибка ветвления совпадения ключа: {:?}", e)))?;

                self.билдер.position_at_end(блок_следующий);
                let индекс_плюс_один = self
                    .билдер
                    .build_int_add(текущий_индекс, i64_тип.const_int(1, false), "индекс_плюс_один")
                    .map_err(|e| ошибка(format!("ошибка инкремента индекса поиска: {:?}", e)))?;
                self.билдер
                    .build_store(индекс_alloca, индекс_плюс_один)
                    .map_err(|e| ошибка(format!("ошибка сохранения индекса поиска: {:?}", e)))?;
                self.билдер
                    .build_unconditional_branch(блок_условие)
                    .map_err(|e| ошибка(format!("ошибка возврата к условию поиска: {:?}", e)))?;

                // --- Найден: строим успех(значение) ---
                self.билдер.position_at_end(блок_найден);
                let значения_данные = self
                    .прочитать_поле_списка(llvm_struct, указатель_на_словарь, 4, указатель_на_тип_значения.into(), "значения")?
                    .into_pointer_value();
                let адрес_значения = unsafe {
                    self.билдер
                        .build_gep(тип_значения, значения_данные, &[текущий_индекс], "адрес_значения")
                        .map_err(|e| ошибка(format!("ошибка адресации значения: {:?}", e)))?
                };
                let найденное_значение = self
                    .билдер
                    .build_load(тип_значения, адрес_значения, "найденное_значение")
                    .map_err(|e| ошибка(format!("ошибка чтения значения: {:?}", e)))?;
                let результат_успех = self.построить_результат_успех(тип_значения, найденное_значение)?;
                self.билдер
                    .build_store(результат_alloca, результат_успех)
                    .map_err(|e| ошибка(format!("ошибка сохранения результата 'найден': {:?}", e)))?;
                self.билдер
                    .build_unconditional_branch(блок_конец)
                    .map_err(|e| ошибка(format!("ошибка перехода после 'найден': {:?}", e)))?;

                // --- Не найден: строим ошибка("ключ не найден") ---
                self.билдер.position_at_end(блок_не_найден);
                let сообщение = self.сгенерировать_текстовый_литерал("ключ не найден")?;
                let результат_ошибка = self.построить_результат_ошибка(тип_значения, сообщение)?;
                self.билдер
                    .build_store(результат_alloca, результат_ошибка)
                    .map_err(|e| ошибка(format!("ошибка сохранения результата 'не найден': {:?}", e)))?;
                self.билдер
                    .build_unconditional_branch(блок_конец)
                    .map_err(|e| ошибка(format!("ошибка перехода после 'не найден': {:?}", e)))?;

                self.билдер.position_at_end(блок_конец);
                self.билдер
                    .build_load(тип_результата, результат_alloca, "итоговый_результат")
                    .map_err(|e| ошибка(format!("ошибка чтения итогового результата: {:?}", e)))
            }

            other => Err(ошибка(format!(
                "у Словарь<...> нет метода '{}' — доступны 'положить', 'получить', 'размер'",
                other
            ))),
        }
    }

    /// Растит ОДИН буфер (используется дважды в "положить" — для ключей и
    /// для значений по отдельности): выделяет новый malloc-буфер под
    /// новую_вместимость элементов, копирует старые данные (если были) через
    /// memcpy, освобождает старый буфер через free. Тот же алгоритм, что
    /// уже применён внутри сгенерировать_метод_списка для "добавить", просто
    /// вынесенный в отдельный метод — здесь он нужен ДВАЖДЫ подряд (для двух
    /// параллельных массивов), поэтому дублировать код целиком было бы хуже,
    /// чем один раз вынести в общий метод.
    fn вырастить_буфер(
        &mut self,
        старый_указатель: PointerValue<'ctx>,
        элемент_тип: BasicTypeEnum<'ctx>,
        старая_вместимость: inkwell::values::IntValue<'ctx>,
        новая_вместимость: inkwell::values::IntValue<'ctx>,
    ) -> Result<PointerValue<'ctx>, ОшибкаКодогенерации> {
        let i64_тип = self.контекст.i64_type();
        let размер_элемента = элемент_тип
            .size_of()
            .ok_or_else(|| ошибка("не удалось вычислить размер элемента при росте буфера"))?;

        let новый_объём_байт = self
            .билдер
            .build_int_mul(новая_вместимость, размер_элемента, "новый_объём_байт")
            .map_err(|e| ошибка(format!("ошибка вычисления нового объёма: {:?}", e)))?;

        let malloc = self
            .модуль
            .get_function("malloc")
            .ok_or_else(|| ошибка("внутренняя ошибка: malloc не была объявлена"))?;
        let новые_данные_сырые = self
            .билдер
            .build_call(malloc, &[новый_объём_байт.into()], "новые_данные")
            .map_err(|e| ошибка(format!("ошибка выделения памяти при росте буфера: {:?}", e)))?
            .try_as_basic_value()
            .left()
            .ok_or_else(|| ошибка("malloc неожиданно не вернул значение"))?
            .into_pointer_value();

        let байт_указатель_тип = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default());
        let старые_данные_null = self
            .билдер
            .build_is_null(старый_указатель, "старые_данные_null")
            .map_err(|e| ошибка(format!("ошибка проверки старых данных: {:?}", e)))?;

        let функция = self
            .текущая_функция
            .ok_or_else(|| ошибка("внутренняя ошибка: рост буфера вне тела функции"))?;
        let блок_копировать = self.контекст.append_basic_block(функция, "буфер_копировать");
        let блок_после = self.контекст.append_basic_block(функция, "буфер_после");

        self.билдер
            .build_conditional_branch(старые_данные_null, блок_после, блок_копировать)
            .map_err(|e| ошибка(format!("ошибка ветвления копирования буфера: {:?}", e)))?;

        self.билдер.position_at_end(блок_копировать);
        let старый_объём_байт = self
            .билдер
            .build_int_mul(старая_вместимость, размер_элемента, "старый_объём_байт")
            .map_err(|e| ошибка(format!("ошибка вычисления старого объёма: {:?}", e)))?;
        let старые_данные_байт = self
            .билдер
            .build_pointer_cast(старый_указатель, байт_указатель_тип, "старые_данные_байт")
            .map_err(|e| ошибка(format!("ошибка приведения старых данных: {:?}", e)))?;
        let memcpy = self
            .модуль
            .get_function("memcpy")
            .ok_or_else(|| ошибка("внутренняя ошибка: memcpy не была объявлена"))?;
        self.билдер
            .build_call(memcpy, &[новые_данные_сырые.into(), старые_данные_байт.into(), старый_объём_байт.into()], "memcpy_буфер")
            .map_err(|e| ошибка(format!("ошибка копирования буфера: {:?}", e)))?;
        let free = self
            .модуль
            .get_function("free")
            .ok_or_else(|| ошибка("внутренняя ошибка: free не была объявлена"))?;
        self.билдер
            .build_call(free, &[старые_данные_байт.into()], "free_буфер")
            .map_err(|e| ошибка(format!("ошибка освобождения буфера: {:?}", e)))?;
        self.билдер
            .build_unconditional_branch(блок_после)
            .map_err(|e| ошибка(format!("ошибка перехода после копирования буфера: {:?}", e)))?;

        self.билдер.position_at_end(блок_после);
        self.билдер
            .build_pointer_cast(новые_данные_сырые, элемент_тип.ptr_type(inkwell::AddressSpace::default()), "новые_данные_типизированные")
            .map_err(|e| ошибка(format!("ошибка приведения новых данных буфера: {:?}", e)))
    }

    /// Строит значение успех(x) из УЖЕ ВЫЧИСЛЕННОГО значения (не из
    /// AST-выражения, в отличие от сгенерировать_успех) — нужно для
    /// Словарь.получить(...), где значение приходит из чтения буфера,
    /// а не из разбора синтаксического дерева. Та же insert_value-цепочка,
    /// что и в сгенерировать_успех, продублирована здесь намеренно — чтобы
    /// не рисковать регрессией уже проверенного (тестами) кода структуры
    /// результат<тип> ради небольшой экономии строк.
    fn построить_результат_успех(&mut self, t_llvm: BasicTypeEnum<'ctx>, значение: BasicValueEnum<'ctx>) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        let тип_результата = тип_результата_llvm(self.контекст, t_llvm);
        let null_сообщение = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default()).const_null();

        let агрегат = тип_результата.get_undef();
        let агрегат = self
            .билдер
            .build_insert_value(агрегат, self.контекст.bool_type().const_int(1, false), 0, "успешно")
            .map_err(|e| ошибка(format!("ошибка построения успех(...): {:?}", e)))?
            .into_struct_value();
        let агрегат = self
            .билдер
            .build_insert_value(агрегат, значение, 1, "значение")
            .map_err(|e| ошибка(format!("ошибка построения успех(...): {:?}", e)))?
            .into_struct_value();
        let агрегат = self
            .билдер
            .build_insert_value(агрегат, null_сообщение, 2, "сообщение")
            .map_err(|e| ошибка(format!("ошибка построения успех(...): {:?}", e)))?
            .into_struct_value();

        Ok(агрегат.into())
    }

    /// Аналог построить_результат_успех, но для ошибка(сообщение) — см. тот
    /// же комментарий про намеренное дублирование логики сгенерировать_ошибку.
    fn построить_результат_ошибка(&mut self, t_llvm: BasicTypeEnum<'ctx>, сообщение: BasicValueEnum<'ctx>) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        let тип_результата = тип_результата_llvm(self.контекст, t_llvm);

        let агрегат = тип_результата.get_undef();
        let агрегат = self
            .билдер
            .build_insert_value(агрегат, self.контекст.bool_type().const_int(0, false), 0, "успешно")
            .map_err(|e| ошибка(format!("ошибка построения ошибка(...): {:?}", e)))?
            .into_struct_value();
        let агрегат = self
            .билдер
            .build_insert_value(агрегат, undef_значение(t_llvm), 1, "значение")
            .map_err(|e| ошибка(format!("ошибка построения ошибка(...): {:?}", e)))?
            .into_struct_value();
        let агрегат = self
            .билдер
            .build_insert_value(агрегат, сообщение, 2, "сообщение")
            .map_err(|e| ошибка(format!("ошибка построения ошибка(...): {:?}", e)))?
            .into_struct_value();

        Ok(агрегат.into())
    }

    fn сгенерировать_вызов_метода(
        &mut self,
        объект: &Выражение,
        метод: &str,
        аргументы: &[Выражение],
    ) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        // "модуль.функция(...)" синтаксически неотличимо от вызова метода
        // на переменной (см. тот же комментарий в semantic.rs) — если
        // "объект" НЕ является ВООБЩЕ никакой известной переменной, а
        // семантика УЖЕ ПРОПУСТИЛА этот код как валидный — единственная
        // разумная интерпретация: это квалифицированный вызов СВОБОДНОЙ
        // ФУНКЦИИ "метод" из модуля "объект", а не попытка вызвать метод.
        //
        // ⚠️ ИЗМЕНЕНО В v2 (разрешение коллизий имён между модулями):
        // раньше (v1) здесь искали LLVM-функцию по буквальному "метод" и,
        // если найдена, конструировали синтетический ВызовФункции — это
        // работало, ПОКА функции из модулей регистрировались под своим
        // буквальным именем на уровне LLVM. Теперь они ВСЕГДА манглированы
        // ("модуль__метод") — нужно искать НАПРЯМУЮ через
        // манглированные_имена_функций по КОНКРЕТНОМУ модулю ("объект"),
        // а не полагаться на резолюцию неквалифицированного имени (которая
        // отклонила бы КОЛЛИЗИРУЮЩИЕ имена, даже когда модуль указан явно).
        if let Выражение::Идентификатор(имя_объекта) = объект {
            if !self.переменные.contains_key(имя_объекта) {
                if let Some(манглированное) = self.манглированные_имена_функций.get(&(имя_объекта.clone(), метод.to_string())).cloned() {
                    let llvm_функция = self
                        .модуль
                        .get_function(&манглированное)
                        .ok_or_else(|| ошибка(format!("внутренняя ошибка: функция '{}' не была объявлена заранее", манглированное)))?;

                    let вычисленные_аргументы: Result<Vec<inkwell::values::BasicMetadataValueEnum>, ОшибкаКодогенерации> = аргументы
                        .iter()
                        .map(|а| self.сгенерировать_выражение(а).map(inkwell::values::BasicMetadataValueEnum::from))
                        .collect();
                    let вычисленные_аргументы = вычисленные_аргументы?;

                    let результат = self
                        .билдер
                        .build_call(llvm_функция, &вычисленные_аргументы, "вызов_квалифицированный")
                        .map_err(|e| ошибка(format!("ошибка вызова функции '{}.{}': {:?}", имя_объекта, метод, e)))?;

                    return match результат.try_as_basic_value().left() {
                        Some(значение) => Ok(значение),
                        None => Ok(self.контекст.i32_type().const_int(0, false).into()),
                    };
                }
            }
        }

        // НОВОЕ (настоящий полиморфизм через контракты): "переменная.метод(...)"
        // где переменная имеет тип "ИмяКонтракта" — динамический вызов через
        // vtable, а не прямой вызов конкретной функции (какую именно функцию
        // вызывать, известно только в рантайме — зависит от того, какая
        // структура на самом деле упакована в этот "толстый указатель").
        if let Выражение::Идентификатор(имя) = объект {
            if let Some((указатель_ячейки, llvm_тип_ячейки, ДополнительнаяИнформация::Контракт(имя_контракта))) =
                self.переменные.get(имя).cloned()
            {
                let сигнатуры_методов = self
                    .контракты_методы
                    .get(&имя_контракта)
                    .cloned()
                    .ok_or_else(|| ошибка(format!("внутренняя ошибка: контракт '{}' не найден при вызове метода", имя_контракта)))?;
                let индекс_метода = сигнатуры_методов
                    .iter()
                    .position(|сигнатура| сигнатура.имя == метод)
                    .ok_or_else(|| ошибка(format!("у контракта '{}' нет метода '{}'", имя_контракта, метод)))?;
                let сигнатура = &сигнатуры_методов[индекс_метода];

                let толстый_указатель = self
                    .билдер
                    .build_load(llvm_тип_ячейки, указатель_ячейки, "загрузка_толстого_указателя")
                    .map_err(|e| ошибка(format!("ошибка чтения переменной контракта '{}': {:?}", имя, e)))?
                    .into_struct_value();

                let байт_указатель = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default());
                let данные = self
                    .билдер
                    .build_extract_value(толстый_указатель, 0, "данные_контракта")
                    .map_err(|e| ошибка(format!("ошибка извлечения данных из '{}': {:?}", имя, e)))?
                    .into_pointer_value();
                let vtable_указатель = self
                    .билдер
                    .build_extract_value(толстый_указатель, 1, "vtable_контракта")
                    .map_err(|e| ошибка(format!("ошибка извлечения vtable из '{}': {:?}", имя, e)))?
                    .into_pointer_value();

                // vtable — это массив i8* (непрозрачных указателей на
                // функции, все элементы одного LLVM-типа — см. генерацию
                // vtable в сгенерировать_программу) — нужный указатель на
                // функцию читается по известному индексу метода.
                let ячейка_метода = unsafe {
                    self.билдер.build_gep(
                        байт_указатель,
                        vtable_указатель,
                        &[self.контекст.i64_type().const_int(индекс_метода as u64, false)],
                        "ячейка_метода_vtable",
                    )
                }
                .map_err(|e| ошибка(format!("ошибка вычисления адреса метода '{}' в vtable: {:?}", метод, e)))?;
                let указатель_на_функцию = self
                    .билдер
                    .build_load(байт_указатель, ячейка_метода, "указатель_на_метод")
                    .map_err(|e| ошибка(format!("ошибка чтения указателя на метод '{}' из vtable: {:?}", метод, e)))?
                    .into_pointer_value();

                // Собираем FunctionType по сигнатуре метода контракта —
                // первый параметр всегда "это" (i8*, непрозрачный — opaque
                // pointers LLVM 18 делают это совместимым с указателем на
                // любую конкретную структуру без явного приведения).
                let тип_возврата_llvm = match &сигнатура.тип_возврата {
                    Some(т) => Some(self.тип_в_llvm(т)?),
                    None => None,
                };
                let mut типы_параметров: Vec<inkwell::types::BasicMetadataTypeEnum> = vec![байт_указатель.into()];
                for параметр in &сигнатура.параметры {
                    типы_параметров.push(self.тип_в_llvm(&параметр.тип)?.into());
                }
                let тип_функции = match тип_возврата_llvm {
                    Some(т) => т.fn_type(&типы_параметров, false),
                    None => self.контекст.void_type().fn_type(&типы_параметров, false),
                };

                let mut вычисленные_аргументы: Vec<inkwell::values::BasicMetadataValueEnum> = vec![данные.into()];
                for аргумент in аргументы {
                    вычисленные_аргументы.push(self.сгенерировать_выражение(аргумент)?.into());
                }

                let результат = self
                    .билдер
                    .build_indirect_call(тип_функции, указатель_на_функцию, &вычисленные_аргументы, "вызов_через_vtable")
                    .map_err(|e| ошибка(format!("ошибка динамического вызова метода '{}': {:?}", метод, e)))?;

                return match результат.try_as_basic_value().left() {
                    Some(значение) => Ok(значение),
                    None => Ok(self.контекст.i32_type().const_int(0, false).into()),
                };
            }
        }

        // Список<тип> — особый случай: его методы не найти через обычный
        // получить_структуру_из_выражения (тот ищет ДополнительнаяИнформация::
        // Структура, а у списка — ДополнительнаяИнформация::Список). Пока
        // поддерживаем только простое имя переменной — тот же класс
        // ограничения, что и у доступа к полям структур (см. получить_
        // структуру_из_выражения, комментарий там же).
        if let Выражение::Идентификатор(имя) = объект {
            if let Some((указатель_ячейки, llvm_тип_ячейки, ДополнительнаяИнформация::Список { ключ, элемент, имя_структуры_элемента, имя_контракта_элемента })) =
                self.переменные.get(имя).cloned()
            {
                // self.переменные хранит АДРЕС ЯЧЕЙКИ переменной (alloca), а не
                // сам указатель на список — нужен load, чтобы получить реальный
                // указатель на объект в куче (та же механика, что и у структур,
                // см. получить_структуру_из_выражения).
                let указатель_на_список = self
                    .билдер
                    .build_load(llvm_тип_ячейки, указатель_ячейки, "загрузка_списка")
                    .map_err(|e| ошибка(format!("ошибка чтения указателя на список '{}': {:?}", имя, e)))?
                    .into_pointer_value();
                return self.сгенерировать_метод_списка(указатель_на_список, &ключ, элемент, имя_структуры_элемента.as_deref(), имя_контракта_элемента.as_deref(), метод, аргументы);
            }

            if let Some((указатель_ячейки, llvm_тип_ячейки, ДополнительнаяИнформация::Словарь { ключ, тип_ключа, тип_значения, имя_структуры_значения })) =
                self.переменные.get(имя).cloned()
            {
                let указатель_на_словарь = self
                    .билдер
                    .build_load(llvm_тип_ячейки, указатель_ячейки, "загрузка_словаря")
                    .map_err(|e| ошибка(format!("ошибка чтения указателя на словарь '{}': {:?}", имя, e)))?
                    .into_pointer_value();
                return self.сгенерировать_метод_словаря(указатель_на_словарь, &ключ, тип_ключа, тип_значения, имя_структуры_значения.as_deref(), метод, аргументы);
            }

            // НОВОЕ (многопоточность, вторая часть): методы канал<T> —
            // отправить(значение)/получить() — тот же принцип, что у
            // Список/Словарь выше.
            if let Some((указатель_ячейки, llvm_тип_ячейки, ДополнительнаяИнформация::Канал { элемент })) =
                self.переменные.get(имя).cloned()
            {
                let указатель_на_канал = self
                    .билдер
                    .build_load(llvm_тип_ячейки, указатель_ячейки, "загрузка_канала")
                    .map_err(|e| ошибка(format!("ошибка чтения указателя на канал '{}': {:?}", имя, e)))?
                    .into_pointer_value();
                return self.сгенерировать_метод_канала(указатель_на_канал, элемент, метод, аргументы);
            }
        }

        let (указатель_на_структуру, имя_структуры) = self.получить_структуру_из_выражения(объект)?;

        let llvm_имя = Self::имя_llvm_метода(&имя_структуры, метод);
        let llvm_функция = self
            .модуль
            .get_function(&llvm_имя)
            .ok_or_else(|| ошибка(format!("метод '{}.{}' не найден", имя_структуры, метод)))?;

        // ⚠️ НАЙДЕНО ПРИ РЕАЛЬНОЙ РАБОТЕ НАД UI-ВИДЖЕТАМИ: семантика теперь
        // допускает числовой аргумент ДРУГОГО размера, чем параметр метода
        // (см. проверить_совместимость_с_приведением в semantic.rs), но
        // LLVM требует ТОЧНОГО совпадения типов при вызове — приводим
        // явно, аналогично тому, что уже сделано для конструктора структуры.
        let типы_параметров_llvm = llvm_функция.get_type().get_param_types();
        let вычисленные_аргументы: Result<Vec<inkwell::values::BasicMetadataValueEnum>, ОшибкаКодогенерации> = аргументы
            .iter()
            .enumerate()
            .map(|(индекс, а)| {
                let значение = self.сгенерировать_выражение(а)?;
                // +1: первый параметр LLVM-функции метода — указатель "это",
                // не соответствующий никакому пользовательскому аргументу.
                let ожидаемый_basic_тип = типы_параметров_llvm.get(индекс + 1).and_then(|т| BasicTypeEnum::try_from(*т).ok());
                let итоговое = match ожидаемый_basic_тип {
                    Some(ожидаемый) if ожидаемый != значение.get_type() => {
                        let целевой_дробный = ожидаемый.is_float_type();
                        self.сгенерировать_приведение_числа(значение, ожидаемый, целевой_дробный, false)?
                    }
                    _ => значение,
                };
                Ok(inkwell::values::BasicMetadataValueEnum::from(итоговое))
            })
            .collect();
        let mut все_аргументы: Vec<inkwell::values::BasicMetadataValueEnum> = vec![указатель_на_структуру.into()];
        все_аргументы.extend(вычисленные_аргументы?);

        let результат = self
            .билдер
            .build_call(llvm_функция, &все_аргументы, "вызов_метода")
            .map_err(|e| ошибка(format!("ошибка вызова метода '{}.{}': {:?}", имя_структуры, метод, e)))?;

        // ⚠️ НАЙДЕННЫЙ ПРИ РЕАЛЬНОМ ТЕСТИРОВАНИИ ПРОБЕЛ (не связанный с
        // generics — воспроизводится и для обычных, необобщённых структур):
        // раньше здесь была ОШИБКА для void-методов (никогда не тестировали
        // вызов метода-сеттера как САМОСТОЯТЕЛЬНОГО оператора — все прошлые
        // тесты использовали только методы, ВОЗВРАЩАЮЩИЕ значение). Метод
        // без "-> тип" — совершенно законный, обычный случай (сеттеры,
        // методы с побочным эффектом) — используем тот же приём, что уже
        // применён для вывести(...): если реального значения нет (build_call
        // вернул Either::Right — void, не Either::Left), отдаём безопасную
        // заглушку. Семантика УЖЕ ГАРАНТИРОВАЛА до этого места, что void-метод
        // не используется там, где значение реально требуется бы (например,
        // "целое х = объект.void_метод();" была бы отклонена раньше,
        // семантическим анализом) — значит заглушка здесь ничем не рискует.
        match результат.try_as_basic_value().left() {
            Some(значение) => Ok(значение),
            None => Ok(self.контекст.i32_type().const_int(0, false).into()),
        }
    }

    /// Генерирует чтение элемента массива: числа[i]. Механика: получаем
    /// указатель НА САМ МАССИВ (не на структуру, без лишнего load — см.
    /// комментарий у получить_массив_из_выражения), затем GEP с ДВУМЯ
    /// индексами — это стандартный, немного неочевидный паттерн LLVM для
    /// индексации массивов: первый индекс "0" означает "сам объект, на
    /// который указывает указатель" (навигация через сам указатель),
    /// второй индекс — реальный номер элемента внутри массива.
    fn сгенерировать_доступ_по_индексу(
        &mut self,
        массив: &Выражение,
        индекс: &Выражение,
    ) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        let (указатель_на_массив, элемент_тип, размер) = self.получить_массив_из_выражения(массив)?;

        let индекс_значение = self.сгенерировать_выражение(индекс)?.into_int_value();
        let индекс_i64 = self
            .билдер
            .build_int_cast(индекс_значение, self.контекст.i64_type(), "индекс")
            .map_err(|e| ошибка(format!("ошибка приведения индекса: {:?}", e)))?;

        let ноль = self.контекст.i64_type().const_int(0, false);
        let тип_массива_llvm = элемент_тип.array_type(размер);

        let адрес_элемента = unsafe {
            self.билдер
                .build_gep(тип_массива_llvm, указатель_на_массив, &[ноль, индекс_i64], "адрес_элемента")
                .map_err(|e| ошибка(format!("ошибка доступа к элементу массива: {:?}", e)))?
        };

        self.билдер
            .build_load(элемент_тип, адрес_элемента, "элемент")
            .map_err(|e| ошибка(format!("ошибка чтения элемента массива: {:?}", e)))
    }

    /// Генерирует литерал массива: [1, 2, 3]. Массивы в LLVM — полноценные
    /// "агрегатные" значения (как и структуры), их можно строить постепенно
    /// через build_insert_value — начинаем с "неопределённого" (undef)
    /// массива нужного размера и последовательно "вставляем" в него
    /// вычисленные значения элементов по одному, как заполнение ячеек.
    ///
    /// ⚠️ Эта конкретная техника (insert_value для построения агрегатного
    /// значения массива) — новая для нашего кодогенератора, использована
    /// впервые именно здесь и не проверена реальной сборкой. Если появится
    /// ошибка компиляции именно в этом методе — присылай текст, поправим.
    fn сгенерировать_массив_литерал(&mut self, элементы: &[Выражение]) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        if элементы.is_empty() {
            return Err(ошибка(
                "пустой литерал массива '[]' не поддержан кодогенератором (как и семантическим анализом)",
            ));
        }

        let значения: Result<Vec<BasicValueEnum>, ОшибкаКодогенерации> =
            элементы.iter().map(|э| self.сгенерировать_выражение(э)).collect();
        let значения = значения?;

        let элемент_тип = значения[0].get_type();
        let тип_массива = элемент_тип.array_type(значения.len() as u32);

        let mut текущий_массив = тип_массива.get_undef();
        for (индекс, значение) in значения.into_iter().enumerate() {
            текущий_массив = self
                .билдер
                .build_insert_value(текущий_массив, значение, индекс as u32, "элемент_массива")
                .map_err(|e| ошибка(format!("ошибка построения литерала массива, элемент №{}: {:?}", индекс, e)))?
                .into_array_value();
        }

        Ok(текущий_массив.into())
    }

    /// Строит значение успех(x) — заполняет анонимную структуру
    /// { i1 успешно, T значение, i8* сообщение } полями (истина, x, null).
    fn сгенерировать_успех(&mut self, внутреннее: &Выражение) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        let значение = self.сгенерировать_выражение(внутреннее)?;
        let t_llvm = значение.get_type();
        let тип_результата = тип_результата_llvm(self.контекст, t_llvm);

        let null_сообщение = self
            .контекст
            .i8_type()
            .ptr_type(inkwell::AddressSpace::default())
            .const_null();

        let агрегат = тип_результата.get_undef();
        let агрегат = self
            .билдер
            .build_insert_value(агрегат, self.контекст.bool_type().const_int(1, false), 0, "успешно")
            .map_err(|e| ошибка(format!("ошибка построения успех(...): {:?}", e)))?
            .into_struct_value();
        let агрегат = self
            .билдер
            .build_insert_value(агрегат, значение, 1, "значение")
            .map_err(|e| ошибка(format!("ошибка построения успех(...): {:?}", e)))?
            .into_struct_value();
        let агрегат = self
            .билдер
            .build_insert_value(агрегат, null_сообщение, 2, "сообщение")
            .map_err(|e| ошибка(format!("ошибка построения успех(...): {:?}", e)))?
            .into_struct_value();

        Ok(агрегат.into())
    }

    /// Строит значение ошибка(msg) — заполняет ту же структуру полями
    /// (ложь, <неопределённое значение>, msg). Тип "T" (успешного значения)
    /// берётся из текущий_ok_тип_llvm — то есть из объявленного типа
    /// возврата ТЕКУЩЕЙ функции (см. поле у Кодогенератора). Без этого
    /// контекста было бы невозможно понять, каким должно быть поле
    /// "значение" — само "ошибка(...)" не несёт этой информации.
    fn сгенерировать_ошибку(&mut self, внутреннее: &Выражение) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        let сообщение = self.сгенерировать_выражение(внутреннее)?;

        let t_llvm = self.текущий_ok_тип_llvm.ok_or_else(|| {
            ошибка(
                "ошибка(...) использована вне функции, объявленной как результат<тип> — \
                 непонятно, каким должен быть тип успешного значения",
            )
        })?;
        let тип_результата = тип_результата_llvm(self.контекст, t_llvm);

        let агрегат = тип_результата.get_undef();
        let агрегат = self
            .билдер
            .build_insert_value(агрегат, self.контекст.bool_type().const_int(0, false), 0, "успешно")
            .map_err(|e| ошибка(format!("ошибка построения ошибка(...): {:?}", e)))?
            .into_struct_value();
        let агрегат = self
            .билдер
            .build_insert_value(агрегат, undef_значение(t_llvm), 1, "значение")
            .map_err(|e| ошибка(format!("ошибка построения ошибка(...): {:?}", e)))?
            .into_struct_value();
        let агрегат = self
            .билдер
            .build_insert_value(агрегат, сообщение, 2, "сообщение")
            .map_err(|e| ошибка(format!("ошибка построения ошибка(...): {:?}", e)))?
            .into_struct_value();

        Ok(агрегат.into())
    }

    /// Генерирует оператор "?": вычисляет выражение (результат<T>), и если
    /// оно оказалось ошибкой — немедленно возвращает эту же ошибку из
    /// ТЕКУЩЕЙ функции (досрочный выход), а если успехом — "разворачивает"
    /// его до самого значения T и продолжает вычисление уже с этим значением.
    ///
    /// Это единственное место в компиляторе, где генерация ВЫРАЖЕНИЯ создаёт
    /// РАЗВЕТВЛЕНИЕ (условный переход) — во всех остальных случаях выражения
    /// это прямые, линейные вычисления без базовых блоков. "?" — по своей
    /// природе управляющая конструкция, спрятанная за синтаксисом выражения.
    fn сгенерировать_проброс(&mut self, внутреннее: &Выражение) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        let результат_значение = self.сгенерировать_выражение(внутреннее)?.into_struct_value();

        let успешно = self
            .билдер
            .build_extract_value(результат_значение, 0, "успешно")
            .map_err(|e| ошибка(format!("ошибка чтения флага успеха: {:?}", e)))?
            .into_int_value();

        let функция = self
            .текущая_функция
            .ok_or_else(|| ошибка("внутренняя ошибка: '?' сгенерирован вне тела функции"))?;

        let блок_ошибка = self.контекст.append_basic_block(функция, "проброс_ошибка");
        let блок_продолжение = self.контекст.append_basic_block(функция, "проброс_продолжение");

        self.билдер
            .build_conditional_branch(успешно, блок_продолжение, блок_ошибка)
            .map_err(|e| ошибка(format!("ошибка генерации условного перехода '?': {:?}", e)))?;

        // Ветка ошибки: пробрасываем то же сообщение дальше, оборачивая его
        // в результат<T'> ТЕКУЩЕЙ функции (T' может отличаться от T
        // внутреннего результата — тип ошибки не меняется, а тип успешного
        // значения задаётся заново под сигнатуру текущей функции), и сразу
        // возвращаемся — досрочный выход, ради которого и существует "?".
        self.билдер.position_at_end(блок_ошибка);
        let сообщение = self
            .билдер
            .build_extract_value(результат_значение, 2, "сообщение")
            .map_err(|e| ошибка(format!("ошибка чтения сообщения об ошибке: {:?}", e)))?;
        let t_текущей_функции = self.текущий_ok_тип_llvm.ok_or_else(|| {
            ошибка("внутренняя ошибка: '?' использован в функции без результат<тип> — должно быть отловлено семантическим анализом раньше")
        })?;
        let внешний_результат_тип = тип_результата_llvm(self.контекст, t_текущей_функции);
        let внешний_результат = внешний_результат_тип.get_undef();
        let внешний_результат = self
            .билдер
            .build_insert_value(внешний_результат, self.контекст.bool_type().const_int(0, false), 0, "успешно")
            .map_err(|e| ошибка(format!("ошибка построения внешнего результата при '?': {:?}", e)))?
            .into_struct_value();
        let внешний_результат = self
            .билдер
            .build_insert_value(внешний_результат, undef_значение(t_текущей_функции), 1, "значение")
            .map_err(|e| ошибка(format!("ошибка построения внешнего результата при '?': {:?}", e)))?
            .into_struct_value();
        let внешний_результат = self
            .билдер
            .build_insert_value(внешний_результат, сообщение, 2, "сообщение")
            .map_err(|e| ошибка(format!("ошибка построения внешнего результата при '?': {:?}", e)))?
            .into_struct_value();

        // ⚠️ НАЙДЕННЫЙ И ИСПРАВЛЕННЫЙ ДОЛГО ЗАДОКУМЕНТИРОВАННЫЙ ПРОБЕЛ ARC:
        // раньше здесь СРАЗУ шёл build_return, без освобождения структур,
        // объявленных в текущей функции (и её вложенных блоках) ДО этого
        // "?" — они просто "утекали" при досрочном выходе. Теперь —
        // тот же вызов, что уже используется для обычного "вернуть"
        // (см. освободить_при_возврате). "None" здесь корректно: наружу
        // при ошибке передаётся только ТЕКСТ сообщения (не структура),
        // значит защищать от освобождения нечего — можно освобождать
        // АБСОЛЮТНО все структуры во всех уровнях стека.
        self.освободить_при_возврате(None)?;

        self.билдер
            .build_return(Some(&внешний_результат))
            .map_err(|e| ошибка(format!("ошибка генерации досрочного возврата при '?': {:?}", e)))?;

        // Ветка успеха: продолжаем вычисление с "развёрнутым" значением T.
        self.билдер.position_at_end(блок_продолжение);
        self.билдер
            .build_extract_value(результат_значение, 1, "значение")
            .map_err(|e| ошибка(format!("ошибка чтения успешного значения при '?': {:?}", e)))
    }

    /// Находит LLVM-адрес (PointerValue), КУДА нужно записать значение,
    /// для произвольного МестоЗаписи — простого имени или цепочки .поле.
    /// Это ключевой метод, который и делает возможным присваивание в поле
    /// структуры: в отличие от чтения (сгенерировать_доступ_к_полю, который
    /// сразу делает load), здесь мы останавливаемся на этапе "вот адрес",
    /// не читая по нему — потому что именно в этот адрес дальше и запишет
    /// значение вызывающий код (build_store).
    fn найти_адрес_места_записи(&mut self, место: &МестоЗаписи) -> Result<PointerValue<'ctx>, ОшибкаКодогенерации> {
        match место {
            МестоЗаписи::Имя(имя) => {
                // Неизменяемость уже была проверена семантическим анализатором
                // раньше — здесь "защита в глубину", а не недоверие к анализатору.
                if *self.неизменные.get(имя).unwrap_or(&false) {
                    return Err(ошибка(format!(
                        "внутренняя проверка: попытка изменить неизменяемую переменную '{}' \
                         дошла до кодогенератора — это должно было быть отловлено раньше",
                        имя
                    )));
                }
                let (указатель, ..) = *self
                    .переменные
                    .get(имя)
                    .ok_or_else(|| ошибка(format!("переменная '{}' не найдена в кодогенераторе", имя)))?;
                Ok(указатель)
            }

            МестоЗаписи::Поле { объект, поле } => {
                // Сначала получаем указатель НА САМУ СТРУКТУРУ (не на поле —
                // на объект целиком) вместе с её именем, затем берём GEP от
                // него до конкретного поля.
                let (указатель_на_структуру, имя_структуры) = self.получить_структуру_из_места(объект)?;

                let (llvm_struct, имена_полей) = self
                    .структуры
                    .get(&имя_структуры)
                    .ok_or_else(|| ошибка(format!("внутренняя ошибка: структура '{}' не найдена", имя_структуры)))?
                    .clone();

                let индекс = имена_полей
                    .iter()
                    .position(|имя_поля| имя_поля == поле)
                    .ok_or_else(|| ошибка(format!("у структуры '{}' нет поля '{}'", имя_структуры, поле)))?;
                let llvm_индекс = индекс as u32 + СМЕЩЕНИЕ_ПОЛЕЙ_ARC;

                let адрес_поля = self.билдер
                    .build_struct_gep(llvm_struct, указатель_на_структуру, llvm_индекс, поле)
                    .map_err(|e| ошибка(format!("ошибка доступа к полю '{}' для записи: {:?}", поле, e)))?;

                Ok(адрес_поля)
            }

            МестоЗаписи::Индекс { массив, индекс } => {
                let (указатель_на_массив, элемент_тип, размер) = self.получить_массив_из_места(массив)?;
                let индекс_значение = self.сгенерировать_выражение(индекс)?.into_int_value();
                let индекс_i64 = self
                    .билдер
                    .build_int_cast(индекс_значение, self.контекст.i64_type(), "индекс")
                    .map_err(|e| ошибка(format!("ошибка приведения индекса: {:?}", e)))?;
                let ноль = self.контекст.i64_type().const_int(0, false);
                let тип_массива_llvm = элемент_тип.array_type(размер);

                let адрес_элемента = unsafe {
                    self.билдер
                        .build_gep(тип_массива_llvm, указатель_на_массив, &[ноль, индекс_i64], "адрес_элемента")
                        .map_err(|e| ошибка(format!("ошибка доступа к элементу массива для записи: {:?}", e)))?
                };

                Ok(адрес_элемента)
            }
        }
    }

    /// Получает (указатель_на_структуру, имя_структуры) из выражения —
    /// объединённая версия того, что раньше было два отдельных, менее
    /// надёжных метода. Пока поддерживает только простой случай — идентификатор
    /// переменной, которая хранит структуру (например, "юзер" в "юзер.имя").
    /// Цепочки вида "а.б.в" потребуют рекурсивного расширения — известное
    /// ограничение текущей версии (см. grammar.md, раздел 16).
    ///
    /// ВАЖНО: имя структуры берётся НАПРЯМУЮ из таблицы переменных (третий
    /// элемент кортежа), а не угадывается по виду LLVM-типа указателя.
    /// Угадывание по типу физически невозможно начиная с LLVM 15: все
    /// указатели в LLVM IR стали "непрозрачными" (opaque pointers) и
    /// выглядят одинаково независимо от того, на структуру какого вида
    /// они указывают — отсюда и была прежняя ошибка "не удалось определить
    /// тип структуры".
    /// НОВОЕ (настоящий полиморфизм через контракты): выделено в отдельную,
    /// переиспользуемую функцию — та же логика упаковки "толстого
    /// указателя" { данные, vtable }, что раньше была продублирована в
    /// объявить_переменную и Оператор::Присваивание/НовоеОбъявление —
    /// теперь нужна и здесь же, для передачи структуры аргументом функции,
    /// параметр которой ожидает контракт.
    fn упаковать_в_толстый_указатель(&mut self, значение: &Выражение, имя_контракта: &str) -> Result<BasicValueEnum<'ctx>, ОшибкаКодогенерации> {
        let (указатель_на_данные, имя_структуры) = self.получить_структуру_из_выражения(значение)?;
        let vtable = self
            .vtables
            .get(&(имя_структуры.clone(), имя_контракта.to_string()))
            .copied()
            .ok_or_else(|| {
                ошибка(format!(
                    "внутренняя ошибка: vtable для '{}' : '{}' не была сгенерирована заранее",
                    имя_структуры, имя_контракта
                ))
            })?;

        let байт_указатель = self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default());
        let данные_как_i8 = self
            .билдер
            .build_pointer_cast(указатель_на_данные, байт_указатель, "данные_контракта")
            .map_err(|e| ошибка(format!("ошибка приведения указателя данных: {:?}", e)))?;
        let vtable_как_i8 = self
            .билдер
            .build_pointer_cast(vtable.as_pointer_value(), байт_указатель, "vtable_контракта")
            .map_err(|e| ошибка(format!("ошибка приведения указателя vtable: {:?}", e)))?;

        let толстый_указатель_тип = self.контекст.struct_type(&[байт_указатель.into(), байт_указатель.into()], false);
        let mut толстый_указатель = толстый_указатель_тип.get_undef();
        толстый_указатель = self
            .билдер
            .build_insert_value(толстый_указатель, данные_как_i8, 0, "вставить_данные")
            .map_err(|e| ошибка(format!("ошибка сборки толстого указателя: {:?}", e)))?
            .into_struct_value();
        толстый_указатель = self
            .билдер
            .build_insert_value(толстый_указатель, vtable_как_i8, 1, "вставить_vtable")
            .map_err(|e| ошибка(format!("ошибка сборки толстого указателя: {:?}", e)))?
            .into_struct_value();

        Ok(толстый_указатель.into())
    }

    fn получить_структуру_из_выражения(&mut self, выражение: &Выражение) -> Result<(PointerValue<'ctx>, String), ОшибкаКодогенерации> {
        match выражение {
            Выражение::Идентификатор(имя) => {
                let (указатель, _, доп_информация) = self
                    .переменные
                    .get(имя)
                    .ok_or_else(|| ошибка(format!("переменная '{}' не найдена", имя)))?
                    .clone();

                let имя_структуры = match доп_информация {
                    ДополнительнаяИнформация::Структура(имя_с) => имя_с,
                    _ => {
                        return Err(ошибка(format!(
                            "переменная '{}' не является структурой — у неё нет полей", имя
                        )));
                    }
                };

                // Переменная хранит УКАЗАТЕЛЬ на структуру (см. тип_в_llvm для
                // Тип::Пользовательский) — значит нужно сделать load один раз,
                // чтобы получить сам этот указатель, а не адрес ячейки на стеке,
                // где он лежит.
                let значение = self
                    .билдер
                    .build_load(
                        self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default()),
                        указатель,
                        "загрузка_структуры",
                    )
                    .map_err(|e| ошибка(format!("ошибка чтения указателя на структуру '{}': {:?}", имя, e)))?;

                Ok((значение.into_pointer_value(), имя_структуры))
            }

            // ⚠️ НАЙДЕННЫЙ ПРИ РЕАЛЬНОМ ТЕСТИРОВАНИИ ПРОБЕЛ: раньше здесь была
            // только обработка простой переменной — цепочка вида
            // "компания.владелец.возраст" (доступ к полю ЧЕРЕЗ поле) падала
            // с ошибкой "доступ к полю поддержан пока только для простых
            // переменных". Мы уже документировали похожее ограничение для
            // ЗАПИСИ (а.б.в = значение) как сознательно неполное — но именно
            // для ЧТЕНИЯ это оказалось НЕДОКУМЕНТИРОВАННЫМ, незамеченным
            // пробелом, не сознательным решением. Исправлено РЕКУРСИВНО —
            // поддерживает цепочку любой глубины (а.б.в.г...), не только
            // конкретно два уровня, которые вскрыл тест.
            //
            // ⚠️ ЕЩЁ ОДНА НАЙДЕННАЯ РАЗНОВИДНОСТЬ ТОЙ ЖЕ ПРОБЛЕМЫ (проверяется
            // ПЕРВОЙ, до общей логики ниже): "результат.значение.поле"
            // (например, "из_словаря.значение.возраст", где из_словаря —
            // результат<Пользователь>). результат<T> хранится ИНАЧЕ, чем
            // обычные структуры — как значение-агрегат (build_extract_value),
            // а не указатель в куче (build_struct_gep) — значит требует
            // отдельной, особой обработки перед тем, как пробовать общий путь.
            Выражение::ДоступКПолю { объект, поле } => {
                if поле == "значение" {
                    if let Выражение::Идентификатор(имя_переменной) = объект.as_ref() {
                        if let Some((указатель, llvm_тип, ДополнительнаяИнформация::Результат { имя_структуры_значения: Some(имя_структуры) })) =
                            self.переменные.get(имя_переменной).cloned()
                        {
                            let агрегат = self
                                .билдер
                                .build_load(llvm_тип, указатель, "результат_для_цепочки")
                                .map_err(|e| ошибка(format!("ошибка чтения переменной '{}': {:?}", имя_переменной, e)))?
                                .into_struct_value();
                            let значение = self
                                .билдер
                                .build_extract_value(агрегат, 1, "значение_из_результата")
                                .map_err(|e| ошибка(format!("ошибка чтения поля 'значение' результата: {:?}", e)))?;
                            return Ok((значение.into_pointer_value(), имя_структуры));
                        }
                    }
                }

                // Общий случай: обычная пользовательская структура (либо
                // "объект.значение" — это ОБЫЧНОЕ поле какой-то структуры
                // с именем "значение", не псевдополе результат<T> — тоже
                // законный случай, попадает сюда же).
                let (указатель_на_объект, имя_структуры_объекта) = self.получить_структуру_из_выражения(объект)?;

                let (llvm_struct, имена_полей) = self
                    .структуры
                    .get(&имя_структуры_объекта)
                    .cloned()
                    .ok_or_else(|| ошибка(format!("внутренняя ошибка: структура '{}' не найдена", имя_структуры_объекта)))?;

                let индекс = имена_полей
                    .iter()
                    .position(|имя_поля| имя_поля == поле)
                    .ok_or_else(|| ошибка(format!("у структуры '{}' нет поля '{}'", имя_структуры_объекта, поле)))?;
                let llvm_индекс = индекс as u32 + СМЕЩЕНИЕ_ПОЛЕЙ_ARC;

                // Цепочка имеет смысл только если ПРОМЕЖУТОЧНОЕ поле само
                // является структурой (иначе "дальше идти некуда" — у
                // целого числа или текста нет полей). Используем ПОЛНУЮ
                // карту (все_структурные_поля, БЕЗ исключения "слабая") —
                // слабая ссылка тоже указывает на структуру, читать через
                // неё нужно нормально (слабость влияет только на владение
                // памятью, см. подробное объяснение у поля).
                let имя_структуры_поля = self
                    .все_структурные_поля
                    .get(&имя_структуры_объекта)
                    .and_then(|поля| поля.iter().find(|(идекс_поля, _)| *идекс_поля == llvm_индекс))
                    .map(|(_, имя)| имя.clone())
                    .ok_or_else(|| ошибка(format!(
                        "поле '{}' структуры '{}' само не является структурой — цепочка доступа \
                         к полю (а.б.в) требует, чтобы каждый промежуточный шаг был структурой",
                        поле, имя_структуры_объекта
                    )))?;

                let (llvm_struct_поля, _) = self
                    .структуры
                    .get(&имя_структуры_поля)
                    .cloned()
                    .ok_or_else(|| ошибка(format!("внутренняя ошибка: структура '{}' не найдена", имя_структуры_поля)))?;
                let тип_указателя_поля = llvm_struct_поля.ptr_type(inkwell::AddressSpace::default());

                let адрес_поля = self
                    .билдер
                    .build_struct_gep(llvm_struct, указатель_на_объект, llvm_индекс, поле)
                    .map_err(|e| ошибка(format!("ошибка доступа к полю '{}' в цепочке: {:?}", поле, e)))?;
                let значение_поля = self
                    .билдер
                    .build_load(тип_указателя_поля, адрес_поля, "цепочка_доступа_к_полю")
                    .map_err(|e| ошибка(format!("ошибка чтения поля '{}' в цепочке: {:?}", поле, e)))?
                    .into_pointer_value();

                Ok((значение_поля, имя_структуры_поля))
            }

            // ⚠️ НАЙДЕННЫЙ ПРИ РЕАЛЬНОМ ТЕСТИРОВАНИИ ПРОБЕЛ (тот же класс,
            // что и ДоступКПолю выше — обнаружен сразу следующим тестом,
            // подтвердив подозрение, что это не единичный случай, а общая
            // недостающая возможность): "объект.метод().поле" — доступ к
            // полю результата вызова метода, если метод возвращает
            // структуру. Раньше падало с той же ошибкой "поддержан только
            // для простых переменных". Требует ЗНАТЬ, какую именно структуру
            // возвращает метод — эта информация раньше не передавалась из
            // семантики в кодогенератор вообще (см. методы_возвращающие_структуру,
            // новый параметр конструктора Кодогенератор::новый).
            // ⚠️ ЕЩЁ ОДИН НАЙДЕННЫЙ ПРИ ТЕСТИРОВАНИИ ПРОБЕЛ — в МОЁМ ЖЕ
            // предыдущем исправлении: "Список<Структура>.получить(i).поле"
            // (например, "сотрудники.получить(0).возраст"). Список — это
            // ВСТРОЕННЫЙ тип, НЕ пользовательская структура — попытка
            // резолвить его через получить_структуру_из_выражения (веткой
            // ниже, для обычных структур) закономерно падала с "переменная
            // 'сотрудники' не является структурой". Нужно перехватить этот
            // случай ОТДЕЛЬНО, ДО общей обработки ВызовМетода — читая
            // ДополнительнаяИнформация переменной напрямую (у нас уже есть
            // имя_структуры_элемента, изначально добавленное для ARC-захвата
            // в Список.добавить — та же информация здесь снова пригодилась).
            Выражение::ВызовМетода { объект, метод, аргументы } if метод == "получить" => {
                if let Выражение::Идентификатор(имя_переменной) = объект.as_ref() {
                    if let Some((_, _, ДополнительнаяИнформация::Список { имя_структуры_элемента: Some(имя_структуры), .. })) =
                        self.переменные.get(имя_переменной).cloned()
                    {
                        let значение = self.сгенерировать_вызов_метода(объект, метод, аргументы)?;
                        return Ok((значение.into_pointer_value(), имя_структуры));
                    }
                }

                // Не оказалось Список<Структура> — падаем в обычную обработку
                // ВызовМетода ниже (объект — пользовательская структура со
                // своим методом "получить", что тоже законно).
                let (_, имя_структуры_объекта) = self.получить_структуру_из_выражения(объект)?;
                let имя_структуры_результата = self
                    .методы_возвращающие_структуру
                    .get(&(имя_структуры_объекта.clone(), метод.clone()))
                    .cloned()
                    .ok_or_else(|| ошибка(format!(
                        "метод '{}.{}' не возвращает структуру — цепочка доступа к полю \
                         (объект.метод().поле) требует, чтобы результат метода сам был структурой",
                        имя_структуры_объекта, метод
                    )))?;
                let значение = self.сгенерировать_вызов_метода(объект, метод, аргументы)?;
                Ok((значение.into_pointer_value(), имя_структуры_результата))
            }

            Выражение::ВызовМетода { объект, метод, аргументы } => {
                let (_, имя_структуры_объекта) = self.получить_структуру_из_выражения(объект)?;

                let имя_структуры_результата = self
                    .методы_возвращающие_структуру
                    .get(&(имя_структуры_объекта.clone(), метод.clone()))
                    .cloned()
                    .ok_or_else(|| ошибка(format!(
                        "метод '{}.{}' не возвращает структуру — цепочка доступа к полю \
                         (объект.метод().поле) требует, чтобы результат метода сам был структурой",
                        имя_структуры_объекта, метод
                    )))?;

                let значение = self.сгенерировать_вызов_метода(объект, метод, аргументы)?;
                Ok((значение.into_pointer_value(), имя_структуры_результата))
            }

            // То же самое, но для СВОБОДНЫХ функций: "функция().поле".
            Выражение::ВызовФункции { имя, .. } if self.функции_возвращающие_структуру.contains_key(имя) => {
                let имя_структуры_результата = self.функции_возвращающие_структуру[имя].clone();
                let значение = self.сгенерировать_выражение(выражение)?;
                Ok((значение.into_pointer_value(), имя_структуры_результата))
            }

            other => Err(ошибка(format!(
                "доступ к полю поддержан пока только для простых переменных (юзер.поле), \
                 цепочек через поля-структуры (а.б.в), и вызовов методов/функций, \
                 возвращающих структуру (объект.метод().поле) — не для {:?}",
                other
            ))),
        }
    }

    /// Аналог получить_структуру_из_выражения, но для массивов. КЛЮЧЕВОЕ
    /// ОТЛИЧИЕ от структур: массив НЕ живёт в куче через отдельный указатель —
    /// переменная-массив хранит сами данные массива прямо в своей ячейке
    /// (alloca с ArrayType), поэтому здесь НЕ нужен build_load, чтобы получить
    /// "адрес массива" — сама переменная уже и есть этот адрес.
    fn получить_массив_из_выражения(&mut self, выражение: &Выражение) -> Result<(PointerValue<'ctx>, BasicTypeEnum<'ctx>, u32), ОшибкаКодогенерации> {
        match выражение {
            Выражение::Идентификатор(имя) => {
                let (указатель, _, доп_информация) = self
                    .переменные
                    .get(имя)
                    .ok_or_else(|| ошибка(format!("переменная '{}' не найдена", имя)))?
                    .clone();

                match доп_информация {
                    ДополнительнаяИнформация::Массив { элемент, размер } => Ok((указатель, элемент, размер)),
                    _ => Err(ошибка(format!("переменная '{}' не является массивом", имя))),
                }
            }
            other => Err(ошибка(format!(
                "индексация поддержана пока только для простых переменных (числа[i]), \
                 не для сложных выражений вроде {:?}",
                other
            ))),
        }
    }

    /// Аналог получить_структуру_из_выражения, но принимает МестоЗаписи
    /// вместо Выражение — нужен, когда мы уже находимся внутри разбора
    /// цепочки присваивания (объект.поле = значение;), а не выражения на
    /// чтение. Та же логика, та же граница поддержки (только простое имя).
    fn получить_структуру_из_места(&mut self, место: &МестоЗаписи) -> Result<(PointerValue<'ctx>, String), ОшибкаКодогенерации> {
        match место {
            МестоЗаписи::Имя(имя) => {
                let (указатель, _, доп_информация) = self
                    .переменные
                    .get(имя)
                    .ok_or_else(|| ошибка(format!("переменная '{}' не найдена", имя)))?
                    .clone();

                let имя_структуры = match доп_информация {
                    ДополнительнаяИнформация::Структура(имя_с) => имя_с,
                    _ => {
                        return Err(ошибка(format!(
                            "переменная '{}' не является структурой — у неё нет полей", имя
                        )));
                    }
                };

                let значение = self
                    .билдер
                    .build_load(
                        self.контекст.i8_type().ptr_type(inkwell::AddressSpace::default()),
                        указатель,
                        "загрузка_структуры",
                    )
                    .map_err(|e| ошибка(format!("ошибка чтения указателя на структуру '{}': {:?}", имя, e)))?;

                Ok((значение.into_pointer_value(), имя_структуры))
            }
            МестоЗаписи::Поле { .. } => Err(ошибка(
                "присваивание в поле структуры, полученной через поле другой структуры \
                 (а.б.в = значение;), пока не поддержано — известное ограничение текущей версии",
            )),
            МестоЗаписи::Индекс { .. } => Err(ошибка(
                "доступ к полю элемента массива структур (числа[i].поле = ...;) пока не поддержан",
            )),
        }
    }

    /// Аналог получить_структуру_из_места, но для массивов — см. пояснение
    /// у получить_массив_из_выражения про отсутствие load для массивов.
    fn получить_массив_из_места(&mut self, место: &МестоЗаписи) -> Result<(PointerValue<'ctx>, BasicTypeEnum<'ctx>, u32), ОшибкаКодогенерации> {
        match место {
            МестоЗаписи::Имя(имя) => {
                let (указатель, _, доп_информация) = self
                    .переменные
                    .get(имя)
                    .ok_or_else(|| ошибка(format!("переменная '{}' не найдена", имя)))?
                    .clone();

                match доп_информация {
                    ДополнительнаяИнформация::Массив { элемент, размер } => Ok((указатель, элемент, размер)),
                    _ => Err(ошибка(format!("переменная '{}' не является массивом", имя))),
                }
            }
            МестоЗаписи::Поле { .. } => Err(ошибка(
                "массив как поле структуры (юзер.массив[i] = ...;) пока не поддержан",
            )),
            МестоЗаписи::Индекс { .. } => Err(ошибка(
                "массив массивов (числа[i][j] = ...;) пока не поддержан",
            )),
        }
    }
}

/// Проверка, не завершён ли уже текущий базовый блок инструкцией-терминатором
/// (return/branch). Нужна, чтобы не пытаться добавить два терминатора подряд —
/// LLVM такое не разрешает и это самая частая ошибка при ручной генерации IR
/// для конструкций вроде if/else, где одна из веток уже может завершаться
/// оператором "вернуть".
fn блок_не_завершён(билдер: &Builder) -> bool {
    билдер
        .get_insert_block()
        .map(|блок| блок.get_terminator().is_none())
        .unwrap_or(false)
}

/// Конвертация типа, выведенного семантическим анализатором (РешённыйТип),
/// в LLVM-тип. Отдельная от тип_в_llvm() функция, потому что работает с
/// другим представлением типа (semantic::РешённыйТип, а не ast::Тип) —
/// в будущем эти два представления, вероятно, стоит объединить, когда
/// семантический анализ будет переписывать AST напрямую, а не возвращать
/// параллельный список решений.
/// Строит стабильный строковый ключ для конкретной инстанциации Список<тип>,
/// однозначно определяемый НАШИМ семантическим представлением типа
/// (РешённыйТип), а НЕ выведенный из LLVM-типа. Это принципиально: начиная
/// с LLVM 15 указатели непрозрачны (opaque pointers) — указатель на
/// Список<Пользователь> и на Список<Собака> выглядели бы в LLVM одинаково,
/// если бы мы попытались получить ключ ИЗ LLVM-типа постфактум (та самая
/// ошибка, которую мы уже совершали и исправляли для обычных структур).
/// Строя ключ из РешённыйТип с самого начала, эта проблема просто не может
/// возникнуть — при чтении текстового ключа для нас пока используются
/// только имена латиницей/цифрами, поэтому это UTF-8-safe-строка.
fn ключ_типа_списка(тип: &РешённыйТип) -> String {
    use РешённыйТип::*;
    match тип {
        Целое => "целое".to_string(),
        Целое8 => "целое8".to_string(),
        Целое16 => "целое16".to_string(),
        Целое32 => "целое32".to_string(),
        Целое64 => "целое64".to_string(),
        Беззнак8 => "беззнак8".to_string(),
        Беззнак16 => "беззнак16".to_string(),
        Беззнак32 => "беззнак32".to_string(),
        Беззнак64 => "беззнак64".to_string(),
        Дробное => "дробное".to_string(),
        Дробное32 => "дробное32".to_string(),
        Дробное64 => "дробное64".to_string(),
        Текст => "текст".to_string(),
        Верно => "верно".to_string(),
        Структура(имя) => format!("структура_{}", имя),
        Массив { элемент, размер } => format!("массив_{}_{}", ключ_типа_списка(элемент), размер),
        Результат(внутренний) => format!("результат_{}", ключ_типа_списка(внутренний)),
        Список(внутренний) => format!("список_{}", ключ_типа_списка(внутренний)),
        Словарь(тип_ключа, тип_значения) => {
            format!("словарь_{}_{}", ключ_типа_списка(тип_ключа), ключ_типа_списка(тип_значения))
        }
        Канал(внутренний) => format!("канал_{}", ключ_типа_списка(внутренний)),
        Контракт(имя) => format!("контракт_{}", имя),
        Неизвестен => "неизвестен".to_string(),
    }
}

/// Строит ключ для инстанциации Словарь<Ключ, Значение> — просто комбинация ключей
/// K и V через ключ_типа_списка (та же функция подходит для одного типа,
/// здесь просто объединяем оба).
fn ключ_типа_словаря(тип_ключа: &РешённыйТип, тип_значения: &РешённыйТип) -> String {
    format!("{}__{}", ключ_типа_списка(тип_ключа), ключ_типа_списка(тип_значения))
}

fn решённый_тип_в_llvm<'ctx>(
    контекст: &'ctx Context,
    тип: &crate::semantic::РешённыйТип,
    структуры: &HashMap<String, (StructType<'ctx>, Vec<String>)>,
) -> Result<BasicTypeEnum<'ctx>, ОшибкаКодогенерации> {
    use crate::semantic::РешённыйТип::*;
    match тип {
        Целое | Целое64 | Беззнак64 => Ok(контекст.i64_type().into()),
        Целое32 | Беззнак32 => Ok(контекст.i32_type().into()),
        Целое16 | Беззнак16 => Ok(контекст.i16_type().into()),
        Целое8 | Беззнак8 => Ok(контекст.i8_type().into()),
        Дробное | Дробное64 => Ok(контекст.f64_type().into()),
        Дробное32 => Ok(контекст.f32_type().into()),
        Верно => Ok(контекст.bool_type().into()),
        Текст => Ok(контекст.i8_type().ptr_type(inkwell::AddressSpace::default()).into()),
        // НОВОЕ: канал<тип> — как и "текст", просто непрозрачный указатель
        // на кучу (сама структура канала: мьютекс + условная переменная +
        // слот значения — читается/пишется напрямую по байтовым смещениям
        // в кодогенерации создать_канал/отправить/получить, не нуждается
        // в именованном LLVM struct type).
        Канал(_) => Ok(контекст.i8_type().ptr_type(inkwell::AddressSpace::default()).into()),
        Структура(имя) => {
            let (llvm_struct, _) = структуры.get(имя).ok_or_else(|| {
                ошибка(format!(
                    "неизвестная структура '{}' при генерации типа — \
                     возможно, поле ссылается на структуру, объявленную позже по файлу \
                     (текущая версия не поддерживает такой порядок для полей структур)",
                    имя
                ))
            })?;
            Ok(llvm_struct.ptr_type(inkwell::AddressSpace::default()).into())
        }
        Массив { элемент, размер } => {
            let llvm_элемент = решённый_тип_в_llvm(контекст, элемент, структуры)?;
            Ok(llvm_элемент.array_type(*размер as u32).into())
        }
        Результат(внутренний) => {
            let llvm_внутренний = решённый_тип_в_llvm(контекст, внутренний, структуры)?;
            Ok(тип_результата_llvm(контекст, llvm_внутренний).into())
        }
        Список(_) => Err(ошибка(
            "Список<тип> нельзя объявить через вывод типа (простое присваивание без \
             явного 'Список<тип>' слева) — используй явное объявление, например: \
             'Список<целое> числа = Список<целое>();'. Это известное, задокументированное \
             ограничение текущей версии (см. README).",
        )),
        Словарь(..) => Err(ошибка(
            "Словарь<Ключ, Значение> нельзя объявить через вывод типа (простое присваивание без \
             явного 'Словарь<Ключ, Значение>' слева) — используй явное объявление, например: \
             'Словарь<целое, текст> телефоны = Словарь<целое, текст>();'. Та же граница, \
             что и у Список<тип> (см. README).",
        )),
        Контракт(_) => {
            // "Толстый указатель" — анонимная (безымянная) LLVM-структура
            // { i8* данные, i8* vtable }, тот же приём, что уже сработал
            // для результат<T> — не нужен отдельный реестр/кэш именованных
            // типов, LLVM сам "склеивает" одинаковые по структуре
            // анонимные типы. "данные" — указатель на реальный экземпляр
            // структуры (любой, чей код объявлен реализующим контракт);
            // "vtable" — указатель на глобальную таблицу указателей на
            // функции, сгенерированную для КОНКРЕТНОЙ пары
            // (структура, контракт) — см. подробное объяснение в месте
            // генерации vtable.
            let байт_указатель = контекст.i8_type().ptr_type(inkwell::AddressSpace::default());
            Ok(контекст.struct_type(&[байт_указатель.into(), байт_указатель.into()], false).into())
        }
        Неизвестен => Err(ошибка(
            "внутренняя ошибка: кодогенератор получил переменную с неопределённым типом — \
             семантический анализатор должен был отловить это раньше",
        )),
    }
}

/// Строит то же самое манглированное имя, что и семантика для конкретной
/// инстанциации обобщённой структуры (см. semantic.rs, манглированное_имя) —
/// НАМЕРЕННО ПРОДУБЛИРОВАНО здесь, а не вызвано напрямую из semantic.rs:
/// эта функция ЧИСТАЯ (без побочных эффектов, без доступа к состоянию
/// анализатора), значит дублирование безопасно — риск расхождения только
/// один: если поменять формат в одном месте, забыв про другое (задокументировано
/// явно здесь и там, взаимной ссылкой в комментариях).
fn манглированное_имя_обобщённой_структуры(имя_шаблона: &str, конкретный_тип: &РешённыйТип) -> String {
    format!("{}__{}", имя_шаблона, манглированное_имя_типа_кодогенератора(конкретный_тип))
}

/// Сопоставляет ИМЯ встроенного числового типа его LLVM-представлению,
/// вместе с ДОПОЛНИТЕЛЬНОЙ информацией, нужной для выбора правильной
/// LLVM-инструкции приведения — является ли тип дробным (float vs int) и
/// беззнаковым (влияет на то, как знаковое расширение/усечение работает
/// при приведении между размерами). Та же логика, что и в semantic.rs
/// (имя_числового_типа_в_решённый_тип) — намеренно продублирована здесь,
/// поскольку кодогенерации нужна ДОПОЛНИТЕЛЬНАЯ информация (не просто
/// РешённыйТип, а сразу LLVM-тип + эти два флага).
/// НОВОЕ (текст под ARC): определяет, ПОРОЖДАЕТ ли выражение НОВЫЙ,
/// malloc'нутый текстовый буфер — конкатенация ("+") или вызов одной из
/// перечисленных функций стандартной библиотеки. Используется, чтобы
/// решить, нужно ли отслеживать переменную, инициализированную ЭТИМ
/// выражением, как "владеющую" (см. стек_arc_областей_текста) — то есть
/// освобождать её при выходе из области видимости.
///
/// ⚠️ ЧЕСТНО НЕ ВКЛЮЧЕНО (см. также комментарий у поля стек_arc_областей_текста):
/// подстрока() — возвращает результат<текст> (значение "внутри" обёртки,
/// сложнее отследить), прочитать_строку()/прочитать_файл() — тоже
/// результат<текст>. Эти случаи — честно отложенный, следующий шаг
/// (текст внутри результат<T> требует дополнительного отслеживания при
/// разворачивании через "?" или ручную проверку .успешно/.значение).
fn является_текст_порождающим(выражение: &Выражение) -> bool {
    match выражение {
        Выражение::Бинарное { оператор: БинарныйОператор::Плюс, .. } => true,
        Выражение::ВызовФункции { имя, .. } => matches!(
            имя.as_str(),
            // ⚠️ НАЙДЕНО РЕАЛЬНОЙ ПРОВЕРКОЙ (не связано с побитовыми
            // операторами, случайно всплыло при их тестировании):
            // "верно_в_текст" раньше была в этом списке, хотя она
            // НИКОГДА не делает malloc — сгенерировать_верно_в_текст
            // возвращает указатель на одну из двух ГОТОВЫХ, глобальных
            // строковых констант ("да"/"нет", через build_select) — то
            // же самое, что и у обычного текстового литерала. Попытка
            // free() на глобальной константе — настоящий, серьёзный
            // краш (invalid pointer), не просто утечка, и он был
            // безусловным — срабатывал при КАЖДОЙ конкатенации с
            // результатом верно_в_текст, включая самый первый, простейший
            // пример из документации языка.
            "регистр_в_верхний" | "регистр_в_нижний" | "целое_в_текст" | "дробное_в_текст"
        ),
        _ => false,
    }
}

/// НОВОЕ (текст под ARC, продолжение): та же идея, что и у
/// является_текст_порождающим выше, но для функций, возвращающих
/// результат<текст> (не голый текст напрямую) — значение "внутри"
/// обёртки result<T> само по себе тоже может быть свежим malloc'нутым
/// буфером, нуждающимся в освобождении, если результат оказался успешным.
fn является_результат_текст_порождающим(выражение: &Выражение) -> bool {
    match выражение {
        Выражение::ВызовФункции { имя, .. } => matches!(
            имя.as_str(),
            "подстрока" | "прочитать_строку" | "прочитать_файл"
        ),
        _ => false,
    }
}

fn информация_числового_типа<'ctx>(контекст: &'ctx Context, имя: &str) -> Option<(BasicTypeEnum<'ctx>, bool, bool)> {
    match имя {
        "целое" | "целое64" => Some((контекст.i64_type().into(), false, false)),
        "целое8" => Some((контекст.i8_type().into(), false, false)),
        "целое16" => Some((контекст.i16_type().into(), false, false)),
        "целое32" => Some((контекст.i32_type().into(), false, false)),
        "беззнак8" => Some((контекст.i8_type().into(), false, true)),
        "беззнак16" => Some((контекст.i16_type().into(), false, true)),
        "беззнак32" => Some((контекст.i32_type().into(), false, true)),
        "беззнак64" => Some((контекст.i64_type().into(), false, true)),
        "дробное" | "дробное64" => Some((контекст.f64_type().into(), true, false)),
        "дробное32" => Some((контекст.f32_type().into(), true, false)),
        _ => None,
    }
}

fn манглированное_имя_типа_кодогенератора(тип: &РешённыйТип) -> String {
    match тип {
        РешённыйТип::Целое => "целое".to_string(),
        РешённыйТип::Целое8 => "целое8".to_string(),
        РешённыйТип::Целое16 => "целое16".to_string(),
        РешённыйТип::Целое32 => "целое32".to_string(),
        РешённыйТип::Целое64 => "целое64".to_string(),
        РешённыйТип::Беззнак8 => "беззнак8".to_string(),
        РешённыйТип::Беззнак16 => "беззнак16".to_string(),
        РешённыйТип::Беззнак32 => "беззнак32".to_string(),
        РешённыйТип::Беззнак64 => "беззнак64".to_string(),
        РешённыйТип::Дробное => "дробное".to_string(),
        РешённыйТип::Дробное32 => "дробное32".to_string(),
        РешённыйТип::Дробное64 => "дробное64".to_string(),
        РешённыйТип::Текст => "текст".to_string(),
        РешённыйТип::Верно => "верно".to_string(),
        РешённыйТип::Структура(имя) => имя.clone(),
        other => format!("{:?}", other),
    }
}

/// Строит LLVM-тип для результат<T> — анонимная (безымянная) структура
/// { i1 успешно, T значение, i8* сообщение }. Анонимные (не именованные)
/// LLVM struct-типы с одинаковым набором полей автоматически считаются
/// одним и тем же типом — в отличие от именованных структур языка "Сфера"
/// (см. структуры/StructType), нам не нужен отдельный реестр/кэш для
/// результат<T>: можно просто строить этот тип заново в любом месте, где
/// он нужен, и LLVM сам "склеит" одинаковые по структуре типы.
///
/// Поле "сообщение" всегда присутствует, даже когда результат успешен
/// (в этом случае оно просто не используется, содержит null) — фиксированный
/// макет проще и надёжнее переменного, для масштаба этого компилятора.
fn тип_результата_llvm<'ctx>(контекст: &'ctx Context, t: BasicTypeEnum<'ctx>) -> StructType<'ctx> {
    let bool_тип = контекст.bool_type().into();
    let текст_тип = контекст.i8_type().ptr_type(inkwell::AddressSpace::default()).into();
    контекст.struct_type(&[bool_тип, t, текст_тип], false)
}

/// "Неопределённое" (undef) значение произвольного базового типа — нужно
/// как заполнитель для поля "значение" при построении ошибка(...), когда
/// самого успешного значения не существует (мы в ветке ошибки, значение
/// не имеет смысла, но поле в структуре физически должно быть чем-то
/// заполнено). Разные конкретные LLVM-типы имеют метод get_undef()
/// каждый по-своему — эта функция просто вызывает нужный вариант.
fn undef_значение(тип: BasicTypeEnum) -> BasicValueEnum {
    match тип {
        BasicTypeEnum::IntType(t) => t.get_undef().into(),
        BasicTypeEnum::FloatType(t) => t.get_undef().into(),
        BasicTypeEnum::PointerType(t) => t.get_undef().into(),
        BasicTypeEnum::ArrayType(t) => t.get_undef().into(),
        BasicTypeEnum::StructType(t) => t.get_undef().into(),
        BasicTypeEnum::VectorType(t) => t.get_undef().into(),
    }
}

/// Аналог дополнительная_информация_из_ast_типа (метод Кодогенератора), но
/// работающий с РешённыйТип вместо ast::Тип — нужен для случая, когда
/// объявление шло через вывод типа (Присваивание -> НовоеОбъявление), а не
/// через явный ast::Тип в исходном коде.
fn дополнительная_информация_из_решённого_типа<'ctx>(
    контекст: &'ctx Context,
    тип: &crate::semantic::РешённыйТип,
    структуры: &HashMap<String, (StructType<'ctx>, Vec<String>)>,
) -> Result<ДополнительнаяИнформация<'ctx>, ОшибкаКодогенерации> {
    use crate::semantic::РешённыйТип::*;
    match тип {
        Структура(имя) => Ok(ДополнительнаяИнформация::Структура(имя.clone())),
        Массив { элемент, размер } => {
            let llvm_элемент = решённый_тип_в_llvm(контекст, элемент, структуры)?;
            Ok(ДополнительнаяИнформация::Массив { элемент: llvm_элемент, размер: *размер as u32 })
        }
        Результат(внутренний) => {
            let имя_структуры_значения = match внутренний.as_ref() {
                Структура(имя) => Some(имя.clone()),
                _ => None,
            };
            Ok(ДополнительнаяИнформация::Результат { имя_структуры_значения })
        }
        Канал(внутренний) => {
            let llvm_элемент = решённый_тип_в_llvm(контекст, внутренний, структуры)?;
            Ok(ДополнительнаяИнформация::Канал { элемент: llvm_элемент })
        }
        _ => Ok(ДополнительнаяИнформация::Нет),
    }
}
